package com.screenocr.tts.capture

import android.graphics.Bitmap
import android.util.Log
import com.screenocr.tts.core.OcrLine
import com.screenocr.tts.core.OcrResult
import com.screenocr.tts.core.Region
import com.screenocr.tts.core.TextHeuristics
import com.screenocr.tts.ocr.OcrEngine
import com.screenocr.tts.settings.Settings
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.currentCoroutineContext
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/** Метрика одного прохода сканирования (аналог on_scan_timing в scanner.py). */
data class ScanTiming(
    val durationMs: Long,
    val text: String,
    val confidence: Float,
    val skipped: Boolean,
)

/** Публичный статус сканера для UI (порт get_status из scanner.py). */
data class ScannerStatus(
    val running: Boolean = false,
    val paused: Boolean = false,
    val intervalMs: Int = 0,
    val detectChanges: Boolean = true,
    val regions: Int = 0,
    val scans: Long = 0,
    val skipped: Long = 0,
    val lastText: String = "",
    val lastDurationMs: Long = 0,
    val lastError: String? = null,
)

/**
 * Порт scanner.py: цикл захвата + детекция изменений кадра + OCR.
 *
 * Отличия от десктопа, вызванные платформой:
 *  - детекция изменений сделана как downsample 64x64 + средняя разница
 *    с порогом Settings.Ocr.CHANGE_THRESHOLD (на десктопе это был хеш
 *    трёх средних, он давал ложные срабатывания на шумах);
 *  - вместо файлов ocr_logs_simple пишем в Logcat.
 */
class ScreenScanner(
    private val capture: ScreenCapture,
    private val settings: Settings,
    private val scope: CoroutineScope,
    engine: OcrEngine,
) {

    var engine: OcrEngine = engine
        private set

    var intervalMs: Int = settings.get(Settings.Ocr.SCAN_INTERVAL_MS, DEFAULT_INTERVAL_MS)
        private set

    var detectChanges: Boolean = settings.get(Settings.Ocr.DETECT_CHANGES, true)
        private set

    private var changeThreshold: Float =
        settings.get(Settings.Ocr.CHANGE_THRESHOLD, 0.05f).coerceIn(0.0005f, 1f)

    private val minConfidence: Int = settings.get(Settings.Ocr.CONFIDENCE, 40)

    @Volatile private var regions: List<Region> = emptyList()
    @Volatile private var running = false
    @Volatile private var paused = false

    private var loopJob: Job? = null
    private var lastScanAt = 0L
    private var scans = 0L
    private var skipped = 0L
    private var lastDurationMs = 0L
    private var lastError: String? = null

    private val debugLogging =
        settings.get(Settings.General.LOG_LEVEL, "INFO").equals("DEBUG", ignoreCase = true)

    // Кэш "уже произнесённого" текста - порт _text_changed из scanner.py
    private val textCache = LinkedHashMap<String, Long>()
    private val cacheLock = Any()
    private var lastCacheCleanup = 0L
    private var lastText = ""

    // Отпечаток кадра для детекции изменений
    private var prevSignature: FloatArray? = null
    private val diffBuffer = FloatArray(SIG_SIZE * SIG_SIZE)
    private val includeMask = BooleanArray(SIG_SIZE * SIG_SIZE)

    private val _status = MutableStateFlow(ScannerStatus(intervalMs = intervalMs, detectChanges = detectChanges))
    val status: StateFlow<ScannerStatus> = _status.asStateFlow()

    var onTextDetected: ((String) -> Unit)? = null
    var onResult: ((OcrResult) -> Unit)? = null
    var onScanTiming: ((ScanTiming) -> Unit)? = null
    var onScanningChanged: ((Boolean) -> Unit)? = null

    init {
        buildIncludeMask()
    }

    // ── управление ─────────────────────────────────────────────

    fun setEngine(engine: OcrEngine) {
        this.engine = engine
    }

    fun setRegions(list: List<Region>) {
        regions = list
        clearCache()
        publish()
    }

    /** Текущий список регионов (пустой - сканируется весь экран). */
    fun regions(): List<Region> = regions

    fun start() {
        if (running) {
            Log.w(TAG, "Сканирование уже запущено")
            return
        }
        running = true
        paused = false
        lastScanAt = 0L
        loopJob = scope.launch(Dispatchers.Default) { scanLoop() }
        onScanningChanged?.invoke(true)
        publish()
        Log.i(TAG, "ScreenScanner запущен, интервал ${intervalMs}мс")
    }

    fun stop() {
        if (!running) return
        running = false
        loopJob?.cancel()
        loopJob = null
        onScanningChanged?.invoke(false)
        publish()
        Log.i(TAG, "ScreenScanner остановлен")
    }

    fun pause() {
        paused = true
        publish()
    }

    fun resume() {
        paused = false
        publish()
    }

    fun togglePause() {
        if (paused) resume() else pause()
    }

    fun setInterval(interval: Int) {
        val value = interval.coerceAtLeast(MIN_INTERVAL_MS)
        intervalMs = value
        settings.set(Settings.Ocr.SCAN_INTERVAL_MS, value)
        publish()
        Log.i(TAG, "Интервал сканирования: ${value}мс")
    }

    fun setDetectChanges(enabled: Boolean) {
        detectChanges = enabled
        settings.set(Settings.Ocr.DETECT_CHANGES, enabled)
        if (!enabled) {
            synchronized(cacheLock) { prevSignature = null }
        }
        publish()
        Log.i(TAG, "Детекция изменений: ${if (enabled) "вкл" else "выкл"}")
    }

    fun setChangeThreshold(value: Float) {
        changeThreshold = value.coerceIn(0.0005f, 1f)
        settings.set(Settings.Ocr.CHANGE_THRESHOLD, changeThreshold)
    }

    fun clearCache() {
        synchronized(cacheLock) {
            textCache.clear()
            prevSignature = null
            lastText = ""
            lastCacheCleanup = 0L
        }
        publish()
    }

    /** Однократное сканирование по кнопке "Сканировать". */
    suspend fun scanOnce(): OcrResult? = withContext(Dispatchers.Default) { runScan() }

    // ── цикл ───────────────────────────────────────────────────

    private suspend fun scanLoop() {
        Log.i(TAG, "Запуск цикла сканирования")
        while (running && currentCoroutineContext().isActive) {
            if (paused) {
                delay(100)
                continue
            }
            val elapsed = System.currentTimeMillis() - lastScanAt
            if (elapsed < intervalMs) {
                delay((intervalMs - elapsed).coerceAtMost(500L))
                continue
            }
            lastScanAt = System.currentTimeMillis()
            try {
                runScan()
            } catch (e: CancellationException) {
                throw e
            } catch (e: Throwable) {
                lastError = e.message ?: e::class.java.simpleName
                Log.e(TAG, "Ошибка в цикле сканирования: $lastError", e)
                publish()
                delay(1000)
            }
        }
        Log.i(TAG, "Цикл сканирования остановлен")
    }

    private suspend fun runScan(): OcrResult? {
        val t0 = System.currentTimeMillis()
        val active = regions.filter { it.enabled }
        val first: Bitmap? = if (active.isEmpty()) capture.captureFull()
        else capture.captureRegion(active.first())

        if (first == null) {
            if (debugLogging) Log.d(TAG, "[SCAN] кадр недоступен")
            delay(100)
            return null
        }

        if (detectChanges && !detectFrameChange(first)) {
            first.recycle()
            skipped++
            onScanTiming?.invoke(ScanTiming(System.currentTimeMillis() - t0, "", 0f, true))
            if (debugLogging) Log.d(TAG, "[SCAN] изменений нет, OCR пропущен")
            publish()
            delay(50)
            return null
        }

        val result = try {
            recognizeAll(active, first)
        } finally {
            if (!first.isRecycled) first.recycle()
        }

        scans++
        val duration = System.currentTimeMillis() - t0
        lastDurationMs = duration
        val accepted = applyConfidenceFilter(result)
        onResult?.invoke(accepted)
        logOcrResult(accepted, duration)

        if (accepted.text.isNotBlank() && textChanged(accepted.text)) {
            onTextDetected?.invoke(accepted.text)
        }
        onScanTiming?.invoke(ScanTiming(duration, accepted.text, accepted.confidence, false))
        if (lastError != null) lastError = null
        publish()
        return accepted
    }

    private suspend fun recognize(bitmap: Bitmap): OcrResult = engine.recognize(bitmap)

    /**
     * Несколько регионов за проход: первый кадр уже захвачен, остальные
     * добираются по одному. Тексты склеиваются переводом строки,
     * confidence усредняется - так же, как работает мультирегион в десктопе.
     */
    private suspend fun recognizeAll(list: List<Region>, first: Bitmap): OcrResult {
        val lines = ArrayList<OcrLine>()
        val text = StringBuilder()
        var confSum = 0f
        var confCount = 0
        var elapsed = 0L
        for ((index, region) in list.withIndex()) {
            val bmp: Bitmap = if (index == 0) first else capture.captureRegion(region) ?: continue
            val res = try {
                recognize(bmp)
            } finally {
                if (index != 0 && !bmp.isRecycled) bmp.recycle()
            }
            elapsed += res.elapsedMs
            if (res.text.isBlank()) continue
            if (text.isNotEmpty()) text.append('\n')
            text.append(res.text)
            lines.addAll(res.lines)
            confSum += res.confidence
            confCount++
        }
        val confidence = if (confCount == 0) 0f else confSum / confCount
        return OcrResult(text.toString(), confidence, lines, engine.id, elapsed)
    }

    private fun applyConfidenceFilter(result: OcrResult): OcrResult {
        // Движок может не отдавать confidence (0) - тогда результат принимается как есть.
        if (result.confidence <= 0f) return result
        if (result.confidence * 100f >= minConfidence) return result
        if (debugLogging) {
            Log.d(TAG, "[OCR-LOG] отброшено по confidence ${result.confidence}")
        }
        return OcrResult("", 0f, emptyList(), result.engine, result.elapsedMs)
    }

    private fun logOcrResult(result: OcrResult, durationMs: Long) {
        if (!debugLogging) return
        val normalized = if (result.text.isBlank()) "(empty)" else TextHeuristics.normalize(result.text)
        Log.d(
            TAG,
            "[OCR-LOG] ${durationMs}ms conf=${(result.confidence * 100).toInt()}% " +
                "engine=${result.engine} raw=\"${result.text.take(60)}\" norm=\"$normalized\"",
        )
    }

    // ── детекция изменений кадра ───────────────────────────────

    /**
     * Порядок как в scanner.py: центральная половина кадра (по краям обычно
     * статичный chrome), downsample до 64x64 в градациях серого, средняя
     * абсолютная разница с предыдущим кадром. Центральные 5% исключены -
     * там может быть курсор/системный жест.
     */
    private fun detectFrameChange(bitmap: Bitmap): Boolean {
        val current = signature(bitmap) ?: return true
        synchronized(cacheLock) {
            val previous = prevSignature
            prevSignature = current
            if (previous == null) return true
            current.copyInto(diffBuffer)

            var sum = 0f
            var count = 0
            for (i in diffBuffer.indices) {
                if (!includeMask[i]) continue
                sum += kotlin.math.abs(diffBuffer[i] - previous[i])
                count++
            }
            if (count == 0) {
                for (i in diffBuffer.indices) {
                    sum += kotlin.math.abs(diffBuffer[i] - previous[i])
                    count++
                }
            }
            val mean = sum / count
            val normalized = mean / 255f
            if (normalized > changeThreshold) {
                if (debugLogging) {
                    Log.d(TAG, "[SCAN] изменение кадра diff=" + (normalized * 1000).toInt() / 1000.0f)
                }
                return true
            }
            return false
        }
    }

    private fun signature(bitmap: Bitmap): FloatArray? {
        var src: Bitmap? = null
        var crop: Bitmap? = null
        return try {
            val cx1 = bitmap.width / 4
            val cy1 = bitmap.height / 4
            val cw = (bitmap.width * 2) / 4
            val ch = (bitmap.height * 2) / 4
            if (cw <= 0 || ch <= 0) return null
            src = Bitmap.createBitmap(bitmap, cx1, cy1, cw, ch)
            crop = Bitmap.createScaledBitmap(src, SIG_SIZE, SIG_SIZE, true)
            val pixels = IntArray(SIG_SIZE * SIG_SIZE)
            crop.getPixels(pixels, 0, SIG_SIZE, 0, 0, SIG_SIZE, SIG_SIZE)
            val out = FloatArray(SIG_SIZE * SIG_SIZE)
            for (i in out.indices) {
                val p = pixels[i]
                val r = (p shr 16) and 0xFF
                val g = (p shr 8) and 0xFF
                val b = p and 0xFF
                out[i] = 0.299f * r + 0.587f * g + 0.114f * b
            }
            out
        } catch (e: Throwable) {
            Log.e(TAG, "Не удалось посчитать отпечаток кадра", e)
            null
        } finally {
            if (crop != null && crop !== src) runCatching { crop.recycle() }
            runCatching { src?.recycle() }
        }
    }

    private fun buildIncludeMask() {
        val marginX = (SIG_SIZE * 0.05f).toInt().coerceAtLeast(1)
        val marginY = (SIG_SIZE * 0.05f).toInt().coerceAtLeast(1)
        val cx = SIG_SIZE / 2
        val cy = SIG_SIZE / 2
        val r = (SIG_SIZE * 0.05f).toInt().coerceAtLeast(1)
        for (y in 0 until SIG_SIZE) {
            for (x in 0 until SIG_SIZE) {
                val inCursor = x >= cx - r && x < cx + r && y >= cy - r && y < cy + r
                val onEdge = x < marginX || y < marginY ||
                    x >= SIG_SIZE - marginX || y >= SIG_SIZE - marginY
                includeMask[y * SIG_SIZE + x] = !inCursor && !onEdge
            }
        }
    }

    // ── кэш текста (порт _text_changed / _cleanup_text_cache) ──

    private fun textChanged(text: String): Boolean {
        if (text.isBlank()) return false
        val normalized = TextHeuristics.normalize(text)
        val key = normalized.trimEnd('.', ',', '!', '?', ':', ';', '-')
        if (key.length <= 3) return false

        val now = System.currentTimeMillis()
        synchronized(cacheLock) {
            if (now - lastCacheCleanup > CACHE_CLEANUP_MS) cleanupTextCache(now)

            if (textCache.containsKey(key)) {
                textCache[key] = now
                return false
            }

            if (lastText.isNotEmpty()) {
                val sim = TextHeuristics.similarity(key, lastText)
                if (sim > SIM_SIMILAR) {
                    if (key.length > lastText.length) {
                        textCache[key] = now
                        lastText = key
                    }
                    return false
                }
            }

            for (cached in textCache.keys) {
                if (cached.contains(key) || key.contains(cached)) {
                    textCache[cached] = now
                    return false
                }
            }

            textCache[key] = now
            lastText = key
            return true
        }
    }

    private fun cleanupTextCache(now: Long) {
        val expired = textCache.keys.filter { (now - (textCache[it] ?: 0L)) > CACHE_TTL_MS }
        for (k in expired) textCache.remove(k)
        lastCacheCleanup = now
        if (expired.isNotEmpty() && debugLogging) {
            Log.d(TAG, "[OCR-LOG] кэш очищен: -${expired.size}, осталось ${textCache.size}")
        }
    }

    private fun publish() {
        _status.value = ScannerStatus(
            running = running,
            paused = paused,
            intervalMs = intervalMs,
            detectChanges = detectChanges,
            regions = regions.count { it.enabled },
            scans = scans,
            skipped = skipped,
            lastText = lastText,
            lastDurationMs = lastDurationMs,
            lastError = lastError,
        )
    }

    companion object {
        private const val TAG = "ScreenOCR"
        private const val DEFAULT_INTERVAL_MS = 700
        private const val MIN_INTERVAL_MS = 120
        private const val SIG_SIZE = 64
        private const val CACHE_TTL_MS = 1000L
        private const val CACHE_CLEANUP_MS = 5000L
        private const val SIM_SIMILAR = 0.85f
    }
}

package com.screenocr.tts.capture

import android.app.Activity
import android.app.Notification
import android.app.NotificationChannel
import android.app.NotificationManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.content.pm.ServiceInfo
import android.media.projection.MediaProjection
import android.media.projection.MediaProjectionManager
import android.os.Build
import android.os.IBinder
import android.util.Log
import androidx.core.app.NotificationCompat
import androidx.core.app.ServiceCompat
import androidx.core.content.IntentCompat
import androidx.lifecycle.LifecycleService
import androidx.lifecycle.lifecycleScope
import com.screenocr.tts.MainActivity
import com.screenocr.tts.R
import com.screenocr.tts.core.OcrResult
import com.screenocr.tts.core.Region
import com.screenocr.tts.live.LiveScanner
import com.screenocr.tts.ocr.OcrEngine
import com.screenocr.tts.ocr.TfliteOcrEngine
import com.screenocr.tts.settings.Settings
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.cancel
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.launch

/** Состояние сервиса для UI: MainActivity/Compose собирает его одним flow. */
data class CaptureSnapshot(
    val state: ServiceState = ServiceState.IDLE,
    val scanning: Boolean = false,
    val regions: List<Region> = emptyList(),
    val lastText: String = "",
    val lastConfidence: Float = 0f,
    val lastDurationMs: Long = 0,
    val error: String? = null,
)

enum class ServiceState { IDLE, STARTING, CAPTURING, ERROR }

/**
 * Foreground-сервис захвата экрана - порт точки входа десктопной main.py.
 *
 * Android 14+ (API 34): startForeground обязан быть вызван с типом
 * FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION в течение 5 секунд, причём ДО
 * вызова getMediaProjection() - иначе система бросает исключение. Тип
 * объявлен в манифесте: android:foregroundServiceType="mediaProjection".
 */
class CaptureService : LifecycleService() {

    private val serviceScope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    private var projection: MediaProjection? = null
    private var capture: ScreenCapture? = null
    private var scanner: ScreenScanner? = null
    private var live: LiveScanner? = null
    private var settingsJob: Job? = null
    private var foreground = false
    private var scanning = false

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        super.onStartCommand(intent, flags, startId)
        // Всегда первым делом: иначе на Android 14 сервис убьют по таймауту 5 c.
        ensureForeground()

        when (intent?.action) {
            ACTION_START -> handleStart(intent)
            ACTION_STOP -> {
                Log.i(TAG, "Остановка по команде")
                shutdown()
                stopSelf()
            }

            ACTION_TOGGLE_SCAN -> toggleScanning()
            ACTION_SCAN_ONCE -> runOnce()
            ACTION_OPEN_SETTINGS -> openSettings()
            ACTION_RELOAD_REGIONS -> reloadRegions()
            else -> if (capture == null) {
                Log.w(TAG, "Пустой Intent, сервис без захвата - останавливаюсь")
                stopSelf()
            }
        }
        // Не START_STICKY: токен MediaProjection одноразовый, после убийства
        // процесса систему всё равно придётся запрашивать заново.
        return START_NOT_STICKY
    }

    override fun onTaskRemoved(rootIntent: Intent?) {
        // Порт "свернуть в трей": по умолчанию завершаемся честно, а при
        // General.START_MINIMIZED продолжаем захват в фоне.
        if (Settings.get(this).get(Settings.General.START_MINIMIZED, false)) {
            Log.i(TAG, "Задача убрана, продолжаю в фоне (START_MINIMIZED)")
            updateNotification()
            super.onTaskRemoved(rootIntent)
            return
        }
        Log.i(TAG, "Задача убрана, останавливаю захват")
        shutdown()
        stopSelf()
        super.onTaskRemoved(rootIntent)
    }

    override fun onDestroy() {
        shutdown()
        serviceScope.cancel()
        super.onDestroy()
    }

    override fun onBind(intent: Intent): IBinder? = super.onBind(intent)

    // ── запуск захвата ─────────────────────────────────────────

    private fun handleStart(intent: Intent) {
        val resultCode = intent.getIntExtra(EXTRA_RESULT_CODE, Activity.RESULT_CANCELED)
        val data: Intent? = IntentCompat.getParcelableExtra(intent, EXTRA_RESULT_DATA, Intent::class.java)
        if (resultCode != Activity.RESULT_OK || data == null) {
            shutdown()
            fail("Не получено согласие на захват экрана")
            stopSelf()
            return
        }

        // Повторный ACTION_START без остановки - освобождаем прошлую проекцию.
        shutdown(keepForeground = true)

        val manager = getSystemService(MediaProjectionManager::class.java)
        val projectionObj = runCatching { manager?.getMediaProjection(resultCode, data) }.getOrNull()
        if (projectionObj == null) {
            fail("MediaProjection не создан")
            stopSelf()
            return
        }
        projection = projectionObj
        publish(state = ServiceState.STARTING)

        val cap = ScreenCapture(applicationContext)
        cap.onProjectionStopped = { onProjectionRevoked() }
        cap.start(projectionObj)
        if (!cap.isRunning) {
            shutdown()
            fail("Захват экрана не запустился")
            stopSelf()
            return
        }
        capture = cap

        val st = Settings.get(this)
        val scan = ScreenScanner(cap, st, serviceScope, buildEngine(st))
        scan.onResult = { result -> publishResult(result) }
        scan.onTextDetected = { text -> live?.onNewText(text) }
        scan.onScanTiming = { timing ->
            if (!timing.skipped) {
                publish(
                    state = currentState(),
                    lastText = timing.text,
                    lastConfidence = timing.confidence,
                    lastDurationMs = timing.durationMs,
                )
            }
        }
        scanner = scan
        screenScannerRef = scan

        val liveScanner = LiveScanner(st, serviceScope)
        live = liveScanner
        liveScannerRef = liveScanner

        scan.setRegions(RegionStore.load(this))
        startScanning()
        watchSettings(st)
        publish(state = ServiceState.CAPTURING)
        updateNotification()
        Log.i(TAG, "Захват запущен: ${cap.screenWidth}x${cap.screenHeight}")
    }

    /**
     * Движок можно подменить через [setEngineFactory] (например, на OcrWrapper
     * с fallback-цепочкой). По умолчанию - локальная TFLite-модель.
     */
    private fun buildEngine(st: Settings): OcrEngine {
        engineFactory?.let { factory ->
            runCatching { factory(this, st) }.getOrNull()?.let { return it }
        }
        val limit = st.get(Settings.Ocr.DET_LIMIT_SIDE, 736)
        val engine = TfliteOcrEngine(applicationContext, limit)
        Log.i(TAG, "OCR-движок: ${engine.id} (предел стороны $limit)")
        return engine
    }

    /** Регионы живут в Settings, поэтому оверлей и сервис видят одно и то же. */
    private fun watchSettings(st: Settings) {
        settingsJob?.cancel()
        settingsJob = lifecycleScope.launch {
            st.changes.collect {
                val sc = scanner ?: return@collect
                val regions = RegionStore.load(this@CaptureService)
                sc.setRegions(regions)
                publish(state = currentState(), regions = sc.regions())
            }
        }
    }

    // ── управление сканированием ───────────────────────────────

    fun startScanning() {
        val sc = scanner ?: return
        if (sc.status.value.running) return
        scanning = true
        sc.start()
        live?.let { if (it.pausedState) it.setPaused(false) }
        publish(state = currentState())
        updateNotification()
    }

    fun stopScanning() {
        scanning = false
        scanner?.stop()
        publish(state = currentState())
        updateNotification()
    }

    private fun toggleScanning() {
        if (scanning) {
            stopScanning()
            Log.i(TAG, "Сканирование остановлено")
        } else {
            startScanning()
            Log.i(TAG, "Сканирование запущено")
        }
    }

    private fun runOnce() {
        val sc = scanner ?: return
        if (scanning) {
            // Цикл уже идёт - он и так захватит свежий кадр.
            Log.d(TAG, "Сканирование уже идёт, разовый проход не нужен")
            return
        }
        serviceScope.launch { sc.scanOnce() }
    }

    private fun reloadRegions() {
        val sc = scanner ?: return
        sc.setRegions(RegionStore.load(this))
        publish(state = currentState(), regions = sc.regions())
    }

    private fun openSettings() {
        val intent = Intent(this, MainActivity::class.java).apply {
            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
            putExtra(EXTRA_OPEN_SETTINGS, true)
        }
        runCatching { startActivity(intent) }
            .onFailure { Log.w(TAG, "Не удалось открыть настройки: ${it.message}") }
    }

    private fun onProjectionRevoked() {
        Log.w(TAG, "Доступ к экрану отозван")
        shutdown()
        publish(state = ServiceState.ERROR, error = "Доступ к экрану отозван")
        stopSelf()
    }

    private fun shutdown(keepForeground: Boolean = false) {
        settingsJob?.cancel()
        settingsJob = null
        scanner?.stop()
        scanner = null
        screenScannerRef = null
        live?.stop()
        live = null
        liveScannerRef = null
        capture?.stop()
        capture = null
        projection = null
        scanning = false
        if (foreground && !keepForeground) {
            ServiceCompat.stopForeground(this, ServiceCompat.STOP_FOREGROUND_REMOVE)
            foreground = false
        }
        // Ошибку не затираем - её должен увидеть UI даже после stopSelf.
        if (_snapshot.value.state != ServiceState.ERROR) {
            publish(state = ServiceState.IDLE)
        } else {
            publish(state = ServiceState.ERROR, error = _snapshot.value.error)
        }
    }

    private fun fail(message: String) {
        Log.e(TAG, message)
        publish(state = ServiceState.ERROR, error = message)
    }

    private fun currentState(): ServiceState =
        if (capture == null) ServiceState.IDLE else ServiceState.CAPTURING

    // ── состояние для UI ───────────────────────────────────────

    private fun publish(
        state: ServiceState = currentState(),
        regions: List<Region>? = null,
        lastText: String? = null,
        lastConfidence: Float? = null,
        lastDurationMs: Long? = null,
        error: String? = null,
    ) {
        val current = _snapshot.value
        _snapshot.value = CaptureSnapshot(
            state = state,
            scanning = scanning,
            regions = regions ?: scanner?.regions() ?: current.regions,
            lastText = lastText ?: current.lastText,
            lastConfidence = lastConfidence ?: current.lastConfidence,
            lastDurationMs = lastDurationMs ?: current.lastDurationMs,
            error = error,
        )
    }

    private fun publishResult(result: OcrResult) {
        publish(
            state = currentState(),
            regions = scanner?.regions(),
            lastText = result.text,
            lastConfidence = result.confidence,
            lastDurationMs = result.elapsedMs,
        )
    }

    // ── уведомление ────────────────────────────────────────────

    private fun ensureForeground() {
        if (foreground) return
        createChannel()
        ServiceCompat.startForeground(
            this,
            NOTIFICATION_ID,
            buildNotification(),
            ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION,
        )
        foreground = true
    }

    private fun createChannel() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val manager = getSystemService(NotificationManager::class.java) ?: return
        if (manager.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            "Захват экрана",
            NotificationManager.IMPORTANCE_LOW,
        ).apply {
            description = "OCR и озвучка с экрана"
            setShowBadge(false)
        }
        manager.createNotificationChannel(channel)
    }

    private fun buildNotification(): Notification {
        val content = PendingIntent.getActivity(
            this,
            0,
            Intent(this, MainActivity::class.java).apply {
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
            },
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
        )
        val regionCount = scanner?.regions()?.size ?: 0
        return NotificationCompat.Builder(this, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_stat_capture)
            .setContentTitle(if (scanning) "OCR: сканирование идёт" else "OCR: на паузе")
            .setContentText(
                if (scanning) {
                    "Интервал ${scanner?.intervalMs ?: 0} мс · регионов: $regionCount"
                } else {
                    "Нажмите, чтобы открыть настройки"
                },
            )
            .setContentIntent(content)
            .setOngoing(scanning)
            .setOnlyAlertOnce(true)
            .setSilent(true)
            .setShowWhen(false)
            .setCategory(NotificationCompat.CATEGORY_SERVICE)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .addAction(R.drawable.ic_stat_capture, if (scanning) "Стоп" else "Старт", servicePendingIntent(ACTION_TOGGLE_SCAN, 1))
            .addAction(R.drawable.ic_stat_capture, "Настройки", servicePendingIntent(ACTION_OPEN_SETTINGS, 2))
            .addAction(R.drawable.ic_stat_capture, "Выход", servicePendingIntent(ACTION_STOP, 3))
            .build()
    }

    private fun servicePendingIntent(action: String, requestCode: Int): PendingIntent =
        PendingIntent.getService(
            this,
            requestCode,
            Intent(this, CaptureService::class.java).setAction(action),
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
        )

    private fun updateNotification() {
        if (!foreground) return
        runCatching {
            getSystemService(NotificationManager::class.java)
                ?.notify(NOTIFICATION_ID, buildNotification())
        }
    }

    companion object {
        private const val TAG = "ScreenOCR"
        const val ACTION_START = "com.screenocr.tts.action.START_CAPTURE"
        const val ACTION_STOP = "com.screenocr.tts.action.STOP_CAPTURE"
        const val ACTION_TOGGLE_SCAN = "com.screenocr.tts.action.TOGGLE_SCAN"
        const val ACTION_SCAN_ONCE = "com.screenocr.tts.action.SCAN_ONCE"
        const val ACTION_OPEN_SETTINGS = "com.screenocr.tts.action.OPEN_SETTINGS"
        const val ACTION_RELOAD_REGIONS = "com.screenocr.tts.action.RELOAD_REGIONS"
        const val EXTRA_RESULT_CODE = "extra_result_code"
        const val EXTRA_RESULT_DATA = "extra_result_data"
        const val EXTRA_OPEN_SETTINGS = "open_settings"
        const val CHANNEL_ID = "screenocr_capture"
        const val NOTIFICATION_ID = 0x50C7

        private val _snapshot = MutableStateFlow(CaptureSnapshot())

        /** Общее состояние: UI подписывается и рисует рамки/статус. */
        val snapshot: StateFlow<CaptureSnapshot> = _snapshot.asStateFlow()

        @Volatile
        private var engineFactory: ((Context, Settings) -> OcrEngine?)? = null

        /** Живой сканер и очередь озвучки - чтобы UI подключил TTS. */
        @Volatile
        var liveScannerRef: LiveScanner? = null
            private set

        @Volatile
        var screenScannerRef: ScreenScanner? = null
            private set

        /** Позволяет подменить OCR-движок, не трогая сервис. */
        fun setEngineFactory(factory: ((Context, Settings) -> OcrEngine?)?) {
            engineFactory = factory
        }

        /** Старт захвата: вызывать из Activity с результатом системного диалога. */
        fun startCapture(context: Context, resultCode: Int, data: Intent) {
            val intent = Intent(context, CaptureService::class.java).apply {
                action = ACTION_START
                putExtra(EXTRA_RESULT_CODE, resultCode)
                putExtra(EXTRA_RESULT_DATA, data)
            }
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.startForegroundService(intent)
            } else {
                context.startService(intent)
            }
        }

        fun stop(context: Context) = send(context, ACTION_STOP)

        fun toggleScan(context: Context) = send(context, ACTION_TOGGLE_SCAN)

        fun scanOnce(context: Context) = send(context, ACTION_SCAN_ONCE)

        fun reloadRegions(context: Context) = send(context, ACTION_RELOAD_REGIONS)

        private fun send(context: Context, action: String) {
            val intent = Intent(context, CaptureService::class.java).setAction(action)
            runCatching { context.startService(intent) }
                .onFailure { Log.w(TAG, "Не удалось отправить $action: ${it.message}") }
        }
    }
}

package com.screenocr.tts.tts

import android.content.Context
import android.media.AudioAttributes
import android.media.AudioFormat
import android.media.AudioTrack
import android.media.MediaPlayer
