package com.screenocr.tts.capture

import android.content.Context
import android.os.Handler
import android.os.Looper
import android.util.Log
import com.screenocr.tts.core.Region
import com.screenocr.tts.settings.Settings
import org.json.JSONArray
import org.json.JSONObject

/**
 * Хранилище регионов захвата.
 *
 * На десктопе регионы лежали в config.json и разделялись между RegionOverlay
 * (отрисовка/редактирование) и LiveScanner (захват кадра). Здесь то же самое,
 * но через Settings: список сериализуется в один JSON-ключ, поэтому любая
 * запись проходит через Settings.set и поднимает Settings.changes - сервис
 * подписан на него и перечитывает регионы без ручной синхронизации.
 */
object RegionStore {

    private const val TAG = "ScreenOCR"
    const val KEY = "capture.regions"
    private const val SAVE_DEBOUNCE_MS = 400L

    private val handler = Handler(Looper.getMainLooper())
    private var pending: List<Region>? = null
    private var pendingContext: Context? = null

    private val saveRunnable = Runnable {
        val ctx = synchronized(this) { pendingContext }
        val list = synchronized(this) { pending }
        if (ctx != null && list != null) save(ctx, list)
    }

    fun load(context: Context): List<Region> {
        val raw = runCatching { Settings.get(context).get(KEY, "") }.getOrDefault("")
        if (raw.isBlank()) return emptyList()
        return runCatching { parse(raw) }
            .getOrElse {
                Log.w(TAG, "Повреждён список регионов, сбрасываю: ${it.message}")
                save(context, emptyList())
                emptyList()
            }
    }

    fun save(context: Context, regions: List<Region>) {
        runCatching { Settings.get(context).set(KEY, serialize(regions)) }
            .onFailure { Log.e(TAG, "Не удалось сохранить регионы", it) }
    }

    /**
     * Отложенное сохранение - при перетаскивании рамки события приходят
     * каждый кадр, писать в prefs на каждом событии нельзя
     * (порт _save_timer в region_overlay.py / text_overlay.py).
     */
    fun scheduleSave(context: Context, regions: List<Region>) {
        synchronized(this) {
            pendingContext = context.applicationContext
            pending = regions.toList()
        }
        handler.removeCallbacks(saveRunnable)
        handler.postDelayed(saveRunnable, SAVE_DEBOUNCE_MS)
    }

    fun add(context: Context, region: Region) {
        save(context, load(context) + region)
    }

    fun removeAt(context: Context, index: Int) {
        val list = load(context).toMutableList()
        if (index in list.indices) {
            list.removeAt(index)
            save(context, list)
        }
    }

    fun clear(context: Context) = save(context, emptyList())

    private fun serialize(regions: List<Region>): String {
        val array = JSONArray()
        for (r in regions) {
            array.put(
                JSONObject()
                    .put("name", r.name)
                    .put("x", r.x)
                    .put("y", r.y)
                    .put("width", r.width)
                    .put("height", r.height)
                    .put("color", r.color)
                    .put("shape", r.shape)
                    .put("enabled", r.enabled),
            )
        }
        return array.toString()
    }

    private fun parse(raw: String): List<Region> {
        val array = JSONArray(raw)
        val out = ArrayList<Region>(array.length())
        for (i in 0 until array.length()) {
            val o = array.optJSONObject(i) ?: continue
            val width = o.optInt("width", 0)
            val height = o.optInt("height", 0)
            if (width <= 0 || height <= 0) continue
            out.add(
                Region(
                    name = o.optString("name", "R${i + 1}"),
                    x = o.optInt("x", 0),
                    y = o.optInt("y", 0),
                    width = width,
                    height = height,
                    color = o.optString("color", "#4caf50"),
                    shape = o.optString("shape", "rect"),
                    enabled = o.optBoolean("enabled", true),
                ),
            )
        }
        return out
    }
}

