    // ── состояние ──────────────────────────────────────────────

    private fun loadState() {
        alphaValue = settings.get(Settings.Overlay.OPACITY, 0.85f).coerceIn(0.1f, 1f)
        fontSize = settings.get(Settings.Overlay.FONT_SIZE, DEFAULT_FONT).coerceIn(MIN_FONT, MAX_FONT)
        textColor = settings.get("$PREFIX$id.text_color", DEFAULT_TEXT)
        bgColor = settings.get("$PREFIX$id.bg_color", DEFAULT_BG)
        enabled = settings.get(Settings.Overlay.ENABLED, true)
        wrap = settings.get("$PREFIX$id.wrap", true)
        collapsed = settings.get("$PREFIX$id.collapsed", false)
    }

    private fun applyState() {
        body?.setHorizontallyScrolling(!wrap)
        body?.setTextSize(TypedValue.COMPLEX_UNIT_SP, fontSize.toFloat())
        applyColors()
        applyCollapsed()
        applyTitleStyle()
    }

    /** Отложенное сохранение позиции при перетаскивании (порт _save_timer). */
    private fun persist() {
        main.removeCallbacks(saveTicker)
        main.postDelayed(saveTicker, SAVE_DEBOUNCE_MS)
    }

    private fun persistNow() {
        main.removeCallbacks(saveTicker)
        if (attached) {
            settings.set("$PREFIX$id.x", posX)
            settings.set("$PREFIX$id.y", posY)
        }
        settings.set("$PREFIX$id.collapsed", collapsed)
        settings.set(Settings.Overlay.FONT_SIZE, fontSize)
    }

    // ── helpers ────────────────────────────────────────────────

