import java.util.Calendar
import java.util.Locale

private const val TAG = "ScreenOCR"
private const val MAX_HISTORY = 40
private const val CAPTURE_LAUNCHER_KEY = "screenocr_capture_request"

/** Одна запись в списке последних распознаваний (порт ocr_logs_simple). */
private data class HistoryEntry(
    val timeMs: Long,
    val text: String,
    val confidence: Float,
    val translation: String,
)

/**
 * Главный экран — порт панели gui_compact.py: одна прокручиваемая колонка
 * секций (статус, управление, OCR, регионы, результат, история).
 *
 * @param context Activity приложения: от неё берутся системные диалоги
 *   захвата экрана, буфер обмена и хранилище регионов.
 * @param settings живой [Settings]: все значения читаются оттуда и пишутся туда же,
 *   сервис подписан на `Settings.changes` и подхватывает их без перезапуска.
 * @param tts движок озвучки (тот же экземпляр, что у сервиса).
 * @param translator переводчик для блока «Результат» и автоперевода.
 * @param regionOverlay оверлей рамок регионов; если null — управление
 *   редактированием оверлея не показывается.
 * @param textOverlay HUD с распознанным текстом; если null — переключатель
 *   показа текста в оверлее не показывается.
 */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun MainScreen(
    settings: Settings,
    tts: TtsEngine,
    translator: Translator,
    modifier: Modifier = Modifier,
    context: Context = LocalContext.current,
    regionOverlay: RegionOverlay? = null,
    textOverlay: TextOverlay? = null,
    onOpenSettings: (() -> Unit)? = null,
) {
    val scope = rememberCoroutineScope()
    val snackbar = remember { SnackbarHostState() }

    val snapshot by CaptureService.snapshot.collectAsState()
    val settingsVersion by settings.changes.collectAsState()

    // Ссылка на живой сканер появляется только после старта захвата, поэтому
    // flow перечитывается при смене состояния сервиса.
    val statusFlow = remember(snapshot.state) {
        CaptureService.screenScannerRef?.status ?: MutableStateFlow(ScannerStatus())
    }
    val status by statusFlow.collectAsState()

    // ── значения настроек ────────────────────────────────────────────
    val engineId = remember(settingsVersion) { settings.get(Settings.Ocr.ENGINE, OcrEngines.ID_TFLITE) }
    val intervalMs = remember(settingsVersion) { settings.get(Settings.Ocr.SCAN_INTERVAL_MS, 700) }
    val confidencePct = remember(settingsVersion) { settings.get(Settings.Ocr.CONFIDENCE, 40) }
    val changeThreshold = remember(settingsVersion) { settings.get(Settings.Ocr.CHANGE_THRESHOLD, 0.05f) }
    val detectChanges = remember(settingsVersion) { settings.get(Settings.Ocr.DETECT_CHANGES, true) }
    val autoTranslate = remember(settingsVersion) { settings.get(Settings.Ocr.AUTO_TRANSLATE, true) }
    val multiPass = remember(settingsVersion) { settings.get(Settings.Ocr.MULTI_PASS, false) }
    val translateOn = remember(settingsVersion) { settings.get(Settings.Translate.ENABLED, true) }
    val srcLang = remember(settingsVersion) { settings.get(Settings.Translate.SRC_LANG, "auto") }
    val dstLang = remember(settingsVersion) { settings.get(Settings.Translate.DST_LANG, "ru") }
    val showOverlayText = remember(settingsVersion) { settings.get(Settings.Overlay.SHOW_TEXT, true) }
    val regions = remember(settingsVersion) { RegionStore.load(context) }

    // ── локальное состояние экрана ───────────────────────────────────
    var recognized by remember { mutableStateOf("") }
    var translated by remember { mutableStateOf("") }
    var translating by remember { mutableStateOf(false) }
    var message by remember { mutableStateOf<String?>(null) }
    var role by remember { mutableStateOf(TtsEngine.Role.NARRATOR) }
    var editMode by remember { mutableStateOf(false) }
    var overlayAttached by remember { mutableStateOf(regionOverlay?.isAttached == true) }
    val history = remember { mutableStateListOf<HistoryEntry>() }

    val permissionTick = rememberPermissionTick()
    val canDrawOverlay = remember(permissionTick) { OverlayPermission.canDrawOverlays(context) }

    val activity = remember(context) { context.findActivity() }
    val captureLauncher = remember(activity) {
        activity?.activityResultRegistry?.register(
            CAPTURE_LAUNCHER_KEY,
            ActivityResultContracts.StartActivityForResult(),
        ) { result ->
            val data = result.data
            if (result.resultCode == Activity.RESULT_OK && data != null) {
                CaptureService.startCapture(context, result.resultCode, data)
                message = "Запрос захвата экрана отправлен"
            } else {
                message = "Доступ к экрану не выдан"
                Log.w(TAG, "Пользователь отказал в захвате экрана")
            }
        }
    }

    // Смена OCR-движка на лету: движок сканера заменяется, старый закрывается
    // с задержкой, чтобы не оборвать уже начатое распознавание кадра.
    val wrapper = remember { mutableStateOf<OcrWrapper?>(null) }

    fun applyEngine(id: String) {
        if (id == engineId) return
        settings.set(Settings.Ocr.ENGINE, id)
        val created = runCatching { OcrWrapper(context, settings, id) }.getOrNull()
        if (created == null) {
            message = "Не удалось создать движок ${OcrEngines.displayName(id)}"
            return
        }
        val previous = wrapper.value
        wrapper.value = created
        CaptureService.screenScannerRef?.setEngine(created)
        scope.launch {
            delay(ENGINE_SWAP_GRACE_MS)
            runCatching { previous?.close() }
        }
    }

    // Новый кадр → перевод → результат + оверлей + история.
    LaunchedEffect(snapshot.lastText, autoTranslate, translateOn, srcLang, dstLang) {
        val raw = snapshot.lastText.trim()
        if (raw.isEmpty()) return@LaunchedEffect
        recognized = raw
        var value = ""
        if (autoTranslate && translateOn) {
            translating = true
            value = runCatching { translator.translate(raw, srcLang, dstLang) }
                .getOrElse {
                    Log.w(TAG, "Перевод не удался: ${it.message}")
                    ""
                }
            // Провайдеры отдают отказ маркером в квадратных скобках — это не перевод.
            if (value.startsWith("[") && value.endsWith("]")) value = ""
            translating = false
        }
        translated = value
        history.add(0, HistoryEntry(System.currentTimeMillis(), raw, snapshot.lastConfidence, value))
        while (history.size > MAX_HISTORY) history.removeAt(history.size - 1)
    }

    // Оверлей текста: HUD получает ровно то, что показано в блоке «Результат».
    LaunchedEffect(recognized, translated, showOverlayText) {
        if (textOverlay == null) return@LaunchedEffect
        if (showOverlayText) {
            textOverlay.setResult(recognized, translated.ifBlank { null })
            textOverlay.show()
        } else {
            textOverlay.hide()
        }
    }

    DisposableEffect(regionOverlay) {
        regionOverlay?.setRegions(regions)
        regionOverlay?.setActiveRole(roleKey(role))
        onDispose { }
    }

    LaunchedEffect(role) {
        tts.setRole(role)
        regionOverlay?.setActiveRole(roleKey(role))
    }

    // Рамки регионов живут в оверлее: держим его список в синхроне с хранилищем.
    LaunchedEffect(regions, editMode) {
        regionOverlay?.setRegions(regions)
        regionOverlay?.setEditMode(editMode)
    }

    val openSettings = onOpenSettings ?: {
        snackbar.showMessage("Экран настроек открывается из MainActivity")
    }

    Scaffold(
        modifier = modifier.fillMaxSize(),
        containerColor = OcrColors.Background,
        snackbarHost = { SnackbarHost(snackbar) },
        topBar = {
            TopAppBar(
                title = {
                    Column {
                        Text(
                            "ScreenOCR · TTS",
                            style = MaterialTheme.typography.titleMedium,
                            fontWeight = FontWeight.Bold,
                        )
                        Text(
                            "OCR ${OcrEngines.displayName(engineId)} · ${status.intervalMs} мс",
                            style = MaterialTheme.typography.labelSmall,
                            color = OcrColors.TextSecondary,
                        )
                    }
                },
                navigationIcon = {
                    IconButton(onClick = { CaptureService.stop(context) }) {
                        Icon(
                            Icons.Filled.Stop,
                            contentDescription = "Остановить захват",
                            tint = OcrColors.Danger,
                        )
                    }
                },
                actions = {
                    IconButton(onClick = { CaptureService.toggleScan(context) }) {
                        Icon(
                            if (snapshot.scanning) Icons.Filled.Stop else Icons.Filled.PlayArrow,
                            contentDescription = "Старт/стоп сканирования",
                            tint = if (snapshot.scanning) OcrColors.Danger else OcrColors.Success,
                        )
                    }
                    IconButton(onClick = {
                        openSettings()
                    }) {
                        Icon(Icons.Filled.Settings, contentDescription = "Настройки")
                    }
                },
                colors = TopAppBarDefaults.topAppBarColors(
                    containerColor = OcrColors.Panel,
                    titleContentColor = OcrColors.TextPrimary,
                    actionIconContentColor = OcrColors.Accent,
                    navigationIconContentColor = OcrColors.TextSecondary,
                ),
            )
        },
        bottomBar = {
            TtsControlBar(
                tts = tts,
                role = role,
                onRoleChange = { role = it },
                modifier = Modifier.navigationBarsPadding(),
            )
        },
    ) { padding ->
        LazyColumn(
            modifier = Modifier
                .fillMaxSize()
                .padding(padding),
            contentPadding = PaddingValues(12.dp),
            verticalArrangement = Arrangement.spacedBy(10.dp),
        ) {
            item("status") {
                StatusSection(
                    snapshotState = snapshot.state,
                    scanning = snapshot.scanning,
                    status = status,
                    message = message,
                    onDismissMessage = { message = null },
                )
            }

            item("control") {
                ControlSection(
                    scanning = snapshot.scanning,
                    hasCapture = snapshot.state != com.screenocr.tts.capture.ServiceState.IDLE,
                    onStartCapture = {
                        val launcher = captureLauncher
                        val intent = MediaProjectionPermission.createScreenCaptureIntent(context)
                        if (launcher == null || intent == null) {
                            message = "Системный диалог захвата недоступен"
                        } else {
                            launcher.launch(intent)
                        }
                    },
                    onToggleScan = { CaptureService.toggleScan(context) },
                    onScanOnce = {
                        CaptureService.scanOnce(context)
                        message = "Разовый проход сканирования запущен"
                    },
                    onSpeak = {
                        val target = translated.ifBlank { recognized }
                        if (target.isBlank()) {
                            message = "Нет текста для озвучки"
                        } else {
                            tts.stop()
                            scope.launch {
                                val ok = runCatching { tts.speak(target, role) }.getOrDefault(false)
                                message = if (ok) "Озвучка завершена" else "Озвучка не удалась"
                            }
                        }
                    },
                    onStopSpeak = {
                        tts.stop()
                        message = "Озвучка остановлена"
                    },
                )
            }

            item("ocr") {
                OcrSection(
                    engineId = engineId,
                    onEngineChange = ::applyEngine,
                    intervalMs = intervalMs,
                    onIntervalChange = { value ->
                        val ms = value.toInt()
                        settings.set(Settings.Ocr.SCAN_INTERVAL_MS, ms)
                        CaptureService.screenScannerRef?.setInterval(ms)
                    },
                    confidencePct = confidencePct,
                    onConfidenceChange = { value ->
                        settings.set(Settings.Ocr.CONFIDENCE, value.toInt().coerceIn(0, 100))
                    },
                    changeThreshold = changeThreshold,
                    onChangeThresholdChange = { value ->
                        val v = (value * 1000f).toInt() / 1000f
                        settings.set(Settings.Ocr.CHANGE_THRESHOLD, v)
                        CaptureService.screenScannerRef?.setChangeThreshold(v)
                    },
                    detectChanges = detectChanges,
                    onDetectChangesChange = { value ->
                        settings.set(Settings.Ocr.DETECT_CHANGES, value)
                        CaptureService.screenScannerRef?.setDetectChanges(value)
                    },
                    autoTranslate = autoTranslate,
                    onAutoTranslateChange = { settings.set(Settings.Ocr.AUTO_TRANSLATE, it) },
                    multiPass = multiPass,
                    onMultiPassChange = { settings.set(Settings.Ocr.MULTI_PASS, it) },
                    liveMode = CaptureService.liveScannerRef?.mode ?: ScanMode.REALTIME_CLEAR,
                    onLiveModeChange = { mode ->
                        CaptureService.liveScannerRef?.setMode(mode)
                        message = "Режим озвучки: ${mode.label()}"
                    },
                )
            }

            item("regions") {
                RegionsSection(
                    regions = regions,
                    canDrawOverlay = canDrawOverlay,
                    overlayAttached = overlayAttached,
                    editMode = editMode,
                    onToggleEditMode = {
                        editMode = it
                        regionOverlay?.setEditMode(it)
                    },
                    onToggleOverlay = {
                        val overlay = regionOverlay
                        if (overlay == null) {
                            message = "Оверлей не создан"
                        } else if (!canDrawOverlay) {
                            runCatching { context.startActivity(OverlayPermission.settingsIntent(context)) }
                                .onFailure { message = "Не удалось открыть настройки оверлея" }
                        } else if (overlayAttached) {
                            overlay.detach()
                            overlayAttached = false
                        } else {
                            overlay.attach()
                            overlayAttached = overlay.isAttached
                        }
                    },
                    onAddCenter = {
                        val created = centerRegion(context, regions.size)
                        RegionStore.add(context, created)
                        regionOverlay?.setRegions(RegionStore.load(context))
                        message = "Регион ${created.name} добавлен"
                    },
                    onDelete = { index ->
                        RegionStore.removeAt(context, index)
                        regionOverlay?.setRegions(RegionStore.load(context))
                    },
                    onToggleRegion = { index, enabled ->
                        val updated = regions.mapIndexed { i, r ->
                            if (i == index) r.copy(enabled = enabled) else r
                        }
                        RegionStore.save(context, updated)
                        regionOverlay?.setRegions(updated)
                    },
                    onClear = {
                        RegionStore.clear(context)
                        regionOverlay?.setRegions(emptyList())
                        message = "Список регионов очищен"
                    },
                    onReload = {
                        CaptureService.reloadRegions(context)
                        message = "Регионы переданы сканеру"
                    },
                )
            }

            item("result") {
                ResultSection(
                    recognized = recognized,
                    translated = translated,
                    translating = translating,
                    autoTranslate = autoTranslate,
                    showOverlayText = showOverlayText,
                    hasTextOverlay = textOverlay != null,
                    onRecognizedChange = { recognized = it },
                    onTranslatedChange = { translated = it },
                    onShowOverlayTextChange = { settings.set(Settings.Overlay.SHOW_TEXT, it) },
                    onCopy = {
                        val text = translated.ifBlank { recognized }
                        copyToClipboard(context, "ScreenOCR", text)
                        message = if (text.isBlank()) "Нечего копировать" else "Скопировано"
                    },
                    onSpeak = {
                        val target = translated.ifBlank { recognized }
                        if (target.isBlank()) {
                            message = "Нет текста для озвучки"
                        } else {
                            tts.stop()
                            scope.launch { runCatching { tts.speak(target, role) } }
                        }
                    },
                    onTranslate = {
                        val text = recognized.trim()
                        if (text.isBlank()) {
                            message = "Нет текста для перевода"
                        } else {
                            scope.launch {
                                translating = true
                                val value = runCatching {
                                    translator.translate(text, srcLang, dstLang)
                                }.getOrElse {
                                    Log.w(TAG, "Перевод не удался: ${it.message}")
                                    ""
                                }
                                translating = false
                                translated = value
                                message = if (value.isBlank()) "Перевод не удался" else "Перевод обновлён"
                            }
                        }
                    },
                )
            }

            item("history") {
                HistorySection(
                    entries = history,
                    onClear = {
                        history.clear()
                        message = "История очищена"
                    },
                    onUse = { entry ->
                        recognized = entry.text
                        translated = entry.translation
                    },
                    onSpeak = { entry ->
                        val target = entry.translation.ifBlank { entry.text }
                        if (target.isBlank()) {
                            message = "Запись пустая"
                        } else {
                            tts.stop()
                            scope.launch { runCatching { tts.speak(target, role) } }
                        }
                    },
                )
            }
        }
    }
}

