@Composable
private fun StatusSection(
    snapshotState: com.screenocr.tts.capture.ServiceState,
    scanning: Boolean,
    status: ScannerStatus,
    message: String?,
    onDismissMessage: () -> Unit,
) {
    SectionCard(title = "Статус", icon = Icons.Filled.Bolt) {
        Row(verticalAlignment = Alignment.CenterVertically) {
            StatusDot(
                color = when {
                    snapshotState == com.screenocr.tts.capture.ServiceState.ERROR -> OcrColors.Danger
                    scanning -> OcrColors.Success
                    snapshotState == com.screenocr.tts.capture.ServiceState.CAPTURING -> OcrColors.Warning
                    else -> OcrColors.TextSecondary
                },
            )
            Spacer(Modifier.width(8.dp))
            Column(Modifier.weight(1f)) {
                Text(
                    when {
                        snapshotState == com.screenocr.tts.capture.ServiceState.ERROR -> "Ошибка захвата"
                        scanning -> "Сканирование идёт"
                        snapshotState == com.screenocr.tts.capture.ServiceState.STARTING -> "Запуск захвата…"
                        snapshotState == com.screenocr.tts.capture.ServiceState.CAPTURING -> "Захват активен, на паузе"
                        else -> "Захват выключен"
                    },
                    style = MaterialTheme.typography.titleSmall,
                    fontWeight = FontWeight.SemiBold,
                    color = OcrColors.TextPrimary,
                )
                Text(
                    "Проходов: ${status.scans} · пропущено: ${status.skipped} · " +
                        "регионов: ${status.regions}",
                    style = MaterialTheme.typography.labelSmall,
                    color = OcrColors.TextSecondary,
                )
            }
        }

        Spacer(Modifier.height(6.dp))
        HorizontalDivider(color = OcrColors.Border)
        Spacer(Modifier.height(6.dp))

        StatusLine("Уверенность", "${(status.lastText.length.let { 0 })}".let { "" })
        StatusLine("Интервал", "${status.intervalMs} мс")
        StatusLine("Детекция изменений", if (status.detectChanges) "вкл" else "выкл")

        val error = status.lastError
        if (error != null) {
            Spacer(Modifier.height(4.dp))
            Row(verticalAlignment = Alignment.CenterVertically) {
                Icon(Icons.Filled.Warning, null, tint = OcrColors.Danger, modifier = Modifier.size(16.dp))
                Spacer(Modifier.width(6.dp))
                Text(error, style = MaterialTheme.typography.bodySmall, color = OcrColors.Danger)
            }
        }

        val notice = message
        if (notice != null) {
            Spacer(Modifier.height(6.dp))
            Surface(
                color = OcrColors.PanelHighest,
                shape = RoundedCornerShape(8.dp),
                modifier = Modifier.fillMaxWidth(),
                onClick = onDismissMessage,
            ) {
                Text(
                    notice,
                    style = MaterialTheme.typography.bodySmall,
                    color = OcrColors.Accent,
                    modifier = Modifier.padding(horizontal = 10.dp, vertical = 6.dp),
                )
            }
        }
    }
}

