}

@Composable
private fun OcrSection(
    engineId: String,
    onEngineChange: (String) -> Unit,
    intervalMs: Int,
    onIntervalChange: (Float) -> Unit,
    confidencePct: Int,
    onConfidenceChange: (Float) -> Unit,
    changeThreshold: Float,
    onChangeThresholdChange: (Float) -> Unit,
    detectChanges: Boolean,
    onDetectChangesChange: (Boolean) -> Unit,
    autoTranslate: Boolean,
    onAutoTranslateChange: (Boolean) -> Unit,
    multiPass: Boolean,
    onMultiPassChange: (Boolean) -> Unit,
    liveMode: ScanMode,
    onLiveModeChange: (ScanMode) -> Unit,
) {
    SectionCard(title = "OCR", icon = Icons.Filled.TextFields) {
        Text("Движок распознавания", style = MaterialTheme.typography.labelMedium, color = OcrColors.TextSecondary)
        Spacer(Modifier.height(6.dp))
        ChoiceChipRow(
            items = OcrEngines.allIds,
            selected = engineId,
            label = { OcrEngines.displayName(it) },
            onSelect = onEngineChange,
        )
        Spacer(Modifier.height(4.dp))
        Text(
            "Цепочка fallback: " + OcrEngines.fallbackChain(engineId).joinToString(" → ") {
                OcrEngines.displayName(it)
            },
            style = MaterialTheme.typography.labelSmall,
            color = OcrColors.TextSecondary,
        )

        Spacer(Modifier.height(10.dp))
        LabeledSlider(
            label = "Интервал сканирования",
            value = intervalMs.toFloat().coerceIn(INTERVAL_MIN, INTERVAL_MAX),
            range = INTERVAL_MIN.toFloat()..INTERVAL_MAX.toFloat(),
            steps = INTERVAL_STEPS,
            valueLabel = "$intervalMs мс",
            onValueChange = onIntervalChange,
        )
        LabeledSlider(
            label = "Порог уверенности",
            value = confidencePct.toFloat().coerceIn(0f, 100f),
            range = 0f..100f,
            steps = 19,
            valueLabel = "$confidencePct %",
            onValueChange = onConfidenceChange,
        )
        LabeledSlider(
            label = "Чувствительность к изменениям кадра",
            value = changeThreshold.coerceIn(THRESHOLD_MIN, THRESHOLD_MAX),
            range = THRESHOLD_MIN..THRESHOLD_MAX,
            steps = 0,
            valueLabel = "%.3f".format(Locale.US, changeThreshold),
            onValueChange = onChangeThresholdChange,
        )

        SwitchRow(
            title = "Детектировать изменения кадра",
            subtitle = "Без этого OCR гоняет TFLite на каждом кадре",
            checked = detectChanges,
            onCheckedChange = onDetectChangesChange,
        )
        SwitchRow(
            title = "Автоперевод",
            subtitle = "$srcLang → $dstLang",
            checked = autoTranslate,
            onCheckedChange = onAutoTranslateChange,
        )
        SwitchRow(
            title = "Многопроходный разбор",
            subtitle = "Повторный проход по регионам с низкой уверенностью",
            checked = multiPass,
            onCheckedChange = onMultiPassChange,
        )

        Spacer(Modifier.height(6.dp))
        Text("Режим озвучки", style = MaterialTheme.typography.labelMedium, color = OcrColors.TextSecondary)
        Spacer(Modifier.height(6.dp))
        ChoiceChipRow(
            items = ScanMode.entries,
            selected = liveMode,
            label = { it.label() },
            onSelect = onLiveModeChange,
        )
    }
}

@Composable
private fun RegionsSection(
    regions: List<Region>,
    canDrawOverlay: Boolean,
    overlayAttached: Boolean,
    editMode: Boolean,
    onToggleEditMode: (Boolean) -> Unit,
    onToggleOverlay: () -> Unit,
    onAddCenter: () -> Unit,
    onDelete: (Int) -> Unit,
    onToggleRegion: (Int, Boolean) -> Unit,
    onClear: () -> Unit,
    onReload: () -> Unit,
) {
    SectionCard(title = "Регионы (${regions.size})", icon = Icons.Filled.Layers) {
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            Button(onClick = onAddCenter, modifier = Modifier.weight(1f)) {
                Icon(Icons.Filled.Add, null, modifier = Modifier.size(18.dp))
                Spacer(Modifier.width(4.dp))
                Text("По центру")
            }
            OutlinedButton(onClick = onToggleOverlay, modifier = Modifier.weight(1f)) {
                Icon(
                    if (overlayAttached) Icons.Filled.Visibility else Icons.Filled.VisibilityOff,
                    null,
                    modifier = Modifier.size(18.dp),
                )
                Spacer(Modifier.width(4.dp))
                Text(if (overlayAttached) "Скрыть" else "Показать")
            }
        }

        Spacer(Modifier.height(6.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            SwitchRow(
                title = "Редактирование оверлея",
                checked = editMode,
                onCheckedChange = onToggleEditMode,
                modifier = Modifier.weight(1f),
            )
        }

        if (!canDrawOverlay) {
            Spacer(Modifier.height(4.dp))
            Text(
                "Нет разрешения на оверлеи — нажмите «Показать», чтобы открыть системные настройки",
                style = MaterialTheme.typography.labelSmall,
                color = OcrColors.Warning,
            )
        }

        Spacer(Modifier.height(8.dp))
        if (regions.isEmpty()) {
            Text(
                "Регионы не заданы — сканируется весь экран",
                style = MaterialTheme.typography.bodySmall,
                color = OcrColors.TextSecondary,
            )
        } else {
            Column(
                Modifier
                    .heightIn(max = 240.dp)
                    .verticalScroll(rememberScrollState()),
                verticalArrangement = Arrangement.spacedBy(6.dp),
            ) {
                regions.forEachIndexed { index, region ->
                    RegionRow(
                        region = region,
                        onToggle = { onToggleRegion(index, it) },
                        onDelete = { onDelete(index) },
                    )
                }
            }
        }

        Spacer(Modifier.height(8.dp))
        Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
            OutlinedButton(onClick = onReload, modifier = Modifier.weight(1f)) {
                Icon(Icons.Filled.Refresh, null, modifier = Modifier.size(18.dp))
                Spacer(Modifier.width(4.dp))
                Text("Передать")
            }
            OutlinedButton(
                onClick = onClear,
                modifier = Modifier.weight(1f),
                enabled = regions.isNotEmpty(),
                colors = ButtonDefaults.outlinedButtonColors(contentColor = OcrColors.Danger),
            ) {
                Icon(Icons.Filled.Delete, null, modifier = Modifier.size(18.dp))
                Spacer(Modifier.width(4.dp))
                Text("Очистить")
            }
        }
    }
}

@Composable
private fun ResultSection(
    recognized: String,
    translated: String,
    translating: Boolean,
    autoTranslate: Boolean,
    showOverlayText: Boolean,
    hasTextOverlay: Boolean,
    onRecognizedChange: (String) -> Unit,
    onTranslatedChange: (String) -> Unit,
