        )

        if (translating) {
            Spacer(Modifier.height(6.dp))
            LinearProgressIndicator(
                modifier = Modifier.fillMaxWidth(),
                color = OcrColors.Accent,
            )
        }

        Spacer(Modifier.height(8.dp))
        OutlinedTextField(
            value = translated,
            onValueChange = onTranslatedChange,
            modifier = Modifier
                .fillMaxWidth()
                .heightIn(min = 72.dp, max = 160.dp),
