                Spacer(Modifier.width(4.dp))
                Text("Копировать")
            }
            OutlinedButton(onClick = onTranslate, modifier = Modifier.weight(1f)) {
                Icon(Icons.Filled.Translate, null, modifier = Modifier.size(18.dp))
                Spacer(Modifier.width(4.dp))
                Text("Перевести")
            }
            Button(
                onClick = onSpeak,
                modifier = Modifier.weight(1f),
