                    containerColor = OcrColors.Accent,
                    contentColor = OcrColors.Background,
                ),
            ) {
                Icon(Icons.Filled.VolumeUp, null, modifier = Modifier.size(18.dp))
                Spacer(Modifier.width(4.dp))
                Text("Озвучить")
            }
        }

        if (hasTextOverlay) {
            Spacer(Modifier.height(6.dp))
            SwitchRow(
                title = "Показывать оверлей текста",
                subtitle = "HUD поверх других приложений",
                checked = showOverlayText,
                onCheckedChange = onShowOverlayTextChange,
            )
        }
        if (!autoTranslate) {
            Spacer(Modifier.height(2.dp))
            Text(
                "Автоперевод выключен — озвучка идёт по исходному тексту",
                style = MaterialTheme.typography.labelSmall,
                color = OcrColors.Warning,
            )
        }
    }
}

