private fun HistoryRow(entry: HistoryEntry, onUse: () -> Unit, onSpeak: () -> Unit) {
    Surface(
        color = OcrColors.PanelHigh,
        shape = RoundedCornerShape(8.dp),
        border = BorderStroke(1.dp, OcrColors.Border),
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onUse),
    ) {
