// Логика, вынесенная из композаблов
// ══════════════════════════════════════════════════════════════════

private const val INTERVAL_MIN = 200
private const val INTERVAL_MAX = 3000
private const val INTERVAL_STEPS = 55
private const val THRESHOLD_MIN = 0.001f
private const val THRESHOLD_MAX = 0.2f
private const val ENGINE_SWAP_GRACE_MS = 1500L
private const val CENTER_REGION_W_RATIO = 0.6f
private const val CENTER_REGION_H_RATIO = 0.18f

/** Регион по центру экрана: порт кнопки «Add» в gui_compact (по умолчанию). */
internal fun centerRegion(context: Context, existing: Int): Region {
    val metrics = context.resources.displayMetrics
    val width = (metrics.widthPixels * CENTER_REGION_W_RATIO).toInt().coerceAtLeast(64)
    val height = (metrics.heightPixels * CENTER_REGION_H_RATIO).toInt().coerceAtLeast(64)
    val x = ((metrics.widthPixels - width) / 2).coerceAtLeast(0)
    val y = ((metrics.heightPixels - height) / 2).coerceAtLeast(0)
    return Region(
        name = "R${existing + 1}",
        x = x,
        y = y,
        width = width,
        height = height,
    ).clampTo(metrics.widthPixels, metrics.heightPixels)
}

internal fun copyToClipboard(context: Context, label: String, text: String) {
    if (text.isBlank()) return
    val manager = context.getSystemService(Context.CLIPBOARD_SERVICE) as? ClipboardManager ?: return
    runCatching { manager.setPrimaryClip(ClipData.newPlainText(label, text)) }
        .onFailure { Log.w(TAG, "Буфер обмена: ${it.message}") }
}

internal fun roleKey(role: TtsEngine.Role): String = when (role) {
    TtsEngine.Role.MALE -> "male"
    TtsEngine.Role.FEMALE -> "female"
    TtsEngine.Role.NARRATOR -> "narrator"
}

internal fun roleColor(role: TtsEngine.Role): Color = when (role) {
    TtsEngine.Role.MALE -> OcrColors.RoleMale
    TtsEngine.Role.FEMALE -> OcrColors.RoleFemale
    TtsEngine.Role.NARRATOR -> OcrColors.RoleNarrator
}

internal fun roleLabel(role: TtsEngine.Role): String = when (role) {
    TtsEngine.Role.MALE -> "♂"
    TtsEngine.Role.FEMALE -> "♀"
    TtsEngine.Role.NARRATOR -> "♪"
}

internal fun roleTitle(role: TtsEngine.Role): String = when (role) {
    TtsEngine.Role.MALE -> "Мужской"
    TtsEngine.Role.FEMALE -> "Женский"
    TtsEngine.Role.NARRATOR -> "Рассказчик"
}

internal fun ScanMode.label(): String = when (this) {
    ScanMode.REALTIME_CLEAR -> "Кадр за кадром"
    ScanMode.REALTIME_KEEP -> "Накопительно"
    ScanMode.PUNCT -> "По знакам"
}

internal fun formatClock(timeMs: Long): String {
    val cal = Calendar.getInstance()
    cal.timeInMillis = timeMs
    return String.format(
        Locale.getDefault(),
        "%02d:%02d:%02d",
        cal.get(Calendar.HOUR_OF_DAY),
        cal.get(Calendar.MINUTE),
        cal.get(Calendar.SECOND),
    )
}

private fun Context.findActivity(): ComponentActivity? {
    var current: Context? = this
    while (current is ContextWrapper) {
        if (current is ComponentActivity) return current
        current = current.baseContext
    }
    return null
}

/**
 * Счётчик, по которому экран перечитывает разрешение на оверлей: оно выдаётся
 * в системных настройках, а не диалогом, поэтому результат виден только после
 * возврата в Activity.
 */
@Composable
private fun rememberPermissionTick(): Int {
    var tick by remember { mutableStateOf(0) }
    val owner = LocalLifecycleOwner.current
    DisposableEffect(owner) {
        val observer = LifecycleEventObserver { _, event ->
            if (event == Lifecycle.Event.ON_RESUME) tick++
        }
        owner.lifecycle.addObserver(observer)
        onDispose { owner.lifecycle.removeObserver(observer) }
    }
    return tick
}

private suspend fun SnackbarHostState.showMessage(text: String) {
    runCatching { showSnackbar(text) }
        .onFailure { Log.w(TAG, "Snackbar: ${it.message}") }
}

