        private const val ZEN_REFERER = "https://github.com/sj0404-collab/overlay-translator"
        private const val ZEN_TITLE = "ScreenOCR_TTS"
        private const val ZEN_PROBE_TEXT = "Say OK"
        private const val PROBE_TEXT = "Hello"
        private const val MAX_TOKENS = 4096

