package com.screenocr.tts.core

/** Порт models Region из десктопной версии (region_overlay.py, region_selector.py). */
data class Region(
    val name: String,
    val x: Int,
    val y: Int,
    val width: Int,
    val height: Int,
    val color: String = "#4caf50",
    val shape: String = "rect",
    val enabled: Boolean = true,
) {
    val right: Int get() = x + width
    val bottom: Int get() = y + height

    fun clampTo(screenW: Int, screenH: Int): Region {
        val w = width.coerceAtMost(screenW)
        val h = height.coerceAtMost(screenH)
        return copy(
            x = x.coerceIn(0, (screenW - w).coerceAtLeast(0)),
            y = y.coerceIn(0, (screenH - h).coerceAtLeast(0)),
            width = w,
            height = h,
        )
    }
}

/** Результат распознавания одного блока текста. Порт OcrResult из ocr_wrapper.py. */
data class OcrLine(
    val text: String,
    val confidence: Float,
    val box: Box? = null,
)

/** Прямоугольник в координатах изображения. */
data class Box(
    val x: Int,
    val y: Int,
    val width: Int,
    val height: Int,
) {
    val right: Int get() = x + width
    val bottom: Int get() = y + height
}

/** Итог распознавания кадра. */
data class OcrResult(
    val text: String,
    val confidence: Float,
    val lines: List<OcrLine> = emptyList(),
    val engine: String = "",
    val elapsedMs: Long = 0,
) {
    val isEmpty: Boolean get() = text.isBlank()

    companion object {
        fun empty(engine: String = "") = OcrResult("", 0f, emptyList(), engine)
    }
}

/** Режим очистки результата между частями. Порт chunk_clear из live_scanner.py. */
enum class ScanMode {
    /** Очищать накопленный текст на каждом кадре. */
    REALTIME_CLEAR,

    /** Накапливать строки, отправлять пачками. */
    REALTIME_KEEP,

    /** Разбивать по знакам препинания. */
    PUNCT,
}

package com.screenocr.tts.ocr

import com.screenocr.tts.core.OcrResult

/**
 * Контракт OCR-движка. Порт EngineType/реестра из ocr_engines.py.
 */
interface OcrEngine {
    val id: String
    val displayName: String

    /** Приоритет: меньше — раньше в цепочке fallback. */
    val priority: Int

    /** Требует ли движок сети. */
    val requiresNetwork: Boolean

    /** Готов ли движок к работе (модели загружены / ключи есть). */
    suspend fun isReady(): Boolean

    /** Основное распознавание кадра. */
    suspend fun recognize(bitmap: android.graphics.Bitmap): OcrResult

    /** Закрыть ресурсы. */
    fun close() {}
}

/**
 * Реестр движков — порт ENGINE_REGISTRY + fallback_chain из ocr_engines.py.
 *
 * Приоритеты сохранены из десктопа, но latin-only движки (rapidocr/easyocr)
 * исключены: приложение работает с кириллицей и не тянет Python-стеки.
 */
object OcrEngines {

    const val ID_TFLITE = "tflite_cyrillic"
    const val ID_LENS = "google_lens"
    const val ID_ZEN = "zen"

    val allIds: List<String> = listOf(ID_TFLITE, ID_LENS, ID_ZEN)

    fun displayName(id: String): String = when (id) {
        ID_TFLITE -> "TFLite (кириллица, офлайн)"
        ID_LENS -> "Google Lens"
        ID_ZEN -> "Zen (vision LLM)"
        else -> id
    }

    fun priority(id: String): Int = when (id) {
        ID_TFLITE -> 10
        ID_LENS -> 0
        ID_ZEN -> 8
        else -> 99
    }

    /**
     * Строит цепочку fallback по возрастанию приоритета, основной движок — первым.
     * Порт fallback_chain() из ocr_engines.py.
     */
    fun fallbackChain(primary: String): List<String> {
        val rest = allIds.filter { it != primary }.sortedBy { priority(it) }
        return if (primary in allIds) listOf(primary) + rest else rest
    }
}

package com.screenocr.tts.ocr

import android.content.Context
import android.graphics.Bitmap
import com.screenocr.tts.core.Box
import com.screenocr.tts.core.OcrLine
import com.screenocr.tts.core.OcrResult
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.io.File

/**
 * Порт tflite_ocr.py + analyzer: детектор БД (DB) + CTC-распознаватель.
 * Работает полностью офлайн на моделях из assets/models.
 */
class TfliteOcrEngine(
    context: Context,
    private val limitSide: Int = 736,
) : OcrEngine {

    override val id = OcrEngines.ID_TFLITE
    override val displayName = OcrEngines.displayName(ID_TFLITE)
    override val priority = 10
    override val requiresNetwork = false

    private val appContext = context.applicationContext
    private var detector: TfliteDetector? = null
    private var recognizer: TfliteRecognizer? = null
    private var verifier: TfliteRecognizer? = null
    @Volatile private var loaded = false
    @Volatile private var loadError: String? = null

    private val lock = Any()

    override suspend fun isReady(): Boolean {
        ensureLoaded()
        return loaded
    }

    private fun ensureLoaded() {
        if (loaded) return
        synchronized(lock) {
            if (loaded) return
            try {
                val dir = File(appContext.filesDir, "models").apply { mkdirs() }
                val det = copyAsset("models/cyrillic_detector.tflite", File(dir, "det.tflite"))
                val rec = copyAsset("models/cyrillic_recognizer_v3.tflite", File(dir, "rec.tflite"))
                val dict3 = copyAsset("models/cyrillic_dict_v3.txt", File(dir, "dict3.txt"))
                val dict5Asset = assetExists("models/cyrillic_dict_v5.txt")
                val dict5 = if (dict5Asset) {
                    copyAsset("models/cyrillic_dict_v5.txt", File(dir, "dict5.txt"))
                } else null

                detector = TfliteDetector(det, limitSide)
                recognizer = TfliteRecognizer(rec, dict3.readText(), recWidth = 320, recHeight = 48)
                if (dict5 != null && assetExists("models/cyrillic_recognizer_v5.tflite")) {
                    val rec5 = copyAsset(
                        "models/cyrillic_recognizer_v5.tflite",
                        File(dir, "rec5.tflite"),
                    )
                    verifier = TfliteRecognizer(rec5, dict5.readText(), recWidth = 320, recHeight = 48)
                }
                loaded = true
            } catch (e: Throwable) {
                loadError = e.message ?: e::class.java.simpleName
            }
        }
    }

    private fun assetExists(path: String): Boolean = try {
        appContext.assets.open(path).close(); true
    } catch (_: Throwable) {
        false
    }

    private fun copyAsset(assetPath: String, target: File): File {
        if (target.exists() && target.length() > 0) return target
        appContext.assets.open(assetPath).use { input ->
            target.outputStream().use { output -> input.copyTo(output) }
        }
        return target
    }

    override suspend fun recognize(bitmap: Bitmap): OcrResult = withContext(Dispatchers.Default) {
        ensureLoaded()
        if (!loaded) return@withContext OcrResult.empty(id).also { it.engine = id }

        val det = detector ?: return@withContext OcrResult.empty(id)
        val rec = recognizer ?: return@withContext OcrResult.empty(id)
        val start = System.currentTimeMillis()

        // 1. Детекция боксов
        val detResult = det.detect(bitmap)

        // 2. Пустое изображение — дешёвый выход
        if (detResult.boxes.isEmpty()) {
            return@withContext OcrResult("", 0f, emptyList(), id, System.currentTimeMillis() - start)
        }

        // 3. Распознавание каждого бокса
        val lines = ArrayList<OcrLine>(detResult.boxes.size)
        for (box in detResult.boxes) {
            try {
                val crop = Bitmap.createBitmap(bitmap, box.x, box.y, box.width, box.height)
                val (text, conf) = rec.recognizeLine(crop)
                if (text.isNotBlank()) {
                    lines.add(OcrLine(text, conf, box))
                }
                if (crop !== bitmap) crop.recycle()
            } catch (_: Throwable) {
                // Пропускаем битые боксы
            }
        }

        val text = lines.joinToString(" ") { it.text }
        val avgConf = if (lines.isEmpty()) 0f else lines.map { it.confidence }.average().toFloat()
        OcrResult(text, avgConf, lines, id, System.currentTimeMillis() - start)
    }

    override fun close() {
        synchronized(lock) {
            detector?.close(); detector = null
            recognizer?.close(); recognizer = null
            verifier?.close(); verifier = null
            loaded = false
        }
    }
}

