package com.screenocr.tts.ocr

import android.content.Context
import android.graphics.Bitmap
import android.util.Log
import com.screenocr.tts.core.OcrResult
import com.screenocr.tts.settings.Settings
import java.security.MessageDigest

/**
 * Порт ocr_wrapper.py: диспетчер движков, цепочка fallback, кеш по хешу кадра,
 * пресеты обработки и фильтр языка.
 */
class OcrWrapper(
    context: Context,
    private val settings: Settings,
    engineId: String = settings.get(Settings.Ocr.ENGINE, OcrEngines.ID_TFLITE),
) {
    companion object {
        private const val TAG = "ScreenOCR"
        private const val SIGNATURE_W = 160
        private const val SIGNATURE_H = 90
        private const val CACHE_TEXT_TTL_MS = 1500L
    }

    private val appContext = context.applicationContext
    private val lock = Any()

    @Volatile
    var engineId: String = engineId
        private set

    private var engines = HashMap<String, OcrEngine>()
    private var lastSignature: String? = null
    private var lastResult: OcrResult? = null
    private var lastAt: Long = 0

    val activeEngine: OcrEngine? get() = synchronized(lock) { engines[engineId] }

    fun setEngine(id: String) {
        if (id == engineId) return
        engineId = id
        synchronized(lock) { ensureEngineLocked(id) }
        invalidateCache()
    }

    private fun ensureEngineLocked(id: String): OcrEngine {
        engines[id]?.let { return it }
        val engine = when (id) {
            OcrEngines.ID_TFLITE -> TfliteOcrEngine(
                appContext,
                settings.get(Settings.Ocr.DET_LIMIT_SIDE, 736),
            )
            OcrEngines.ID_LENS -> GoogleLensEngine(appContext, settings)
            OcrEngines.ID_ZEN -> ZenOcrEngine(appContext, settings)
            else -> TfliteOcrEngine(appContext, settings.get(Settings.Ocr.DET_LIMIT_SIDE, 736))
        }
        engines[id] = engine
        return engine
    }

    fun availableEngines(): List<String> = OcrEngines.allIds

    /**
     * Распознавание кадра: кеш по сигнатуре, затем цепочка fallback.
     * Порт recognize() из ocr_wrapper.py.
     */
    suspend fun recognize(bitmap: Bitmap): OcrResult {
        cached(bitmap)?.let { return it }

        val minConfidence = settings.get(Settings.Ocr.CONFIDENCE, 40) / 100f
        var lastFailure: OcrResult = OcrResult.empty()

        for (id in OcrEngines.fallbackChain(engineId)) {
            val engine = synchronized(lock) { ensureEngineLocked(id) }
            if (engine.requiresNetwork && !NetworkProbe.isOnline(appContext)) {
                Log.d(TAG, "OCR: $id пропущен — нет сети")
                continue
            }
            val ready = runCatching { engine.isReady() }.getOrDefault(false)
            if (!ready) {
                Log.d(TAG, "OCR: $id не готов")
                continue
            }
            val result = runCatching { engine.recognize(bitmap) }.getOrElse { e ->
                Log.w(TAG, "OCR: $id упал: ${e.message}")
                OcrResult.empty(id)
            }
            if (result.text.isBlank()) continue
            if (result.confidence < minConfidence && result.text.length < 4) {
                lastFailure = result
                continue
            }
            val cleaned = result.copy(
                text = OcrTextCleaner.fullCleanPipeline(result.text, id),
                engine = id,
            )
            store(bitmap, cleaned)
            return cleaned
        }
        lastFailure.let { return OcrResult.empty(engineId) }
    }

    private fun cached(bitmap: Bitmap): OcrResult? {
        if (!settings.get(Settings.Ocr.DETECT_CHANGES, true)) return null
        val sig = signature(bitmap) ?: return null
        synchronized(lock) {
            val hit = lastResult
            if (sig == lastSignature && hit != null &&
                System.currentTimeMillis() - lastAt < CACHE_TEXT_TTL_MS
            ) {
                return hit
            }
        }
        return null
    }

    private fun store(bitmap: Bitmap, result: OcrResult) {
        if (!settings.get(Settings.Ocr.DETECT_CHANGES, true)) return
        val sig = signature(bitmap) ?: return
        synchronized(lock) {
            lastSignature = sig
            lastResult = result
            lastAt = System.currentTimeMillis()
        }
    }

    fun invalidateCache() {
        synchronized(lock) {
            lastSignature = null
            lastResult = null
            lastAt = 0
        }
    }

    /** Компактная сигнатура кадра: уменьшенная серая матрица → hex md5. */
    private fun signature(bitmap: Bitmap): String? = try {
        val w = SIGNATURE_W
        val h = SIGNATURE_H
        val scaled = Bitmap.createScaledBitmap(bitmap, w, h, true)
        val pixels = IntArray(w * h)
        scaled.getPixels(pixels, 0, w, 0, 0, w, h)
        if (scaled !== bitmap) scaled.recycle()
        val gray = ByteArray(w * h)
        for (i in pixels.indices) {
            val p = pixels[i]
            val l = (((p shr 16 and 0xFF) * 299 + (p shr 8 and 0xFF) * 587 +
                (p and 0xFF) * 114) / 1000).toByte()
            gray[i] = l
        }
        val md = MessageDigest.getInstance("MD5")
        md.update(gray)
        md.digest().joinToString("") { "%02x".format(it) }
    } catch (e: Throwable) {
        Log.d(TAG, "OCR: сигнатура не построена: ${e.message}")
        null
    }

    fun close() {
        synchronized(lock) {
            engines.values.forEach { runCatching { it.close() } }
            engines.clear()
            invalidateCache()
        }
    }
}

package com.screenocr.tts.ocr

import android.content.Context
import android.net.ConnectivityManager
import android.net.NetworkCapabilities

internal object NetworkProbe {
    fun isOnline(context: Context): Boolean = try {
        val cm = context.getSystemService(Context.CONNECTIVITY_SERVICE) as? ConnectivityManager
        val caps = cm?.getNetworkCapabilities(cm.activeNetwork)
        caps != null && caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET)
    } catch (_: Throwable) {
        false
    }
}

