import okhttp3.RequestBody.Companion.toRequestBody
import org.json.JSONObject
import java.io.ByteArrayOutputStream
import java.util.concurrent.TimeUnit

/**
 * Порт online_ocr.py (ZenOCR) — vision-LLM распознавание текста экрана.
 * Требует сети; включён только явным выбором движка.
 */
class ZenOcrEngine(
    context: Context,
    private val settings: Settings,
) : OcrEngine {

    override val id = OcrEngines.ID_ZEN
    override val displayName = OcrEngines.displayName(OcrEngines.ID_ZEN)
    override val priority = 8
    override val requiresNetwork = true

    private val appContext = context.applicationContext
    private val client = OkHttpClient.Builder()
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .build()

    override suspend fun isReady(): Boolean =
        NetworkProbe.isOnline(appContext) && !settings.get(Settings.Translate.ZEN_KEY, "").isNullOrBlank()

    override suspend fun recognize(bitmap: Bitmap): OcrResult = withContext(Dispatchers.IO) {
        val jpeg = bitmap.toJpegBase64(1024)
        val model = settings.get(Settings.Translate.ZEN_MODEL, "space-bunny-free")
        val key = settings.get(Settings.Translate.ZEN_KEY, "")

        val body = JSONObject()
            .put("model", model)
            .put("stream", false)
            .put(
                "messages",
                org.json.JSONArray().put(
                    JSONObject()
                        .put("role", "user")
                        .put(
                            "content",
                            org.json.JSONArray()
                                .put(
                                    JSONObject()
                                        .put("type", "text")
                                        .put(
                                            "text",
                                            "Extract all visible text from this screenshot. " +
                                                "Return only the text, preserving line breaks. " +
                                                "Do not translate, do not comment.",
                                        ),
                                )
                                .put(
                                    JSONObject()
                                        .put("type", "image_url")
                                        .put(
                                            "image_url",
                                            JSONObject().put("url", "data:image/jpeg;base64,$jpeg"),
                                        ),
                                ),
                        ),
                ),
            )
            .toString()

        val builder = Request.Builder()
            .url("https://opencode.ai/zen/v1/chat/completions")
            .post(body.toRequestBody("application/json".toMediaType()))
        if (key.isNotBlank()) builder.header("Authorization", "Bearer $key")

        client.newCall(builder.build()).execute().use { response ->
            if (!response.isSuccessful) {
                android.util.Log.w("ScreenOCR", "Zen OCR HTTP ${response.code}")
                return@withContext OcrResult.empty(id)
            }
            val payload = response.body?.string().orEmpty()
            val text = parseContent(payload)
            OcrResult(text, 0.9f, emptyList(), id)
        }
    }

    private fun parseContent(payload: String): String = try {
        val choices = JSONObject(payload).optJSONArray("choices") ?: return ""
        val first = choices.optJSONObject(0) ?: return ""
        val message = first.optJSONObject("message") ?: return ""
        when (val content = message.opt("content")) {
            is String -> content.trim()
            is org.json.JSONArray -> buildString {
                for (i in 0 until content.length()) {
                    val part = content.optJSONObject(i) ?: continue
                    append(part.optString("text", ""))
                }
            }.trim()
            else -> ""
        }
    } catch (e: Throwable) {
        ""
    }

    private fun Bitmap.toJpegBase64(maxSide: Int): String {
        val scale = if (width > maxSide || height > maxSide) {
            maxSide.toFloat() / maxOf(width, height)
        } else 1f
        val w = (width * scale).toInt().coerceAtLeast(1)
        val h = (height * scale).toInt().coerceAtLeast(1)
        val scaled = if (scale < 1f) Bitmap.createScaledBitmap(this, w, h, true) else this
        val out = ByteArrayOutputStream()
        scaled.compress(Bitmap.CompressFormat.JPEG, 85, out)
        if (scaled !== this) scaled.recycle()
        return Base64.encodeToString(out.toByteArray(), Base64.NO_WRAP)
    }
}

