package com.screenocr.tts.ocr

import java.io.ByteArrayOutputStream

/**
 * Минимальный protobuf-writer/reader — порт ProtoWriter/ProtoReader из glens_ocr.py.
 * Нужен для ручной сборки запроса к Lens без внешних protobuf-библиотек.
 */
internal object Proto {

    class Writer {
        private val buf = ByteArrayOutputStream()

        fun writeInt32(field: Int, value: Int) {
            tag(field, 0); varint(value.toLong())
        }

        fun writeUint64(field: Int, value: Long) {
            tag(field, 0); varint(value)
        }

        fun writeBool(field: Int, value: Boolean) {
            tag(field, 0); varint(if (value) 1L else 0L)
        }

        fun writeString(field: Int, value: String) = writeBytes(field, value.toByteArray(Charsets.UTF_8))

        fun writeBytes(field: Int, value: ByteArray) {
            tag(field, 2); varint(value.size.toLong()); buf.write(value)
        }

        fun writeMessage(field: Int, build: (Writer) -> Unit) {
            val inner = Writer()
            build(inner)
            writeBytes(field, inner.toByteArray())
        }

        fun toByteArray(): ByteArray = buf.toByteArray()

        private fun tag(field: Int, wire: Int) = varint(((field.toLong() shl 3) or wire.toLong()))

        private fun varint(v: Long) {
            var x = v
            while (x and 0x7FL.inv() != 0L) {
                buf.write(((x and 0x7F).toInt() or 0x80))
                x = x ushr 7
            }
            buf.write((x and 0x7F).toInt())
        }
    }

    class Reader(private val data: ByteArray) {
        private var pos = 0

        fun hasRemaining(): Boolean = pos < data.size

        fun readTag(): Int? {
            if (!hasRemaining()) return null
            return readVarint().toInt()
        }

        fun readBytes(): ByteArray {
            val len = readVarint().toInt()
            if (len < 0 || pos + len > data.size) { pos = data.size; return ByteArray(0) }
            val out = data.copyOfRange(pos, pos + len)
            pos += len
            return out
        }

        fun skipField(wire: Int) {
            when (wire) {
                0 -> readVarint()
                1 -> pos += 4
                2 -> readVarint()
                5 -> pos += 4
                else -> pos = data.size
            }
            if (pos > data.size) pos = data.size
        }

        private fun readVarint(): Long {
            var result = 0L
            var shift = 0
            while (shift < 64) {
                if (!hasRemaining()) return result
                val b = data[pos++].toInt()
                result = result or ((b.toLong() and 0x7FL) shl shift)
                if (b and 0x80 == 0) return result
                shift += 7
            }
            return result
        }
    }
}

package com.screenocr.tts.ocr

import android.content.Context
import android.graphics.Bitmap
import android.util.Log
import com.screenocr.tts.core.OcrResult
import com.screenocr.tts.settings.Settings
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody.Companion.toRequestBody
import java.io.ByteArrayOutputStream
import java.security.SecureRandom
import java.util.concurrent.TimeUnit

/**
 * Порт glens_ocr.py: Google Lens OCR через protobuf-эндпоинт crupload.
 * Требует сети и API-ключа; включён только явным выбором движка.
 */
class GoogleLensEngine(
    context: Context,
    private val settings: Settings,
) : OcrEngine {

    override val id = OcrEngines.ID_LENS
    override val displayName = OcrEngines.displayName(OcrEngines.ID_LENS)
    override val priority = 0
    override val requiresNetwork = true

    private val appContext = context.applicationContext
    private val random = SecureRandom()

    private val client = OkHttpClient.Builder()
        .connectTimeout(30, TimeUnit.SECONDS)
        .readTimeout(30, TimeUnit.SECONDS)
        .build()

    override suspend fun isReady(): Boolean =
        NetworkProbe.isOnline(appContext) && apiKey().isNotBlank()

    private fun apiKey(): String = settings.get("ocr.online_api_key", "")

    override suspend fun recognize(bitmap: Bitmap): OcrResult = withContext(Dispatchers.IO) {
        val m = maxOf(bitmap.width, bitmap.height)
        var source = bitmap
        if (m > MAX_IMAGE_DIMENSION) {
            val s = MAX_IMAGE_DIMENSION.toFloat() / m
            source = Bitmap.createScaledBitmap(
                bitmap,
                (bitmap.width * s).toInt().coerceAtLeast(1),
                (bitmap.height * s).toInt().coerceAtLeast(1),
                true,
            )
        }
        val png = source.let {
            val out = ByteArrayOutputStream()
            it.compress(Bitmap.CompressFormat.PNG, 100, out)
            if (it !== bitmap) it.recycle()
            out.toByteArray()
        }

        val payload = buildRequest(png, source.width, source.height)
        val request = Request.Builder()
            .url(ENDPOINT)
            .post(payload.toRequestBody("application/x-protobuf".toMediaType()))
            .header("User-Agent", USER_AGENT)
            .header("X-Goog-Api-Key", apiKey())
            .build()

        client.newCall(request).execute().use { response ->
            if (!response.isSuccessful) {
                Log.w("ScreenOCR", "Lens OCR HTTP ${response.code}")
                return@withContext OcrResult.empty(id)
            }
            val text = extractText(response.body?.bytes() ?: ByteArray(0))
            OcrResult(text, 0.95f, emptyList(), id)
        }
    }

    private fun buildRequest(png: ByteArray, width: Int, height: Int): ByteArray {
        val requestId = random.nextLong() and Long.MAX_VALUE shr 1
        val w = Proto.Writer()
        w.writeMessage(1) { obj ->
            obj.writeMessage(1) { ctx ->
                ctx.writeMessage(3) { rid ->
                    rid.writeUint64(1, requestId)
                    rid.writeInt32(2, 0)
                    rid.writeInt32(3, 0)
                    val nonce = ByteArray(16)
                    random.nextBytes(nonce)
                    rid.writeBytes(4, nonce)
                }
                ctx.writeMessage(4) { cc ->
                    cc.writeInt32(1, 3)
                    cc.writeInt32(2, 4)
                    cc.writeMessage(4) { lc ->
                        lc.writeString(1, CLIENT_LANGUAGE)
                        lc.writeString(2, CLIENT_REGION)
                    }
                    cc.writeMessage(7) { filters ->
                        filters.writeMessage(1) { it.writeInt32(1, 1) }
                    }
                }
            }
            obj.writeMessage(3) { img ->
                img.writeMessage(1) { it.writeBytes(1, png) }
                img.writeMessage(3) { d ->
                    d.writeInt32(1, width)
                    d.writeInt32(2, height)
                }
            }
        }
        return w.toByteArray()
    }

    private fun extractText(data: ByteArray): String {
        val lines = ArrayList<String>()
        val reader = Proto.Reader(data)
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag shr 3
            val wire = tag and 0x7
            if (field == 2 && wire == 2) {
                lines += parseObjectsResponse(reader.readBytes())
            } else {
                reader.skipField(wire)
            }
        }
        return lines.joinToString("\n").trim()
    }

    private fun parseObjectsResponse(data: ByteArray): List<String> {
        val lines = ArrayList<String>()
        val reader = Proto.Reader(data)
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag shr 3
            val wire = tag and 0x7
            if (field == 3 && wire == 2) {
                lines += parseText(reader.readBytes())
            } else {
                reader.skipField(wire)
            }
        }
        return lines
    }

    private fun parseText(data: ByteArray): List<String> {
        val result = ArrayList<String>()
        val reader = Proto.Reader(data)
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag shr 3
            val wire = tag and 0x7
            if (field == 1 && wire == 2) {
                result += parseTextLayout(reader.readBytes())
            } else {
                reader.skipField(wire)
            }
        }
        return result
    }

    private fun parseTextLayout(data: ByteArray): List<String> {
        val lines = ArrayList<String>()
        val reader = Proto.Reader(data)
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag shr 3
            val wire = tag and 0x7
            if (field == 1 && wire == 2) {
                lines += parseParagraph(reader.readBytes())
            } else {
                reader.skipField(wire)
            }
        }
        return lines
    }

    private fun parseParagraph(data: ByteArray): List<String> {
        val lines = ArrayList<String>()
        val reader = Proto.Reader(data)
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag shr 3
            val wire = tag and 0x7
            if (field == 2 && wire == 2) {
                val line = parseLine(reader.readBytes())
                if (line.isNotBlank()) lines += line
            } else {
                reader.skipField(wire)
            }
        }
        return lines
    }

    private fun parseLine(data: ByteArray): String {
        val sb = StringBuilder()
        val reader = Proto.Reader(data)
        while (reader.hasRemaining()) {
            val tag = reader.readTag() ?: break
            val field = tag shr 3
            val wire = tag and 0x7
            if (field == 1 && wire == 2) {
                sb.append(String(reader.readBytes(), Charsets.UTF_8))
            } else {
                reader.skipField(wire)
            }
        }
        return sb.toString()
    }

    private companion object {
        const val ENDPOINT = "https://lensfrontend-pa.googleapis.com/v1/crupload"
        const val USER_AGENT =
            "Mozilla/5.0 (Linux; Android 13) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Mobile Safari/537.36"
        const val CLIENT_LANGUAGE = "ru"
        const val CLIENT_REGION = "ru"
        const val MAX_IMAGE_DIMENSION = 1500
    }
}

package com.screenocr.tts.ocr

import android.graphics.Bitmap
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.ColorMatrix
import android.graphics.ColorMatrixColorFilter
import android.graphics.Paint
import kotlin.math.abs
import kotlin.math.max
import kotlin.math.min
import kotlin.math.roundToInt

/**
 * Порт image_preprocessor.py: контраст, яркость, инверсия, HSV-усиление,
 * адаптивный порог, подавление шума, режим auto по яркости кадра.
 */
object ImagePreprocessor {

    const val PRESET_AUTO = "auto"
    const val PRESET_NONE = "none"
    const val PRESET_BALANCED = "balanced"
    const val PRESET_SHARP = "sharp"
    const val PRESET_DARK = "dark"
    const val PRESET_LIGHT = "light"

    fun preprocessForOcr(
        src: Bitmap,
        preset: String = PRESET_AUTO,
        contrast: Float = 1.0f,
        brightness: Float = 1.0f,
    ): Bitmap = when (preset) {
        PRESET_NONE -> src
        PRESET_BALANCED -> adjust(src, contrast.coerceAtLeast(1.0f), brightness, false)
        PRESET_SHARP -> enhanceEdges(src)
        PRESET_DARK -> adjust(src, contrast, brightness, false)
        PRESET_LIGHT -> adjust(src, contrast, brightness, false)
        PRESET_AUTO -> autoPreprocess(src, contrast, brightness)
        else -> autoPreprocess(src, contrast, brightness)
    }

    /** Порт _auto_preprocess: гистограмма яркости решает режим. */
    fun autoPreprocess(src: Bitmap, contrast: Float, brightness: Float): Bitmap {
        val mean = meanLuma(src)
        return when {
            mean < 70f -> adjust(src, max(contrast, 1.3f), max(brightness, 1.15f), false)
            mean > 190f -> adjust(src, max(contrast, 1.2f), min(brightness, 0.92f), false)
            else -> adjust(src, contrast, brightness, false)
        }
    }

    fun meanLuma(src: Bitmap): Float {
        val w = min(src.width, 64)
        val h = min(src.height, 64)
        val scaled = Bitmap.createScaledBitmap(src, w, h, true)
        val px = IntArray(w * h)
        scaled.getPixels(px, 0, w, 0, 0, w, h)
        if (scaled !== src) scaled.recycle()
        var sum = 0.0
        for (p in px) {
            sum += (Color.red(p) * 0.299 + Color.green(p) * 0.587 + Color.blue(p) * 0.114)
        }
        return (sum / px.size).toFloat()
    }

    /** Порт rgb_auto_contrast + rgb_channel_boost + rgb_invert через ColorMatrix. */
    fun adjust(
        src: Bitmap,
        contrast: Float,
        brightness: Float,
        invert: Boolean,
    ): Bitmap {
        if (contrast == 1f && brightness == 1f && !invert) return src
        val out = Bitmap.createBitmap(src.width, src.height, Bitmap.Config.ARGB_8888)
        val c = contrast.coerceIn(0.1f, 4f)
        val b = brightness.coerceIn(0.1f, 4f)
        val translate = 128f * (1f - c) + (if (invert) 255f else 0f)
        val scale = if (invert) -c * b else c * b
        val matrix = ColorMatrix(
            floatArrayOf(
                scale, 0f, 0f, 0f, translate,
                0f, scale, 0f, 0f, translate,
                0f, 0f, scale, 0f, translate,
                0f, 0f, 0f, 1f, 0f,
            ),
        )
        val paint = Paint().apply {
            colorFilter = ColorMatrixColorFilter(matrix)
            isAntiAlias = false
            isFilterBitmap = false
        }
        Canvas(out).drawBitmap(src, 0f, 0f, paint)
        return out
    }

    /** Порт hsv_enhance_text: подъём насыщенности и яркости без смены тона. */
    fun enhanceHsv(src: Bitmap, saturation: Float = 1.2f, value: Float = 1.1f): Bitmap {
        val out = Bitmap.createBitmap(src.width, src.height, Bitmap.Config.ARGB_8888)
        val paint = Paint()
        val hsl = FloatArray(3)
        val hslMatrix = Array(src.height) { IntArray(src.width) }
        val px = IntArray(src.width * src.height)
        src.getPixels(px, 0, src.width, 0, 0, src.width, src.height)
        for (i in px.indices) {
            Color.colorToHSL(px[i], hsl)
            hsl[1] = (hsl[1] * saturation).coerceIn(0f, 1f)
            hsl[2] = (hsl[2] * value).coerceIn(0f, 1f)
            hslMatrix[i / src.width][i % src.width] = Color.HSVToColor(Color.alpha(px[i]), hsl)
        }
        for (y in 0 until src.height) {
            out.setPixels(hslMatrix[y], 0, src.width, 0, y, src.width, 1)
        }
        paint.isAntiAlias = false
        return out
    }

    /** Порт hsv_grayscale_enhance: серый + локальное усиление контраста. */
    fun grayscaleEnhance(src: Bitmap): Bitmap {
        val out = Bitmap.createBitmap(src.width, src.height, Bitmap.Config.ARGB_8888)
        val px = IntArray(src.width * src.height)
        src.getPixels(px, 0, src.width, 0, 0, src.width, src.height)
        val luma = IntArray(px.size) { i ->
            val p = px[i]
            val l = (Color.red(p) * 0.299 + Color.green(p) * 0.587 + Color.blue(p) * 0.114)
                .roundToInt().coerceIn(0, 255)
            Color.argb(Color.alpha(p), l, l, l)
        }
        out.setPixels(luma, 0, src.width, 0, 0, src.width, src.height)
        return out
    }

    /** Порт edge_enhance: подъём локального контраста (unsharp-подобный). */
    fun enhanceEdges(src: Bitmap, strength: Float = 1.5f): Bitmap {
        val w = src.width
        val h = src.height
        val px = IntArray(w * h)
        src.getPixels(px, 0, w, 0, 0, w, h)
        val out = IntArray(px.size)
        for (y in 0 until h) {
            for (x in 0 until w) {
                val i = y * w + x
                val p = px[i]
                val luma = Color.red(p) * 0.299 + Color.green(p) * 0.587 + Color.blue(p) * 0.114
                val left = if (x > 0) lumaAt(px, w, i - 1) else luma
                val right = if (x < w - 1) lumaAt(px, w, i + 1) else luma
                val boosted = luma + (luma - (left + right) / 2f) * (strength - 1f)
                val v = boosted.roundToInt().coerceIn(0, 255)
                out[i] = Color.argb(Color.alpha(p), v, v, v)
            }
        }
        val result = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        result.setPixels(out, 0, w, 0, 0, w, h)
        return result
    }

    private fun lumaAt(px: IntArray, w: Int, i: Int): Float {
        val p = px[i]
        return Color.red(p) * 0.299 + Color.green(p) * 0.587 + Color.blue(p) * 0.114
    }

    /**
     * Порт adaptive_threshold: локальный порог по окну blockSize (метод средних).
     */
    fun adaptiveThreshold(src: Bitmap, blockSize: Int = 15, c: Int = 8): Bitmap {
        val w = src.width
        val h = src.height
        val gray = grayscaleEnhance(src)
        val px = IntArray(w * h)
        gray.getPixels(px, 0, w, 0, 0, w, h)
        if (gray !== src) gray.recycle()
        val integral = IntArray((w + 1) * (h + 1))
        for (y in 0 until h) {
            var rowSum = 0
            for (x in 0 until w) {
                rowSum += Color.red(px[y * w + x])
                integral[(y + 1) * (w + 1) + (x + 1)] = integral[y * (w + 1) + (x + 1)] + rowSum
            }
        }
        val half = max(1, blockSize / 2)
        val out = IntArray(px.size)
        for (y in 0 until h) {
            val y0 = max(0, y - half)
            val y1 = min(h - 1, y + half)
            for (x in 0 until w) {
                val x0 = max(0, x - half)
                val x1 = min(w - 1, x + half)
                val area = (y1 - y0 + 1) * (x1 - x0 + 1)
                val sum = integral[(y1 + 1) * (w + 1) + (x1 + 1)] -
                    integral[y0 * (w + 1) + (x1 + 1)] -
                    integral[(y1 + 1) * (w + 1) + x0] +
                    integral[y0 * (w + 1) + x0]
                val mean = sum.toFloat() / area
                val v = Color.red(px[y * w + x])
                val outVal = if ((v - mean) > -c) 0 else 255
                out[y * w + x] = Color.argb(255, outVal, outVal, outVal)
            }
        }
        val result = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        result.setPixels(out, 0, w, 0, 0, w, h)
        return result
    }

    /** Порт hsv_isolate_color: оставить пиксели в диапазоне тона, остальное — белым. */
    fun isolateColor(
        src: Bitmap,
        hueCenter: Float,
        hueRange: Float = 30f,
        saturationMin: Float = 0.25f,
    ): Bitmap {
        val w = src.width
        val h = src.height
        val px = IntArray(w * h)
        src.getPixels(px, 0, w, 0, 0, w, h)
        val hsl = FloatArray(3)
        for (i in px.indices) {
            Color.colorToHSL(px[i], hsl)
            val dh = hueDelta(hsl[0] * 360f, hueCenter)
            val keep = dh <= hueRange && hsl[1] >= saturationMin
            px[i] = if (keep) px[i] else Color.WHITE
        }
        val out = Bitmap.createBitmap(w, h, Bitmap.Config.ARGB_8888)
        out.setPixels(px, 0, w, 0, 0, w, h)
        return out
    }

    private fun hueDelta(a: Float, b: Float): Float {
        var d = abs(a - b) % 360f
        if (d > 180f) d = 360f - d
        return d
    }
}

