    for (i in px.indices) {
        rgbToHsv(Color.red(px[i]), Color.green(px[i]), Color.blue(px[i]), hsv)
        hsv[1] = (hsv[1] * saturation).coerceIn(0f, 1f)
        hsv[2] = (hsv[2] * value).coerceIn(0f, 1f)
        val rgb = hsvToColor(Color.alpha(px[i]), hsv)
        rows[i / src.width][i % src.width] = rgb
    }
    for (y in 0 until src.height) {
        out.setPixels(rows[y], 0, src.width, 0, y, src.width, 1)
    }
    return out
}

/** RGB → HSV, h в градусах (0..360), s и v в 0..1. */
private fun rgbToHsv(r: Int, g: Int, b: Int, out: FloatArray) {
    val rf = r / 255f
    val gf = g / 255f
    val bf = b / 255f
    val maxC = maxOf(rf, gf, bf)
    val minC = minOf(rf, gf, bf)
    val delta = maxC - minC
    out[2] = maxC
    out[1] = if (maxC <= 0f) 0f else delta / maxC
    out[0] = when {
        delta <= 0f -> 0f
        maxC == rf -> 60f * (((gf - bf) / delta) % 6f)
        maxC == gf -> 60f * (((bf - rf) / delta) + 2f)
        else -> 60f * (((rf - gf) / delta) + 4f)
    }
    if (out[0] < 0f) out[0] += 360f
}

private fun hsvToColor(alpha: Int, hsv: FloatArray): Int {
    val h = hsv[0]
    val s = hsv[1]
    val v = hsv[2]
    val c = v * s
    val x = c * (1f - kotlin.math.abs((h / 60f) % 2f - 1f))
    val m = v - c
    val rp: Float
    val gp: Float
    val bp: Float
    when ((h / 60f).toInt()) {
        0 -> { rp = c; gp = x; bp = 0f }
        1 -> { rp = x; gp = c; bp = 0f }
        2 -> { rp = 0f; gp = c; bp = x }
        3 -> { rp = 0f; gp = x; bp = c }
        4 -> { rp = x; gp = 0f; bp = c }
        else -> { rp = c; gp = 0f; bp = x }
    }
    return Color.argb(
        alpha,
        ((rp + m) * 255f).toInt().coerceIn(0, 255),
        ((gp + m) * 255f).toInt().coerceIn(0, 255),
        ((bp + m) * 255f).toInt().coerceIn(0, 255),
    )
}

