package com.screenocr.tts.core

import java.util.Locale
import kotlin.math.abs
import kotlin.math.max

/**
 * Общие текстовые эвристики десктопной версии, вынесенные в ядро,
 * потому что их используют и сканер (scanner.py), и live-сканер (live_scanner.py):
 *
 *  - [similarity]      <- ScreenScanner._similarity (LCS-ratio)
 *  - [isValidText]     <- LiveScanner._is_valid_text (фильтр мусора OCR)
 *  - [normalizeLine]   <- LiveScanner._normalize_line
 *  - [textDelta]       <- ScreenScanner._get_text_delta
 *  - [splitSentences]  <- LiveScanner._split_sentences
 */
object TextHeuristics {

    /** Ограничение длины для DP: текст длиннее 400 символов сравнивать бессмысленно. */
    private const val MAX_COMPARE = 400

    private const val TRAILING_PUNCT = ".,!?:;-"

    private val WHITESPACE_RE = Regex("\\s+")
    private val DATE_RE = Regex("\\d{4}[-/.]\\d{2}[-/.]\\d{2}")
    private val TIME_RE = Regex("\\d{1,2}:\\d{2}(:\\d{2})?")
    private val SENTENCE_RE = Regex("(?<=[.!?])\\s+|\\n{2,}")
    private val COMMA_RE = Regex("(?<=,)\\s+")
    private val ROLE_RE = Regex("^[A-Za-z\\u0410-\\u042F\\u0430-\\u044F\\u0401\\u0451]+:")

    private const val ALLOWED_PUNCT = ".,!?-:;'\"()"

    private const val REPLACEMENT_CHAR = 0xFFFD

    /** Приводит текст к каноничному виду для сравнения: trim + lower + один пробел. */
    fun normalize(text: String): String =
        text.trim().lowercase(Locale.ROOT).replace(WHITESPACE_RE, " ")

    /** Нормализация строки со срезом хвостовой пунктуации (порт _normalize_line). */
    fun normalizeLine(line: String): String =
        normalize(line).trimEnd(*TRAILING_PUNCT.toCharArray())

    /**
     * Доля longest common substring (порт ScreenScanner._similarity).
     * Быстрый выход по разнице длин - как в оригинале.
     */
    fun similarity(a0: String, b0: String): Float {
        if (a0.isEmpty() || b0.isEmpty()) return 0f
        if (a0 == b0) return 1f
        var a = if (a0.length > MAX_COMPARE) a0.substring(0, MAX_COMPARE) else a0
        var b = if (b0.length > MAX_COMPARE) b0.substring(0, MAX_COMPARE) else b0
        val maxLen = max(a.length, b.length)
        if (abs(a.length - b.length) > maxLen * 0.3) return 0f
        if (a.length < b.length) {
            val t = a
            a = b
            b = t
        }
        var prev = IntArray(b.length + 1)
        var cur = IntArray(b.length + 1)
        var best = 0
        for (i in 1..a.length) {
            cur.fill(0)
            val ai = a[i - 1]
            for (j in 1..b.length) {
                if (ai == b[j - 1]) {
                    val v = prev[j - 1] + 1
                    cur[j] = v
                    if (v > best) best = v
                }
            }
            val swap = prev
            prev = cur
            cur = swap
        }
        return if (maxLen == 0) 0f else best.toFloat() / maxLen
    }

    /**
     * Проверка текста на мусор OCR (порт LiveScanner._is_valid_text):
     * кракозябры, таймстемпы, шум, слишком короткие слова.
     */
    fun isValidText(text: String): Boolean {
        val t = text.trim()
        if (t.length < 3) return false
        if (t.indexOf(REPLACEMENT_CHAR.toChar()) >= 0) return false

        var letters = 0
        var digits = 0
        var special = 0
        for (c in t) {
            when {
                c.isLetter() -> letters++
                c.isDigit() -> digits++
                c.isWhitespace() -> Unit
                c in ALLOWED_PUNCT -> Unit
                else -> special++
            }
        }
        if (letters == 0) return false
        if (digits > letters) return false
        if (DATE_RE.containsMatchIn(t)) return false
        if (TIME_RE.containsMatchIn(t)) return false
        if (special > letters * 0.4) return false

        // Все слова короче 3 символов - типичный шум распознавания
        return t.split(WHITESPACE_RE).any { it.length > 2 }
    }

    /** Только новая часть текста относительно предыдущего кадра (порт _get_text_delta). */
    fun textDelta(oldText: String, newText: String): String {
        if (newText.isBlank()) return ""
        val old = oldText.trim()
        val neu = newText.trim()
        if (old.isNotEmpty() && neu.startsWith(old)) {
            return neu.substring(old.length).trim()
        }
        return neu
    }

    /**
     * Разбивка на предложения (порт LiveScanner._split_sentences).
     * Строка длиннее 80 символов дополнительно режется по запятым.
     */
    fun splitSentences(text: String): List<String> {
        if (text.isBlank()) return emptyList()
        val result = ArrayList<String>()
        for (part in SENTENCE_RE.split(text.trim())) {
            val p = part.trim()
            if (p.isEmpty()) continue
            if (p.length > 80) {
                for (sub in COMMA_RE.split(p)) {
                    val s = sub.trim()
                    if (s.isNotEmpty()) result.add(s)
                }
            } else {
                result.add(p)
            }
        }
        return result
    }

    /** Строка вида "Роль: текст" - используется мультиголосовым режимом. */
    fun isRoleLine(line: String): Boolean = ROLE_RE.containsMatchIn(line)
}

package com.screenocr.tts.capture

import android.content.Context
import android.graphics.Bitmap
import android.graphics.PixelFormat
import android.graphics.Point
import android.hardware.display.DisplayManager
import android.hardware.display.VirtualDisplay
import android.media.Image
import android.media.ImageReader
import android.media.projection.MediaProjection
import android.os.Build
import android.os.Handler
import android.os.HandlerThread
import android.os.Looper
import android.os.SystemClock
import android.util.Log
import android.util.TypedValue
import android.view.Display
import com.screenocr.tts.core.Region

/**
 * Порт захвата экрана: ImageReader + MediaProjection.createVirtualDisplay.
 *
 * Формат RGBA_8888, изображение читается из image.planes[0] с учётом
 * rowStride/pixelStride. Каждый Image обязательно закрывается - иначе
 * буферный пул ImageReader переполняется и захват встаёт.
 *
 * Экземпляр не потокобезопасен на уровне полей, но все публичные методы
 * синхронизированы: захват кадра всегда вызывается из одного потока сканера.
 */
class ScreenCapture(context: Context) {

    private val appContext = context.applicationContext
    private val mainHandler = Handler(Looper.getMainLooper())
    private val lock = Any()

    private var thread: HandlerThread? = null
    private var handler: Handler? = null
    private var imageReader: ImageReader? = null
    private var virtualDisplay: VirtualDisplay? = null
    private var projection: MediaProjection? = null

    private var size = Point(0, 0)

    /**
     * Вызывается, когда пользователь отозвал доступ к экрану
     * (системный диалог "Остановить проекцию" или истечение токена).
     */
    var onProjectionStopped: (() -> Unit)? = null

    val isRunning: Boolean
        get() = synchronized(lock) { imageReader != null }

    val screenWidth: Int get() = synchronized(lock) { size.x }

    val screenHeight: Int get() = synchronized(lock) { size.y }

    /**
     * Android 14+ (API 34) требует зарегистрировать MediaProjection.Callback
     * ДО вызова createVirtualDisplay, иначе бросается IllegalStateException.
     */
    private val projectionCallback = object : MediaProjection.Callback() {
        override fun onStop() {
            Log.i(TAG, "MediaProjection остановлен системой")
            teardown()
            mainHandler.post { onProjectionStopped?.invoke() }
        }
    }

    fun start(projection: MediaProjection) {
        synchronized(lock) {
            stopLocked()
            val metrics = currentDisplaySize()
            if (metrics.x <= 0 || metrics.y <= 0) {
                Log.e(TAG, "Не удалось определить размер дисплея")
                return
            }
            val ht = HandlerThread("screen-capture").apply { start() }
            val h = Handler(ht.looper)
            val reader = ImageReader.newInstance(
                metrics.x, metrics.y, PixelFormat.RGBA_8888, MAX_IMAGES,
            )
            val dpi = TypedValue.applyDimension(
                TypedValue.COMPLEX_UNIT_DENSITY, 1f, appContext.resources.displayMetrics,
            ).toInt().coerceAtLeast(120)

            runCatching { projection.registerCallback(projectionCallback, h) }
                .onFailure { Log.e(TAG, "registerCallback не удался", it) }

            val vd = projection.createVirtualDisplay(
                VIRTUAL_DISPLAY_NAME,
                metrics.x, metrics.y, dpi,
                DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,
                reader.surface, null, h,
            )

            thread = ht
            handler = h
            imageReader = reader
            virtualDisplay = vd
            this.projection = projection
            size = metrics
        }
        Log.i(TAG, "Захват экрана запущен: ${screenWidth}x${screenHeight}")
    }

    fun stop() {
        synchronized(lock) { stopLocked() }
        Log.i(TAG, "Захват экрана остановлен")
    }

    /** Кадр целиком (в системных координатах дисплея). */
    fun captureFull(): Bitmap? = acquireBitmap()

    /**
     * Кадр с вырезанным регионом. Регион прижимается к границам экрана,
     * чтобы Bitmap.createBitmap не бросил исключение на битых координатах.
     */
    fun captureRegion(region: Region): Bitmap? {
        val full = acquireBitmap() ?: return null
        val w = full.width
        val h = full.height
        val x = region.x.coerceIn(0, (w - 1).coerceAtLeast(0))
        val y = region.y.coerceIn(0, (h - 1).coerceAtLeast(0))
        val cw = region.width.coerceIn(1, w - x)
        val ch = region.height.coerceIn(1, h - y)
        if (cw <= 0 || ch <= 0) {
            full.recycle()
            return null
        }
        return try {
            if (cw == w && ch == h) full
            else Bitmap.createBitmap(full, x, y, cw, ch)
        } catch (e: Throwable) {
            Log.e(TAG, "Не удалось вырезать регион ${region.name}", e)
            null
        } finally {
            if (cw != w || ch != h) full.recycle()
        }
    }

    // ── internals ───────────────────────────────────────────────

    private fun stopLocked() {
        val vd = virtualDisplay
        val reader = imageReader
        val p = projection
        virtualDisplay = null
        imageReader = null
        projection = null
        runCatching { vd?.release() }
        runCatching { reader?.close() }
        if (p != null) {
            runCatching { p.unregisterCallback(projectionCallback) }
            runCatching { p.stop() }
        }
        thread?.quitSafely()
        thread = null
        handler = null
        size = Point(0, 0)
    }

    private fun teardown() {
        synchronized(lock) { stopLocked() }
    }

    private fun currentDisplaySize(): Point {
        val dm = appContext.getSystemService(Context.DISPLAY_SERVICE) as? DisplayManager
        val display = dm?.getDisplay(Display.DEFAULT_DISPLAY) ?: return Point(0, 0)
        val metrics = android.util.DisplayMetrics()
        @Suppress("DEPRECATION")
        display.getRealMetrics(metrics)
        return Point(metrics.widthPixels, metrics.heightPixels)
    }

    private fun acquireBitmap(): Bitmap? {
        val image = acquireImage(ACQUIRE_TIMEOUT_MS) ?: return null
        return try {
            imageToBitmap(image)
        } catch (e: Throwable) {
            Log.e(TAG, "Ошибка конвертации кадра", e)
            null
        } finally {
            runCatching { image.close() }
        }
    }

    @Suppress("DEPRECATION")
    private fun acquireImage(timeoutMs: Long): Image? {
        val reader = synchronized(lock) { imageReader } ?: return null
        val deadline = SystemClock.uptimeMillis() + timeoutMs
        while (true) {
            if (!isRunning) return null
            val left = deadline - SystemClock.uptimeMillis()
            if (left <= 0) return null
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
                val img = runCatching { reader.acquireNextImage(left) }.getOrNull()
                if (img != null) return img
            } else {
                val img = runCatching { reader.acquireNextImage() }.getOrNull()
                if (img != null) return img
                runCatching { Thread.sleep(4) }
            }
        }
    }

    private fun imageToBitmap(image: Image): Bitmap? {
        val plane = image.planes.getOrNull(0) ?: return null
        val width = image.width
        val height = image.height
        val pixelStride = plane.pixelStride
        val rowStride = plane.rowStride
        val rowBytes = width * pixelStride
        val buffer = plane.buffer
        buffer.rewind()

        if (rowBytes <= 0 || rowStride < rowBytes || (height - 1) * rowStride + rowBytes > buffer.capacity()) {
            Log.w(TAG, "Неожиданная геометрия буфера: rowStride=$rowStride cap=${buffer.capacity()}")
            return null
        }

        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        if (pixelStride == 4 && rowStride == rowBytes) {
            // Быстрый путь: плотный буфер, ARGB_8888 в памяти совпадает с RGBA байтами.
            buffer.position(0)
            buffer.limit(rowBytes * height)
            bitmap.copyPixelsFromBuffer(buffer)
            return bitmap
        }

        val row = ByteArray(rowBytes)
        val pixels = IntArray(width * height)
        for (y in 0 until height) {
            buffer.position(y * rowStride)
            buffer.get(row, 0, rowBytes)
            val out = y * width
            for (x in 0 until width) {
                val o = x * pixelStride
                val a = if (pixelStride >= 4) row[o + 3].toInt() and 0xFF else 255
                val r = row[o].toInt() and 0xFF
                val g = row[o + 1].toInt() and 0xFF
                val b = row[o + 2].toInt() and 0xFF
                pixels[out + x] = (a shl 24) or (r shl 16) or (g shl 8) or b
            }
        }
        bitmap.setPixels(pixels, 0, width, 0, 0, width, height)
        return bitmap
    }

    companion object {
        private const val TAG = "ScreenOCR"
        private const val VIRTUAL_DISPLAY_NAME = "screenocr-capture"
        private const val MAX_IMAGES = 2
        private const val ACQUIRE_TIMEOUT_MS = 400L
    }
}

