package com.screenocr.tts.capture

import android.graphics.Bitmap
import android.util.Log
import com.screenocr.tts.core.OcrLine
import com.screenocr.tts.core.OcrResult
import com.screenocr.tts.core.Region
import com.screenocr.tts.core.TextHeuristics
import com.screenocr.tts.ocr.OcrEngine
import com.screenocr.tts.settings.Settings
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext

/** Метрика одного прохода сканирования (аналог on_scan_timing в scanner.py). */
data class ScanTiming(
    val durationMs: Long,
    val text: String,
    val confidence: Float,
    val skipped: Boolean,
)

/** Публичный статус сканера для UI (порт get_status из scanner.py). */
data class ScannerStatus(
    val running: Boolean = false,
    val paused: Boolean = false,
    val intervalMs: Int = 0,
    val detectChanges: Boolean = true,
    val regions: Int = 0,
    val scans: Long = 0,
    val skipped: Long = 0,
    val lastText: String = "",
    val lastDurationMs: Long = 0,
    val lastError: String? = null,
)

/**
 * Порт scanner.py: цикл захвата + детекция изменений кадра + OCR.
 *
 * Отличия от десктопа, вызванные платформой:
 *  - детекция изменений сделана как downsample 64x64 + средняя разница
 *    с порогом Settings.Ocr.CHANGE_THRESHOLD (на десктопе это был хеш
 *    трёх средних, он давал ложные срабатывания на шумах);
 *  - вместо файлов ocr_logs_simple пишем в Logcat.
 */
class ScreenScanner(
    private val capture: ScreenCapture,
    private val settings: Settings,
    private val scope: CoroutineScope,
    engine: OcrEngine,
) {

    var engine: OcrEngine = engine
        private set

    var intervalMs: Int = settings.get(Settings.Ocr.SCAN_INTERVAL_MS, DEFAULT_INTERVAL_MS)
        private set

    var detectChanges: Boolean = settings.get(Settings.Ocr.DETECT_CHANGES, true)
        private set

    private var changeThreshold: Float =
        settings.get(Settings.Ocr.CHANGE_THRESHOLD, 0.05f).coerceIn(0.0005f, 1f)

    private val minConfidence: Int = settings.get(Settings.Ocr.CONFIDENCE, 40)

    @Volatile private var regions: List<Region> = emptyList()
    @Volatile private var running = false
    @Volatile private var paused = false

    private var loopJob: Job? = null
    private var lastScanAt = 0L
    private var scans = 0L
    private var skipped = 0L
    private var lastError: String? = null

    private val debugLogging =
        settings.get(Settings.General.LOG_LEVEL, "INFO").equals("DEBUG", ignoreCase = true)

    // Кэш "уже произнесённого" текста - порт _text_changed из scanner.py
    private val textCache = LinkedHashMap<String, Long>()
    private val cacheLock = Any()
    private var lastCacheCleanup = 0L
    private var lastText = ""

    // Отпечаток кадра для детекции изменений
    private var prevSignature: FloatArray? = null
    private val diffBuffer = FloatArray(SIG_SIZE * SIG_SIZE)
    private val includeMask = BooleanArray(SIG_SIZE * SIG_SIZE)

    private val _status = MutableStateFlow(ScannerStatus(intervalMs = intervalMs, detectChanges = detectChanges))
    val status: StateFlow<ScannerStatus> = _status.asStateFlow()

    var onTextDetected: ((String) -> Unit)? = null
    var onResult: ((OcrResult) -> Unit)? = null
    var onScanTiming: ((ScanTiming) -> Unit)? = null
    var onScanningChanged: ((Boolean) -> Unit)? = null

    init {
        buildIncludeMask()
    }

    // ── управление ─────────────────────────────────────────────

    fun setEngine(engine: OcrEngine) {
        this.engine = engine
    }

    fun setRegions(list: List<Region>) {
        regions = list
        clearCache()
        publish()
    }

    fun start() {
        if (running) {
            Log.w(TAG, "Сканирование уже запущено")
            return
        }
        running = true
        paused = false
        lastScanAt = 0L
        loopJob = scope.launch(Dispatchers.Default) { scanLoop() }
        onScanningChanged?.invoke(true)
        publish()
        Log.i(TAG, "ScreenScanner запущен, интервал ${intervalMs}мс")
    }

    fun stop() {
        if (!running) return
        running = false
        loopJob?.cancel()
        loopJob = null
        onScanningChanged?.invoke(false)
        publish()
        Log.i(TAG, "ScreenScanner остановлен")
    }

    fun pause() {
        paused = true
        publish()
    }

    fun resume() {
        paused = false
        publish()
    }

    fun togglePause() {
        if (paused) resume() else pause()
    }

    fun setInterval(interval: Int) {
        val value = interval.coerceAtLeast(MIN_INTERVAL_MS)
        intervalMs = value
        settings.set(Settings.Ocr.SCAN_INTERVAL_MS, value)
        publish()
        Log.i(TAG, "Интервал сканирования: ${value}мс")
    }

    fun setDetectChanges(enabled: Boolean) {
        detectChanges = enabled
        settings.set(Settings.Ocr.DETECT_CHANGES, enabled)
        if (!enabled) {
            synchronized(cacheLock) { prevSignature = null }
        }
        publish()
        Log.i(TAG, "Детекция изменений: ${if (enabled) "вкл" else "выкл"}")
    }

    fun setChangeThreshold(value: Float) {
        changeThreshold = value.coerceIn(0.0005f, 1f)
        settings.set(Settings.Ocr.CHANGE_THRESHOLD, changeThreshold)
    }

    fun clearCache() {
        synchronized(cacheLock) {
            textCache.clear()
            prevSignature = null
            lastText = ""
            lastCacheCleanup = 0L
        }
        publish()
    }

    /** Однократное сканирование по кнопке "Сканировать". */
    suspend fun scanOnce(): OcrResult? = withContext(Dispatchers.Default) { runScan() }

    // ── цикл ───────────────────────────────────────────────────

    private suspend fun scanLoop() {
        Log.i(TAG, "Запуск цикла сканирования")
        while (isActive && running) {
            if (paused) {
                delay(100)
                continue
            }
            val elapsed = System.currentTimeMillis() - lastScanAt
            if (elapsed < intervalMs) {
                delay((intervalMs - elapsed).coerceAtMost(500L))
                continue
            }
            lastScanAt = System.currentTimeMillis()
            try {
                runScan()
            } catch (e: CancellationException) {
                throw e
            } catch (e: Throwable) {
                lastError = e.message ?: e::class.java.simpleName
                Log.e(TAG, "Ошибка в цикле сканирования: $lastError", e)
                publish()
                delay(1000)
            }
        }
        Log.i(TAG, "Цикл сканирования остановлен")
    }

    private suspend fun runScan(): OcrResult? {
        val t0 = System.currentTimeMillis()
        val active = regions.filter { it.enabled }
        val first: Bitmap? = if (active.isEmpty()) capture.captureFull()
        else capture.captureRegion(active.first())

        if (first == null) {
            if (debugLogging) Log.d(TAG, "[SCAN] кадр недоступен")
            delay(100)
            return null
        }

        if (detectChanges && !detectFrameChange(first)) {
            first.recycle()
            skipped++
            onScanTiming?.invoke(ScanTiming(System.currentTimeMillis() - t0, "", 0f, true))
            if (debugLogging) Log.d(TAG, "[SCAN] изменений нет, OCR пропущен")
            publish()
            delay(50)
            return null
        }

        val result = try {
            if (active.size <= 1) {
                recognize(first)
            } else {
                first.recycle()
                recognizeAll(active)
            }
        } finally {
            if (!first.isRecycled) first.recycle()
        }

        scans++
        val duration = System.currentTimeMillis() - t0
        val accepted = applyConfidenceFilter(result)
        onResult?.invoke(accepted)
        logOcrResult(accepted, duration)

        if (accepted.text.isNotBlank() && textChanged(accepted.text)) {
            onTextDetected?.invoke(accepted.text)
        }
        onScanTiming?.invoke(ScanTiming(duration, accepted.text, accepted.confidence, false))
        if (lastError != null) lastError = null
        publish()
        return accepted
    }

    private suspend fun recognize(bitmap: Bitmap): OcrResult = engine.recognize(bitmap)

    private suspend fun recognizeAll(list: List<Region>): OcrResult {
        val lines = ArrayList<OcrLine>()
        val text = StringBuilder()
        var confSum = 0f
        var confCount = 0
        var elapsed = 0L
        for (region in list) {
            val bmp = capture.captureRegion(region) ?: continue
            val res = try {
                recognize(bmp)
            } finally {
                if (!bmp.isRecycled) bmp.recycle()
            }
            elapsed += res.elapsedMs
            if (res.text.isBlank()) continue
            if (text.isNotEmpty()) text.append('\n')
            text.append(res.text)
            lines.addAll(res.lines)
            confSum += res.confidence
            confCount++
        }
        val confidence = if (confCount == 0) 0f else confSum / confCount
        return OcrResult(text.toString(), confidence, lines, engine.id, elapsed)
    }

    private fun applyConfidenceFilter(result: OcrResult): OcrResult {
        // Движок может не отдавать confidence (0) - тогда результат принимается как есть.
        if (result.confidence <= 0f) return result
        if (result.confidence * 100f >= minConfidence) return result
        if (debugLogging) {
            Log.d(TAG, "[OCR-LOG] отброшено по confidence ${result.confidence}")
        }
        return OcrResult("", 0f, emptyList(), result.engine, result.elapsedMs)
    }

    private fun logOcrResult(result: OcrResult, durationMs: Long) {
        if (!debugLogging) return
        val normalized = if (result.text.isBlank()) "(empty)" else TextHeuristics.normalize(result.text)
        Log.d(
            TAG,
            "[OCR-LOG] ${durationMs}ms conf=${(result.confidence * 100).toInt()}% " +
                "engine=${result.engine} raw=\"${result.text.take(60)}\" norm=\"$normalized\"",
        )
    }

    // ── детекция изменений кадра ───────────────────────────────

    /**
     * Порядок как в scanner.py: центральная половина кадра (по краям обычно
     * статичный chrome), downsample до 64x64 в градациях серого, средняя
     * абсолютная разница с предыдущим кадром. Центральные 5% исключены -
     * там может быть курсор/системный жест.
     */
    private fun detectFrameChange(bitmap: Bitmap): Boolean {
        val current = signature(bitmap) ?: return true
        synchronized(cacheLock) {
            val previous = prevSignature
            prevSignature = current
            if (previous == null) return true

            var sum = 0f
            var count = 0
            for (i in diffBuffer.indices) {
                if (!includeMask[i]) continue
                sum += kotlin.math.abs(diffBuffer[i] - previous[i])
                count++
            }
            if (count == 0) {
                for (i in diffBuffer.indices) {
                    sum += kotlin.math.abs(diffBuffer[i] - previous[i])
                    count++
                }
            }
            val mean = sum / count
            val normalized = mean / 255f
            if (normalized > changeThreshold) {
                if (debugLogging) Log.d(TAG, "[SCAN] изменение кадра diff=${"%.4f".format(normalized)}")
                return true
            }
            return false
        }
    }

    private fun signature(bitmap: Bitmap): FloatArray? {
        var src: Bitmap? = null
        var crop: Bitmap? = null
        return try {
            val cx1 = bitmap.width / 4
            val cy1 = bitmap.height / 4
            val cw = (bitmap.width * 2) / 4
            val ch = (bitmap.height * 2) / 4
            if (cw <= 0 || ch <= 0) return null
            src = Bitmap.createBitmap(bitmap, cx1, cy1, cw, ch)
            crop = Bitmap.createScaledBitmap(src, SIG_SIZE, SIG_SIZE, true)
            val pixels = IntArray(SIG_SIZE * SIG_SIZE)
            crop.getPixels(pixels, 0, SIG_SIZE, 0, 0, SIG_SIZE, SIG_SIZE)
            val out = FloatArray(SIG_SIZE * SIG_SIZE)
            for (i in out.indices) {
                val p = pixels[i]
                val r = (p shr 16) and 0xFF
                val g = (p shr 8) and 0xFF
                val b = p and 0xFF
                out[i] = 0.299f * r + 0.587f * g + 0.114f * b
            }
            out
        } catch (e: Throwable) {
            Log.e(TAG, "Не удалось посчитать отпечаток кадра", e)
            null
        } finally {
            runCatching { crop?.recycle() }
            runCatching { src?.recycle() }
        }
    }

    private fun buildIncludeMask() {
        val marginX = (SIG_SIZE * 0.05f).toInt().coerceAtLeast(1)
        val marginY = (SIG_SIZE * 0.05f).toInt().coerceAtLeast(1)
        val cx = SIG_SIZE / 2
        val cy = SIG_SIZE / 2
        val r = (SIG_SIZE * 0.05f).toInt().coerceAtLeast(1)
        for (y in 0 until SIG_SIZE) {
            for (x in 0 until SIG_SIZE) {
                val inCursor = x >= cx - r && x < cx + r && y >= cy - r && y < cy + r
                val onEdge = x < marginX || y < marginY ||
                    x >= SIG_SIZE - marginX || y >= SIG_SIZE - marginY
                includeMask[y * SIG_SIZE + x] = !inCursor && !onEdge
            }
        }
    }

    // ── кэш текста (порт _text_changed / _cleanup_text_cache) ──

    private fun textChanged(text: String): Boolean {
        if (text.isBlank()) return false
        val normalized = TextHeuristics.normalize(text)
        val key = normalized.trimEnd('.', ',', '!', '?', ':', ';', '-')
        if (key.length <= 3) return false

        val now = System.currentTimeMillis()
        synchronized(cacheLock) {
            if (now - lastCacheCleanup > CACHE_CLEANUP_MS) cleanupTextCache(now, cacheLock)

            if (textCache.containsKey(key)) {
                textCache[key] = now
                return false
            }

            if (lastText.isNotEmpty()) {
                val sim = TextHeuristics.similarity(key, lastText)
                if (sim > SIM_SIMILAR) {
                    if (key.length > lastText.length) {
                        textCache[key] = now
                        lastText = key
                    }
                    return false
                }
            }

            for (cached in textCache.keys) {
                if (cached.contains(key) || key.contains(cached)) {
                    textCache[cached] = now
                    return false
                }
            }

            textCache[key] = now
            lastText = key
            return true
        }
    }

    private fun cleanupTextCache(now: Long, lock: Any) {
        if (lock !== cacheLock) return
        val expired = textCache.keys.filter { (now - (textCache[it] ?: 0L)) > CACHE_TTL_MS }
        for (k in expired) textCache.remove(k)
        lastCacheCleanup = now
        if (expired.isNotEmpty() && debugLogging) {
            Log.d(TAG, "[OCR-LOG] кэш очищен: -${expired.size}, осталось ${textCache.size}")
        }
    }

    private fun publish() {
        _status.value = ScannerStatus(
            running = running,
            paused = paused,
            intervalMs = intervalMs,
            detectChanges = detectChanges,
            regions = regions.count { it.enabled },
            scans = scans,
            skipped = skipped,
            lastText = lastText,
            lastDurationMs = 0L,
            lastError = lastError,
        )
    }

    companion object {
        private const val TAG = "ScreenOCR"
        private const val DEFAULT_INTERVAL_MS = 700
        private const val MIN_INTERVAL_MS = 120
        private const val SIG_SIZE = 64
        private const val CACHE_TTL_MS = 1000L
        private const val CACHE_CLEANUP_MS = 5000L
        private const val SIM_SIMILAR = 0.85f
    }
}

