package com.screenocr.tts.overlay

import android.app.Activity
import android.content.Context
import android.content.Intent
import android.net.Uri
import android.provider.Settings as AndroidSettings
import androidx.activity.result.ActivityResultLauncher
import androidx.activity.result.contract.ActivityResultContracts

/**
 * Проверка и запрос разрешения на оверлеи (SYSTEM_ALERT_WINDOW).
 *
 * ВАЖНО: это НЕ runtime-разрешение, поэтому ActivityResultContracts.RequestPermission
 * для него не работает - Android его просто не выдаёт. Нужен переход в настройки
 * с колбэком, то есть ActivityResultContracts.StartActivityForResult.
 */
object OverlayPermission {

    fun canDrawOverlays(context: Context): Boolean =
        AndroidSettings.canDrawOverlays(context)

    /** Intent для системного экрана «Отображение поверх других приложений». */
    fun settingsIntent(context: Context): Intent =
        Intent(
            AndroidSettings.ACTION_MANAGE_OVERLAY_PERMISSION,
            Uri.parse("package:" + context.packageName),
        )

    /**
     * Регистрация запроса разрешения. Вызывать из Activity (onCreate).
     *
     * ```
     * private val overlayPermission = OverlayPermission.register(this) { granted ->
     *     if (granted) startCapture() else showOverlayRationale()
     * }
     * // кнопка:
     * if (OverlayPermission.canDrawOverlays(this)) startCapture()
     * else overlayPermission.launch(Unit)
     * ```
     */
    fun register(
        activity: Activity,
        onResult: (granted: Boolean) -> Unit,
    ): ActivityResultLauncher<Unit> {
        val launcher = activity.registerForActivityResult(
            ActivityResultContracts.StartActivityForResult(),
        ) {
            onResult(canDrawOverlays(activity))
        }
        return ActivityResultLauncher<Unit> { launcher.launch(settingsIntent(activity)) }
    }
}

/**
 * Запрос согласия на захват экрана (MediaProjection).
 *
 * Тоже не runtime-разрешение: нужен системный диалог, результат приходит
 * в Activity, а дальше Intent передаётся в CaptureService.
 */
object MediaProjectionPermission {

    fun createScreenCaptureIntent(context: Context): Intent? = runCatching {
        val manager = context.getSystemService(android.media.projection.MediaProjectionManager::class.java)
        manager?.createScreenCaptureIntent()
    }.getOrNull()

    /**
     * ```
     * private val screenCapture = MediaProjectionPermission.register(this) { result ->
     *     if (result != null) CaptureService.startCapture(this, result.first, result.second)
     * }
     * screenCapture.launch(Unit)
     * ```
     */
    fun register(
        activity: Activity,
        onResult: (result: Pair<Int, Intent>?) -> Unit,
    ): ActivityResultLauncher<Unit> {
        val launcher = activity.registerForActivityResult(
            ActivityResultContracts.StartActivityForResult(),
        ) { res ->
            if (res.resultCode == Activity.RESULT_OK && res.data != null) {
                onResult(res.resultCode to res.data)
            } else {
                onResult(null)
            }
        }
        return ActivityResultLauncher<Unit> { launcher.launch(createScreenCaptureIntent(activity)) }
    }
}

