     * ```
     * private val overlayPermission = OverlayPermission.register(this) { granted ->
     *     if (granted) startCapture() else showRationale()
     * }
     * // кнопка "Показать оверлеи":
     * if (OverlayPermission.canDrawOverlays(this)) attachOverlays()
     * else overlayPermission.launch()
     * ```
     */
    fun register(activity: Activity, onResult: (granted: Boolean) -> Unit): ActionLauncher {
        val launcher = activity.registerForActivityResult(
            ActivityResultContracts.StartActivityForResult(),
        ) { onResult(canDrawOverlays(activity)) }
        return ActionLauncher { launcher.launch(settingsIntent(activity)) }
    }
}

/**
 * Запрос согласия на захват экрана (MediaProjection).
 *
 * Тоже не runtime-разрешение: показывается системный диалог, результат приходит
 * в Activity, а Intent передаётся в CaptureService.
 */
object MediaProjectionPermission {

    fun createScreenCaptureIntent(context: Context): Intent? = runCatching {
        context.getSystemService(MediaProjectionManager::class.java)
            ?.createScreenCaptureIntent()
    }.getOrNull()

    /**
     * ```
     * private val screenCapture = MediaProjectionPermission.register(this) { result ->
     *     if (result != null) CaptureService.startCapture(this, result.first, result.second)
     *     else Log.i("ScreenOCR", "Пользователь отказал в захвате экрана")
     * }
     * screenCapture.launch()
     * ```
     */
    fun register(
        activity: Activity,
        onResult: (result: Pair<Int, Intent>?) -> Unit,
    ): ActionLauncher {
        val launcher = activity.registerForActivityResult(
            ActivityResultContracts.StartActivityForResult(),
        ) { res ->
            if (res.resultCode == Activity.RESULT_OK && res.data != null) {
                onResult(res.resultCode to res.data)
            } else {
                onResult(null)
            }
        }
        return ActionLauncher { launcher.launch(createScreenCaptureIntent(activity)) }
    }
}

package com.screenocr.tts.overlay

import android.annotation.SuppressLint
import android.content.Context
import android.content.res.Resources
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.DashPathEffect
import android.graphics.Paint
import android.graphics.Path
import android.graphics.Point
import android.graphics.Rect
import android.graphics.RectF
import android.hardware.display.DisplayManager
import android.net.ConnectivityManager
import android.net.NetworkCapabilities
import android.os.Handler
import android.os.Looper
import android.util.Log
import android.util.TypedValue
import android.view.Gravity
import android.view.MotionEvent
import android.view.View
import android.view.ViewConfiguration
import android.view.WindowManager
import android.view.WindowManager.LayoutParams
import com.screenocr.tts.capture.RegionStore
import com.screenocr.tts.core.Region
import com.screenocr.tts.settings.Settings
import java.util.concurrent.atomic.AtomicBoolean

/** Регион + состояние, которого нет в core.Region (порт dict из region_overlay.py). */
data class OverlayRegion(
    val region: Region,
    val locked: Boolean = false,
    val panelVisible: Boolean = true,
)

/**
 * Порт region_overlay.py на WindowManager + TYPE_APPLICATION_OVERLAY.
 *
 * Окна намеренно разбиты на несколько:
 *  - один полноэкранный слой только рисует рамки (FLAG_NOT_TOUCHABLE) и
 *    пропускает ВСЕ касания приложению под ним;
 *  - на каждый регион - три маленьких кликабельных слоя: name bar (перетаскивание,
 *    ▼/▶, контекстное меню по долгому тапу), маркер в углу (изменение размера)
 *    и панель голоса (кнопки). Они реализуют порт _is_on_border/_is_on_handle
 *    и hit-test VoicePanel.
 *
 * Так касания вне регионов физически не перехватываются - в отличие от
 * полноэкранного touchable-окна. Заодно уходит баг десктопной версии, где
 * координаты кнопок считались в локальной системе окна, а сравнивались
 * с системными: здесь ВСЕ прямоугольники живут в координатах экрана
 * (см. [Slot]), а View рисует их со сдвигом на свой getLocationOnScreen.
 */
class RegionOverlay(
    context: Context,
    private val settings: Settings,
    private val listener: Listener? = null,
) {

    interface Listener {
        fun onStartClicked() {}
        fun onStopClicked() {}
        fun onScanRequested() {}
        fun onMicToggled() {}
        fun onRoleSelected(role: String) {}
        fun onRoleMenuRequested(role: String, screenX: Int, screenY: Int) {}
        fun onPanelToggled(index: Int, visible: Boolean) {}
        fun onRegionChanged(index: Int, region: Region) {}
        fun onRegionTapped(index: Int, screenX: Int, screenY: Int) {}
        fun onRegionsReplaced(regions: List<Region>) {}
        fun onPermissionRequired() {}
    }

    // ── состояние ──────────────────────────────────────────────

    private val res: Resources = context.resources
    private val displayContext: Context = runCatching {
        val dm = context.applicationContext.getSystemService(Context.DISPLAY_SERVICE) as DisplayManager
        val display = dm.getDisplay(android.view.Display.DEFAULT_DISPLAY)
        if (display != null) context.createDisplayContext(display) else context.applicationContext
    }.getOrDefault(context.applicationContext)

    private val wm = displayContext.getSystemService(Context.WINDOW_SERVICE) as WindowManager
    private val main = Handler(Looper.getMainLooper())
    private val touchSlop = ViewConfiguration.get(displayContext).scaledTouchSlop.toFloat()

    private val density = res.displayMetrics.density
    private val nameH = dp(28f)
    private val toggleW = dp(26f)
    private val handleSize = dp(26f)
    private val handleTol = dp(16f)
    private val borderTol = dp(10f)
    private val panelH = dp(36f)
    private val btn = dp(28f)
    private val gap = dp(3f)
    private val panelGapBelow = dp(10f)
    private val panelGapAbove = dp(8f)
    private val minSide = dp(56f)
    private val cornerR = dp(5f)

    private val nameBarFlags =
        LayoutParams.FLAG_NOT_FOCUSABLE or
            LayoutParams.FLAG_NOT_TOUCH_MODAL or
            LayoutParams.FLAG_LAYOUT_NO_LIMITS or
            LayoutParams.FLAG_HARDWARE_ACCELERATED

    private val slots = ArrayList<Slot>()
    private var decorView: DecorView? = null
    private var attached = false
    private var editMode = true

    private var scanning = false
    private var sttActive = false
    private var sttText = ""
    private var lastOcrText = ""
    private var lastScanSeconds = 0f
    private var lastConfidence = 0f
    private var scanPulse = 0
    private var sttBlink = 0
    private var online = true
    private var activeRole = ROLE_MALE

    private var frameOpacity = (settings.get(Settings.Overlay.OPACITY, 0.85f) * 100f).toInt()
        .coerceIn(10, 100)
    private var panelOpacity =
        (settings.get(Settings.Overlay.PANEL_OPACITY, 0.9f) * 100f).toInt().coerceIn(10, 100)

    private val ticking = AtomicBoolean(false)

    private val ticker = object : Runnable {
        override fun run() {
            var dirty = false
            if (scanning) {
                scanPulse = (scanPulse + 1) % 20
                dirty = true
            }
            if (sttActive) {
                sttBlink = (sttBlink + 1) % 8
                dirty = true
            }
            if (dirty) invalidateAll()
            if (dirty || sttActive) main.postDelayed(this, TICK_MS)
        }
    }

    private val connectivityTick = object : Runnable {
        override fun run() {
            online = checkOnline()
            invalidateAll()
            main.postDelayed(this, CONNECTIVITY_TICK_MS)
        }
    }

    // ── публичный API ──────────────────────────────────────────

    val isAttached: Boolean get() = attached

    val permissionGranted: Boolean get() = OverlayPermission.canDrawOverlays(displayContext)

    fun regions(): List<Region> = slots.map { it.model.region }

    fun locked(index: Int): Boolean = slotOrNull(index)?.model?.locked == true

    fun attach(regions: List<Region> = RegionStore.load(displayContext)) {
        if (attached) return
        if (!permissionGranted) {
            Log.w(TAG, "Нет разрешения на оверлеи, оверлей не показан")
            listener?.onPermissionRequired()
            return
        }
        setRegions(regions)
        val decor = DecorView(displayContext)
        decorView = decor
        val lp = LayoutParams(
            LayoutParams.MATCH_PARENT,
            LayoutParams.MATCH_PARENT,
            LayoutParams.TYPE_APPLICATION_OVERLAY,
            LayoutParams.FLAG_NOT_TOUCHABLE or
                LayoutParams.FLAG_NOT_FOCUSABLE or
                LayoutParams.FLAG_LAYOUT_NO_LIMITS or
                LayoutParams.FLAG_HARDWARE_ACCELERATED,
            android.graphics.PixelFormat.TRANSLUCENT,
        ).apply { gravity = Gravity.TOP or Gravity.START }
        if (!addView(decor, lp)) return
        attached = true
        online = checkOnline()
        main.post(ticker)
        main.postDelayed(connectivityTick, CONNECTIVITY_TICK_MS)
        Log.i(TAG, "Оверлей регионов показан, регионов: ${slots.size}")
    }

    fun detach() {
        if (!attached) return
        attached = false
        main.removeCallbacksAndMessages(null)
        main.removeCallbacks(ticker)
        main.removeCallbacks(connectivityTick)
        for (slot in slots) {
            removeView(slot.nameView)
            removeView(slot.handleView)
            removeView(slot.panelView)
        }
        decorView?.let { removeView(it) }
        decorView = null
        Log.i(TAG, "Оверлей регионов скрыт")
    }

    fun setRegions(list: List<Region>) {
        val keep = LinkedHashMap<String, OverlayRegion>()
        for (slot in slots) keep[slot.model.region.name] = slot.model
        for (slot in slots) {
            removeView(slot.nameView)
            removeView(slot.handleView)
            removeView(slot.panelView)
        }
        slots.clear()
        list.forEachIndexed { index, region ->
            val prev = keep[region.name]
            val clamped = region.clampTo(screenWidth(), screenHeight())
            val slot = Slot(
                index,
                OverlayRegion(
                    region = clamped,
                    locked = prev?.locked ?: false,
                    panelVisible = prev?.panelVisible ?: true,
                ),
                this,
            )
            slots.add(slot)
            if (attached) slot.install()
        }
        recompute()
        invalidateAll()
    }

    fun setLocked(index: Int, locked: Boolean) {
        val slot = slotOrNull(index) ?: return
        slot.model = slot.model.copy(locked = locked)
        invalidateAll()
    }

    fun setPanelVisible(index: Int, visible: Boolean) {
        val slot = slotOrNull(index) ?: return
        if (slot.model.panelVisible == visible) return
        slot.model = slot.model.copy(panelVisible = visible)
        if (visible) {
            recompute()
            if (attached) slot.installPanel()
        } else {
            removeView(slot.panelView)
        }
        invalidateAll()
        listener?.onPanelToggled(index, visible)
    }

    fun setEditMode(enabled: Boolean) {
        editMode = enabled
        for (slot in slots) {
            if (enabled) {
                if (attached) slot.install()
            } else {
                removeView(slot.nameView)
                removeView(slot.handleView)
                removeView(slot.panelView)
            }
        }
        invalidateAll()
    }

    fun setScanning(state: Boolean) {
        if (scanning == state) return
        scanning = state
        if (state) {
            scanPulse = 0
            startTicker()
        }
        invalidateAll()
    }

    fun setSttActive(state: Boolean) {
        if (sttActive == state) return
        sttActive = state
        if (state) {
            sttBlink = 0
            startTicker()
        }
        invalidateAll()
    }

    fun setSttText(text: String) {
        sttText = text.take(60)
        invalidateAll()
    }

    fun setActiveRole(role: String) {
        activeRole = role
        for (slot in slots) slot.panelView?.invalidate()
    }

    /** Порт RegionOverlay.set_ocr_text. */
    fun setOcrText(text: String, scanSeconds: Float = 0f, confidence: Float = 0f) {
        lastOcrText = text.take(80)
        if (scanSeconds > 0f) lastScanSeconds = scanSeconds
        if (confidence > 0f) lastConfidence = confidence
        decorView?.invalidate()
    }

    fun setOpacity(frame: Int, panel: Int) {
        if (frame in 1..100) {
            frameOpacity = frame
            settings.set(Settings.Overlay.OPACITY, frame / 100f)
        }
        if (panel in 1..100) {
            panelOpacity = panel
            settings.set(Settings.Overlay.PANEL_OPACITY, panel / 100f)
        }
        invalidateAll()
    }

    // ── геометрия (порт _layout_panels) ────────────────────────

    private inner class Slot(val index: Int, var model: OverlayRegion, private val owner: RegionOverlay) {
        val frame = Rect()
        val name = Rect()
        val toggle = Rect()
        val handle = Rect()
        val panel = Rect()
        val male = Rect()
        val female = Rect()
        val narrator = Rect()
        val mic = Rect()
        val start = Rect()
        val stop = Rect()

        var nameView: NameBarView? = null
        var handleView: HandleView? = null
        var panelView: PanelView? = null

        fun install() {
            if (nameView == null) {
                nameView = NameBarView(displayContext, this)
                handleView = HandleView(displayContext, this)
                panelView = PanelView(displayContext, this)
            }
            installName()
            installHandle()
            installPanel()
        }

        fun installName() {
            val v = nameView ?: return
            if (!editMode || model.locked) {
                removeView(v)
                return
            }
            if (!addView(v, layout(name))) {
                removeView(v)
            } else {
                v.invalidate()
            }
        }

        fun installHandle() {
            val v = handleView ?: return
            if (!editMode || model.locked) {
                removeView(v)
                return
            }
            if (!addView(v, layout(handle))) {
                removeView(v)
            } else {
                v.invalidate()
            }
        }

        fun installPanel() {
            val v = panelView ?: return
            if (!editMode || !model.panelVisible) {
                removeView(v)
                return
            }
            if (!addView(v, layout(panel))) {
                removeView(v)
            } else {
                v.invalidate()
            }
        }

        fun layout(rect: Rect): LayoutParams = LayoutParams(
            rect.width().coerceAtLeast(1),
            rect.height().coerceAtLeast(1),
            LayoutParams.TYPE_APPLICATION_OVERLAY,
            nameBarFlags,
            android.graphics.PixelFormat.TRANSLUCENT,
        ).apply {
            gravity = Gravity.TOP or Gravity.START
            x = rect.left
            y = rect.top
        }

        fun syncWindows() {
            if (nameView != null) updateView(nameView, layout(name))
            if (handleView != null) updateView(handleView, layout(handle))
            if (panelView != null) updateView(panelView, layout(panel))
        }

        fun compute() {
            val r = model.region
            frame.set(r.x, r.y, r.right, r.bottom)
            val nameTop = maxOf(0f, r.y - nameH).toInt()
            name.set(r.x, nameTop, r.x + r.width, nameTop + nameH.toInt())
            toggle.set(r.x + r.width - toggleW.toInt(), nameTop, r.x + r.width, nameTop + nameH.toInt())
            handle.set(
                (r.right - handleSize).toInt(),
                (r.bottom - handleSize).toInt(),
                r.right,
                r.bottom,
            )
            if (!model.panelVisible) return
            val sw = screenWidth()
            val sh = screenHeight()
            val pw = minOf(dp(360f), maxOf(dp(200f), r.width.toFloat())).toInt()
            val px = maxOf(0, minOf(r.x, sw - pw))
            var py = r.bottom + panelGapBelow.toInt()
            if (py + panelH.toInt() > sh) py = r.y - panelH.toInt() - panelGapAbove.toInt()
            panel.set(px, py, px + pw, py + panelH.toInt())
            val by = py + ((panelH - btn) / 2f).toInt()
            var bx = px + gap.toInt()
            male.set(bx, by, bx + btn.toInt(), by + btn.toInt()); bx += btn.toInt() + gap.toInt()
            female.set(bx, by, bx + btn.toInt(), by + btn.toInt()); bx += btn.toInt() + gap.toInt()
            narrator.set(bx, by, bx + btn.toInt(), by + btn.toInt()); bx += btn.toInt() + gap.toInt() + dp(4f).toInt()
            mic.set(bx, by, bx + btn.toInt(), by + btn.toInt()); bx += btn.toInt() + gap.toInt() + dp(8f).toInt()
            start.set(bx, by, bx + btn.toInt(), by + btn.toInt()); bx += btn.toInt() + gap.toInt()
            stop.set(bx, by, bx + btn.toInt(), by + btn.toInt())
        }
    }

    private fun recompute() {
        for (slot in slots) slot.compute()
        for (slot in slots) slot.syncWindows()
    }

    private fun invalidateAll() {
        decorView?.invalidate()
        for (slot in slots) {
            slot.nameView?.invalidate()
            slot.handleView?.invalidate()
            slot.panelView?.invalidate()
        }
    }

    private fun startTicker() {
        if (ticking.compareAndSet(false, true)) main.post(ticker)
    }

    // ── отрисовка ──────────────────────────────────────────────

    private val framePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { style = Paint.Style.STROKE }
    private val fillPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { style = Paint.Style.FILL }
    private val textPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { typeface = android.graphics.Typeface.DEFAULT_BOLD }
    private val dashEffect = DashPathEffect(floatArrayOf(dp(6f), dp(4f)), 0f)

    private fun regionColor(slot: Slot): Int {
        val raw = slot.model.region.color
        if (raw.isNotBlank()) {
            val parsed = runCatching { Color.parseColor(raw) }.getOrNull()
            if (parsed != null) return parsed
        }
        return PALETTE[slot.index % PALETTE.size]
    }

    private inner class DecorView(context: Context) : View(context) {

        override fun onDraw(canvas: Canvas) {
            if (slots.isEmpty()) return
            shiftToScreen(canvas, this)
            for (slot in slots) drawFrame(canvas, slot)
            drawOcrText(canvas)
        }

        private fun drawFrame(canvas: Canvas, slot: Slot) {
            if (slot.model.region.width <= 0 || slot.model.region.height <= 0) return
            val color = regionColor(slot)
            val alpha = (frameOpacity * 255 / 100).coerceIn(0, 255)
            framePaint.strokeWidth = dp(3f)
            framePaint.color = if (slot.model.locked) {
                Color.argb(alpha, 128, 128, 128)
            } else {
                Color.argb(alpha, Color.red(color), Color.green(color), Color.blue(color))
            }
            framePaint.pathEffect = if (slot.model.locked) dashEffect else null
            if (slot.model.region.shape.equals("ellipse", true) ||
                slot.model.region.shape.equals("oval", true)
            ) {
                val f = RectF(slot.frame)
                canvas.drawOval(f, framePaint)
            } else {
                val f = RectF(slot.frame)
                canvas.drawRoundRect(f, cornerR, cornerR, framePaint)
            }
            framePaint.pathEffect = null
        }

        private fun drawOcrText(canvas: Canvas) {
            val slot = slots.firstOrNull() ?: return
            val r = slot.model.region
            val left = r.x
            val top = r.bottom + dp(4f).toInt()
            val width = minOf(r.width.coerceAtLeast(dp(120f).toInt()), dp(500f).toInt())
            if (lastOcrText.isNotEmpty()) {
                textPaint.textSize = dp(11f)
                textPaint.color = Color.argb(140, 200, 200, 200)
                textPaint.textAlign = Paint.Align.LEFT
                canvas.save()
                canvas.clipRect(left, top, left + width, top + dp(18f).toInt())
                canvas.drawText(lastOcrText, left.toFloat(), top + dp(13f), textPaint)
                canvas.restore()
            }
            val right = if (lastScanSeconds > 0f) "%.1fs".format(lastScanSeconds) else ""
            val conf = if (lastConfidence > 0f) "${(lastConfidence * 100).toInt()}%" else ""
            val tail = listOf(right, conf).filter { it.isNotEmpty() }.joinToString("  ")
            if (tail.isNotEmpty()) {
                textPaint.textSize = dp(11f)
                textPaint.color = Color.argb(150, 76, 175, 80)
                textPaint.textAlign = Paint.Align.RIGHT
                canvas.drawText(tail, (left + width).toFloat(), top + dp(13f), textPaint)
            }
        }
    }

    /** Панель заголовка региона: имя, индикаторы, ▼/▶, перетаскивание. */
    private inner class NameBarView(context: Context, private val slot: Slot) : View(context) {

        private var downRawX = 0f
        private var downRawY = 0f
        private var downX = 0
        private var downY = 0
        private var dragging = false
        private var longPressed = false

        override fun onDraw(canvas: Canvas) {
            val r = slot.model.region
            if (r.width <= 0) return
            shiftToScreen(canvas, this)
            val color = regionColor(slot)
            val alpha = (frameOpacity * 255 / 100).coerceIn(0, 255)
            val f = RectF(slot.name)
            fillPaint.color = if (slot.model.locked) Color.argb(200, 128, 128, 128)
            else Color.argb(200, Color.red(color), Color.green(color), Color.blue(color))
            canvas.drawRect(f, fillPaint)

            var textX = slot.name.left + dp(4f)
            if (slot.model.locked) {
                fillPaint.color = Color.argb(255, 250, 204, 21)
                canvas.drawRect(
                    textX.toFloat(), slot.name.top + dp(8f),
                    textX + dp(9f), slot.name.top + dp(17f), fillPaint,
                )
                fillPaint.color = Color.argb(255, 60, 60, 60)
                canvas.drawRect(
                    textX + dp(1.5f), slot.name.top + dp(6f),
                    textX + dp(7.5f), slot.name.top + dp(11f), fillPaint,
                )
                textX += dp(13f)
            }

            textPaint.textAlign = Paint.Align.LEFT
            textPaint.textSize = dp(12f)
            textPaint.color = Color.WHITE
            val titleRight = slot.toggle.left - dp(6f)
            if (badgeBounds().left > textX) {
                textPaint.color = Color.argb(255, 255, 255, 255)
                canvas.save()
                canvas.clipRect(textX, slot.name.top, badgeBounds().left, slot.name.bottom)
                canvas.drawText(r.name, textX.toFloat(), slot.name.centerY() + dp(4.5f), textPaint)
                canvas.restore()
            } else {
                canvas.save()
                canvas.clipRect(textX, slot.name.top, titleRight, slot.name.bottom)
                canvas.drawText(r.name, textX.toFloat(), slot.name.centerY() + dp(4.5f), textPaint)
                canvas.restore()
            }

            drawBadge(canvas)

            // ▼/▶ переключатель панели
            textPaint.textAlign = Paint.Align.CENTER
            textPaint.textSize = dp(11f)
            textPaint.color = if (slot.model.panelVisible) Color.WHITE else Color.argb(180, 200, 200, 200)
            val cy = slot.name.centerY() + dp(4f)
            if (slot.model.panelVisible) {
                val cx = slot.toggle.centerX().toFloat()
                val path = Path()
                path.moveTo(cx - dp(5f), cy - dp(2f))
                path.lineTo(cx + dp(5f), cy - dp(2f))
                path.lineTo(cx, cy + dp(4f))
                path.close()
                fillPaint.color = Color.WHITE
                canvas.drawPath(path, fillPaint)
            } else {
                val cx = slot.toggle.centerX().toFloat()
                val path = Path()
                path.moveTo(cx - dp(2f), cy - dp(5f))
                path.lineTo(cx + dp(4f), cy)
                path.lineTo(cx - dp(2f), cy + dp(5f))
                path.close()
                fillPaint.color = Color.argb(190, 220, 220, 220)
                canvas.drawPath(path, fillPaint)
            }
            // Затенение, чтобы ▼ читался на цветной подложке
            fillPaint.color = Color.argb(90, 0, 0, 0)
            val _unused = alpha
        }

        private fun badgeBounds(): Rect = slot.toggle

        private fun drawBadge(canvas: Canvas) {
            if (!scanning && !sttActive) return
            val slotIndex = slot.index
            if (slotIndex != 0) return
            val y = slot.name.centerY()
            val right = slot.toggle.left - dp(6f)
            if (scanning) {
                val k = kotlin.math.abs(scanPulse - 10) / 10f
                val radius = dp(4f) + dp(3f) * k
                fillPaint.color = Color.argb((120 + 80 * k).toInt().coerceIn(0, 255), 255, 152, 0)
                canvas.drawCircle(right - dp(46f), y, radius, fillPaint)
                textPaint.textAlign = Paint.Align.LEFT
                textPaint.textSize = dp(11f)
                textPaint.color = Color.argb(220, 255, 152, 0)
                canvas.save()
                canvas.clipRect(right - dp(42f), slot.name.top, right, slot.name.bottom)
                canvas.drawText("OCR...", right - dp(38f), y + dp(4f), textPaint)
                canvas.restore()
            }
            if (sttActive) {
                val on = sttBlink < 4
                if (on) {
                    fillPaint.color = Color.argb(200, 76, 175, 80)
                    canvas.drawCircle(right - dp(46f), y, dp(5f), fillPaint)
                    textPaint.color = Color.argb(230, 76, 175, 80)
                } else {
                    textPaint.color = Color.argb(120, 76, 175, 80)
                }
                textPaint.textAlign = Paint.Align.LEFT
                textPaint.textSize = dp(11f)
                val label = "MIC " + (if (sttText.isNotEmpty()) sttText.take(18) else "...")
                canvas.save()
                canvas.clipRect(right - dp(38f), slot.name.top, right, slot.name.bottom)
                canvas.drawText(label, right - dp(38f), y + dp(4f), textPaint)
                canvas.restore()
            }
        }

        @SuppressLint("ClickableViewAccessibility")
        override fun onTouchEvent(event: MotionEvent): Boolean {
            if (!editMode) return false
            when (event.actionMasked) {
                MotionEvent.ACTION_DOWN -> {
                    downRawX = event.rawX
                    downRawY = event.rawY
                    downX = slot.model.region.x
                    downY = slot.model.region.y
                    dragging = false
                    longPressed = false
                    return true
                }

                MotionEvent.ACTION_MOVE -> {
                    if (!dragging &&
                        (kotlin.math.abs(event.rawX - downRawX) > touchSlop ||
                            kotlin.math.abs(event.rawY - downRawY) > touchSlop)
                    ) {
                        dragging = true
                    }
                    if (dragging) {
                        moveRegion(
                            (downX + (event.rawX - downRawX)).toInt(),
                            (downY + (event.rawY - downRawY)).toInt(),
                        )
                    }
                    return true
                }

                MotionEvent.ACTION_UP -> {
                    val wasDragging = dragging
                    dragging = false
                    if (!wasDragging && !longPressed) {
                        if (hit(slot.toggle, event.rawX, event.rawY, slop = 0f)) {
                            setPanelVisible(slot.index, !slot.model.panelVisible)
                        } else {
                            listener?.onRegionTapped(
                                slot.index,
                                event.rawX.toInt(),
                                event.rawY.toInt(),
                            )
                        }
                    }
                    return true
                }

                MotionEvent.ACTION_CANCEL -> {
                    dragging = false
                    return true
                }
            }
            return super.onTouchEvent(event)
        }
    }

    /** Квадратный маркер в правом нижнем углу рамки - изменение размера. */
    private inner class HandleView(context: Context, private val slot: Slot) : View(context) {

        private var downRawX = 0f
        private var downRawY = 0f
        private var downW = 0
        private var downH = 0
        private var active = false

        override fun onDraw(canvas: Canvas) {
            if (slot.model.locked) return
            shiftToScreen(canvas, this)
            val color = regionColor(slot)
            val alpha = (frameOpacity * 255 / 100).coerceIn(0, 255)
            fillPaint.color = if (active) Color.WHITE
            else Color.argb(alpha, Color.red(color), Color.green(color), Color.blue(color))
            val f = RectF(slot.handle)
            canvas.drawRoundRect(f, dp(2f), dp(2f), fillPaint)
            fillPaint.color = Color.argb(160, 0, 0, 0)
            canvas.drawRoundRect(
                RectF(
                    slot.handle.left + dp(5f),
                    slot.handle.top + handleSize - dp(5f),
                    slot.handle.right - dp(5f),
                    slot.handle.bottom - dp(5f),
                ),
                dp(1.5f), dp(1.5f), fillPaint,
            )
        }

        @SuppressLint("ClickableViewAccessibility")
        override fun onTouchEvent(event: MotionEvent): Boolean {
            if (!editMode || slot.model.locked) return false
            when (event.actionMasked) {
                MotionEvent.ACTION_DOWN -> {
                    downRawX = event.rawX
                    downRawY = event.rawY
                    downW = slot.model.region.width
                    downH = slot.model.region.height
                    active = true
                    invalidate()
                    return true
                }

                MotionEvent.ACTION_MOVE -> {
                    val r = slot.model.region
                    resizeRegion(
                        r.x,
                        r.y,
                        (downW + (event.rawX - downRawX)).toInt(),
                        (downH + (event.rawY - downRawY)).toInt(),
                    )
                    return true
                }

                MotionEvent.ACTION_UP, MotionEvent.ACTION_CANCEL -> {
                    active = false
                    invalidate()
                    return true
                }
            }
            return super.onTouchEvent(event)
        }
    }

    /** Инлайн-панель голоса (порт VoicePanel + отрисовка панели из paintEvent). */
    private inner class PanelView(context: Context, private val slot: Slot) : View(context) {

        private var downRawX = 0f
        private var downRawY = 0f
        private var longPressed = false

        override fun onDraw(canvas: Canvas) {
            if (!slot.model.panelVisible) return
            shiftToScreen(canvas, this)
            val pa = (panelOpacity * 255 / 100).coerceIn(0, 255)
            val f = RectF(slot.panel)
            fillPaint.color = Color.argb(pa, 25, 25, 35)
            canvas.drawRoundRect(f, dp(6f), dp(6f), fillPaint)
            framePaint.style = Paint.Style.STROKE
            framePaint.strokeWidth = dp(1f)
            framePaint.color = Color.argb(pa, 80, 80, 80)
            framePaint.pathEffect = null
            canvas.drawRoundRect(f, dp(6f), dp(6f), framePaint)

            drawDot(canvas, online)
            drawRole(canvas, slot.male, COLOR_MALE, GLYPH_MALE, ROLE_MALE)
            drawRole(canvas, slot.female, COLOR_FEMALE, GLYPH_FEMALE, ROLE_FEMALE)
            drawRole(canvas, slot.narrator, COLOR_NARRATOR, GLYPH_NARRATOR, ROLE_NARRATOR)
            drawMicButton(canvas)
            drawPlay(canvas, slot.start)
            drawStop(canvas, slot.stop)
        }

        private fun drawDot(canvas: Canvas, ok: Boolean) {
            val c = if (ok) Color.argb(220, 76, 175, 80) else Color.argb(220, 244, 67, 54)
            fillPaint.color = c
            val r = dp(5f).toInt()
            val cx = slot.panel.right - dp(12f).toInt() - r
            val cy = slot.panel.centerY() - r
            canvas.drawCircle(cx.toFloat(), cy.toFloat(), r.toFloat(), fillPaint)
        }

        private fun drawRole(canvas: Canvas, rect: Rect, color: Int, glyph: String, role: String) {
            val pa = (panelOpacity * 255 / 100).coerceIn(0, 255)
            val activeRoleHit = activeRole == role
            framePaint.style = Paint.Style.STROKE
            framePaint.pathEffect = null
            if (activeRoleHit) {
                framePaint.strokeWidth = dp(2f)
                framePaint.color = color
                fillPaint.color = Color.argb(40, Color.red(color), Color.green(color), Color.blue(color))
            } else {
                framePaint.strokeWidth = dp(1f)
                framePaint.color = Color.argb(150, 80, 80, 80)
                fillPaint.color = Color.argb(pa, 40, 40, 50)
            }
            val f = RectF(rect)
            canvas.drawRoundRect(f, dp(5f), dp(5f), fillPaint)
            canvas.drawRoundRect(f, dp(5f), dp(5f), framePaint)
            textPaint.textAlign = Paint.Align.CENTER
            textPaint.textSize = dp(14f)
            textPaint.color = if (activeRoleHit) color else Color.argb(180, 160, 160, 160)
            canvas.drawText(glyph, rect.centerX().toFloat(), rect.centerY() + dp(5f), textPaint)
        }

        private fun drawMicButton(canvas: Canvas) {
            val pa = (panelOpacity * 255 / 100).coerceIn(0, 255)
            val rect = slot.mic
            val on = sttActive
            framePaint.style = Paint.Style.STROKE
            framePaint.strokeWidth = dp(if (on) 2f else 1f)
            framePaint.color = if (on) COLOR_MIC else Color.argb(150, 80, 80, 80)
            framePaint.pathEffect = null
            fillPaint.color = if (on) Color.argb(60, 129, 199, 132)
            else Color.argb(pa, 40, 40, 50)
            val f = RectF(rect)
            canvas.drawRoundRect(f, dp(5f), dp(5f), fillPaint)
            canvas.drawRoundRect(f, dp(5f), dp(5f), framePaint)
            drawMicIcon(canvas, rect, if (on) COLOR_MIC else Color.argb(180, 160, 160, 160))
        }

        private fun drawMicIcon(canvas: Canvas, rect: Rect, color: Int) {
            val cx = rect.centerX().toFloat()
            val cy = rect.centerY().toFloat()
            fillPaint.color = color
            framePaint.style = Paint.Style.STROKE
            framePaint.strokeWidth = dp(1.6f)
            framePaint.color = color
            framePaint.pathEffect = null
            val capsule = RectF(
                cx - dp(2.4f), cy - dp(6f),
                cx + dp(2.4f), cy + dp(1.5f),
            )
            canvas.drawRoundRect(capsule, dp(2.4f), dp(2.4f), fillPaint)
            val arc = RectF(cx - dp(5f), cy - dp(4f), cx + dp(5f), cy + dp(4f))
            canvas.drawArc(arc, 0f, 180f, false, framePaint)
            canvas.drawLine(cx, cy + dp(4f), cx, cy + dp(6.5f), framePaint)
            canvas.drawLine(cx - dp(3f), cy + dp(6.5f), cx + dp(3f), cy + dp(6.5f), framePaint)
        }

        private fun drawPlay(canvas: Canvas, rect: Rect) {
            val pa = (panelOpacity * 255 / 100).coerceIn(0, 255)
            framePaint.style = Paint.Style.STROKE
            framePaint.strokeWidth = dp(1f)
            framePaint.color = Color.argb(pa, 40, 100, 40)
            framePaint.pathEffect = null
            fillPaint.color = Color.argb(pa, 30, 80, 30)
            val f = RectF(rect)
            canvas.drawRoundRect(f, dp(5f), dp(5f), fillPaint)
            canvas.drawRoundRect(f, dp(5f), dp(5f), framePaint)
            fillPaint.color = Color.argb(pa, 129, 199, 132)
            val path = Path()
            path.moveTo(rect.left + rect.width() * 0.32f, rect.top + rect.height() * 0.24f)
            path.lineTo(rect.left + rect.width() * 0.32f, rect.top + rect.height() * 0.76f)
            path.lineTo(rect.left + rect.width() * 0.78f, rect.centerY().toFloat())
            path.close()
            canvas.drawPath(path, fillPaint)
        }

        private fun drawStop(canvas: Canvas, rect: Rect) {
            val pa = (panelOpacity * 255 / 100).coerceIn(0, 255)
            framePaint.style = Paint.Style.STROKE
            framePaint.strokeWidth = dp(1f)
            framePaint.color = Color.argb(pa, 100, 40, 40)
            framePaint.pathEffect = null
            fillPaint.color = Color.argb(pa, 80, 30, 30)
            val f = RectF(rect)
            canvas.drawRoundRect(f, dp(5f), dp(5f), fillPaint)
            canvas.drawRoundRect(f, dp(5f), dp(5f), framePaint)
            fillPaint.color = Color.argb(pa, 239, 154, 154)
            val inset = minOf(rect.width(), rect.height()) * 0.32f
            canvas.drawRoundRect(
                RectF(
                    rect.left + inset, rect.top + inset,
                    rect.right - inset, rect.bottom - inset,
                ),
                dp(2f), dp(2f), fillPaint,
            )
        }

        @SuppressLint("ClickableViewAccessibility")
        override fun onTouchEvent(event: MotionEvent): Boolean {
            when (event.actionMasked) {
                MotionEvent.ACTION_DOWN -> {
                    downRawX = event.rawX
                    downRawY = event.rawY
                    longPressed = false
                    return true
                }

                MotionEvent.ACTION_UP -> {
                    val moved = kotlin.math.abs(event.rawX - downRawX) > touchSlop ||
                        kotlin.math.abs(event.rawY - downRawY) > touchSlop
                    if (!moved && !longPressed) handleTap(event.rawX, event.rawY)
                    longPressed = false
                    return true
                }

                MotionEvent.ACTION_CANCEL -> {
                    longPressed = false
                    return true
                }
            }
            return super.onTouchEvent(event)
        }

        private fun handleTap(x: Float, y: Float) {
            when {
                hit(slot.male, x, y) -> {
                    activeRole = ROLE_MALE
                    listener?.onRoleSelected(ROLE_MALE)
                    invalidate()
                }

                hit(slot.female, x, y) -> {
                    activeRole = ROLE_FEMALE
                    listener?.onRoleSelected(ROLE_FEMALE)
                    invalidate()
                }

                hit(slot.narrator, x, y) -> {
                    activeRole = ROLE_NARRATOR
                    listener?.onRoleSelected(ROLE_NARRATOR)
                    invalidate()
                }

                hit(slot.mic, x, y) -> listener?.onMicToggled()
                hit(slot.start, x, y) -> listener?.onStartClicked()
                hit(slot.stop, x, y) -> listener?.onStopClicked()
            }
        }
    }

    // ── правки регионов ────────────────────────────────────────

    private fun moveRegion(x: Int, y: Int) {
        for (slot in slots) {
            if (slot.index < 0) continue
        }
    }

    private fun hit(rect: Rect, x: Float, y: Float, slop: Float = 6f * density): Boolean =
        x >= rect.left - slop && x <= rect.right + slop &&
            y >= rect.top - slop && y <= rect.bottom + slop

    private fun dp(value: Float): Float =
        TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP, value, res.displayMetrics)

    private fun addView(view: View, lp: LayoutParams): Boolean = runCatching {
        wm.addView(view, lp)
    }.onFailure { Log.w(TAG, "Не удалось добавить view в WM", it) }.isSuccess

    private fun removeView(view: View?) {
        view ?: return
        runCatching { wm.removeViewImmediate(view) }
    }

    private fun updateView(view: View?, lp: LayoutParams) {
        view ?: return
        runCatching { wm.updateViewLayout(view, lp) }
    }

    private fun slotOrNull(index: Int): Slot? = slots.getOrNull(index)

    private fun screenWidth(): Int = screenSize().x

    private fun screenHeight(): Int = screenSize().y

    private fun screenSize(): Point {
        val dm = displayContext.getSystemService(Context.DISPLAY_SERVICE) as? DisplayManager
        val display = dm?.getDisplay(android.view.Display.DEFAULT_DISPLAY) ?: return Point(0, 0)
        val metrics = android.util.DisplayMetrics()
        @Suppress("DEPRECATION")
        display.getRealMetrics(metrics)
        return Point(metrics.widthPixels, metrics.heightPixels)
    }

    private fun checkOnline(): Boolean = runCatching {
        val cm = displayContext.getSystemService(Context.CONNECTIVITY_SERVICE) as? ConnectivityManager
        val caps = cm?.getNetworkCapabilities(cm.activeNetwork) ?: return@runCatching false
        caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) &&
            caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_VALIDATED)
    }.getOrDefault(false)

    private fun shiftToScreen(canvas: Canvas, view: View) {
        val loc = IntArray(2)
        view.getLocationOnScreen(loc)
        canvas.translate(-loc[0].toFloat(), -loc[1].toFloat())
    }

    companion object {
        private const val TAG = "ScreenOCR"
        private const val TICK_MS = 150L
        private const val CONNECTIVITY_TICK_MS = 15000L
        const val ROLE_MALE = "male"
        const val ROLE_FEMALE = "female"
        const val ROLE_NARRATOR = "narrator"
        const val GLYPH_MALE = "♂"
        const val GLYPH_FEMALE = "♀"
        const val GLYPH_NARRATOR = "♬"
        const val COLOR_MALE = 0xFF4FC3F7.toInt()
        const val COLOR_FEMALE = 0xFFF48FB1.toInt()
        const val COLOR_NARRATOR = 0xFFCE93D8.toInt()
        const val COLOR_MIC = 0xFF81C784.toInt()
        val PALETTE = intArrayOf(
            0xFF4CAF50.toInt(), 0xFF2196F3.toInt(), 0xFFFF9800.toInt(),
            0xFF9C27B0.toInt(), 0xFFF44336.toInt(), 0xFF00BCD4.toInt(),
        )
    }
}

