// ── правки регионов ────────────────────────────────────────

/** Перенос рамки. Координаты экранные - так же, как в Region (core). */
private fun moveRegion(slot: Slot, x: Int, y: Int) {
    val r = slot.model.region
    val sw = screenWidth()
    val sh = screenHeight()
    val nx = x.coerceIn(0, (sw - r.width).coerceAtLeast(0))
    val ny = y.coerceIn(0, (sh - r.height).coerceAtLeast(0))
    if (nx == r.x && ny == r.y) return
    slot.model = slot.model.copy(region = r.copy(x = nx, y = ny))
    applyGeometry()
}

/** Изменение размера за нижний правый маркер (порт mouseMoveEvent + _is_on_handle). */
private fun resizeRegion(slot: Slot, x: Int, y: Int, width: Int, height: Int) {
    val r = slot.model.region
    val sw = screenWidth()
    val sh = screenHeight()
    val nw = width.coerceIn(minSide.toInt(), (sw - r.x).coerceAtLeast(1))
    val nh = height.coerceIn(minSide.toInt(), (sh - r.y).coerceAtLeast(1))
    if (nw == r.width && nh == r.height) return
    slot.model = slot.model.copy(region = r.copy(width = nw, height = nh))
    applyGeometry()
}

private fun applyGeometry() {
    recompute()
    invalidateAll()
    val list = slots.map { it.model.region }
    listener?.onRegionsReplaced(list)
}

private fun hit(rect: Rect, x: Float, y: Float, slop: Float = 6f * density): Boolean =
    x >= rect.left - slop && x <= rect.right + slop &&
        y >= rect.top - slop && y <= rect.bottom + slop

/**
 * Порт RegionOverlay._is_on_border: точка на границе рамки (плюс name bar).
 * Используется для подсветки курсора и для выбора режима перетаскивания.
 */
private fun isOnBorder(region: Region, x: Float, y: Float): Boolean {
    if (isOnNameBar(region, x, y)) return true
    if (x < region.x || x > region.right || y < region.y || y > region.bottom) return false
    val b = borderTol
    return kotlin.math.abs(x - region.x) < b || kotlin.math.abs(x - region.right) < b ||
        kotlin.math.abs(y - region.y) < b || kotlin.math.abs(y - region.bottom) < b
}

/** Порт _is_on_name. */
private fun isOnNameBar(region: Region, x: Float, y: Float): Boolean {
    val top = maxOf(0, region.y - nameH.toInt())
    return x >= region.x && x <= region.x + region.width && y >= top && y <= top + nameH.toInt()
}

/** Порт _is_on_handle - попадание в маркер изменения размера. */
private fun isOnHandle(region: Region, x: Float, y: Float): Boolean =
    kotlin.math.abs(x - region.right) < handleTol &&
        kotlin.math.abs(y - region.bottom) < handleTol

