/**
 * Что находится под точкой экрана. Хост (MainActivity) использует это,
 * чтобы показать своё контекстное меню там же, где меню было на десктопе.
 */
fun hitTest(x: Int, y: Int): Hit? {
    val px = x.toFloat()
    val py = y.toFloat()
    for (slot in slots) {
        val region = slot.model.region
        if (slot.model.panelVisible && hit(slot.panel, px, py)) {
            val part = when {
                hit(slot.male, px, py) -> Part.ROLE_MALE
                hit(slot.female, px, py) -> Part.ROLE_FEMALE
                hit(slot.narrator, px, py) -> Part.ROLE_NARRATOR
                hit(slot.mic, px, py) -> Part.MIC
                hit(slot.start, px, py) -> Part.START
                hit(slot.stop, px, py) -> Part.STOP
                else -> Part.PANEL
            }
            return Hit(slot.index, part)
        }
        if (isOnHandle(region, px, py)) return Hit(slot.index, Part.HANDLE)
        if (hit(slot.toggle, px, py, slop = 0f)) return Hit(slot.index, Part.TOGGLE)
        if (isOnNameBar(region, px, py)) return Hit(slot.index, Part.NAME)
        if (isOnBorder(region, px, py)) return Hit(slot.index, Part.BORDER)
    }
    return null
}

data class Hit(val index: Int, val part: Part)

enum class Part { NAME, TOGGLE, BORDER, HANDLE, PANEL, ROLE_MALE, ROLE_FEMALE, ROLE_NARRATOR, MIC, START, STOP }

