private inner class Slot(val index: Int, var model: OverlayRegion, private val owner: RegionOverlay) {
    val frame = Rect()
    val name = Rect()
    val toggle = Rect()
    val handle = Rect()
    val panel = Rect()
    val male = Rect()
    val female = Rect()
    val narrator = Rect()
    val mic = Rect()
    val start = Rect()
    val stop = Rect()

    var nameView: NameBarView? = null
    var handleView: HandleView? = null
    var panelView: PanelView? = null

    fun install() {
        if (nameView == null) {
            nameView = NameBarView(displayContext, this)
            handleView = HandleView(displayContext, this)
            panelView = PanelView(displayContext, this)
        }
        installName()
        installHandle()
        installPanel()
    }

    fun installName() {
        val v = nameView ?: return
        if (!editMode || model.locked) {
            removeView(v)
            return
        }
        if (!addView(v, layout(name))) {
            removeView(v)
        } else {
            v.invalidate()
        }
    }

    fun installHandle() {
        val v = handleView ?: return
        if (!editMode || model.locked) {
            removeView(v)
            return
        }
        if (!addView(v, layout(handle))) {
            removeView(v)
        } else {
            v.invalidate()
        }
    }

    fun installPanel() {
        val v = panelView ?: return
        if (!editMode || !model.panelVisible) {
            removeView(v)
            return
        }
        if (!addView(v, layout(panel))) {
            removeView(v)
        } else {
            v.invalidate()
        }
    }

    fun layout(rect: Rect): LayoutParams = LayoutParams(
        rect.width().coerceAtLeast(1),
        rect.height().coerceAtLeast(1),
        LayoutParams.TYPE_APPLICATION_OVERLAY,
        nameBarFlags,
        android.graphics.PixelFormat.TRANSLUCENT,
    ).apply {
        gravity = Gravity.TOP or Gravity.START
        x = rect.left
        y = rect.top
    }

    fun syncWindows() {
        if (nameView != null) updateView(nameView, layout(name))
        if (handleView != null) updateView(handleView, layout(handle))
        if (panelView != null) updateView(panelView, layout(panel))
    }

    fun compute() {
        val r = model.region
        frame.set(r.x, r.y, r.right, r.bottom)
        val nameTop = maxOf(0f, r.y - nameH).toInt()
        name.set(r.x, nameTop, r.x + r.width, nameTop + nameH.toInt())
        toggle.set(r.x + r.width - toggleW.toInt(), nameTop, r.x + r.width, nameTop + nameH.toInt())
        handle.set(
            (r.right - handleSize).toInt(),
            (r.bottom - handleSize).toInt(),
            r.right,
            r.bottom,
        )
        if (!model.panelVisible) return
        val sw = screenWidth()
        val sh = screenHeight()
        val pw = minOf(dp(360f), maxOf(dp(200f), r.width.toFloat())).toInt()
        val px = maxOf(0, minOf(r.x, sw - pw))
        var py = r.bottom + panelGapBelow.toInt()
        if (py + panelH.toInt() > sh) py = r.y - panelH.toInt() - panelGapAbove.toInt()
        panel.set(px, py, px + pw, py + panelH.toInt())
        val by = py + ((panelH - btn) / 2f).toInt()

