private val framePaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { style = Paint.Style.STROKE }
private val fillPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { style = Paint.Style.FILL }
private val textPaint = Paint(Paint.ANTI_ALIAS_FLAG).apply { typeface = android.graphics.Typeface.DEFAULT_BOLD }
private val dashEffect = DashPathEffect(floatArrayOf(dp(6f), dp(4f)), 0f)

private fun regionColor(slot: Slot): Int {
    val raw = slot.model.region.color
    if (raw.isNotBlank()) {
        val parsed = runCatching { Color.parseColor(raw) }.getOrNull()
        if (parsed != null) return parsed
    }
    return PALETTE[slot.index % PALETTE.size]
}

private inner class DecorView(context: Context) : View(context) {

    override fun onDraw(canvas: Canvas) {
        if (slots.isEmpty()) return
        shiftToScreen(canvas, this)
        for (slot in slots) drawFrame(canvas, slot)
        drawOcrText(canvas)
    }

    private fun drawFrame(canvas: Canvas, slot: Slot) {
        if (slot.model.region.width <= 0 || slot.model.region.height <= 0) return
        val color = regionColor(slot)
        val alpha = (frameOpacity * 255 / 100).coerceIn(0, 255)
        framePaint.strokeWidth = dp(3f)
        framePaint.color = if (slot.model.locked) {
            Color.argb(alpha, 128, 128, 128)
        } else {
            Color.argb(alpha, Color.red(color), Color.green(color), Color.blue(color))
        }
        framePaint.pathEffect = if (slot.model.locked) dashEffect else null
        if (slot.model.region.shape.equals("ellipse", true) ||
            slot.model.region.shape.equals("oval", true)
        ) {
            val f = RectF(slot.frame)
            canvas.drawOval(f, framePaint)
        } else {
            val f = RectF(slot.frame)
            canvas.drawRoundRect(f, cornerR, cornerR, framePaint)
        }
        framePaint.pathEffect = null
    }

    private fun drawOcrText(canvas: Canvas) {
        val slot = slots.firstOrNull() ?: return
        val r = slot.model.region
        val left = r.x
        val top = r.bottom + dp(4f).toInt()
        val width = minOf(r.width.coerceAtLeast(dp(120f).toInt()), dp(500f).toInt())
        if (lastOcrText.isNotEmpty()) {
            textPaint.textSize = dp(11f)
            textPaint.color = Color.argb(140, 200, 200, 200)
            textPaint.textAlign = Paint.Align.LEFT
            canvas.save()
            canvas.clipRect(left, top, left + width, top + dp(18f).toInt())
            canvas.drawText(lastOcrText, left.toFloat(), top + dp(13f), textPaint)
            canvas.restore()
        }
        val right = if (lastScanSeconds > 0f) "%.1fs".format(lastScanSeconds) else ""
        val conf = if (lastConfidence > 0f) "${(lastConfidence * 100).toInt()}%" else ""
        val tail = listOf(right, conf).filter { it.isNotEmpty() }.joinToString("  ")
        if (tail.isNotEmpty()) {
            textPaint.textSize = dp(11f)
            textPaint.color = Color.argb(150, 76, 175, 80)
            textPaint.textAlign = Paint.Align.RIGHT
            canvas.drawText(tail, (left + width).toFloat(), top + dp(13f), textPaint)
        }
    }
}

