/**
 * Порт text_overlay.py: отдельное плавающее HUD-окно с распознанным/переведённым
 * текстом. Отдельный TYPE_APPLICATION_OVERLAY, не перехватывает касания вне себя.
 *
 * Отличия от десктопа:
 *  - QTextEdit -> ScrollView + TextView;
 *  - сохранение состояния в Settings по плоским ключам (config_key -> префикс);
 *  - "тап по телу HUD" сворачивает/разворачивает текст (на десктопе кнопка "-"),
 *    а по области заголовка тянется окно (порт mousePressEvent по y <= 26).
 */
class TextOverlay(
    context: Context,
    private val settings: Settings,
    private val id: String = "text",
    private val title: String = "OCR",
    private val actionLabel: String? = "Scan OCR",
    private val listener: Listener? = null,
) {

    interface Listener {
        fun onActionClicked() {}
        fun onDeleted(id: String) {}
    }

    private val appContext = context.applicationContext
    private val displayContext: Context = runCatching {
        val dm = appContext.getSystemService(Context.DISPLAY_SERVICE) as DisplayManager
        val display = dm.getDisplay(android.view.Display.DEFAULT_DISPLAY)
        if (display != null) appContext.createDisplayContext(display) else appContext
    }.getOrDefault(appContext)
    private val wm = displayContext.getSystemService(Context.WINDOW_SERVICE) as WindowManager
    private val main = Handler(Looper.getMainLooper())

    private var root: LinearLayout? = null
    private var titleView: TextView? = null
    private var body: TextView? = null
    private var scroller: View? = null
    private var settingsPanel: View? = null
    private var actionButton: OverlayButton? = null
    private var attached = false

    private val maxLines = 200
    private var enabled = true
    private var userHidden = false
    private var collapsed = false
    private var wrap = true
    private var scanning = false
    private var scanPulse = 0
    private var followRegion: Region? = null

    private var posX = 0
    private var posY = 0
    private var winW = 0
    private var winH = 0

    private var textColor = DEFAULT_TEXT
    private var bgColor = DEFAULT_BG
    private var fontSize = settings.get(Settings.Overlay.FONT_SIZE, DEFAULT_FONT)

    private val density = displayContext.resources.displayMetrics.density
    private var dragRawX = 0f
    private var dragRawY = 0f
    private var dragX = 0
    private var dragY = 0
    private var dragging = false

    private val scanTicker = object : Runnable {
        override fun run() {
            if (!scanning) return
            scanPulse = (scanPulse + 1) % 20
            applyTitleStyle()
            main.postDelayed(this, SCAN_TICK_MS)
        }
    }

    private val saveTicker = Runnable { persist() }

    val isAttached: Boolean get() = attached

    val content: String get() = body?.text?.toString().orEmpty()

    // ── публичный API ──────────────────────────────────────────

    fun show() {
        if (attached) return
        if (!OverlayPermission.canDrawOverlays(displayContext)) {
            Log.w(TAG, "Нет разрешения на оверлеи, HUD не показан")
            return
        }
        build()
        val lp = baseParams()
        if (!runCatching { wm.addView(root, lp) }.isSuccess) {
            root = null
            return
        }
        attached = true
        userHidden = false
        persist()
        Log.i(TAG, "HUD «$title» показан")
    }

    fun hide() {
        userHidden = true
        detachWindow()
        persist()
    }

    fun toggleVisible() {
        if (attached) hide() else show()
    }

    fun delete() {
        detachWindow()
        persist()
        listener?.onDeleted(id)
    }

    /** Полная замена содержимого (порт set_text). */
    fun setText(text: String) {
        if (!enabled) return
        main.post { applyText(text.trim()) }
    }

    /** Добавление строки (порт append_line). */
    fun appendLine(text: String, prefix: String = "") {
        if (!enabled) return
        main.post {
            val view = body ?: return@post
            val line = if (prefix.isEmpty()) text else prefix + text
            view.text = (view.text.toString() + "\n" + line).trim('\n')
            trimLines()
            maybeAutoShow()
        }
    }

    /** Замена последней строки - «живые» субтитры (порт replace_last_line). */
    fun replaceLastLine(text: String) {
        if (!enabled) return
        main.post {
            val view = body ?: return@post
            val lines = view.text.toString().split("\n").toMutableList()
            if (lines.isNotEmpty() && lines.last().isNotBlank()) {
                lines[lines.lastIndex] = text
            } else {
                lines.add(text)
            }
            view.text = lines.joinToString("\n")
            maybeAutoShow()
        }
    }

    /** Распознанный текст + перевод (перевод показывается вторым блоком). */
    fun setResult(source: String, translated: String?) {
        val text = if (translated.isNullOrBlank()) source else "$source\n→ $translated"
        setText(text)
    }

    fun clearText() {
        main.post { body?.text = "" }
    }

    fun setEnabled(state: Boolean) {
        enabled = state
        settings.set(Settings.Overlay.ENABLED, state)
        if (!state) hide()
    }

    fun setScanning(state: Boolean) {
        if (scanning == state) return
        scanning = state
        if (state) {
            scanPulse = 0
            main.post(scanTicker)
        } else {
            main.removeCallbacks(scanTicker)
        }
        applyTitleStyle()
    }

    fun setOpacity(percent: Int) {
        settings.set(Settings.Overlay.OPACITY, (percent.coerceIn(10, 100)) / 100f)
        lp()?.let { p ->
            p.alpha = percent.coerceIn(10, 100) / 100f
            runCatching { wm.updateViewLayout(root, p) }
        }
        persist()
    }

    fun setFontSize(size: Int) {
        fontSize = size.coerceIn(MIN_FONT, MAX_FONT)
        settings.set(Settings.Overlay.FONT_SIZE, fontSize)
        body?.setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, fontSize.toFloat())
        persist()
    }

    fun setTextColor(color: Int) {
        textColor = color
        settings.set("$PREFIX$id.text_color", color)
        applyColors()
        persist()
    }

    fun setBackgroundColor(color: Int) {
        bgColor = color
        settings.set("$PREFIX$id.bg_color", color)
        applyColors()
        persist()
    }

    /** Привязка к региону: HUD "дрейфует" вместе с рамкой. */
    fun attachToRegion(region: Region?, gap: Int = dp(10f).toInt()) {
        followRegion = region
        if (region != null) follow(region, gap)
    }

    fun updateFollow(region: Region, gap: Int = dp(10f).toInt()) {
        if (!settings.get("$PREFIX$id.follow", true)) return
        followRegion = region
        follow(region, gap)
    }

    // ── построение UI ──────────────────────────────────────────

    @SuppressLint("ClickableViewAccessibility")
    private fun build() {
        val rootView = LinearLayout(displayContext).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(4f).toInt(), 0, dp(4f).toInt(), 0)
            background = rounded(ColorDrawable(bgColor), dp(8f).toFloat())
        }
        root = rootView

        val bar = LinearLayout(displayContext).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(6f).toInt(), dp(2f).toInt(), dp(4f).toInt(), dp(2f).toInt())
            background = rounded(ColorDrawable(lighten(bgColor, 0x18)), dp(6f).toFloat())
        }
        rootView.addView(bar, lp(LayoutParams.MATCH_PARENT, dp(28f).toInt()))

        val titleText = TextView(displayContext).apply {
            setTextColor(Color.WHITE)
            setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, 11f)
            typeface = Typeface.DEFAULT_BOLD
            text = title
            maxLines = 1
        }
        titleView = titleText
        bar.addView(titleText, LinearLayout.LayoutParams(0, LayoutParams.MATCH_PARENT, 1f).apply {
            gravity = Gravity.CENTER_VERTICAL
        })

        if (actionLabel != null) {
            val action = OverlayButton(displayContext, actionLabel)
            actionButton = action
            action.setOnClickListener { listener?.onActionClicked() }
            bar.addView(action, lp(dp(76f).toInt(), dp(20f).toInt()))
        }

        bar.addView(
            OverlayButton(displayContext, "–").apply {
                setOnClickListener { hide() }
            },
            lp(dp(26f).toInt(), dp(22f).toInt()),
        )
        bar.addView(
            OverlayButton(displayContext, "⚙").apply {
                setOnClickListener {
                    val panel = settingsPanel ?: return@setOnClickListener
                    panel.visibility =
                        if (panel.visibility == View.VISIBLE) View.GONE else View.VISIBLE
                    persist()
                }
            },
            lp(dp(26f).toInt(), dp(22f).toInt()),
        )
        bar.addView(
            OverlayButton(displayContext, "×").apply {
                setOnClickListener { delete() }
            },
            lp(dp(26f).toInt(), dp(22f).toInt()),
        )

        // Область перетаскивания = заголовок (порт mousePressEvent при y <= 26)
        bar.setOnTouchListener { _, event ->
            onBarTouch(event)
            true
        }

        val panel = buildSettingsPanel()
        settingsPanel = panel
        rootView.addView(panel, lp(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))

        val text = MonoFont(displayContext).apply {
            setTextColor(textColor)
            setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, fontSize.toFloat())
            typeface = MonoFont.face()
            setPadding(dp(6f).toInt(), dp(6f).toInt(), dp(6f).toInt(), dp(6f).toInt())
            setTextIsSelectable(true)
        }
        body = text
        val scroll = android.widget.ScrollView(displayContext).apply {
            isFillViewport = true
            addView(
                text,
                ViewGroup.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT),
            )
        }
        scroller = scroll
        rootView.addView(scroll, lp(LayoutParams.MATCH_PARENT, 0, 1f))

        applyColors()
        applyCollapsed()
        restoreState()
    }

    private fun buildSettingsPanel(): View {
        val panel = LinearLayout(displayContext).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(8f).toInt(), dp(6f).toInt(), dp(8f).toInt(), dp(6f).toInt())
            background = rounded(ColorDrawable(darken(bgColor, 0x10)), dp(0f).toFloat())
            visibility = View.GONE
        }

        panel.addView(
            labeledSeek("Прозрачность", opacityPercent(), 10, 100) { setOpacity(it) },
            lp(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT),
        )
        panel.addView(
            labeledSeek("Шрифт", fontSize, MIN_FONT, MAX_FONT) { setFontSize(it) },
            lp(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT),
        )

        val colors = LinearLayout(displayContext).apply { orientation = LinearLayout.HORIZONTAL }
        colors.addView(
            OverlayButton(displayContext, "Цвет текста").apply {
                setOnClickListener { setTextColor(nextColor(textColor, TEXT_PALETTE)) }
            },
            LinearLayout.LayoutParams(0, dp(24f).toInt(), 1f),
        )
        colors.addView(
            OverlayButton(displayContext, "Цвет фона").apply {
                setOnClickListener { setBackgroundColor(nextColor(bgColor, BG_PALETTE)) }
            },
            LinearLayout.LayoutParams(0, dp(24f).toInt(), 1f),
        )
        panel.addView(colors, lp(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))

        val checks = LinearLayout(displayContext).apply { orientation = LinearLayout.HORIZONTAL }
        checks.addView(
            CheckBox(displayContext).apply {
                text = "Обновления"
                isChecked = enabled
                setOnCheckedChangeListener { _, v -> enabled = v; settings.set(Settings.Overlay.ENABLED, v) }
            },
            LinearLayout.LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f),
        )
        checks.addView(
            CheckBox(displayContext).apply {
                text = "Перенос"
                isChecked = wrap
                setOnCheckedChangeListener { _, v ->
                    wrap = v
                    body?.setHorizontallyScrolling(!v)
                    persist()
                }
            },
            LinearLayout.LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f),
        )
        panel.addView(checks, lp(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))

        val actions = LinearLayout(displayContext).apply { orientation = LinearLayout.HORIZONTAL }
        actions.addView(
            OverlayButton(displayContext, "Очистить").apply { setOnClickListener { clearText() } },
            LinearLayout.LayoutParams(0, dp(24f).toInt(), 1f),
        )
        actions.addView(
            OverlayButton(displayContext, "Сброс позиции").apply { setOnClickListener { resetPosition() } },
            LinearLayout.LayoutParams(0, dp(24f).toInt(), 1f),
        )
        panel.addView(actions, lp(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))
        return panel
    }

    private fun labeledSeek(
        label: String,
        value: Int,
        min: Int,
        max: Int,
        onChange: (Int) -> Unit,
    ): View {
        val row = LinearLayout(displayContext).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
        }
        val caption = TextView(displayContext).apply {
            text = label
            setTextColor(Color.parseColor("#cccccc"))
            setTextSize(android.util.TypedValue.COMPLEX_UNIT_SP, 11f)
        }
        row.addView(caption, LinearLayout.LayoutParams(0, LayoutParams.WRAP_CONTENT, 0.9f))
        val seek = OverlaySeek(displayContext)
        seek.max = max
        seek.progress = value.coerceIn(min, max)
        seek.setOnSeekBarChangeListener(
            object : SeekBar.OnSeekBarChangeListener {
                override fun onProgressChanged(sb: SeekBar?, progress: Int, fromUser: Boolean) {
                    if (fromUser) onChange(progress)
                }

                override fun onStartTrackingTouch(sb: SeekBar?) = Unit
                override fun onStopTrackingTouch(sb: SeekBar?) = Unit
            },
        )
        row.addView(seek, LinearLayout.LayoutParams(0, LayoutParams.WRAP_CONTENT, 1.4f))
        return row
    }

    private fun onBarTouch(event: MotionEvent) {
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                val p = lp()
                dragRawX = event.rawX
                dragRawY = event.rawY
                dragX = p?.x ?: posX
                dragY = p?.y ?: posY
                dragging = false
            }

            MotionEvent.ACTION_MOVE -> {
                if (kotlin.math.abs(event.rawX - dragRawX) > dp(3f) ||
                    kotlin.math.abs(event.rawY - dragRawY) > dp(3f)
                ) {
                    dragging = true
                }
                if (!dragging) return
                moveTo(
                    (dragX + (event.rawX - dragRawX)).toInt(),
                    (dragY + (event.rawY - dragRawY)).toInt(),
                )
            }

            MotionEvent.ACTION_UP -> {
                if (dragging) persist() else toggleCollapsed()
            }

            MotionEvent.ACTION_CANCEL -> Unit
        }
    }

    // ── состояние окна ─────────────────────────────────────────

    private fun baseParams(): LayoutParams {
        val screen = screenSize()
        winW = DEFAULT_W.coerceAtMost(screen.x - dp(16f).toInt()).coerceAtLeast(dp(200f).toInt())
        winH = DEFAULT_H.coerceAtMost(screen.y - dp(32f).toInt()).coerceAtLeast(dp(120f).toInt())
        posX = settings.get("$PREFIX$id.x", -1)
        posY = settings.get("$PREFIX$id.y", -1)
        if (posX < 0 || posY < 0) {
            posX = (screen.x - winW) / 2
            posY = (screen.y - winH) / 2
        }
        return LayoutParams(
            winW,
            winH,
            LayoutParams.TYPE_APPLICATION_OVERLAY,
            LayoutParams.FLAG_NOT_FOCUSABLE or
                LayoutParams.FLAG_NOT_TOUCH_MODAL or
                LayoutParams.FLAG_LAYOUT_NO_LIMITS or
                LayoutParams.FLAG_HARDWARE_ACCELERATED,
            PixelFormat.TRANSLUCENT,
        ).apply {
            gravity = Gravity.TOP or Gravity.START
            x = posX
            y = posY
            alpha = opacityPercent() / 100f
        }
    }

    private fun lp(): LayoutParams? = root?.let { view ->
        runCatching { wm.updateViewLayout(view, lp(0, 0)) }.getOrNull()
    }

    private fun moveTo(x: Int, y: Int) {
        val r = root ?: return
        val screen = screenSize()
        val nx = x.coerceIn(0, (screen.x - dp(80f).toInt()).coerceAtLeast(0))
        val ny = y.coerceIn(0, (screen.y - dp(40f).toInt()).coerceAtLeast(0))
        val p = LayoutParams(winW, winH, LayoutParams.TYPE_APPLICATION_OVERLAY,
            LayoutParams.FLAG_NOT_FOCUSABLE or LayoutParams.FLAG_NOT_TOUCH_MODAL or
                LayoutParams.FLAG_LAYOUT_NO_LIMITS or LayoutParams.FLAG_HARDWARE_ACCELERATED,
            PixelFormat.TRANSLUCENT).apply {
            gravity = Gravity.TOP or Gravity.START
            this.x = nx
            this.y = ny
            alpha = opacityPercent() / 100f
        }
        if (runCatching { wm.updateViewLayout(r, p) }.isSuccess) {
            posX = nx
            posY = ny
        }
    }

    private fun follow(region: Region, gap: Int) {
        val r = root ?: return
        val screen = screenSize()
        val nx = (region.x - winW / 4).coerceIn(0, (screen.x - dp(80f).toInt()).coerceAtLeast(0))
        val ny = (region.bottom + gap).coerceIn(0, (screen.y - dp(40f).toInt()).coerceAtLeast(0))
        if (nx == posX && ny == posY) return
        val p = LayoutParams(winW, winH, LayoutParams.TYPE_APPLICATION_OVERLAY,
            LayoutParams.FLAG_NOT_FOCUSABLE or LayoutParams.FLAG_NOT_TOUCH_MODAL or
                LayoutParams.FLAG_LAYOUT_NO_LIMITS or LayoutParams.FLAG_HARDWARE_ACCELERATED,
            PixelFormat.TRANSLUCENT).apply {
            gravity = Gravity.TOP or Gravity.START
            x = nx
            y = ny
            alpha = opacityPercent() / 100f
        }
        if (runCatching { wm.updateViewLayout(r, p) }.isSuccess) {
            posX = nx
            posY = ny
        }
    }

    private fun resetPosition() {
        val screen = screenSize()
        moveTo((screen.x - winW) / 2, (screen.y - winH) / 2)
        persist()
    }

    private fun detachWindow() {
        if (!attached) return
        attached = false
        main.removeCallbacks(scanTicker)
        root?.let { runCatching { wm.removeViewImmediate(it) } }
        root = null
        titleView = null
        body = null
        scroller = null
        settingsPanel = null
        actionButton = null
    }

    // ── содержимое ─────────────────────────────────────────────

    private fun applyText(text: String) {
        val view = body ?: return
        view.text = text
        trimLines()
        maybeAutoShow()
    }

    /** Порог _max_lines: не даём HUD расти бесконечно. */
    private fun trimLines() {
        val view = body ?: return
        val lines = view.text.toString().split("\n")
        if (lines.size <= maxLines) return
        view.text = lines.takeLast(maxLines).joinToString("\n")
    }

    private fun maybeAutoShow() {
        if (attached || userHidden) return
        if (content.isNotBlank()) show()
    }

    private fun toggleCollapsed() {
        collapsed = !collapsed
        applyCollapsed()
        persist()
    }

    private fun applyCollapsed() {
        val s = scroller ?: return
        s.visibility = if (collapsed) View.GONE else View.VISIBLE
        val panel = settingsPanel ?: return
        if (collapsed) panel.visibility = View.GONE
    }

    private fun applyColors() {
        body?.setTextColor(textColor)
        root?.background = rounded(ColorDrawable(bgColor), dp(8f).toFloat())
    }

    private fun applyTitleStyle() {
        val t = titleView ?: return
        t.text = if (scanning) "OCR..." else title
        t.setTextColor(
            if (scanning) {
                val k = 150 + 100 * kotlin.math.abs(scanPulse - 10) / 10
                Color.rgb(255, (152 + scanPulse * 5).coerceIn(0, 255), 0)
            } else {
                Color.WHITE
            },
        )
    }

    // ── сохранение ─────────────────────────────────────────────

    private fun restoreState() {
        setFontSize(settings.get(Settings.Overlay.FONT_SIZE, DEFAULT_FONT))
        textColor = settings.get("$PREFIX$id.text_color", DEFAULT_TEXT)
        bgColor = settings.get("$PREFIX$id.bg_color", DEFAULT_BG)
        enabled = settings.get(Settings.Overlay.ENABLED, true)
        wrap = settings.get("$PREFIX$id.wrap", true)
        collapsed = settings.get("$PREFIX$id.collapsed", false)
        body?.setHorizontallyScrolling(!wrap)
        applyColors()
        applyCollapsed()
    }

    private fun persist() {
        if (!attached) return
        settings.set("$PREFIX$id.x", posX)
        settings.set("$PREFIX$id.y", posY)
        settings.set("$PREFIX$id.collapsed", collapsed)
        settings.set("$PREFIX$id.wrap", wrap)
        settings.set(Settings.Overlay.FONT_SIZE, fontSize)
        main.removeCallbacks(saveTicker)
        main.postDelayed(saveTicker, SAVE_DEBOUNCE_MS)
    }

    private fun opacityPercent(): Int =
        (settings.get(Settings.Overlay.OPACITY, 0.85f) * 100f).toInt().coerceIn(10, 100)

    // ── helpers ────────────────────────────────────────────────

    private fun lp(width: Int, height: Int): LinearLayout.LayoutParams =
        LinearLayout.LayoutParams(width, height)

    private fun lp(width: Int, height: Int, weight: Float): LinearLayout.LayoutParams =
        LinearLayout.LayoutParams(width, height, weight)

    private fun dp(value: Float): Float =
        TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP, value, displayContext.resources.displayMetrics)

    private fun rounded(drawable: ColorDrawable, radius: Float): ColorDrawable {
        drawable.cornerRadius = radius
        return drawable
    }

    private fun screenSize(): android.graphics.Point {
        val dm = displayContext.getSystemService(Context.DISPLAY_SERVICE) as? DisplayManager
        val display = dm?.getDisplay(android.view.Display.DEFAULT_DISPLAY)
            ?: return android.graphics.Point(dp(400f).toInt(), dp(600f).toInt())
        val metrics = android.util.DisplayMetrics()
        @Suppress("DEPRECATION")
        display.getRealMetrics(metrics)
        return android.graphics.Point(metrics.widthPixels, metrics.heightPixels)
    }

    private fun nextColor(current: Int, palette: IntArray): Int {
        val index = palette.indexOfFirst { it == current }
        return palette[(index + 1).mod(palette.size)]
    }

    companion object {
        private const val TAG = "ScreenOCR"
        private const val PREFIX = "overlay.text."
        private const val DEFAULT_W = 420
        private const val DEFAULT_H = 320
        private const val DEFAULT_FONT = 14
        private const val MIN_FONT = 8
        private const val MAX_FONT = 32
        private const val SCAN_TICK_MS = 80L
        private const val SAVE_DEBOUNCE_MS = 400L
        const val DEFAULT_TEXT = 0xFFC9D1D9.toInt()
        const val DEFAULT_BG = 0xFF0D1117.toInt()
        val TEXT_PALETTE = intArrayOf(
            0xFFC9D1D9.toInt(), 0xFFFFFFFF.toInt(), 0xFF81C784.toInt(),
            0xFF4FC3F7.toInt(), 0xFFFFD54F.toInt(), 0xFFFF8A80.toInt(),
        )
        val BG_PALETTE = intArrayOf(
            0xFF0D1117.toInt(), 0xFF000000.toInt(), 0xFF1A1A2E.toInt(),
            0xFF21262D.toInt(), 0xFF102A43.toInt(), 0xFF2D1B2E.toInt(),
        )

        internal fun lighten(color: Int, delta: Int): Int = runCatching {
            Color.rgb(
                (Color.red(color) + delta).coerceIn(0, 255),
                (Color.green(color) + delta).coerceIn(0, 255),
                (Color.blue(color) + delta).coerceIn(0, 255),
            )
        }.getOrDefault(color)

        internal fun darken(color: Int, delta: Int): Int = runCatching {
            Color.rgb(
                (Color.red(color) - delta).coerceIn(0, 255),
                (Color.green(color) - delta).coerceIn(0, 255),
                (Color.blue(color) - delta).coerceIn(0, 255),
            )
        }.getOrDefault(color)
    }
}

package com.screenocr.tts.overlay

import android.annotation.SuppressLint
import android.content.Context
import android.graphics.Color
import android.graphics.PixelFormat
import android.graphics.Point
import android.graphics.Typeface
import android.graphics.drawable.ColorDrawable
import android.hardware.display.DisplayManager
import android.os.Handler
import android.os.Looper
import android.util.DisplayMetrics
import android.util.Log
import android.util.TypedValue
import android.view.Gravity
import android.view.MotionEvent
import android.view.View
import android.view.ViewGroup
import android.view.WindowManager
import android.view.WindowManager.LayoutParams
import android.widget.CheckBox
import android.widget.LinearLayout
import android.widget.ScrollView
import android.widget.SeekBar
import android.widget.TextView
import com.screenocr.tts.core.Region
import com.screenocr.tts.settings.Settings

/**
 * Порт text_overlay.py: отдельное плавающее HUD-окно с распознанным/переведённым
 * текстом. Живёт в своём TYPE_APPLICATION_OVERLAY и не перехватывает касания
 * вне своих границ.
 *
 * Отличия от десктопа:
 *  - QTextEdit -> ScrollView + TextView (clipping/перенос строк);
 *  - состояние в Settings по плоским ключам (config_key -> префикс "overlay.text.");
 *  - тап по заголовку сворачивает/разворачивает текст вместо кнопки "-",
 *    перетаскивание окна осталось на заголовке (порт mousePressEvent при y <= 26);
 *  - "дрейф" за регионом: attachToRegion/updateFollow держит HUD под рамкой,
 *    пока пользователь её двигает.
 */
class TextOverlay(
    context: Context,
    private val settings: Settings,
    private val id: String = "text",
    private val title: String = "OCR",
    private val actionLabel: String? = "Scan OCR",
    private val listener: Listener? = null,
) {

    interface Listener {
        fun onActionClicked() {}
        fun onDeleted(id: String) {}
    }

    private val appContext = context.applicationContext
    private val displayContext: Context = runCatching {
        val dm = appContext.getSystemService(Context.DISPLAY_SERVICE) as DisplayManager
        val display = dm.getDisplay(android.view.Display.DEFAULT_DISPLAY)
        if (display != null) appContext.createDisplayContext(display) else appContext
    }.getOrDefault(appContext)
    private val wm = displayContext.getSystemService(Context.WINDOW_SERVICE) as WindowManager
    private val main = Handler(Looper.getMainLooper())

    private var root: LinearLayout? = null
    private var titleView: TextView? = null
    private var body: TextView? = null
    private var scroller: View? = null
    private var settingsPanel: View? = null
    private var attached = false

    private var enabled = true
    private var userHidden = false
    private var collapsed = false
    private var wrap = true
    private var scanning = false
    private var scanPulse = 0

    private var posX = 0
    private var posY = 0
    private var winW = DEFAULT_W
    private var winH = DEFAULT_H
    private var alphaValue = 0.85f

    private var textColor = DEFAULT_TEXT
    private var bgColor = DEFAULT_BG
    private var fontSize = DEFAULT_FONT

    private var dragRawX = 0f
    private var dragRawY = 0f
    private var dragX = 0
    private var dragY = 0
    private var dragging = false

    private val scanTicker = object : Runnable {
        override fun run() {
            if (!scanning) return
            scanPulse = (scanPulse + 1) % 20
            applyTitleStyle()
            main.postDelayed(this, SCAN_TICK_MS)
        }
    }

    private val saveTicker = Runnable { persistNow() }

    val isAttached: Boolean get() = attached

    val content: String get() = body?.text?.toString().orEmpty()

    // ── публичный API ──────────────────────────────────────────

    fun show() {
        if (attached) return
        if (!OverlayPermission.canDrawOverlays(displayContext)) {
            Log.w(TAG, "Нет разрешения на оверлеи, HUD не показан")
            return
        }
        build()
        val view = root ?: return
        val screen = screenSize()
        winW = DEFAULT_W.coerceAtMost(screen.x - dp(16f).toInt()).coerceAtLeast(dp(220f).toInt())
        winH = DEFAULT_H.coerceAtMost(screen.y - dp(32f).toInt()).coerceAtLeast(dp(140f).toInt())
        posX = settings.get("$PREFIX$id.x", -1).let { if (it < 0) (screen.x - winW) / 2 else it }
        posY = settings.get("$PREFIX$id.y", -1).let { if (it < 0) (screen.y - winH) / 2 else it }
        if (runCatching { wm.addView(view, windowParams()) }.isFailure) {
            root = null
            return
        }
        attached = true
        userHidden = false
        persistNow()
        Log.i(TAG, "HUD \"$title\" показан")
    }

    fun hide() {
        userHidden = true
        detachWindow()
        persistNow()
    }

    fun toggleVisible() {
        if (attached) hide() else show()
    }

    fun delete() {
        detachWindow()
        persistNow()
        listener?.onDeleted(id)
    }

    /** Полная замена содержимого (порт set_text). */
    fun setText(text: String) {
        if (!enabled) return
        main.post {
            val view = body ?: return@post
            view.text = text.trim()
            trimLines()
            maybeAutoShow()
        }
    }

    /** Добавление строки (порт append_line). */
    fun appendLine(text: String, prefix: String = "") {
        if (!enabled) return
        main.post {
            val view = body ?: return@post
            val line = if (prefix.isEmpty()) text else prefix + text
            view.text = (view.text.toString() + "\n" + line).trim('\n')
            trimLines()
            maybeAutoShow()
        }
    }

    /** Замена последней строки - "живые" субтитры (порт replace_last_line). */
    fun replaceLastLine(text: String) {
        if (!enabled) return
        main.post {
            val view = body ?: return@post
            val lines = view.text.toString().split("\n").toMutableList()
            if (lines.isNotEmpty() && lines.last().isNotBlank()) {
                lines[lines.lastIndex] = text
            } else {
                lines.add(text)
            }
            view.text = lines.joinToString("\n")
            maybeAutoShow()
        }
    }

    /** Распознанный текст + перевод: перевод показывается вторым блоком. */
    fun setResult(source: String, translated: String?) {
        setText(if (translated.isNullOrBlank()) source else "$source\n→ $translated")
    }

    fun clearText() {
        main.post { body?.text = "" }
    }

    fun setEnabled(state: Boolean) {
        enabled = state
        settings.set(Settings.Overlay.ENABLED, state)
        if (!state) hide()
    }

    fun setScanning(state: Boolean) {
        if (scanning == state) return
        scanning = state
        if (state) {
            scanPulse = 0
            main.post(scanTicker)
        } else {
            main.removeCallbacks(scanTicker)
        }
        applyTitleStyle()
    }

    fun setOpacity(percent: Int) {
        alphaValue = (percent.coerceIn(10, 100)) / 100f
        settings.set(Settings.Overlay.OPACITY, alphaValue)
        updateLayout()
        persistNow()
    }

    fun setFontSize(size: Int) {
        fontSize = size.coerceIn(MIN_FONT, MAX_FONT)
        settings.set(Settings.Overlay.FONT_SIZE, fontSize)
        body?.setTextSize(TypedValue.COMPLEX_UNIT_SP, fontSize.toFloat())
        persistNow()
    }

    fun setTextColor(color: Int) {
        textColor = color
        settings.set("$PREFIX$id.text_color", color)
        applyColors()
        persistNow()
    }

    fun setBackgroundColor(color: Int) {
        bgColor = color
        settings.set("$PREFIX$id.bg_color", color)
        applyColors()
        persistNow()
    }

    /** Привязка к региону: HUD "дрейфует" вместе с рамкой. */
    fun attachToRegion(region: Region?, gap: Int = dp(10f).toInt()) {
        if (region != null) follow(region, gap)
    }

    fun updateFollow(region: Region, gap: Int = dp(10f).toInt()) {
        if (!settings.get("$PREFIX$id.follow", true)) return
        follow(region, gap)
    }

    // ── построение UI ──────────────────────────────────────────

    private inner class MiniButton(label: String) : TextView(displayContext) {
        init {
            text = label
            gravity = Gravity.CENTER
            setTextColor(Color.parseColor("#c9d1d9"))
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 11f)
            setPadding(dp(4f).toInt(), 0, dp(4f).toInt(), 0)
            background = rounded(ColorDrawable(Color.parseColor("#30363d")), dp(3f).toFloat())
        }
    }

    @SuppressLint("ClickableViewAccessibility")
    private fun build() {
        val rootView = LinearLayout(displayContext).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(4f).toInt(), 0, dp(4f).toInt(), 0)
        }
        root = rootView

        val bar = LinearLayout(displayContext).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
            setPadding(dp(6f).toInt(), dp(2f).toInt(), dp(4f).toInt(), dp(2f).toInt())
            background = rounded(ColorDrawable(lighten(DEFAULT_BG, 0x18)), dp(6f).toFloat())
        }
        rootView.addView(bar, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, dp(28f).toInt()))

        val titleText = TextView(displayContext).apply {
            setTextColor(Color.WHITE)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 11f)
            typeface = Typeface.DEFAULT_BOLD
            text = title
            maxLines = 1
        }
        titleView = titleText
        bar.addView(
            titleText,
            LinearLayout.LayoutParams(0, LayoutParams.MATCH_PARENT, 1f).apply {
                gravity = Gravity.CENTER_VERTICAL
            },
        )

        if (actionLabel != null) {
            bar.addView(
                MiniButton(actionLabel).apply { setOnClickListener { listener?.onActionClicked() } },
                LinearLayout.LayoutParams(dp(76f).toInt(), dp(20f).toInt()).apply {
                    val m = dp(3f).toInt()
                    setMargins(m, 0, m, 0)
                },
            )
        }
        bar.addView(
            MiniButton("-").apply { setOnClickListener { hide() } },
            barButtonParams(),
        )
        bar.addView(
            MiniButton("⚙").apply {
                setOnClickListener {
                    val panel = settingsPanel ?: return@setOnClickListener
                    panel.visibility =
                        if (panel.visibility == View.VISIBLE) View.GONE else View.VISIBLE
                }
            },
            barButtonParams(),
        )
        bar.addView(
            MiniButton("×").apply { setOnClickListener { delete() } },
            barButtonParams(),
        )

        // Зона перетаскивания окна = заголовок (порт mousePressEvent при y <= 26)
        bar.setOnTouchListener { _, event ->
            onBarTouch(event)
            true
        }

        val panel = buildSettingsPanel()
        settingsPanel = panel
        rootView.addView(
            panel,
            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT),
        )

        val text = TextView(displayContext).apply {
            typeface = Typeface.MONOSPACE
            setTextColor(textColor)
            setTextSize(TypedValue.COMPLEX_UNIT_SP, fontSize.toFloat())
            setPadding(dp(6f).toInt(), dp(6f).toInt(), dp(6f).toInt(), dp(6f).toInt())
            setTextIsSelectable(true)
        }
        body = text
        val scroll = ScrollView(displayContext).apply {
            isFillViewport = true
            addView(text, ViewGroup.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))
        }
        scroller = scroll
        rootView.addView(scroll, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, 0, 1f))

        restoreState()
    }

    private fun barButtonParams(): LinearLayout.LayoutParams =
        LinearLayout.LayoutParams(dp(26f).toInt(), dp(22f).toInt()).apply {
            val m = dp(2f).toInt()
            setMargins(m, 0, m, 0)
        }

    private fun buildSettingsPanel(): View {
        val panel = LinearLayout(displayContext).apply {
            orientation = LinearLayout.VERTICAL
            setPadding(dp(8f).toInt(), dp(6f).toInt(), dp(8f).toInt(), dp(6f).toInt())
            visibility = View.GONE
        }

        panel.addView(
            labeledSeek("Прозрачность", (alphaValue * 100).toInt(), 10, 100) { setOpacity(it) },
            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT),
        )
        panel.addView(
            labeledSeek("Шрифт", fontSize, MIN_FONT, MAX_FONT) { setFontSize(it) },
            LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT),
        )

        val colors = LinearLayout(displayContext).apply { orientation = LinearLayout.HORIZONTAL }
        colors.addView(
            MiniButton("Цвет текста").apply {
                setOnClickListener { setTextColor(nextColor(textColor, TEXT_PALETTE)) }
            },
            LinearLayout.LayoutParams(0, dp(24f).toInt(), 1f),
        )
        colors.addView(
            MiniButton("Цвет фона").apply {
                setOnClickListener { setBackgroundColor(nextColor(bgColor, BG_PALETTE)) }
            },
            LinearLayout.LayoutParams(0, dp(24f).toInt(), 1f),
        )
        panel.addView(colors, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))

        val checks = LinearLayout(displayContext).apply { orientation = LinearLayout.HORIZONTAL }
        checks.addView(
            CheckBox(displayContext).apply {
                text = "Обновления"
                isChecked = enabled
                setOnCheckedChangeListener { _, v ->
                    enabled = v
                    settings.set(Settings.Overlay.ENABLED, v)
                    if (!v) hide()
                }
            },
            LinearLayout.LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f),
        )
        checks.addView(
            CheckBox(displayContext).apply {
                text = "Перенос"
                isChecked = wrap
                setOnCheckedChangeListener { _, v ->
                    wrap = v
                    body?.setHorizontallyScrolling(!v)
                    persistNow()
                }
            },
            LinearLayout.LayoutParams(0, LayoutParams.WRAP_CONTENT, 1f),
        )
        panel.addView(checks, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))

        val actions = LinearLayout(displayContext).apply { orientation = LinearLayout.HORIZONTAL }
        actions.addView(
            MiniButton("Очистить").apply { setOnClickListener { clearText() } },
            LinearLayout.LayoutParams(0, dp(24f).toInt(), 1f),
        )
        actions.addView(
            MiniButton("Сброс позиции").apply { setOnClickListener { resetPosition() } },
            LinearLayout.LayoutParams(0, dp(24f).toInt(), 1f),
        )
        panel.addView(actions, LinearLayout.LayoutParams(LayoutParams.MATCH_PARENT, LayoutParams.WRAP_CONTENT))
        return panel
    }

    private fun labeledSeek(
        label: String,
        value: Int,
        min: Int,
        max: Int,
        onChange: (Int) -> Unit,
    ): View {
        val row = LinearLayout(displayContext).apply {
            orientation = LinearLayout.HORIZONTAL
            gravity = Gravity.CENTER_VERTICAL
        }
        val caption = TextView(displayContext).apply {
            text = label
            setTextColor(Color.parseColor("#cccccc"))
            setTextSize(TypedValue.COMPLEX_UNIT_SP, 11f)
        }
        row.addView(caption, LinearLayout.LayoutParams(0, LayoutParams.WRAP_CONTENT, 0.9f))
        val seek = SeekBar(displayContext).apply {
            this.max = max
            progress = value.coerceIn(min, max)
            setOnSeekBarChangeListener(
                object : SeekBar.OnSeekBarChangeListener {
                    override fun onProgressChanged(sb: SeekBar?, progress: Int, fromUser: Boolean) {
                        if (fromUser) onChange(progress)
                    }

                    override fun onStartTrackingTouch(sb: SeekBar?) = Unit
                    override fun onStopTrackingTouch(sb: SeekBar?) = Unit
                },
            )
        }
        row.addView(seek, LinearLayout.LayoutParams(0, LayoutParams.WRAP_CONTENT, 1.4f))
        return row
    }

    @SuppressLint("ClickableViewAccessibility")
    private fun onBarTouch(event: MotionEvent) {
        when (event.actionMasked) {
            MotionEvent.ACTION_DOWN -> {
                dragRawX = event.rawX
                dragRawY = event.rawY
                dragX = posX
                dragY = posY
                dragging = false
            }

            MotionEvent.ACTION_MOVE -> {
                if (kotlin.math.abs(event.rawX - dragRawX) > dp(3f) ||
                    kotlin.math.abs(event.rawY - dragRawY) > dp(3f)
                ) {
                    dragging = true
                }
                if (!dragging) return
                moveTo(
                    (dragX + (event.rawX - dragRawX)).toInt(),
                    (dragY + (event.rawY - dragRawY)).toInt(),
                )
            }

            MotionEvent.ACTION_UP -> if (dragging) persistNow() else toggleCollapsed()

            MotionEvent.ACTION_CANCEL -> Unit
        }
    }

    // ── геометрия окна ─────────────────────────────────────────

    private fun windowParams(): LayoutParams = LayoutParams(
        winW,
        winH,
        LayoutParams.TYPE_APPLICATION_OVERLAY,
        LayoutParams.FLAG_NOT_FOCUSABLE or
            LayoutParams.FLAG_NOT_TOUCH_MODAL or
            LayoutParams.FLAG_LAYOUT_NO_LIMITS or
            LayoutParams.FLAG_HARDWARE_ACCELERATED,
        PixelFormat.TRANSLUCENT,
    ).apply {
        gravity = Gravity.TOP or Gravity.START
        x = posX
        y = posY
        alpha = alphaValue
    }

    private fun updateLayout() {
        val view = root ?: return
        if (!attached) return
        runCatching { wm.updateViewLayout(view, windowParams()) }
            .onFailure { Log.w(TAG, "Не удалось обновить окно HUD", it) }
    }

    private fun moveTo(x: Int, y: Int) {
        val screen = screenSize()
        posX = x.coerceIn(0, (screen.x - dp(80f).toInt()).coerceAtLeast(0))
        posY = y.coerceIn(0, (screen.y - dp(40f).toInt()).coerceAtLeast(0))
        updateLayout()
    }

    private fun follow(region: Region, gap: Int) {
        val screen = screenSize()
        val nx = (region.x - winW / 4)
            .coerceIn(0, (screen.x - dp(80f).toInt()).coerceAtLeast(0))
        val ny = (region.bottom + gap)
            .coerceIn(0, (screen.y - dp(40f).toInt()).coerceAtLeast(0))
        if (nx == posX && ny == posY) return
        posX = nx
        posY = ny
        updateLayout()
    }

    private fun resetPosition() {
        val screen = screenSize()
        moveTo((screen.x - winW) / 2, (screen.y - winH) / 2)
        persistNow()
    }

    private fun detachWindow() {
        if (!attached) return
        attached = false
        main.removeCallbacks(scanTicker)
        root?.let { runCatching { wm.removeViewImmediate(it) } }
        root = null
        titleView = null
        body = null
        scroller = null
        settingsPanel = null
    }

    // ── содержимое ─────────────────────────────────────────────

    private fun trimLines() {
        val view = body ?: return
        val lines = view.text.toString().split("\n")
        if (lines.size <= MAX_LINES) return
        view.text = lines.takeLast(MAX_LINES).joinToString("\n")
    }

    private fun maybeAutoShow() {
        if (attached || userHidden) return
        if (content.isNotBlank()) show()
    }

    private fun toggleCollapsed() {
        collapsed = !collapsed
        applyCollapsed()
        persistNow()
    }

    private fun applyCollapsed() {
        val s = scroller ?: return
        s.visibility = if (collapsed) View.GONE else View.VISIBLE
        settingsPanel?.visibility = if (collapsed) View.GONE else View.GONE
    }

    private fun applyColors() {
        body?.setTextColor(textColor)
        root?.background = rounded(ColorDrawable(bgColor), dp(8f).toFloat())
    }

    private fun applyTitleStyle() {
        val t = titleView ?: return
        t.text = if (scanning) "OCR..." else title
        t.setTextColor(
            if (scanning) Color.rgb(255, (152 + scanPulse * 5).coerceIn(0, 255), 0)
            else Color.WHITE,
        )
    }

    // ── состояние ──────────────────────────────────────────────

    private fun restoreState() {
        alphaValue = settings.get(Settings.Overlay.OPACITY, 0.85f).coerceIn(0.1f, 1f)
        fontSize = settings.get(Settings.Overlay.FONT_SIZE, DEFAULT_FONT).coerceIn(MIN_FONT, MAX_FONT)
        textColor = settings.get("$PREFIX$id.text_color", DEFAULT_TEXT)
        bgColor = settings.get("$PREFIX$id.bg_color", DEFAULT_BG)
        enabled = settings.get(Settings.Overlay.ENABLED, true)
        wrap = settings.get("$PREFIX$id.wrap", true)
        collapsed = settings.get("$PREFIX$id.collapsed", false)
        body?.setHorizontallyScrolling(!wrap)
        body?.setTextSize(TypedValue.COMPLEX_UNIT_SP, fontSize.toFloat())
        applyColors()
        applyCollapsed()
        applyTitleStyle()
    }

    /** Отложенное сохранение позиции при перетаскивании (порт _save_timer). */
    private fun persist() {
        main.removeCallbacks(saveTicker)
        main.postDelayed(saveTicker, SAVE_DEBOUNCE_MS)
    }

    private fun persistNow() {
        main.removeCallbacks(saveTicker)
        if (attached) {
            settings.set("$PREFIX$id.x", posX)
            settings.set("$PREFIX$id.y", posY)
        }
        settings.set("$PREFIX$id.collapsed", collapsed)
        settings.set(Settings.Overlay.FONT_SIZE, fontSize)
    }

    // ── helpers ────────────────────────────────────────────────

    private fun dp(value: Float): Float =
        TypedValue.applyDimension(TypedValue.COMPLEX_UNIT_DIP, value, displayContext.resources.displayMetrics)

    private fun rounded(drawable: ColorDrawable, radius: Float): ColorDrawable {
        drawable.cornerRadius = radius
        return drawable
    }

    private fun screenSize(): Point {
        val dm = displayContext.getSystemService(Context.DISPLAY_SERVICE) as? DisplayManager
        val display = dm?.getDisplay(android.view.Display.DEFAULT_DISPLAY)
            ?: return Point(dp(400f).toInt(), dp(600f).toInt())
        val metrics = DisplayMetrics()
        @Suppress("DEPRECATION")
        display.getRealMetrics(metrics)
        return Point(metrics.widthPixels, metrics.heightPixels)
    }

    private fun nextColor(current: Int, palette: IntArray): Int {
        val index = palette.indexOfFirst { it == current }
        return palette[(index + 1).mod(palette.size)]
    }

    private fun lighten(color: Int, delta: Int): Int = Color.rgb(
        (Color.red(color) + delta).coerceIn(0, 255),
        (Color.green(color) + delta).coerceIn(0, 255),
        (Color.blue(color) + delta).coerceIn(0, 255),
    )

    companion object {
        private const val TAG = "ScreenOCR"
        private const val PREFIX = "overlay.text."
        private const val DEFAULT_W = 420
        private const val DEFAULT_H = 320
        private const val DEFAULT_FONT = 14
        private const val MIN_FONT = 8
        private const val MAX_FONT = 32
        private const val MAX_LINES = 200
        private const val SCAN_TICK_MS = 80L
        private const val SAVE_DEBOUNCE_MS = 400L

        const val DEFAULT_TEXT = 0xFFC9D1D9.toInt()
        const val DEFAULT_BG = 0xFF0D1117.toInt()

        val TEXT_PALETTE = intArrayOf(
            0xFFC9D1D9.toInt(), 0xFFFFFFFF.toInt(), 0xFF81C784.toInt(),
            0xFF4FC3F7.toInt(), 0xFFFFD54F.toInt(), 0xFFFF8A80.toInt(),
        )
        val BG_PALETTE = intArrayOf(
            0xFF0D1117.toInt(), 0xFF000000.toInt(), 0xFF1A1A2E.toInt(),
            0xFF21262D.toInt(), 0xFF102A43.toInt(), 0xFF2D1B2E.toInt(),
        )
    }
}

