package com.screenocr.tts.live

import android.util.Log
import com.screenocr.tts.core.ScanMode
import com.screenocr.tts.core.TextHeuristics
import com.screenocr.tts.settings.Settings
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Job
import kotlinx.coroutines.delay
import kotlinx.coroutines.isActive
import kotlinx.coroutines.launch
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock

/**
 * Порт live_scanner.py: очередь текста для озвучки.
 *
 * Что перенесено:
 *  - фильтр мусора OCR (_is_valid_text) и дедупликация по similarity;
 *  - накопительный буфер с flush по порогу (_chunk_buffer + продюсер);
 *  - построчный режим с кэшем произнесённого (_spoken_lines);
 *  - punctuation stream: буфер до запятой/точки, автосброс по idle;
 *  - разбивка на предложения (_split_sentences);
 *  - пауза озвучки (_tts_paused).
 *
 * Режимы [ScanMode]:
 *  - REALTIME_CLEAR - озвучиваем текст кадра целиком, буфер очищаем (chunk_clear);
 *  - REALTIME_KEEP  - копим строки/предложения, отдаём пачками по порогу;
 *  - PUNCT          - копим до запятой/точки либо пока не наберётся 15 слов,
 *                    остаток уходит при простое в PUNCT_IDLE_MS.
 *
 * Все колбэки вызываются из потока, который вызвал [onNewText]
 * (в приложении это Dispatchers.Default из ScreenScanner).
 */
class LiveScanner(
    private val settings: Settings,
    private val scope: CoroutineScope,
) {

    /** Приёмник текста для озвучки (порт tts_engine). */
    interface Speaker {
        fun speak(text: String)
        fun stop()
    }

    var speaker: Speaker? = null

    /** Колбэк на каждую фразу, отданную озвучке (порт on_text_spoken). */
    var onSpeak: ((String) -> Unit)? = null

    /** Колбэк с текстом, который остался в буфере (для HUD «прочитано / осталось»). */
    var onRemainingChanged: ((String) -> Unit)? = null

    var mode: ScanMode = modeFromSettings()
        private set

    private val lock = Any()
    private val mutex = Mutex()

    private val buffer = StringBuilder()
    private val spokenLines = LinkedHashSet<String>()
    private val spokenChunks = LinkedHashSet<String>()
    private var lastSpoken = ""
    private var paused = false
    private var lastPunctUpdate = 0L
    private var watchdog: Job? = null

    val pending: String get() = synchronized(lock) { buffer.toString() }

    val pausedState: Boolean get() = paused

    // ── вход ───────────────────────────────────────────────────

    /** Основная точка входа: новый текст с кадра. */
    fun onNewText(text: String) {
        if (!TextHeuristics.isValidText(text)) {
            logDebug("отброшен как мусор: ${text.take(40)}")
            return
        }
        ensureWatchdog()
        when (mode) {
            ScanMode.REALTIME_CLEAR -> handleRealtimeClear(text)
            ScanMode.REALTIME_KEEP -> handleKeep(text)
            ScanMode.PUNCT -> handlePunct(text)
        }
    }

    fun setMode(mode: ScanMode) {
        if (this.mode == mode) return
        this.mode = mode
        settings.set(KEY_MODE, mode.name)
        flushInternal(force = true, reason = "смена режима")
        if (mode == ScanMode.PUNCT) {
            lastPunctUpdate = now()
        }
        ensureWatchdog()
        Log.i(TAG, "Режим live-сканера: $mode")
    }

    fun setPunctMode(enabled: Boolean) {
        setMode(if (enabled) ScanMode.PUNCT else ScanMode.REALTIME_CLEAR)
    }

    /** Пауза озвучки (порт _tts_paused). */
    fun setPaused(value: Boolean) {
        paused = value
        Log.i(TAG, "Озвучка ${if (value) "приостановлена" else "возобновлена"}")
    }

    /** Очистка кэша произнесённых строк (порт clear_spoken_lines). */
    fun clearSpokenLines() {
        synchronized(lock) {
            spokenLines.clear()
            spokenChunks.clear()
            lastSpoken = ""
        }
        Log.i(TAG, "Кэш озвученных строк очищен")
    }

    /** Полный сброс: кэш + буфер (порт LiveScanner.clear_cache). */
    fun clearAll() {
        clearSpokenLines()
        flushInternal(force = true, reason = "сброс")
    }

    /** Принудительно отдать накопленное (кнопка "Озвучить всё"). */
    fun flush(force: Boolean = true) = flushInternal(force, reason = "ручной flush")

    fun stop() {
        watchdog?.cancel()
        watchdog = null
    }

    // ── обработчики режимов ────────────────────────────────────

    private fun handleRealtimeClear(text: String) {
        val normalized = TextHeuristics.normalize(text)
        if (normalized.isEmpty()) return
        // Дедуп: не озвучиваем то, что почти совпадает с предыдущим кадром.
        if (lastSpoken.isNotEmpty() && TextHeuristics.similarity(normalized, lastSpoken) > SIM_REALTIME) {
            logDebug("похоже на предыдущее, пропускаем")
            return
        }
        flushInternal(force = true, reason = "сброс буфера")
        emit(text.trim())
    }

    private fun handleKeep(text: String) {
        val fresh = mutableListOf<String>()
        synchronized(lock) {
            for (line in text.split('\n')) {
                val trimmed = line.trim()
                if (trimmed.isEmpty()) continue
                val key = TextHeuristics.normalizeLine(trimmed)
                if (key.length < 3) continue
                if (isAlreadySpoken(key)) continue
                spokenLines.add(key)
                fresh.add(trimmed)
            }
            if (fresh.isEmpty()) return
            // Разбиваем на предложения, чтобы не читать обрывки.
            for (piece in fresh) {
                val sentences = TextHeuristics.splitSentences(piece)
                for (s in sentences) {
                    if (buffer.isNotEmpty()) buffer.append(' ')
                    buffer.append(s)
                }
            }
        }
        maybeFlushKeep()
    }

    private fun handlePunct(text: String) {
        val trimmed = text.trim()
        if (trimmed.isEmpty()) return
        val normalized = TextHeuristics.normalize(trimmed)
        if (normalized.length <= 2) return
        lastPunctUpdate = now()
        var trigger: String? = null
        synchronized(lock) {
            val current = TextHeuristics.normalize(buffer.toString())
            if (current == normalized) return
            if (buffer.isNotEmpty()) buffer.append(' ')
            buffer.append(trimmed)
            logDebug("буферpunct (${buffer.length}): ${buffer.toString().take(60)}")
            val text2 = buffer.toString().trim()
            if (text2.endsWith(",") || text2.endsWith(".")) {
                val candidate = text2.dropLast(1).trim()
                // Короткие обрывки ждём дальше
                if (candidate.split(' ').count { it.isNotBlank() } >= PUNCT_MIN_WORDS) {
                    trigger = candidate
                }
            }
            if (trigger == null && text2.split(' ').count { it.isNotBlank() } > PUNCT_MAX_WORDS) {
                trigger = text2
            }
            if (trigger != null) buffer.setLength(0)
        }
        if (trigger != null) {
            Log.i(TAG, "PUNCT отправка: ${trigger.take(60)}")
            emit(trigger)
        }
    }

    /** Порог для REALTIME_KEEP: копим, пока не наберётся FLUSH_WORDS слов. */
    private fun maybeFlushKeep() {
        var ready = false
        synchronized(lock) {
            val words = buffer.split(' ').count { it.isNotBlank() }
            val hasSentenceEnd = buffer.toString().trimEnd().let {
                it.endsWith('.') || it.endsWith('!') || it.endsWith('?')
            }
            val overChars = buffer.length >= FLUSH_CHARS
            if (words >= FLUSH_WORDS || overChars || (hasSentenceEnd && words >= SENTENCE_MIN_WORDS)) {
                buffer.setLength(0)
                ready = true
            }
        }
        if (ready) flushInternal(force = true, reason = "порог накопления")
    }

    private fun flushInternal(force: Boolean, reason: String) {
        var chunk: String? = null
        synchronized(lock) {
            val text = buffer.toString().trim()
            buffer.setLength(0)
            if (text.isEmpty()) return
            if (!force && text.split(' ').count { it.isNotBlank() } < SENTENCE_MIN_WORDS) {
                // фрагмент слишком короткий - возвращаем в буфер
                buffer.append(text)
                return
            }
            val key = TextHeuristics.normalize(text)
            if (spokenChunks.contains(key)) return
            spokenChunks.add(key)
            trimCache(spokenChunks)
            chunk = text
        }
        logDebug("flush ($reason): ${chunk?.take(60)}")
        onRemainingChanged?.invoke("")
        chunk?.let { emit(it) }
    }

    // ── выдача текста ──────────────────────────────────────────

    private fun emit(text: String) {
        val clean = text.trim()
        if (clean.isEmpty()) return
        if (!TextHeuristics.isValidText(clean)) return
        if (paused) {
            logDebug("озвучка на паузе, текст пропущен")
            return
        }
        val target = speaker
        val hook = onSpeak
        if (target == null && hook == null) {
            logDebug("нет получателя озвучки, текст отброшен")
            return
        }
        synchronized(lock) {
            lastSpoken = TextHeuristics.normalize(clean)
            for (line in clean.split('\n')) {
                val key = TextHeuristics.normalizeLine(line)
                if (key.isNotEmpty()) spokenLines.add(key)
            }
            trimCache(spokenLines)
        }
        Log.i(TAG, "[TTS] озвучка: ${clean.take(60)}")
        runCatching {
            if (target?.isPlaying() == true) target.stop()
            target?.speak(clean)
            hook?.invoke(clean)
        }.onFailure { Log.e(TAG, "Ошибка озвучки: ${it.message}", it) }
    }

    private fun Speaker.isPlaying(): Boolean = this is PlayingAware && isPlaying

    /** Реализуйте в движке, если умеете отдавать текущее состояние воспроизведения. */
    interface PlayingAware {
        val isPlaying: Boolean
    }

    private fun isAlreadySpoken(key: String): Boolean {
        if (spokenChunks.contains(key)) return true
        for (spoken in spokenLines) {
            if (TextHeuristics.similarity(key, spoken) > SIM_LINE) return true
        }
        return false
    }

    private fun trimCache(set: LinkedHashSet<String>) {
        while (set.size > MAX_CACHE) {
            val it = set.iterator()
            it.next()
            it.remove()
        }
    }

    // ── idle-таймер для PUNCT ──────────────────────────────────

    /**
     * В десктопе idle проверялся в каждом кадре, в Android кадров может не быть
     * (пауза сканирования), поэтому нужен собственный сторож.
     */
    private fun ensureWatchdog() {
        if (watchdog != null) return
        watchdog = scope.launch {
            while (isActive) {
                delay(WATCHDOG_MS)
                if (mode == ScanMode.PUNCT) checkPunctIdle()
            }
        }
    }

    private fun checkPunctIdle() {
        val idleFor = now() - lastPunctUpdate
        if (idleFor <= PUNCT_IDLE_MS) return
        var chunk: String? = null
        synchronized(lock) {
            val text = buffer.toString().trim()
            buffer.setLength(0)
            if (text.isNotEmpty() && text.split(' ').count { it.isNotBlank() } >= 2) {
                chunk = text
            }
        }
        if (chunk != null) {
            Log.i(TAG, "PUNCT idle ${PUNCT_IDLE_MS}мс: отправка остатка")
            emit(chunk)
        }
    }

    // ── прочее ─────────────────────────────────────────────────

    private fun modeFromSettings(): ScanMode = runCatching {
        ScanMode.valueOf(settings.get(KEY_MODE, ScanMode.REALTIME_CLEAR.name))
    }.getOrDefault(ScanMode.REALTIME_CLEAR)

    private fun now(): Long = System.currentTimeMillis()

    private fun logDebug(message: String) {
        if (debugLogging) Log.d(TAG, "[LIVE] $message")
    }

    companion object {
        private const val TAG = "ScreenOCR"
        const val KEY_MODE = "live.mode"
        private const val FLUSH_WORDS = 12
        private const val SENTENCE_MIN_WORDS = 3
        private const val FLUSH_CHARS = 240
        private const val PUNCT_MIN_WORDS = 3
        private const val PUNCT_MAX_WORDS = 15
        private const val PUNCT_IDLE_MS = 5000L
        private const val WATCHDOG_MS = 500L
        private const val SIM_REALTIME = 0.80f
        private const val SIM_LINE = 0.85f
        private const val MAX_CACHE = 400
    }
}

