    private var foreground = false
    private var scanning = false

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        super.onStartCommand(intent, flags, startId)
        // Всегда первым делом: иначе на Android 14 сервис убьют по таймауту 5 c.
        ensureForeground()

        when (intent?.action) {
            ACTION_START -> handleStart(intent)
            ACTION_STOP -> {
                Log.i(TAG, "Остановка по команде")
                shutdown()
                stopSelf()
            }

            ACTION_TOGGLE_SCAN -> toggleScanning()
            ACTION_SCAN_ONCE -> runOnce()
            ACTION_OPEN_SETTINGS -> openSettings()
            ACTION_RELOAD_REGIONS -> reloadRegions()
            else -> if (capture == null) {
                Log.w(TAG, "Пустой Intent, сервис без захвата - останавливаюсь")
                stopSelf()
            }
        }
        return START_STICKY
    }

    override fun onTaskRemoved(rootIntent: Intent?) {
        // Порт "свернуть в трей": по умолчанию завершаемся честно, а при
        // General.START_MINIMIZED продолжаем захват в фоне.
        if (Settings.get(this).get(Settings.General.START_MINIMIZED, false)) {
            Log.i(TAG, "Задача убрана, продолжаю в фоне (START_MINIMIZED)")
            updateNotification()
            super.onTaskRemoved(rootIntent)
            return
        }
        Log.i(TAG, "Задача убрана, останавливаю захват")
        shutdown()
        stopSelf()
        super.onTaskRemoved(rootIntent)
    }

    override fun onDestroy() {
        shutdown()
        serviceScope.cancel()
        super.onDestroy()
    }

    override fun onBind(intent: Intent): IBinder? = super.onBind(intent)

    // ── запуск захвата ─────────────────────────────────────────

    private fun handleStart(intent: Intent) {
        val resultCode = intent.getIntExtra(EXTRA_RESULT_CODE, Activity.RESULT_CANCELED)
        val data: Intent? = IntentCompat.getParcelableExtra(intent, EXTRA_RESULT_DATA, Intent::class.java)
        if (resultCode != Activity.RESULT_OK || data == null) {
            fail("Не получено согласие на захват экрана")
            shutdown()
            stopSelf()
            return
        }

        // Повторный ACTION_START без остановки - освобождаем прошлую проекцию.
        shutdown(keepForeground = true)

        val manager = getSystemService(MediaProjectionManager::class.java)
        val projectionObj = runCatching { manager?.getMediaProjection(resultCode, data) }.getOrNull()
        if (projectionObj == null) {
            fail("MediaProjection не создан")
            stopSelf()
            return
        }
        projection = projectionObj
        publish(state = ServiceState.STARTING)

        val cap = ScreenCapture(applicationContext)
        cap.onProjectionStopped = { onProjectionRevoked() }
        cap.start(projectionObj)
        if (!cap.isRunning) {
            fail("Захват экрана не запустился")
            shutdown()
            stopSelf()
            return
        }
        capture = cap

        val st = Settings.get(this)
        val scan = ScreenScanner(cap, st, serviceScope, buildEngine(st))
        scan.onResult = { result -> publishResult(result) }
        scan.onTextDetected = { text -> live?.onNewText(text) }
        scan.onScanTiming = { timing ->
            if (!timing.skipped) {
                publish(
                    state = currentState(),
                    lastText = timing.text,
                    lastConfidence = timing.confidence,
                    lastDurationMs = timing.durationMs,
                )
            }
        }
        scanner = scan

        val liveScanner = LiveScanner(st, serviceScope)
        live = liveScanner
        liveScannerRef = liveScanner

        scan.setRegions(RegionStore.load(this))
        startScanning()
        watchSettings(st)
        publish(state = ServiceState.CAPTURING)
        updateNotification()
        Log.i(TAG, "Захват запущен: ${cap.screenWidth}x${cap.screenHeight}")
    }

    /**
     * Движок можно подменить через [setEngineFactory] (например, на OcrWrapper
     * с fallback-цепочкой). По умолчанию - локальная TFLite-модель.
     */
    private fun buildEngine(st: Settings): OcrEngine {
        engineFactory?.let { factory ->
            runCatching { factory(this, st) }.getOrNull()?.let { return it }
        }
        val limit = st.get(Settings.Ocr.DET_LIMIT_SIDE, 736)
        val engine = TfliteOcrEngine(applicationContext, limit)
        Log.i(TAG, "OCR-движок: ${engine.id} (предел стороны $limit)")
        return engine
    }

    /** Регионы живут в Settings, поэтому оверлей и сервис видят одно и то же. */
    private fun watchSettings(st: Settings) {
        settingsJob?.cancel()
        settingsJob = lifecycleScope.launch {
            st.changes.collect {
                val sc = scanner ?: return@collect
                val regions = RegionStore.load(this@CaptureService)
                sc.setRegions(regions)
                publish(state = currentState(), regions = sc.regions())
            }
        }
    }

    // ── управление сканированием ───────────────────────────────

    fun startScanning() {
        val sc = scanner ?: return
        if (sc.status.value.running) return
        scanning = true
        sc.start()
        live?.let { if (it.pausedState) it.setPaused(false) }
        publish(state = currentState())
        updateNotification()
    }

    fun stopScanning() {
        scanning = false
        scanner?.stop()
        publish(state = currentState())
        updateNotification()
    }

    private fun toggleScanning() {
        if (scanning) {
            stopScanning()
            Log.i(TAG, "Сканирование остановлено")
        } else {
            startScanning()
            Log.i(TAG, "Сканирование запущено")
        }
    }

    private fun runOnce() {
        val sc = scanner ?: return
        if (scanning) {
            // Цикл уже идёт - он и так захватит свежий кадр.
            Log.d(TAG, "Сканирование уже идёт, разовый проход не нужен")
            return
        }
        serviceScope.launch { sc.scanOnce() }
    }

    private fun reloadRegions() {
        val sc = scanner ?: return
        sc.setRegions(RegionStore.load(this))
        publish(state = currentState(), regions = sc.regions())
    }

    private fun openSettings() {
        val intent = Intent(this, MainActivity::class.java).apply {
            addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
            putExtra(EXTRA_OPEN_SETTINGS, true)
        }
        runCatching { startActivity(intent) }
            .onFailure { Log.w(TAG, "Не удалось открыть настройки: ${it.message}") }
    }

    private fun onProjectionRevoked() {
        Log.w(TAG, "Доступ к экрану отозван")
        shutdown()
        publish(state = ServiceState.ERROR, error = "Доступ к экрану отозван")
        stopSelf()
    }

    private fun shutdown(keepForeground: Boolean = false) {
        settingsJob?.cancel()
        settingsJob = null
        scanner?.stop()
        scanner = null
        screenScannerRef = null
        live?.stop()
        live = null
        liveScannerRef = null
        capture?.stop()
        capture = null
        projection = null
        scanning = false
        if (foreground && !keepForeground) {
            ServiceCompat.stopForeground(this, ServiceCompat.STOP_FOREGROUND_REMOVE)
            foreground = false
        }
        publish(state = ServiceState.IDLE)
    }

    private fun fail(message: String) {
        Log.e(TAG, message)
        publish(state = ServiceState.ERROR, error = message)
    }

    private fun currentState(): ServiceState =
        if (capture == null) ServiceState.IDLE else ServiceState.CAPTURING

    // ── состояние для UI ───────────────────────────────────────

    private fun publish(
        state: ServiceState = currentState(),
        regions: List<Region>? = null,
        lastText: String? = null,
        lastConfidence: Float? = null,
        lastDurationMs: Long? = null,
        error: String? = null,
    ) {
        val current = _snapshot.value
        _snapshot.value = CaptureSnapshot(
            state = state,
            scanning = scanning,
            regions = regions ?: scanner?.regions() ?: current.regions,
            lastText = lastText ?: current.lastText,
            lastConfidence = lastConfidence ?: current.lastConfidence,
            lastDurationMs = lastDurationMs ?: current.lastDurationMs,
            error = error,
        )
    }

    private fun publishResult(result: OcrResult) {
        publish(
            state = currentState(),
            regions = scanner?.regions(),
            lastText = result.text,
            lastConfidence = result.confidence,
            lastDurationMs = result.elapsedMs,
        )
    }

    // ── уведомление ────────────────────────────────────────────

    private fun ensureForeground() {
        if (foreground) return
        createChannel()
        ServiceCompat.startForeground(
            this,
            NOTIFICATION_ID,
            buildNotification(),
            ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PROJECTION,
        )
        foreground = true
    }

    private fun createChannel() {
        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
        val manager = getSystemService(NotificationManager::class.java) ?: return
        if (manager.getNotificationChannel(CHANNEL_ID) != null) return
        val channel = NotificationChannel(
            CHANNEL_ID,
            "Захват экрана",
            NotificationManager.IMPORTANCE_LOW,
        ).apply {
            description = "OCR и озвучка с экрана"
            setShowBadge(false)
        }
        manager.createNotificationChannel(channel)
    }

    private fun buildNotification(): Notification {
        val content = PendingIntent.getActivity(
            this,
            0,
            Intent(this, MainActivity::class.java).apply {
                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TOP)
            },
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
        )
        val regionCount = scanner?.regions()?.size ?: 0
        return NotificationCompat.Builder(this, CHANNEL_ID)
            .setSmallIcon(R.drawable.ic_stat_capture)
            .setContentTitle(if (scanning) "OCR: сканирование идёт" else "OCR: на паузе")
            .setContentText(
                if (scanning) {
                    "Интервал ${scanner?.intervalMs ?: 0} мс · регионов: $regionCount"
                } else {
                    "Нажмите, чтобы открыть настройки"
                },
            )
            .setContentIntent(content)
            .setOngoing(scanning)
            .setOnlyAlertOnce(true)
            .setSilent(true)
            .setShowWhen(false)
            .setCategory(NotificationCompat.CATEGORY_SERVICE)
            .setPriority(NotificationCompat.PRIORITY_LOW)
            .addAction(R.drawable.ic_stat_capture, if (scanning) "Стоп" else "Старт", servicePendingIntent(ACTION_TOGGLE_SCAN, 1))
            .addAction(R.drawable.ic_stat_capture, "Настройки", servicePendingIntent(ACTION_OPEN_SETTINGS, 2))
            .addAction(R.drawable.ic_stat_capture, "Выход", servicePendingIntent(ACTION_STOP, 3))
            .build()
    }

    private fun servicePendingIntent(action: String, requestCode: Int): PendingIntent =
        PendingIntent.getService(
            this,
            requestCode,
            Intent(this, CaptureService::class.java).setAction(action),
            PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT,
        )

    private fun updateNotification() {
        if (!foreground) return
        runCatching {
            getSystemService(NotificationManager::class.java)
                ?.notify(NOTIFICATION_ID, buildNotification())
        }
    }

    companion object {
        private const val TAG = "ScreenOCR"
        const val ACTION_START = "com.screenocr.tts.action.START_CAPTURE"
        const val ACTION_STOP = "com.screenocr.tts.action.STOP_CAPTURE"
        const val ACTION_TOGGLE_SCAN = "com.screenocr.tts.action.TOGGLE_SCAN"
        const val ACTION_SCAN_ONCE = "com.screenocr.tts.action.SCAN_ONCE"
        const val ACTION_OPEN_SETTINGS = "com.screenocr.tts.action.OPEN_SETTINGS"
        const val ACTION_RELOAD_REGIONS = "com.screenocr.tts.action.RELOAD_REGIONS"
        const val EXTRA_RESULT_CODE = "extra_result_code"
        const val EXTRA_RESULT_DATA = "extra_result_data"
        const val EXTRA_OPEN_SETTINGS = "open_settings"
        const val CHANNEL_ID = "screenocr_capture"
        const val NOTIFICATION_ID = 0x50C7

        private val _snapshot = MutableStateFlow(CaptureSnapshot())

        /** Общее состояние: UI подписывается и рисует рамки/статус. */
        val snapshot: StateFlow<CaptureSnapshot> = _snapshot.asStateFlow()

        @Volatile
        private var engineFactory: ((Context, Settings) -> OcrEngine?)? = null

        /** Живой сканер и очередь озвучки - чтобы UI подключил TTS. */
        @Volatile
        var liveScannerRef: LiveScanner? = null
            private set

        @Volatile
        var screenScannerRef: ScreenScanner? = null
            private set

        /** Позволяет подменить OCR-движок, не трогая сервис. */
        fun setEngineFactory(factory: ((Context, Settings) -> OcrEngine?)?) {
            engineFactory = factory
        }

        /** Старт захвата: вызывать из Activity с результатом системного диалога. */
        fun startCapture(context: Context, resultCode: Int, data: Intent) {
            val intent = Intent(context, CaptureService::class.java).apply {
                action = ACTION_START
                putExtra(EXTRA_RESULT_CODE, resultCode)
                putExtra(EXTRA_RESULT_DATA, data)
            }
            if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
                context.startForegroundService(intent)
            } else {
                context.startService(intent)
            }
        }

        fun stop(context: Context) = send(context, ACTION_STOP)

        fun toggleScan(context: Context) = send(context, ACTION_TOGGLE_SCAN)

        fun scanOnce(context: Context) = send(context, ACTION_SCAN_ONCE)

        fun reloadRegions(context: Context) = send(context, ACTION_RELOAD_REGIONS)

        private fun send(context: Context, action: String) {
            val intent = Intent(context, CaptureService::class.java).setAction(action)
            runCatching { context.startService(intent) }
                .onFailure { Log.w(TAG, "Не удалось отправить $action: ${it.message}") }
        }
    }
}

