    private fun teardown() {
        synchronized(lock) { stopLocked() }
    }

    private fun currentDisplaySize(): Point {
        val dm = appContext.getSystemService(Context.DISPLAY_SERVICE) as? DisplayManager
        val display = dm?.getDisplay(Display.DEFAULT_DISPLAY) ?: return Point(0, 0)
        val metrics = android.util.DisplayMetrics()
        @Suppress("DEPRECATION")
        display.getRealMetrics(metrics)
        return Point(metrics.widthPixels, metrics.heightPixels)
    }

    private fun acquireBitmap(): Bitmap? {
        val image = acquireImage(ACQUIRE_TIMEOUT_MS) ?: return null
        return try {
            imageToBitmap(image)
        } catch (e: Throwable) {
            Log.e(TAG, "Ошибка конвертации кадра", e)
            null
        } finally {
            runCatching { image.close() }
        }
    }

    /**
     * acquireNextImage() без таймаута - единственная публичная перегрузка,
     * поэтому опрашиваем буфер до дедлайна. Возвращает null, если кадра нет.
     */
    private fun acquireImage(timeoutMs: Long): Image? {
        val reader = synchronized(lock) { imageReader } ?: return null
        val deadline = SystemClock.uptimeMillis() + timeoutMs
        while (true) {
            if (!isRunning) return null
            val image = runCatching { reader.acquireNextImage() }.getOrNull()
            if (image != null) return image
            if (SystemClock.uptimeMillis() >= deadline) return null
            runCatching { Thread.sleep(POLL_MS) }
        }
    }

    private fun imageToBitmap(image: Image): Bitmap? {
        val plane = image.planes.getOrNull(0) ?: return null
        val width = image.width
        val height = image.height
        val pixelStride = plane.pixelStride
        val rowStride = plane.rowStride
        val rowBytes = width * pixelStride
        val buffer = plane.buffer
        buffer.rewind()

        if (rowBytes <= 0 || rowStride < rowBytes || (height - 1) * rowStride + rowBytes > buffer.capacity()) {
            Log.w(TAG, "Неожиданная геометрия буфера: rowStride=$rowStride cap=${buffer.capacity()}")
            return null
        }

        val bitmap = Bitmap.createBitmap(width, height, Bitmap.Config.ARGB_8888)
        if (pixelStride == 4 && rowStride == rowBytes) {
            // Быстрый путь: плотный буфер, ARGB_8888 в памяти совпадает с RGBA байтами.
            buffer.position(0)
            buffer.limit(rowBytes * height)
            bitmap.copyPixelsFromBuffer(buffer)
            return bitmap
        }

        val row = ByteArray(rowBytes)
        val pixels = IntArray(width * height)
        for (y in 0 until height) {
            buffer.position(y * rowStride)
            buffer.get(row, 0, rowBytes)
            val out = y * width
            for (x in 0 until width) {
                val o = x * pixelStride
                val a = if (pixelStride >= 4) row[o + 3].toInt() and 0xFF else 255
                val r = row[o].toInt() and 0xFF
                val g = row[o + 1].toInt() and 0xFF
                val b = row[o + 2].toInt() and 0xFF
                pixels[out + x] = (a shl 24) or (r shl 16) or (g shl 8) or b
            }
        }
        bitmap.setPixels(pixels, 0, width, 0, 0, width, height)
        return bitmap
    }

    companion object {
        private const val TAG = "ScreenOCR"
        private const val VIRTUAL_DISPLAY_NAME = "screenocr-capture"
        private const val MAX_IMAGES = 2
        private const val ACQUIRE_TIMEOUT_MS = 400L
        private const val POLL_MS = 4L
    }
}

parts.text:
One issue: when a `captureRegion` crop happens, the returned bitmap is ARGB_8888 with premultiplied alpha from RGBA. TFLite conversion usually uses `getPixels` which unpremultiplies — fine.

Another consideration: MediaProjection frames come as **opaque** (alpha = 255) usually, so premultiplied == straight. Good.

The `teardown()` on projection stop: `projectionCallback.onStop()` → teardown → synchronized(lock) { stopLocked() } → which calls `p.stop()` on the same projection (already stopped; runCatching) and `thread?.quitSafely()`. onStop is delivered on the handler thread, so quitSafely from that thread is fine.

But careful: `stopLocked()` calls `p.unregisterCallback` and `p.stop()`. If the user revoked the projection, the system already stopped it; calling stop() again is a no-op or throws (caught). OK.

Now, one more important design check: `captureRegion` calls `acquireBitmap()` which acquires a full frame and then crops — meaning we transfer the whole screen through the buffer each scan. For a 1080x2400 RGBA frame that's ~10MB per copy. At 700ms intervals that's fine, and the alternative (per-row crop during the read) would be much more complex. Acceptable. Actually, I could optimize by reading only the needed rows when the region is a horizontal band — a nice optimization but adds complexity. Let me add it since captureRegion is the hot path: pass an optional crop rect to acquireBitmap and only convert the needed rows.

Implementation: `private fun acquireBitmap(crop: Rect?): Bitmap?` where crop is in *image* coordinates. In the row loop, only iterate over the intersecting rows and write into the output bitmap with setPixels per row (when cropping). For the fast path (rowStride == rowBytes), copyPixelsFromBuffer must consume from the start, so cropping needs per-row handling: use `buffer.position(y*rowStride)` and `bitmap.setPixels` from a row buffer.

Let me restructure imageToBitmap to take an optional crop rect:

```kotlin
private fun acquireBitmap(crop: Rect? = null): Bitmap? {
    val image = acquireImage(...) ?: return null
    try { return imageToBitmap(image, crop) } finally { image.close() }
}

private fun imageToBitmap(image: Image, crop: Rect?): Bitmap? {
    ... compute srcX, srcY, srcW, srcH from crop clamped to image bounds ...
    val full = (srcX == 0 && srcY == 0 && srcW == width && srcH == height)
    val bmp = Bitmap.createBitmap(srcW, srcH, ARGB_8888)
    if (full && pixelStride == 4 && rowStride == rowBytes) { fast path }
    else {
        // per-row conversion, only rows srcY until srcY+srcH
        val row = ByteArray(rowBytes)
        val pixels = IntArray(srcW)
        for (y in 0 until srcH) {
            buffer.position((srcY + y) * rowStride + srcX * pixelStride)
            buffer.get(row, 0, srcW * pixelStride)
            for (x in 0 until srcW) { ... pixels[x] = ... }
            bmp.setPixels(pixels, 0, srcW, 0, y, srcW, 1)
        }
    }
}
```
Note the `buffer.get(row, 0, srcW*pixelStride)` starting at `srcX*pixelStride` — correct for the pixel offset.

This is both faster and avoids a second full-frame Bitmap. And `captureRegion` then doesn't need to crop afterwards.

Careful about the buffer capacity check: keep the check on the full row range: `(srcY+srcH-1)*rowStride + (srcX+srcW)*pixelStride <= capacity`.

Let me rewrite that part of ScreenCapture. Also `captureFull()` = acquireBitmap(null) and `captureRegion` = acquireBitmap(crop in screen coords, clamped to size).

Also: should I worry that a Bitmap with width*height for the full screen every scan is heavy for GC? With cropping, only the region is allocated.

Let me rewrite.

