/** Кадр целиком (в системных координатах дисплея). */
fun captureFull(): Bitmap? = acquireBitmap(null)

/**
 * Кадр с вырезанным регионом: конвертируются только нужные строки буфера,
 * поэтому регион не читается дважды и не тратит память на весь экран.
 * Регион прижимается к границам кадра.
 */
fun captureRegion(region: Region): Bitmap? {
    val w = screenWidth
    val h = screenHeight
    if (w <= 0 || h <= 0) return null
    val x = region.x.coerceIn(0, w - 1)
    val y = region.y.coerceIn(0, h - 1)
    val cw = region.width.coerceIn(1, w - x)
    val ch = region.height.coerceIn(1, h - y)
    return acquireBitmap(Rect(x, y, x + cw, y + ch))
}

