/** Кадр целиком (в системных координатах дисплея). */
fun captureFull(): Bitmap? = acquireBitmap()

/**
 * Кадр с вырезанным регионом. Регион прижимается к границам экрана,
 * чтобы Bitmap.createBitmap не бросил исключение на битых координатах.
 */
fun captureRegion(region: Region): Bitmap? {
    val full = acquireBitmap() ?: return null
    val w = full.width
    val h = full.height
    val x = region.x.coerceIn(0, (w - 1).coerceAtLeast(0))
    val y = region.y.coerceIn(0, (h - 1).coerceAtLeast(0))
    val cw = region.width.coerceIn(1, w - x)
    val ch = region.height.coerceIn(1, h - y)
    if (cw <= 0 || ch <= 0) {
        full.recycle()
        return null
    }
    val whole = cw == w && ch == h
    if (whole) return full
    return try {
        Bitmap.createBitmap(full, x, y, cw, ch)
    } catch (e: Throwable) {
        Log.e(TAG, "Не удалось вырезать регион ${region.name}", e)
        null
    } finally {
        full.recycle()
    }
}

