/** Принудительно отдать накопленное (кнопка "Озвучить всё"). */
fun flush(force: Boolean = true) = flushInternal(force, reason = "ручной flush")

fun stop() {
    watchdog?.cancel()
    watchdog = null
}

// ── обработчики режимов ────────────────────────────────────

private fun handleRealtimeClear(text: String) {
    val normalized = TextHeuristics.normalize(text)
    if (normalized.isEmpty()) return
    // Дедуп: не озвучиваем то, что почти совпадает с предыдущим кадром.
    if (lastSpoken.isNotEmpty() && TextHeuristics.similarity(normalized, lastSpoken) > SIM_REALTIME) {
        logDebug("похоже на предыдущее, пропускаем")
        return
    }
    flushInternal(force = true, reason = "сброс буфера")
    emit(text.trim(), interrupt = true)
}

private fun handleKeep(text: String) {
    val fresh = mutableListOf<String>()
    synchronized(lock) {
        for (line in text.split('\n')) {
            val trimmed = line.trim()
            if (trimmed.isEmpty()) continue
            val key = TextHeuristics.normalizeLine(trimmed)
            if (key.length < 3) continue
            if (isAlreadySpoken(key)) continue
            spokenLines.add(key)
            fresh.add(trimmed)
        }
        if (fresh.isEmpty()) return
        // Разбиваем на предложения, чтобы не читать обрывки.
        for (piece in fresh) {
            val sentences = TextHeuristics.splitSentences(piece)
            for (s in sentences) {
                if (buffer.isNotEmpty()) buffer.append(' ')
                buffer.append(s)
            }
        }
    }
    maybeFlushKeep()
}

private fun handlePunct(text: String) {
    val trimmed = text.trim()
    if (trimmed.isEmpty()) return
    val normalized = TextHeuristics.normalize(trimmed)
    if (normalized.length <= 2) return
    lastPunctUpdate = now()
    var trigger: String? = null
    synchronized(lock) {
        val current = TextHeuristics.normalize(buffer.toString())
        if (current == normalized) return
        if (buffer.isNotEmpty()) buffer.append(' ')
        buffer.append(trimmed)
        logDebug("буфер (${buffer.length}): ${buffer.toString().take(60)}")
        val text2 = buffer.toString().trim()
        if (text2.endsWith(",") || text2.endsWith(".")) {
            val candidate = text2.dropLast(1).trim()
            // Короткие обрывки ждём дальше
            if (candidate.split(' ').count { it.isNotBlank() } >= PUNCT_MIN_WORDS) {
                trigger = candidate
            }
        }
        if (trigger == null && text2.split(' ').count { it.isNotBlank() } > PUNCT_MAX_WORDS) {
            trigger = text2
        }
