    private fun emit(text: String, interrupt: Boolean = false) {
        val clean = text.trim()
        if (clean.isEmpty()) return
        if (!TextHeuristics.isValidText(clean)) return
        if (paused) {
            logDebug("озвучка на паузе, текст пропущен")
            return
        }
        val target = speaker
        val hook = onSpeak
        if (target == null && hook == null) {
            logDebug("нет получателя озвучки, текст отброшен")
            return
        }
        synchronized(lock) {
            lastSpoken = TextHeuristics.normalize(clean)
            for (line in clean.split('\n')) {
                val key = TextHeuristics.normalizeLine(line)
                if (key.isNotEmpty()) spokenLines.add(key)
            }
            trimCache(spokenLines)
        }
        Log.i(TAG, "[TTS] озвучка: ${clean.take(60)}")
        runCatching {
            // В режиме кадра текущая фраза обрывается (порт force_stop в _on_new_text)
            if (interrupt) target?.stop()
            target?.speak(clean)
            hook?.invoke(clean)
        }.onFailure { Log.e(TAG, "Ошибка озвучки: ${it.message}", it) }
    }

    private fun isAlreadySpoken(key: String): Boolean {
        if (spokenChunks.contains(key)) return true
        // Сравниваем только с последними SIM_WINDOW строками: полный проход по
        // кэшу с DP-сравнением на телефоне слишком дорогой.
        for (spoken in spokenLines.toList().asReversed().take(SIM_WINDOW)) {
            if (TextHeuristics.similarity(key, spoken) > SIM_LINE) return true
        }
        return false
    }

    private fun trimCache(set: LinkedHashSet<String>) {
        while (set.size > MAX_CACHE) {
            val it = set.iterator()
            it.next()
            it.remove()
        }
    }

    // ── idle-таймер для PUNCT ──────────────────────────────────

    /**
     * В десктопе idle проверялся в каждом кадре, в Android кадров может не быть
     * (пауза сканирования), поэтому нужен собственный сторож.
     */
    private fun ensureWatchdog() {
        if (watchdog != null) return
        watchdog = scope.launch {
            while (isActive) {
                delay(WATCHDOG_MS)
                if (mode == ScanMode.PUNCT) checkPunctIdle()
            }
        }
    }

    private fun checkPunctIdle() {
        val idleFor = now() - lastPunctUpdate
        if (idleFor <= PUNCT_IDLE_MS) return
        var chunk: String? = null
        synchronized(lock) {
            val text = buffer.toString().trim()
            buffer.setLength(0)
            if (text.isNotEmpty() && text.split(' ').count { it.isNotBlank() } >= 2) {
                chunk = text
            }
        }
        if (chunk != null) {
            Log.i(TAG, "PUNCT idle ${PUNCT_IDLE_MS}мс: отправка остатка")
            emit(chunk)
        }
    }

    // ── прочее ─────────────────────────────────────────────────

    private fun modeFromSettings(): ScanMode = runCatching {
        ScanMode.valueOf(settings.get(KEY_MODE, ScanMode.REALTIME_CLEAR.name))
    }.getOrDefault(ScanMode.REALTIME_CLEAR)

    private fun now(): Long = System.currentTimeMillis()

    private fun logDebug(message: String) {
        if (debugLogging) Log.d(TAG, "[LIVE] $message")
    }

    companion object {
        private const val TAG = "ScreenOCR"
        const val KEY_MODE = "live.mode"
        private const val FLUSH_WORDS = 12
        private const val SENTENCE_MIN_WORDS = 3
        private const val FLUSH_CHARS = 240
        private const val PUNCT_MIN_WORDS = 3
        private const val PUNCT_MAX_WORDS = 15
        private const val PUNCT_IDLE_MS = 5000L
        private const val WATCHDOG_MS = 500L
        private const val SIM_REALTIME = 0.80f
        private const val SIM_LINE = 0.85f
        private const val SIM_WINDOW = 32
        private const val MAX_CACHE = 400
    }
}

