package com.screenocr.tts.overlay

import android.annotation.SuppressLint
import android.content.Context
import android.content.res.Resources
import android.graphics.Canvas
import android.graphics.Color
import android.graphics.DashPathEffect
import android.graphics.Paint
import android.graphics.Path
import android.graphics.Point
import android.graphics.Rect
import android.graphics.RectF
import android.hardware.display.DisplayManager
import android.net.ConnectivityManager
import android.net.NetworkCapabilities
import android.os.Handler
import android.os.Looper
import android.util.Log
import android.util.TypedValue
import android.view.Gravity
import android.view.MotionEvent
import android.view.View
import android.view.ViewConfiguration
import android.view.WindowManager
import android.view.WindowManager.LayoutParams
import com.screenocr.tts.capture.RegionStore
import com.screenocr.tts.core.Region
import com.screenocr.tts.settings.Settings
import java.util.concurrent.atomic.AtomicBoolean

/** Регион + состояние, которого нет в core.Region (порт dict из region_overlay.py). */
data class OverlayRegion(
    val region: Region,
    val locked: Boolean = false,
    val panelVisible: Boolean = true,
)

/**
 * Порт region_overlay.py на WindowManager + TYPE_APPLICATION_OVERLAY.
 *
 * Окна намеренно разбиты на несколько:
 *  - один полноэкранный слой только рисует рамки (FLAG_NOT_TOUCHABLE) и
 *    пропускает ВСЕ касания приложению под ним;
 *  - на каждый регион - три маленьких кликабельных слоя: name bar (перетаскивание,
 *    ▼/▶, контекстное меню по долгому тапу), маркер в углу (изменение размера)
 *    и панель голоса (кнопки). Они реализуют порт _is_on_border/_is_on_handle
 *    и hit-test VoicePanel.
 *
 * Так касания вне регионов физически не перехватываются - в отличие от
 * полноэкранного touchable-окна. Заодно уходит баг десктопной версии, где
 * координаты кнопок считались в локальной системе окна, а сравнивались
 * с системными: здесь ВСЕ прямоугольники живут в координатах экрана
 * (см. [Slot]), а View рисует их со сдвигом на свой getLocationOnScreen.
 */
class RegionOverlay(
    context: Context,
    private val settings: Settings,
    private val listener: Listener? = null,
) {

    interface Listener {
        fun onStartClicked() {}
        fun onStopClicked() {}
        fun onScanRequested() {}
        fun onMicToggled() {}
        fun onRoleSelected(role: String) {}

        /** Долгий тап по кнопке роли (аналог ПКМ в paintEvent → _on_panel_right_click). */
        fun onRoleMenuRequested(role: String, screenX: Int, screenY: Int) {}
        fun onPanelToggled(index: Int, visible: Boolean) {}

        /** Каждый шаг перетаскивания/ресайза - координаты и размер уже применены. */
        fun onRegionChanged(index: Int, region: Region) {}

        /** Короткий тап по рамке; долгий тап (контекстное меню) - тоже сюда же. */
        fun onRegionTapped(index: Int, screenX: Int, screenY: Int) {}
        fun onRegionsReplaced(regions: List<Region>) {}
        fun onPermissionRequired() {}
    }

    // ── состояние ──────────────────────────────────────────────

    private val res: Resources = context.resources
    private val displayContext: Context = runCatching {
        val dm = context.applicationContext.getSystemService(Context.DISPLAY_SERVICE) as DisplayManager
        val display = dm.getDisplay(android.view.Display.DEFAULT_DISPLAY)
        if (display != null) context.createDisplayContext(display) else context.applicationContext
    }.getOrDefault(context.applicationContext)

    private val wm = displayContext.getSystemService(Context.WINDOW_SERVICE) as WindowManager
    private val main = Handler(Looper.getMainLooper())
    private val touchSlop = ViewConfiguration.get(displayContext).scaledTouchSlop.toFloat()

    private val density = res.displayMetrics.density
    private val nameH = dp(28f)
    private val toggleW = dp(26f)
    private val handleSize = dp(26f)
    private val handleTol = dp(16f)
    private val borderTol = dp(10f)
    private val panelH = dp(36f)
    private val btn = dp(28f)
    private val gap = dp(3f)
    private val panelGapBelow = dp(10f)
    private val panelGapAbove = dp(8f)
    private val minSide = dp(56f)
    private val cornerR = dp(5f)

    private val nameBarFlags =
        LayoutParams.FLAG_NOT_FOCUSABLE or
            LayoutParams.FLAG_NOT_TOUCH_MODAL or
            LayoutParams.FLAG_LAYOUT_NO_LIMITS or
            LayoutParams.FLAG_HARDWARE_ACCELERATED

    private val slots = ArrayList<Slot>()
    private var decorView: DecorView? = null
    private var attached = false
    private var editMode = true

    private var scanning = false
    private var sttActive = false
    private var sttText = ""
    private var lastOcrText = ""
    private var lastScanSeconds = 0f
    private var lastConfidence = 0f
    private var scanPulse = 0
    private var sttBlink = 0
    private var online = true
    private var activeRole = ROLE_MALE

    private var frameOpacity = (settings.get(Settings.Overlay.OPACITY, 0.85f) * 100f).toInt()
        .coerceIn(10, 100)
    private var panelOpacity =
        (settings.get(Settings.Overlay.PANEL_OPACITY, 0.9f) * 100f).toInt().coerceIn(10, 100)

