private fun handleKeep(text: String) {
    val lines = text.split('\n').map { it.trim() }.filter { it.isNotEmpty() }
    val deltas = mutableListOf<String>()
    for ((i, line) in lines.withIndex()) {
        // Растущая строка (субтитры, чат) даёт дельту, а не весь текст заново -
        // иначе каждое слово проглатывалось бы как "похожее на предыдущее".
        val prev = prevFrameLines.getOrNull(i).orEmpty()
        val delta = TextHeuristics.textDelta(prev, line)
        deltas.add(if (delta.isNotBlank()) delta else line)
    }
    prevFrameLines = lines

    val fresh = mutableListOf<String>()
    synchronized(lock) {
        for (piece in deltas) {
            val trimmed = piece.trim()
            if (trimmed.isEmpty()) continue
            val key = TextHeuristics.normalizeLine(trimmed)
            if (key.length < 3) continue
            if (isAlreadySpoken(key)) continue
            spokenLines.add(key)
            fresh.add(trimmed)
        }
        if (fresh.isEmpty()) return
        // Разбиваем на предложения, чтобы не читать обрывки.
        for (piece in fresh) {
            for (s in TextHeuristics.splitSentences(piece)) {
                if (buffer.isNotEmpty()) buffer.append(' ')
                buffer.append(s)
            }
        }
    }
    maybeFlushKeep()
}

private fun handlePunct(text: String) {
    val trimmed = text.trim()
    if (trimmed.isBlank()) return
    if (TextHeuristics.normalize(trimmed).length <= 2) return
    val delta = TextHeuristics.textDelta(lastFrameText, trimmed)
    lastFrameText = trimmed
    if (delta.isBlank()) {
        logDebug("кадр не изменился")
        return
    }
    lastPunctUpdate = now()
    var trigger: String? = null
    synchronized(lock) {
        if (buffer.isNotEmpty()) buffer.append(' ')
        buffer.append(delta.trim())
        logDebug("буфер (${buffer.length}): ${buffer.toString().take(60)}")
        val text2 = buffer.toString().trim()
        if (text2.endsWith(",") || text2.endsWith(".")) {
            val candidate = text2.dropLast(1).trim()
            // Короткие обрывки ждём дальше
            if (candidate.split(' ').count { it.isNotBlank() } >= PUNCT_MIN_WORDS) {
                trigger = candidate
            }
        }
        if (trigger == null && text2.split(' ').count { it.isNotBlank() } > PUNCT_MAX_WORDS) {
            trigger = text2
        }
        if (trigger != null) {
            buffer.setLength(0)
            lastFrameText = ""
        }
    }
    if (trigger != null) {
        Log.i(TAG, "PUNCT отправка: ${trigger.take(60)}")
        emit(trigger)
    }
}

