/**
 * Эмоция, определяемая по тексту.
 *
 * Объединение наборов emotion_rules.py (happy / sad / angry / surprised /
 * thinking / sleeping / wink / neutral) и live_voices.py (anime voice pack v5 —
 * самый полный словарь: shout, pain, fear, laugh, love, annoy, sarcasm, whisper).
 */
enum class Emotion {
    SHOUT, ANGER, PAIN, FEAR, SURPRISE, LAUGH, HAPPY, LOVE, SAD,
    ANNOY, SARCASM, WHISPER, THINKING, WINK, SLEEPING, NEUTRAL
}

/**
 * Изменение темпа и высоты под эмоцию.
 * rate — проценты (-100..+100), pitch — единицы desktop-диапазона (-50..+50),
 * которые Edge отдаёт как Hz. Порт EMOTION_DEFAULTS.
 */
data class EmotionProsody(val rate: Int, val pitch: Int)

/**
 * Порт emotion_rules.py + emotion_rules/EMOTION_DICTS из tts_engine.py +
 * D_* из live_voices.py.
 */
object EmotionRules {

    /** Порядок разрешения равенств, порт EMOTION_PRIORITY. */
    val PRIORITY: List<Emotion> = listOf(
        Emotion.SHOUT, Emotion.ANGER, Emotion.PAIN, Emotion.FEAR, Emotion.SURPRISE,
        Emotion.LAUGH, Emotion.HAPPY, Emotion.LOVE, Emotion.SAD, Emotion.ANNOY,
        Emotion.SARCASM, Emotion.WHISPER, Emotion.THINKING, Emotion.WINK,
        Emotion.SLEEPING, Emotion.NEUTRAL,
    )

    /** Порт EMOTION_DEFAULTS (tts_engine.py == live_voices.py). */
    private val DEFAULTS: Map<Emotion, EmotionProsody> = mapOf(
        Emotion.SHOUT to EmotionProsody(50, 25),
        Emotion.ANGER to EmotionProsody(30, -10),
        Emotion.PAIN to EmotionProsody(10, 8),
        Emotion.FEAR to EmotionProsody(15, 18),
        Emotion.SURPRISE to EmotionProsody(10, 15),
        Emotion.LAUGH to EmotionProsody(15, 12),
        Emotion.HAPPY to EmotionProsody(20, 15),
        Emotion.LOVE to EmotionProsody(-5, 5),
        Emotion.SAD to EmotionProsody(-20, -8),
        Emotion.ANNOY to EmotionProsody(20, -3),
