            Emotion.LOVE to D_LOVE,
            Emotion.SAD to D_SAD,
            Emotion.ANNOY to D_ANNOY,
            Emotion.SARCASM to D_SARCASM,
            Emotion.WHISPER to D_WHISPER,
            Emotion.THINKING to D_THINK,
            Emotion.WINK to D_WINK,
            Emotion.SLEEPING to D_SLEEPING,
        )
        source.mapValues { (_, words) ->
            Lexicon(
                inner = words.filter { !it.startsWith(" ") && !it.endsWith(" ") }
                    .map { normalize(it) }.filter { it.isNotEmpty() },
                anchored = words.filter { it.startsWith(" ") || it.endsWith(" ") }
                    .map { normalize(it.trim()) }.filter { it.isNotEmpty() },
            )
        }
    }

    private val PROFANITY: List<String> by lazy { D_PROFANITY.map { normalize(it) } }

    private val SHOUT_UPPER = Regex("[А-ЯЁ]{2,}")
    private val SHOUT_REPEAT = Regex("([а-яё])\\1{3,}")
    private val PUNCT = Regex("[!?.,;:\\-…]+")
    private val SPACES = Regex("\\s+")
    private val FIX_CACHE = ArrayList<Pair<Regex, String>>(TEXT_FIXES.size)

    /**
     * Определяет эмоцию по тексту.
     * @return null, если сигналов нет (в tts_engine.py это трактуется как 'normal').
     */
    fun detectEmotion(text: String?): Emotion? {
        if (text.isNullOrBlank()) return null
        val lower = text.lowercase().replace('ё', 'е')

        // Крики (CAPS или повторы букв) проверяются первыми — как в tts_engine.py
        if (SHOUT_UPPER.containsMatchIn(text) || SHOUT_REPEAT.containsMatchIn(lower)) {
            return Emotion.SHOUT
        }

        val padded = " $lower "
        val clean = SPACES.replace(PUNCT.replace(lower, " "), " ").trim()
        if (clean.isEmpty()) return null

        val scores = HashMap<Emotion, Double>(16)
        for (emotion in LEXICONS.keys) {
            val lex = LEXICONS[emotion] ?: continue
            var hit = 0
            for (w in lex.inner) if (clean.contains(w)) hit++
            for (w in lex.anchored) if (padded.contains(" $w ")) hit++
            if (hit > 0) scores[emotion] = hit.toDouble()
        }

        if (PROFANITY.any { clean.contains(it) }) {
            scores[Emotion.ANGER] = (scores[Emotion.ANGER] ?: 0.0) + 2.0
        }
        if (clean.contains('?')) {
            scores[Emotion.THINKING] = (scores[Emotion.THINKING] ?: 0.0) + 1.0
            scores[Emotion.SURPRISE] = (scores[Emotion.SURPRISE] ?: 0.0) + 0.5
        }
        if (clean.contains('!')) {
            val best = scores.maxByOrNull { it.value }?.key
            if (best != null) scores[best] = (scores[best] ?: 0.0) + 1.0
            else scores[Emotion.SURPRISE] = (scores[Emotion.SURPRISE] ?: 0.0) + 0.5
        }

        val letters = text.filter { it.isLetter() }
        if (letters.size > 4) {
            val caps = letters.count { it.isUpperCase() }
            if (caps.toDouble() / letters.size > 0.55) {
                if ((scores[Emotion.HAPPY] ?: 0.0) > 0.0) {
                    scores[Emotion.HAPPY] = (scores[Emotion.HAPPY] ?: 0.0) + 1.0
                } else {
                    scores[Emotion.ANGER] = (scores[Emotion.ANGER] ?: 0.0) + 1.0
                }
            }
        }

        val best = scores.filterValues { it >= 1.0 }.maxWithOrNull(
            compareBy<Map.Entry<Emotion, Double>> { it.value }
                .thenBy { PRIORITY.indexOf(it.key) }
        ) ?: return null
        Log.d(TAG, "[EMOTION] ${text.take(60)} → ${best.key} (score=${best.value})")
        return best.key
    }

    /** Просодия эмоции; NORMAL для null. */
    fun prosodyFor(emotion: Emotion?): EmotionProsody =
        DEFAULTS[emotion ?: Emotion.NEUTRAL] ?: DEFAULTS.getValue(Emotion.NEUTRAL)

    /**
     * Нормализация растянутых звуков перед синтезом.
     * Порт _preprocess_emotion_text / _preprocess.
     */
    fun preprocess(text: String): String {
        var result = text
        if (FIX_CACHE.isEmpty()) {
            synchronized(FIX_CACHE) {
                if (FIX_CACHE.isEmpty()) {
                    for ((bad, good) in TEXT_FIXES) {
                        FIX_CACHE += Regex(Regex.escape(bad), RegexOption.IGNORE_CASE) to good
                    }
                }
            }
        }
        for ((pattern, good) in FIX_CACHE) {
            result = pattern.replace(result, good)
        }
        return result
    }

    /** Нижний регистр + ё→е — общая нормализация словарей и текста. */
    private fun normalize(s: String): String = s.lowercase().replace('ё', 'е')
}

package com.screenocr.tts.tts

import android.util.Log
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.exp
import kotlin.math.floor
import kotlin.math.log2
import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import kotlin.math.roundToInt
import kotlin.math.sin
import kotlin.math.sqrt
import kotlin.math.tanh

private const val TAG = "ScreenOCR"

/**
 * Порт voice_changer.py: DSP-трансформация голоса (pitch / speed / formant)
 * на моно-PCM 24 кГц.
 *
 * В Python питч меняется ресемплингом, а скорость — тем же ресемплингом
 * (то есть всегда вместе с питчем). Здесь разделено: питч — WSOLA
 * time-stretch + ресемплинг, скорость — только WSOLA. Так тембр не «плавает».
 */
object VoiceChanger {

    const val SAMPLE_RATE = 24000
    const val SEMITONE_RATIO = 2.0.pow(1.0 / 12.0)

    data class Preset(
        val name: String,
        val label: String,
        val pitchSemitones: Float = 0f,
        val speedFactor: Float = 1f,
        val formantShift: Float = 0f,
        val gender: String = "neutral",
        val description: String = "",
    )

    /** Порт PRESETS. */
    val PRESETS: Map<String, Preset> = linkedMapOf(
        "original" to Preset("original", "Оригинал", 0f, 1f, 0f, "neutral", "Без изменений"),
        "male_deep" to Preset("male_deep", "Бас", -5f, 0.95f, -1f, "male", "Глубокий мужской"),
        "male_old" to Preset("male_old", "Старик", -3f, 0.85f, -0.5f, "male", "Пожилой мужчина"),
        "male_young" to Preset("male_young", "Молодой", 1f, 1.05f, 0.5f, "male", "Молодой мужчина"),
        "male_giant" to Preset("male_giant", "Великан", -7f, 0.8f, -2f, "male", "Очень низкий голос"),
        "female" to Preset("female", "Женщина", 4f, 1f, 1f, "female", "Женский голос"),
        "female_sweet" to Preset("female_sweet", "Нежная", 5f, 1f, 1.5f, "female", "Мягкий женский"),
        "female_lord" to Preset("female_lord", "Госпожа", 3f, 0.95f, 0.5f, "female", "Строгий женский"),
        "female_girl" to Preset("female_girl", "Девочка", 7f, 1.15f, 2f, "female", "Юный голос"),
        "child" to Preset("child", "Ребёнок", 7f, 1.2f, 2f, "neutral", "Голос ребёнка"),
        "baby" to Preset("baby", "Малыш", 10f, 1.3f, 3f, "neutral", "Очень высокий голос"),
        "robot" to Preset("robot", "Робот", 0f, 1f, 0f, "neutral", "Роботизированный"),
        "whisper" to Preset("whisper", "Шёпот", 2f, 0.9f, 1f, "neutral", "Шёпот"),
        "slow" to Preset("slow", "Медленный", -2f, 0.7f, -0.5f, "neutral", "Размеренная речь"),
        "fast" to Preset("fast", "Быстрый", 1f, 1.3f, 0f, "neutral", "Быстрая речь"),
        "alien" to Preset("alien", "Пришелец", 8f, 0.9f, 3f, "neutral", "Инопланетный"),
        "monster" to Preset("monster", "Монстр", -8f, 0.7f, -3f, "male", "Чудовище"),
        "loud" to Preset("loud", "Громкий", 1f, 1f, 0f, "neutral", "Усиленная громкость"),
        "quiet" to Preset("quiet", "Тихий", -1f, 0.95f, 0f, "neutral", "Пониженная громкость"),
        "echo" to Preset("echo", "Эхо", 0f, 1f, 0f, "neutral", "С эхом-эффектом"),
        "telephone" to Preset("telephone", "Телефон", 2f, 1.1f, 1f, "neutral", "Как по телефону"),
        "radio" to Preset("radio", "Радио", 1f, 1f, 1f, "neutral", "Эффект радио"),
    )

    private const val CATEGORIES_LABEL_ORDER = 0

    /** Порт get_presets_by_category. */
    fun presetsByCategory(): Map<String, List<Preset>> = linkedMapOf(
        "Оригинал" to listOf("original"),
        "Мужские" to listOf("male_deep", "male_old", "male_young", "male_giant"),
        "Женские" to listOf("female", "female_sweet", "female_lord", "female_girl"),
        "Детские" to listOf("child", "baby"),
        "Эффекты" to listOf("robot", "whisper", "slow", "fast", "alien", "monster"),
        "Громкость" to listOf("loud", "quiet"),
        "Канал" to listOf("echo", "telephone", "radio"),
    ).mapValues { (_, names) -> names.mapNotNull { PRESETS[it] } }

    fun getPreset(name: String?): Preset? = name?.let { PRESETS[it] }

    // ── основной вход ────────────────────────────────────────────

    /** Порт transform_audio: PCM → PCM по пресету. */
    fun transform(pcm: ShortArray, presetName: String, sampleRate: Int = SAMPLE_RATE): ShortArray {
        val preset = PRESETS[presetName]
        if (preset == null) {
            Log.w(TAG, "[VoiceChanger] Неизвестный пресет: $presetName, берём original")
            return pcm
        }
        if (preset.name == "original" || pcm.isEmpty()) return pcm

        Log.i(
            TAG,
            "[VoiceChanger] ${preset.label}: pitch=${preset.pitchSemitones}st, " +
                "speed=${preset.speedFactor}x, formant=${preset.formantShift}",
        )
        var audio = toFloat(pcm)
        if (abs(preset.pitchSemitones) > 0.1f) audio = changePitch(audio, preset.pitchSemitones)
        if (abs(preset.speedFactor - 1f) > 0.01f) audio = timeStretch(audio, 1f / preset.speedFactor)
        if (abs(preset.formantShift) > 0.1f) audio = formantShift(audio, sampleRate, preset.formantShift)

        audio = when (preset.name) {
            "robot" -> robot(audio, sampleRate)
            "whisper" -> whisper(audio, sampleRate)
            "echo" -> echo(audio, sampleRate)
            "loud" -> loud(audio)
            "quiet" -> scale(audio, 0.5f)
            "telephone" -> scale(telephoneBand(audio, sampleRate, 2), 2f)
            "radio" -> FloatArray(audio.size) { i -> tanh(0.7f * telephoneBand(audio, sampleRate, 2)[i] * 1.5f) }
            else -> audio
        }
        return toShort(audio)
    }

    /** Сдвиг тона на полутон�� без изменения длительности. */
    fun changePitch(pcm: ShortArray, semitones: Float, sampleRate: Int = SAMPLE_RATE): ShortArray {
        if (pcm.isEmpty()) return pcm
        return toShort(changePitch(toFloat(pcm), semitones))
    }

    /** Изменение темпа без изменения высоты тона. factor > 1 — быстрее. */
    fun changeSpeed(pcm: ShortArray, factor: Float, sampleRate: Int = SAMPLE_RATE): ShortArray {
        if (pcm.isEmpty()) return pcm
        return toShort(timeStretch(toFloat(pcm), 1f / factor))
    }

    // ── DSP ──────────────────────────────────────────────────────

    private fun changePitch(input: FloatArray, semitones: Float): FloatArray {
        val ratio = SEMITONE_RATIO.pow(semitones)
        if (abs(ratio - 1.0) < 0.005) return input
        // Растягиваем по времени в ratio раз, затем сжимаем обратно ресемплингом:
        // длительность сохраняется, высота растёт в ratio раз.
        val stretched = timeStretch(input, ratio)
        return resample(stretched, 1.0 / ratio)
    }

    /**
     * WSOLA: overlap-add с поиском оптимального сдвига анализируемого окна.
     * factor > 1 — длиннее и медленнее, factor < 1 — короче и быстрее.
     */
    fun timeStretch(input: FloatArray, factor: Float): FloatArray {
        if (abs(factor - 1f) < 0.01f || input.size < 4096) return input
        val frame = 1024
        val synHop = frame / 4
        val anaHop = max(1, (synHop * factor).roundToInt())
        val search = frame / 8
        val window = hann(frame)

        val frames = max(1, (input.size - frame) / anaHop + 1)
        val outSize = (frames - 1) * synHop + frame
        val out = FloatArray(outSize)
        val norm = FloatArray(outSize)

        var anaPos = 0
        var synPos = 0
        while (anaPos + frame <= input.size) {
            val start = if (synPos == 0) anaPos else bestOffset(input, out, anaPos, synPos, search)
            for (i in 0 until frame) {
                val w = window[i]
                out[synPos + i] += input[start + i] * w
                norm[synPos + i] += w
            }
            anaPos += anaHop
            synPos += synHop
        }
        val tail = min(outSize, synPos + frame)
        val result = FloatArray(tail)
        for (i in 0 until tail) {
            result[i] = if (norm[i] > 1e-4f) out[i] / norm[i] else 0f
        }
        return result
    }

    /** Максимизация корреляции с естественным продолжением уже синтезированного сигнала. */
    private fun bestOffset(
        input: FloatArray,
        out: FloatArray,
        anaPos: Int,
        synPos: Int,
        search: Int,
    ): Int {
        val limit = min(search, min(anaPos, input.size - anaPos - 512).coerceAtLeast(0))
        if (limit <= 0) return anaPos
        var bestPos = anaPos
        var bestScore = Float.NEGATIVE_INFINITY
        for (delta in -limit..limit) {
            val pos = anaPos + delta
            if (pos < 0 || pos + 512 > input.size) continue
            var score = 0f
            var i = 0
            while (i < 256) {
                score += out[synPos - 256 + i] * input[pos + i]
                i += 2
            }
            if (score > bestScore) {
                bestScore = score
                bestPos = pos
            }
        }
        return bestPos
    }

    /** Линейная передискретизация: out.length ≈ input.length * ratio. */
    fun resample(input: FloatArray, ratio: Double): FloatArray {
        if (ratio <= 0.0 || abs(ratio - 1.0) < 1e-6 || input.isEmpty()) return input
        val outSize = max(1, (input.size * ratio).roundToInt())
        val out = FloatArray(outSize)
        val step = input.size.toDouble() / outSize
        for (i in 0 until outSize) {
            val src = i * step
            val idx = src.toInt()
            val frac = (src - idx).toFloat()
            val a = input[min(idx, input.size - 1)]
            val b = input[min(idx + 1, input.size - 1)]
            out[i] = a + (b - a) * frac
        }
        return out
    }

    /** Порт _apply_formant_shift: полосовой фильтр + подмешивание 30% к оригиналу. */
    fun formantShift(input: FloatArray, sampleRate: Int, shift: Float): FloatArray {
        if (abs(shift) < 0.1f) return input
        val center = 500f * 2f.pow(shift * 0.3f)
        val low = max(20f, center - 200f)
        val high = min(sampleRate / 2f - 100f, center + 200f)
        if (high <= low) return input
        val filtered = bandpass(input, sampleRate, low, high)
        return FloatArray(input.size) { i -> 0.7f * input[i] + 0.3f * filtered[i] }
    }

    /** Кольцевая модуляция 50 Гц + bitcrush до 16 уровней. */
    fun robot(input: FloatArray, sampleRate: Int): FloatArray {
        val out = FloatArray(input.size)
        val levels = 16f
        for (i in input.indices) {
            val t = i.toDouble() / sampleRate
            val mod = sin(2.0 * PI * 50.0 * t).toFloat()
            out[i] = (round(input[i] * mod * levels) / levels).coerceIn(-1f, 1f)
        }
        return out
    }

    /** Фильтр ВЧ 500 Гц + слабый шум. */
    fun whisper(input: FloatArray, sampleRate: Int): FloatArray {
        val filtered = highpass(input, sampleRate, 500f)
        val rnd = java.util.Random(0x5EEDL)
        val out = FloatArray(input.size)
        for (i in input.indices) {
            out[i] = (filtered[i] + (rnd.nextFloat() - 0.5f) * 0.03f).coerceIn(-1f, 1f)
        }
        return out
    }

    /** Эхо: две задержки 150/250 мс с затуханием 0.4. */
    fun echo(input: FloatArray, sampleRate: Int): FloatArray {
        val out = FloatArray(input.size) { input[it] }
        for (delayMs in listOf(150, 250)) {
            val delay = sampleRate * delayMs / 1000
            if (delay >= input.size) continue
            for (i in delay until input.size) {
                out[i] = (out[i] + input[i - delay] * 0.4f).coerceIn(-1f, 1f)
            }
        }
        return out
    }

    fun loud(input: FloatArray): FloatArray {
        val out = FloatArray(input.size)
        for (i in input.indices) out[i] = tanh(input[i] * 1.5f)
        return out
    }

    // ── биквадные фильтры (замена scipy butter) ──────────────────

    /** Полосовой Баттерворта 2-го порядка: ФВЧ(low) → ФНЧ(high). */
    fun bandpass(input: FloatArray, sampleRate: Int, low: Float, high: Float): FloatArray {
        var signal = highpass(input, sampleRate, low)
        signal = lowpass(signal, sampleRate, high)
        return signal
    }

    /** Полосовой 4-го порядка (телефонный канал). */
    fun telephoneBand(input: FloatArray, sampleRate: Int, order: Int = 2): FloatArray {
        var signal = input
        repeat(order) {
            signal = bandpass(signal, sampleRate, 300f, 3400f)
        }
        return signal
    }

    fun highpass(input: FloatArray, sampleRate: Int, freq: Float): FloatArray {
        val w0 = 2.0 * PI * freq / sampleRate
        val cosw = cos(w0)
        val alpha = sin(w0) / (2.0 * 0.7071067811865476)
        val a0 = 1.0 + alpha
        val b0 = (1.0 + cosw) / 2.0 / a0
        val b1 = -(1.0 + cosw) / a0
        val b2 = b0
        val a1 = -2.0 * cosw / a0
        val a2 = (1.0 - alpha) / a0
        return biquad(input, b0, b1, b2, a1, a2)
    }

    fun lowpass(input: FloatArray, sampleRate: Int, freq: Float): FloatArray {
        val w0 = 2.0 * PI * freq / sampleRate
        val cosw = cos(w0)
        val alpha = sin(w0) / (2.0 * 0.7071067811865476)
        val a0 = 1.0 + alpha
        val b0 = (1.0 - cosw) / 2.0 / a0
        val b1 = (1.0 - cosw) / a0
        val b2 = b0
        val a1 = -2.0 * cosw / a0
        val a2 = (1.0 - alpha) / a0
        return biquad(input, b0, b1, b2, a1, a2)
    }

    private fun biquad(input: FloatArray, b0: Double, b1: Double, b2: Double, a1: Double, a2: Double): FloatArray {
        val out = FloatArray(input.size)
        var x1 = 0.0; var x2 = 0.0
        var y1 = 0.0; var y2 = 0.0
        for (i in input.indices) {
            val x0 = input[i].toDouble()
            val y0 = b0 * x0 + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
            x2 = x1; x1 = x0
            y2 = y1; y1 = y0
            out[i] = y0.toFloat()
        }
        return out
    }

    // ── утилиты ──────────────────────────────────────────────────

    private fun hann(size: Int): FloatArray {
        val w = FloatArray(size)
        for (i in 0 until size) w[i] = (0.5 - 0.5 * cos(2.0 * PI * i / (size - 1))).toFloat()
        return w
    }

    private fun scale(input: FloatArray, factor: Float): FloatArray {
        val out = FloatArray(input.size)
        for (i in input.indices) out[i] = (input[i] * factor).coerceIn(-1f, 1f)
        return out
    }

    private fun round(v: Float): Float = floor(v + 0.5f)

    fun toFloat(pcm: ShortArray): FloatArray {
        val out = FloatArray(pcm.size)
        for (i in pcm.indices) out[i] = pcm[i] / 32768f
        return out
    }

    fun toShort(audio: FloatArray): ShortArray {
        val out = ShortArray(audio.size)
        for (i in audio.indices) {
            val v = (audio[i].coerceIn(-1f, 1f) * 32767f).roundToInt()
            out[i] = v.coerceIn(-32768, 32767).toShort()
        }
        return out
    }

    /** Полутон → коэффициент, как SEMITONE_RATIO ** semitones. */
    fun semitoneRatio(semitones: Float): Double = SEMITONE_RATIO.pow(semitones.toDouble())

    @Suppress("unused")
    private fun unusedGuard() {
        // держим импорты, нужные для констант DSP
        log2(1.0); exp(0.0); sqrt(1.0)
    }
}

package com.screenocr.tts.tts

import android.util.Log
import kotlin.math.PI
import kotlin.math.abs
import kotlin.math.cos
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min
import kotlin.math.pow
import kotlin.math.roundToInt
import kotlin.math.sin
import kotlin.math.tanh

private const val TAG = "ScreenOCR"

/**
 * Порт voice_changer.py: DSP-трансформация голоса (pitch / speed / formant)
 * на моно-PCM 24 кГц.
 *
 * В Python и питч, и скорость меняются одним ресемплингом (то есть всегда
 * вместе). Здесь разделено: питч — WSOLA-растяжение + ресемплинг, темп —
 * только WSOLA. Так при ускорении голос не «плавает» по высоте.
 */
object VoiceChanger {

    const val SAMPLE_RATE = 24000
    const val SEMITONE_RATIO = 2.0.pow(1.0 / 12.0)

    data class Preset(
        val name: String,
        val label: String,
        val pitchSemitones: Float = 0f,
        val speedFactor: Float = 1f,
        val formantShift: Float = 0f,
        val gender: String = "neutral",
        val description: String = "",
    )

    /** Порт PRESETS. */
    val PRESETS: Map<String, Preset> = linkedMapOf(
        "original" to Preset("original", "Оригинал", 0f, 1f, 0f, "neutral", "Без изменений"),
        "male_deep" to Preset("male_deep", "Бас", -5f, 0.95f, -1f, "male", "Глубокий мужской"),
        "male_old" to Preset("male_old", "Старик", -3f, 0.85f, -0.5f, "male", "Пожилой мужчина"),
