        "female" to Preset("female", "Женщина", 4f, 1f, 1f, "female", "Женский голос"),
        "female_sweet" to Preset("female_sweet", "Нежная", 5f, 1f, 1.5f, "female", "Мягкий женский"),
        "female_lord" to Preset("female_lord", "Госпожа", 3f, 0.95f, 0.5f, "female", "Строгий женский"),
        "female_girl" to Preset("female_girl", "Девочка", 7f, 1.15f, 2f, "female", "Юный голос"),
        "child" to Preset("child", "Ребёнок", 7f, 1.2f, 2f, "neutral", "Голос ребёнка"),
        "baby" to Preset("baby", "Малыш", 10f, 1.3f, 3f, "neutral", "Очень высокий голос"),
        "robot" to Preset("robot", "Робот", 0f, 1f, 0f, "neutral", "Роботизированный"),
        "whisper" to Preset("whisper", "Шёпот", 2f, 0.9f, 1f, "neutral", "Шёпот"),
        "slow" to Preset("slow", "Медленный", -2f, 0.7f, -0.5f, "neutral", "Размеренная речь"),
        "fast" to Preset("fast", "Быстрый", 1f, 1.3f, 0f, "neutral", "Быстрая речь"),
        "alien" to Preset("alien", "Пришелец", 8f, 0.9f, 3f, "neutral", "Инопланетный"),
        "monster" to Preset("monster", "Монстр", -8f, 0.7f, -3f, "male", "Чудовище"),
        "loud" to Preset("loud", "Громкий", 1f, 1f, 0f, "neutral", "Усиленная громкость"),
        "quiet" to Preset("quiet", "Тихий", -1f, 0.95f, 0f, "neutral", "Пониженная громкость"),
        "echo" to Preset("echo", "Эхо", 0f, 1f, 0f, "neutral", "С эхом-эффектом"),
        "telephone" to Preset("telephone", "Телефон", 2f, 1.1f, 1f, "neutral", "Как по телефону"),
        "radio" to Preset("radio", "Радио", 1f, 1f, 1f, "neutral", "Эффект радио"),
    )

    /** Порт get_presets_by_category. */
    fun presetsByCategory(): Map<String, List<Preset>> {
        val categories = linkedMapOf(
            "Оригинал" to listOf("original"),
            "Мужские" to listOf("male_deep", "male_old", "male_young", "male_giant"),
            "Женские" to listOf("female", "female_sweet", "female_lord", "female_girl"),
            "Детские" to listOf("child", "baby"),
            "Эффекты" to listOf("robot", "whisper", "slow", "fast", "alien", "monster"),
            "Громкость" to listOf("loud", "quiet"),
            "Канал" to listOf("echo", "telephone", "radio"),
        )
        return categories.mapValues { (_, names) -> names.mapNotNull { PRESETS[it] } }
    }

    fun getPreset(name: String?): Preset? = name?.let { PRESETS[it] }

    // ── основной вход ────────────────────────────────────────────

    /** Порт transform_audio: PCM → PCM по пресету. */
    fun transform(pcm: ShortArray, presetName: String, sampleRate: Int = SAMPLE_RATE): ShortArray {
        val preset = PRESETS[presetName]
        if (preset == null) {
            Log.w(TAG, "[VoiceChanger] Неизвестный пресет: $presetName, берём original")
            return pcm
        }
        if (preset.name == "original" || pcm.isEmpty()) return pcm

        Log.i(
            TAG,
            "[VoiceChanger] ${preset.label}: pitch=${preset.pitchSemitones}st, " +
                "speed=${preset.speedFactor}x, formant=${preset.formantShift}",
        )
        var audio = toFloat(pcm)
        if (abs(preset.pitchSemitones) > 0.1f) audio = changePitch(audio, preset.pitchSemitones)
        if (abs(preset.speedFactor - 1f) > 0.01f) audio = timeStretch(audio, 1f / preset.speedFactor)
        if (abs(preset.formantShift) > 0.1f) audio = formantShift(audio, sampleRate, preset.formantShift)

        audio = when (preset.name) {
            "robot" -> robot(audio, sampleRate)
            "whisper" -> whisper(audio, sampleRate)
            "echo" -> echo(audio, sampleRate)
            "loud" -> loud(audio)
            "quiet" -> scale(audio, 0.5f)
            "telephone" -> scale(telephoneBand(audio, sampleRate, 2), 2f)
            "radio" -> {
                val band = telephoneBand(audio, sampleRate, 2)
                FloatArray(band.size) { i -> tanh(0.7f * band[i] * 1.5f) }
            }
            else -> audio
        }
        return toShort(audio)
    }

    /** Сдвиг тона на полутонов без изменения длительности. */
    fun changePitch(pcm: ShortArray, semitones: Float): ShortArray {
        if (pcm.isEmpty()) return pcm
        return toShort(changePitch(toFloat(pcm), semitones))
    }

    /** Изменение темпа без изменения высоты тона. factor > 1 — быстрее. */
    fun changeSpeed(pcm: ShortArray, factor: Float): ShortArray {
        if (pcm.isEmpty()) return pcm
        return toShort(timeStretch(toFloat(pcm), 1f / factor))
    }

    // ── DSP ──────────────────────────────────────────────────────

    private fun changePitch(input: FloatArray, semitones: Float): FloatArray {
        val ratio = SEMITONE_RATIO.pow(semitones)
        if (abs(ratio - 1.0) < 0.005) return input
        // Растягиваем по времени в ratio раз, затем сжимаем обратно ресемплингом:
        // длительность сохраняется, высота тона растёт в ratio раз.
        val stretched = timeStretch(input, ratio)
        return resample(stretched, 1.0 / ratio)
    }

    /**
     * WSOLA: overlap-add с поиском оптимального сдвига анализируемого окна.
     * factor > 1 — длиннее и медленнее, factor < 1 — короче и быстрее.
     */
    fun timeStretch(input: FloatArray, factor: Float): FloatArray {
        if (abs(factor - 1f) < 0.01f || input.size < 4096) return input
        val frame = 1024
        val synHop = frame / 4
        val anaHop = max(1, (synHop * factor).roundToInt())
        val search = frame / 8
        val window = hann(frame)

        val frames = (input.size - frame) / anaHop + 1
        val outSize = (frames - 1) * synHop + frame
        val out = FloatArray(outSize)
        val norm = FloatArray(outSize)

        var anaPos = 0
        var synPos = 0
        while (anaPos + frame <= input.size) {
            val start = if (synPos == 0) anaPos else bestOffset(input, out, anaPos, synPos, search)
            for (i in 0 until frame) {
                val w = window[i]
                out[synPos + i] += input[start + i] * w
                norm[synPos + i] += w
            }
            anaPos += anaHop
            synPos += synHop
        }
        val result = FloatArray(outSize)
        for (i in outSize.indices) {
            result[i] = if (norm[i] > 1e-4f) out[i] / norm[i] else 0f
        }
        return result
    }

    /** Сдвиг, при котором сигнал лучше всего продолжает уже синтезированный фрагмент. */
    private fun bestOffset(
        input: FloatArray,
        out: FloatArray,
        anaPos: Int,
        synPos: Int,
        search: Int,
    ): Int {
        val limit = min(search, min(anaPos, input.size - anaPos - 512).coerceAtLeast(0))
        if (limit <= 0 || synPos < 256) return anaPos
        var bestPos = anaPos
        var bestScore = Float.NEGATIVE_INFINITY
        for (delta in -limit..limit) {
            val pos = anaPos + delta
            if (pos < 0 || pos + 512 > input.size) continue
            var score = 0f
            var i = 0
            while (i < 256) {
                score += out[synPos - 256 + i] * input[pos + i]
                i += 2
            }
            if (score > bestScore) {
                bestScore = score
                bestPos = pos
            }
        }
        return bestPos
    }

    /** Линейная передискретизация: out.size ≈ in.size * ratio. */
    fun resample(input: FloatArray, ratio: Double): FloatArray {
        if (ratio <= 0.0 || abs(ratio - 1.0) < 1e-6 || input.isEmpty()) return input
        val outSize = max(1, (input.size * ratio).roundToInt())
        val out = FloatArray(outSize)
        val step = input.size.toDouble() / outSize
        for (i in 0 until outSize) {
            val src = i * step
            val idx = src.toInt()
            val frac = (src - idx).toFloat()
            val a = input[min(idx, input.size - 1)]
            val b = input[min(idx + 1, input.size - 1)]
            out[i] = a + (b - a) * frac
        }
        return out
    }

    /** Порт _apply_formant_shift: полосовой фильтр, 30% фильтра + 70% оригинала. */
    fun formantShift(input: FloatArray, sampleRate: Int, shift: Float): FloatArray {
        if (abs(shift) < 0.1f) return input
        val center = 500f * 2f.pow(shift * 0.3f)
        val low = max(20f, center - 200f)
        val high = min(sampleRate / 2f - 100f, center + 200f)
        if (high <= low) return input
        val filtered = bandpass(input, sampleRate, low, high)
        return FloatArray(input.size) { i -> 0.7f * input[i] + 0.3f * filtered[i] }
    }

    /** Кольцевая модуляция 50 Гц + bitcrush до 16 уровней. */
    fun robot(input: FloatArray, sampleRate: Int): FloatArray {
        val out = FloatArray(input.size)
        val levels = 16f
        for (i in input.indices) {
            val t = i.toDouble() / sampleRate
            val mod = sin(2.0 * PI * 50.0 * t).toFloat()
            out[i] = (floor(input[i] * mod * levels + 0.5f) / levels).coerceIn(-1f, 1f)
        }
        return out
    }

    /** Фильтр ВЧ 500 Гц + слабый шум. */
    fun whisper(input: FloatArray, sampleRate: Int): FloatArray {
        val filtered = highpass(input, sampleRate, 500f)
        val rnd = java.util.Random(0x5EEDL)
        val out = FloatArray(input.size)
        for (i in input.indices) {
            out[i] = (filtered[i] + (rnd.nextFloat() - 0.5f) * 0.03f).coerceIn(-1f, 1f)
        }
        return out
    }

    /** Эхо: задержки 150 и 250 мс, затухание 0.4. */
    fun echo(input: FloatArray, sampleRate: Int): FloatArray {
        val out = FloatArray(input.size) { input[it] }
        for (delayMs in listOf(150, 250)) {
            val delay = sampleRate * delayMs / 1000
            if (delay >= input.size) continue
            for (i in delay until input.size) {
                out[i] = (out[i] + input[i - delay] * 0.4f).coerceIn(-1f, 1f)
            }
        }
        return out
    }

    fun loud(input: FloatArray): FloatArray {
        val out = FloatArray(input.size)
        for (i in input.indices) out[i] = tanh(input[i] * 1.5f)
        return out
    }

    // ── биквадные фильтры (замена scipy.signal.butter) ───────────

    /** Полосовой Баттерворта 2-го порядка: ФВЧ(low) → ФНЧ(high). */
    fun bandpass(input: FloatArray, sampleRate: Int, low: Float, high: Float): FloatArray {
        val highPassed = highpass(input, sampleRate, low)
        return lowpass(highPassed, sampleRate, high)
    }

    /** Полосовой 4-го порядка — телефонный канал 300..3400 Гц. */
    fun telephoneBand(input: FloatArray, sampleRate: Int, order: Int = 2): FloatArray {
        var signal = input
        repeat(order) {
            signal = bandpass(signal, sampleRate, 300f, 3400f)
        }
        return signal
    }

    fun highpass(input: FloatArray, sampleRate: Int, freq: Float): FloatArray {
        val w0 = 2.0 * PI * freq / sampleRate
        val cosw = cos(w0)
        val alpha = sin(w0) / (2.0 * Q_BUTTERWORTH)
        val a0 = 1.0 + alpha
        val b0 = (1.0 + cosw) / 2.0 / a0
        val b1 = -(1.0 + cosw) / a0
        val a1 = -2.0 * cosw / a0
        val a2 = (1.0 - alpha) / a0
        return biquad(input, b0, b1, b0, a1, a2)
    }

    fun lowpass(input: FloatArray, sampleRate: Int, freq: Float): FloatArray {
        val w0 = 2.0 * PI * freq / sampleRate
        val cosw = cos(w0)
        val alpha = sin(w0) / (2.0 * Q_BUTTERWORTH)
        val a0 = 1.0 + alpha
        val b0 = (1.0 - cosw) / 2.0 / a0
        val b1 = (1.0 - cosw) / a0
        val a1 = -2.0 * cosw / a0
        val a2 = (1.0 - alpha) / a0
        return biquad(input, b0, b1, b0, a1, a2)
    }

    private const val Q_BUTTERWORTH = 0.7071067811865476

    /** Форма разности: y[n] = b0·x[n] + b1·x[n-1] + b2·x[n-2] − a1·y[n-1] − a2·y[n-2]. */
    private fun biquad(
        input: FloatArray,
        b0: Double, b1: Double, b2: Double, a1: Double, a2: Double,
    ): FloatArray {
        val out = FloatArray(input.size)
        var x1 = 0.0; var x2 = 0.0
        var y1 = 0.0; var y2 = 0.0
        for (i in input.indices) {
            val x0 = input[i].toDouble()
            val y0 = b0 * x0 + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2
            x2 = x1; x1 = x0
            y2 = y1; y1 = y0
            out[i] = y0.toFloat()
        }
        return out
    }

    // ── утилиты ──────────────────────────────────────────────────

    private fun hann(size: Int): FloatArray {
        val w = FloatArray(size)
        for (i in 0 until size) w[i] = (0.5 - 0.5 * cos(2.0 * PI * i / (size - 1))).toFloat()
        return w
    }

    private fun scale(input: FloatArray, factor: Float): FloatArray {
        val out = FloatArray(input.size)
        for (i in input.indices) out[i] = (input[i] * factor).coerceIn(-1f, 1f)
        return out
    }

    fun toFloat(pcm: ShortArray): FloatArray {
        val out = FloatArray(pcm.size)
        for (i in pcm.indices) out[i] = pcm[i] / 32768f
        return out
    }

    fun toShort(audio: FloatArray): ShortArray {
        val out = ShortArray(audio.size)
        for (i in audio.indices) {
            val v = (audio[i].coerceIn(-1f, 1f) * 32767f).roundToInt()
            out[i] = v.coerceIn(-32768, 32767).toShort()
        }
        return out
    }
}

package com.screenocr.tts.tts

import android.content.Context
import android.util.Log
import com.screenocr.tts.tts.TtsEngine.Role
import org.json.JSONObject
import java.io.File

private const val TAG = "ScreenOCR"

/**
 * Порт voice_profiles.py: профили голоса, словарь персонажей и роутер языка.
 * Пользовательские профили грузятся из voice_profiles.json (assets либо filesDir),
 * при отсутствии файла используются встроенные — как _create_defaults().
 */
data class VoiceProfile(
    val name: String,
    val gender: String,
    val voiceCode: String,
    val rate: Int = 0,
    val pitch: Int = 0,
    val language: String = "auto",
    val volume: Float = 1f,
    val emotion: String = "normal",
    val description: String = "",
    val isBuiltin: Boolean = false,
)

object VoiceProfiles {

    /** Порт _create_defaults() + VoiceDictionary._load_defaults(). */
    val DEFAULTS: List<VoiceProfile> = listOf(
        VoiceProfile("Рассказчик", "male", "edge:ru-RU-DmitryNeural", 0, 0, "ru", description = "Рассказчик (ru)"),
        VoiceProfile("Герой", "male", "edge:ru-RU-DmitryNeural", -10, 0, "ru", description = "Герой (ru)"),
        VoiceProfile("Героиня", "female", "edge:ru-RU-SvetlanaNeural", 0, 0, "ru", volume = 0.9f, description = "Героиня (ru)"),
        VoiceProfile("Narrator", "male", "edge:en-US-GuyNeural", 0, 0, "en", description = "Narrator (en)"),
        VoiceProfile("Hero", "male", "edge:en-US-GuyNeural", -10, 0, "en", description = "Hero (en)"),
        VoiceProfile("Heroine", "female", "edge:en-US-JennyNeural", 0, 0, "en", volume = 0.9f, description = "Heroine (en)"),
    )

    val DEFAULT: VoiceProfile = VoiceProfile("default", "any", "edge:ru-RU-DmitryNeural")

    private val RUSSIAN_WORDS = setOf(
        "и", "в", "не", "на", "я", "что", "он", "с", "это", "а", "как", "но", "да",
        "мы", "за", "то", "она", "они", "вы", "от", "по", "его", "её", "их", "бы",
        "же", "уже", "для", "был", "была", "были", "быть", "есть", "или", "если",
        "когда", "где", "чем", "кто", "этот", "эта", "эти", "тот", "та", "те",
    )

    private val ENGLISH_WORDS = setOf(
        "the", "a", "an", "and", "or", "but", "in", "on", "at", "to", "for", "of", "with",
        "by", "from", "as", "is", "was", "are", "were", "be", "been", "being", "have",
        "has", "had", "do", "does", "did", "will", "would", "could", "should", "may",
        "i", "you", "he", "she", "it", "we", "they", "me", "him", "her", "my", "your",
        "what", "which", "who", "where", "when", "why", "how", "all", "each", "every",
        "this", "that", "these", "those", "not", "only", "same", "so", "than", "too",
    )

    /** Порт SUPPORTED_LANGUAGES. */
    val SUPPORTED_LANGUAGES: Map<String, String> = linkedMapOf(
        "ru" to "Russian", "en" to "English", "ja" to "Japanese", "de" to "German",
        "fr" to "French", "es" to "Spanish", "it" to "Italian", "uk" to "Ukrainian",
        "pl" to "Polish", "pt" to "Portuguese", "tr" to "Turkish", "ar" to "Arabic",
        "hi" to "Hindi", "th" to "Thai", "zh" to "Chinese", "ko" to "Korean",
    )

    val all: List<VoiceProfile> get() = DEFAULTS

    fun byName(name: String?): VoiceProfile? {
        if (name.isNullOrBlank()) return null
        val key = name.lowercase().trim()
        return DEFAULTS.firstOrNull { it.name.lowercase() == key }
    }

    /**
     * Порт VoiceRouter.get_voice_for_lang: голос для языка и роли.
     * ru/en разведены по гендеру, остальные языки отдают русский дефолт.
     */
    fun getVoiceForLanguage(lang: String, role: Role): VoiceProfile {
        val language = lang.lowercase().substringBefore('-')
        val gender = when (role) {
            Role.MALE, Role.NARRATOR -> "male"
            Role.FEMALE -> "female"
        }
        DEFAULTS.firstOrNull { it.language == language && it.gender == gender }
            ?.let { return it }
        DEFAULTS.firstOrNull { it.language == language && it.gender == "male" }
            ?.let { return it }
        return byName("Рассказчик") ?: DEFAULT
    }

    /**
     * Порт MultiVoiceParser.detect_language: по алфавиту, затем по стоп-словам.
     */
    fun detectLanguage(text: String?): String {
        if (text.isNullOrBlank()) return "auto"
        if (CYRILLIC.containsMatchIn(text)) return "ru"
        if (CJK.containsMatchIn(text)) return "ja"
        if (GERMAN.containsMatchIn(text)) return "de"
        if (FRENCH.containsMatchIn(text)) return "fr"
        val words = WORDS.findAll(text.lowercase()).map { it.value }.toList()
        if (words.isEmpty()) return "auto"
        val ru = words.count { it in RUSSIAN_WORDS }
        val en = words.count { it in ENGLISH_WORDS }
        if (ru > en && ru > 0) return "ru"
        if (en > ru && en > 0) return "en"
        return "en"
    }

    /** Порт _detect_text_lang из tts_engine.py: доля кириллицы > 0.3 → ru. */
    fun detectTextLanguage(text: String?): String {
        if (text.isNullOrEmpty()) return "en"
        var cyrillic = 0
        var total = 0
        for (ch in text) {
            if (!ch.isLetter()) continue
            total++
            if (ch.code in 0x0400..0x04FF) cyrillic++
        }
        if (total == 0) return "en"
        return if (cyrillic.toDouble() / total > 0.3) "ru" else "en"
    }

    private val CYRILLIC = Regex("[А-Яа-яёЁ]")
    private val CJK = Regex("[぀-ヿ一-鿿가-힯]")
    private val GERMAN = Regex("[äöüßÄÖÜ]")
    private val FRENCH = Regex("[àâçéèêëïîôùûüÿœæÀÂÇÉÈÊËÏÎÔÙÛÜŸŒÆ]")
    private val WORDS = Regex("[A-Za-zа-яёА-ЯЁ]+")

    /** Порт MultiVoiceParser.parse_line: «A: текст», «A> текст», «[A] текст», «(A) текст». */
    fun parseLine(text: String): Pair<String?, String> {
        val line = text.trim()
        if (line.isEmpty()) return null to ""
        for (pattern in DIALOGUE_PATTERNS) {
            val m = pattern.matchEntire(line) ?: pattern.find(line) ?: continue
            if (m.groupCount >= 2) {
                val speaker = m.groupValues[1].trim()
                val body = m.groupValues[2].trim()
                if (speaker.isNotEmpty() && body.isNotEmpty()) return speaker to body
            }
        }
        return null to line
    }

    private val DIALOGUE_PATTERNS = listOf(
        Regex("^([^:>]+)[:>]\\s*(.+)$"),
        Regex("^\\[([^]]+)]\\s*(.+)$"),
        Regex("^\\(([^)]+)\\)\\s*(.+)$"),
    )

    /**
     * Пользовательские профили из voice_profiles.json.
     * Файл ищется в assets, затем в filesDir; если его нет — возвращаются
     * встроенные (как _create_defaults() + _save() в Python-версии).
     */
    fun loadUserProfiles(context: Context): List<VoiceProfile> {
        val json = readJson(context) ?: return DEFAULTS
        val result = ArrayList<VoiceProfile>()
        val names = json.keys()
        while (names.hasNext()) {
            val name = names.next()
            val obj = json.optJSONObject(name) ?: continue
            result += VoiceProfile(
                name = name,
                gender = genderName(obj.optString("voice", ""), obj.optString("gender", "any")),
                voiceCode = obj.optString("voice", DEFAULT.voiceCode),
                rate = obj.optInt("rate", 0),
                pitch = obj.optInt("pitch", 0),
                language = obj.optString("language", "auto"),
                volume = obj.optDouble("volume", 1.0).toFloat(),
                emotion = obj.optString("emotion", "normal"),
                description = obj.optString("description", ""),
                isBuiltin = obj.optBoolean("is_builtin", false),
            )
        }
        if (result.isEmpty()) {
            Log.w(TAG, "[VoiceProfiles] voice_profiles.json пуст, беру дефолты")
            return DEFAULTS
        }
        Log.i(TAG, "[VoiceProfiles] Загружено профилей: ${result.size}")
        return result
    }

    private fun readJson(context: Context): JSONObject? {
        val fromAssets = try {
            context.assets.open("voice_profiles.json").use { it.readBytes().toString(Charsets.UTF_8) }
        } catch (_: Throwable) {
            null
        }
        val raw = fromAssets ?: runCatching {
            val f = File(context.filesDir, "voice_profiles.json")
            if (f.exists()) f.readText() else null
        }.getOrNull() ?: return null
        return try {
            JSONObject(raw)
        } catch (e: Throwable) {
            Log.w(TAG, "[VoiceProfiles] Битый voice_profiles.json: ${e.message}")
            null
        }
    }

    /** «rhvoice:Aleksandr» / «ru-RU-DmitryNeural» → male, «Svetlana» → female. */
    private fun genderName(voiceCode: String, explicit: String): String {
        if (explicit.isNotBlank() && explicit != "unknown") return explicit.lowercase()
        val lower = voiceCode.lowercase()
        return when {
            listOf("svetlana", "alena", "katya", "milena", "female", "женск").any { lower.contains(it) } -> "female"
            listOf("dmitry", "pavel", "aleksandr", "yuri", "male", "мужск").any { lower.contains(it) } -> "male"
            else -> "any"
        }
    }
}

