package com.screenocr.tts.tts

import android.content.Context
import android.os.Bundle
import android.speech.tts.TextToSpeech
import android.speech.tts.UtteranceProgressListener
import android.speech.tts.Voice
import android.util.Log
import kotlinx.coroutines.CompletableDeferred
import kotlinx.coroutines.withTimeoutOrNull
import java.io.File
import java.util.Locale
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean

private const val TAG = "ScreenOCR"

/**
 * Порт tts_engine.py::_speak_sapi5 — системный синтез речи.
 *
 * На Android это android.speech.tts.TextToSpeech: он есть на любом устройстве,
 * работает офлайн и потому является основным бэкендом, когда Edge недоступен.
 */
class AndroidTtsBackend(private val context: Context) {

    private val appContext = context.applicationContext
    private val lock = Any()
    private val readySignal = CompletableDeferred<Boolean>()
    private val pending = ConcurrentHashMap<String, CompletableDeferred<Int>>()
    private val shuttingDown = AtomicBoolean(false)

    @Volatile
    private var engine: TextToSpeech? = null

    @Volatile
    private var initialized = false

    @Volatile
    var lastError: String? = null
        private set

    private val progressListener = object : UtteranceProgressListener() {
        override fun onStart(utteranceId: String?) = Unit

        override fun onDone(utteranceId: String?) {
            utteranceId?.let { pending.remove(it)?.complete(TextToSpeech.SUCCESS) }
        }

        @Suppress("OVERRIDE_DEPRECATION", "DEPRECATION")
        override fun onError(utteranceId: String?) {
            utteranceId?.let { pending.remove(it)?.complete(TextToSpeech.ERROR) }
        }

        override fun onError(utteranceId: String?, errorCode: Int) {
            utteranceId?.let { pending.remove(it)?.complete(errorCode) }
        }

        override fun onStop(utteranceId: String?, interrupted: Boolean) {
            if (interrupted) utteranceId?.let { pending.remove(it)?.complete(TextToSpeech.ERROR) }
        }
    }

    /** Создаёт TextToSpeech при первом обращении; потокобезопасно. */
    private fun ensureCreated() {
        if (engine != null) return
        synchronized(lock) {
            if (engine != null) return
            try {
                engine = TextToSpeech(appContext) { status ->
                    val tts = engine
                    if (status == TextToSpeech.SUCCESS && tts != null) {
                        runCatching { tts.setOnUtteranceProgressListener(progressListener) }
                            .onFailure { Log.w(TAG, "[SystemTTS] listener не установлен: ${it.message}") }
                        initialized = true
                        readySignal.complete(true)
                        Log.i(TAG, "[SystemTTS] Инициализирован: ${tts.defaultEngine}")
                    } else {
                        lastError = "TextToSpeech init status=$status"
                        readySignal.complete(false)
                        Log.e(TAG, "[SystemTTS] $lastError")
                    }
                }
            } catch (e: Throwable) {
                lastError = e.message ?: e::class.java.simpleName
                readySignal.complete(false)
                Log.e(TAG, "[SystemTTS] Создание не удалось: $lastError")
            }
        }
    }

    /** Ждёт готовности движка. */
    suspend fun awaitReady(): Boolean {
        ensureCreated()
        return readySignal.await()
    }

    val isReady: Boolean get() = initialized

    /** Готов ли движокSpeak'ить русский (в системе может не быть ru-данных). */
    fun isLanguageAvailable(locale: Locale = Locale("ru", "RU")): Boolean {
        val tts = engine ?: return false
        if (!initialized) return false
        return runCatching { tts.isLanguageAvailable(locale) >= TextToSpeech.LANG_AVAILABLE }
            .getOrDefault(false)
    }

    /**
     * Доступные голоса, отфильтрованные по русской локали — требование контракта.
     * [includeAllLanguages] нужен для диагностики на устройствах без ru-голосов.
     */
    fun listVoices(includeAllLanguages: Boolean = false): List<TtsEngine.VoiceInfo> {
        val tts = engine ?: return emptyList()
        if (!initialized) return emptyList()
        val voices: Set<Voice> = runCatching { tts.voices }.getOrElse {
            Log.w(TAG, "[SystemTTS] voices недоступны: ${it.message}")
            return emptyList()
        }
        return voices.asSequence()
            .filter { includeAllLanguages || isRussian(it.locale) }
            .sortedWith(compareBy({ !it.features.contains(TextToSpeech.Engine.KEY_FEATURE_NETWORK_SYNTHESIS) }, { it.name }))
            .map { it.toVoiceInfo() }
            .toList()
    }

    private fun isRussian(locale: Locale): Boolean =
        locale.language.equals("ru", ignoreCase = true) ||
            locale.toLanguageTag().startsWith("ru", ignoreCase = true)

    private fun Voice.toVoiceInfo() = TtsEngine.VoiceInfo(
        code = "system:$name",
        name = name,
        engine = "system",
        gender = when {
            Voice.GENDER_MALE == gender -> "Male"
            Voice.GENDER_FEMALE == gender -> "Female"
            else -> "Unknown"
        },
        locale = locale.toLanguageTag(),
    )

    /**
     * Озвучивание. Возвращает true, если движок дошёл до конца фразы.
     * rate/pitch — в процентах десктопного диапазона (rate: -100..+100, pitch: -50..+50).
     */
    suspend fun speak(
        text: String,
        utteranceId: String,
        ratePercent: Int = 0,
        pitchPercent: Int = 0,
        volume: Float = 1f,
        flush: Boolean = true,
    ): Boolean {
        if (text.isBlank()) return false
        if (!awaitReady()) return false
        val tts = engine ?: return false

        val deferred = CompletableDeferred<Int>()
        pending.remove(utteranceId)?.cancel()
        pending[utteranceId] = deferred

        runCatching {
            tts.setSpeechRate(rateMultiplier(ratePercent))
            tts.setPitch(pitchMultiplier(pitchPercent))
        }.onFailure { Log.w(TAG, "[SystemTTS] rate/pitch: ${it.message}") }

        val params = Bundle().apply {
            putString(TextToSpeech.Engine.KEY_PARAM_UTTERANCE_ID, utteranceId)
            putFloat(TextToSpeech.Engine.KEY_PARAM_VOLUME, volume.coerceIn(0f, 1f))
        }
        val queueMode = if (flush) TextToSpeech.QUEUE_FLUSH else TextToSpeech.QUEUE_ADD
        val rc = runCatching { tts.speak(text, queueMode, params, utteranceId) }.getOrElse {
            Log.e(TAG, "[SystemTTS] speak() упал: ${it.message}")
            TextToSpeech.ERROR
        }
        if (rc != TextToSpeech.SUCCESS) {
            pending.remove(utteranceId)
            lastError = "speak rc=$rc"
            return false
        }
        val result = deferred.await()
        if (result != TextToSpeech.SUCCESS) lastError = "utterance result=$result"
        return result == TextToSpeech.SUCCESS
    }

    /**
     * Синтез без воспроизведения: движок пишет WAV во временный файл,
     * который разбирается в PCM. Нужно для generatePcm() и DSP-пресетов.
     */
    suspend fun synthesizeToPcm(
        text: String,
        utteranceId: String,
        ratePercent: Int = 0,
        pitchPercent: Int = 0,
    ): ShortArray? {
        if (text.isBlank()) return null
        if (!awaitReady()) return null
        val tts = engine ?: return null

        val target = File(appContext.cacheDir, "tts_synth_$utteranceId.wav")
        target.delete()

        val deferred = CompletableDeferred<Int>()
        pending.remove(utteranceId)?.cancel()
        pending[utteranceId] = deferred

        runCatching {
            tts.setSpeechRate(rateMultiplier(ratePercent))
            tts.setPitch(pitchMultiplier(pitchPercent))
        }.onFailure { Log.w(TAG, "[SystemTTS] rate/pitch: ${it.message}") }

        val params = Bundle().apply {
            putString(TextToSpeech.Engine.KEY_PARAM_UTTERANCE_ID, utteranceId)
        }
        val rc = runCatching {
            tts.synthesizeToFile(text, params, target, utteranceId)
        }.getOrElse {
            Log.w(TAG, "[SystemTTS] synthesizeToFile недоступен: ${it.message}")
            TextToSpeech.ERROR
        }
        if (rc != TextToSpeech.SUCCESS) {
            pending.remove(utteranceId)
            return null
        }
        val result = withTimeoutOrNull(SYNTH_TIMEOUT_MS) { deferred.await() } ?: TextToSpeech.ERROR
        pending.remove(utteranceId)
        if (result != TextToSpeech.SUCCESS || !target.exists() || target.length() < 64) {
            target.delete()
            Log.w(TAG, "[SystemTTS] Синтез в файл не удался (result=$result)")
            return null
        }
        val pcm = try {
            readWav(target.readBytes())
        } finally {
            target.delete()
        }
        if (pcm == null || pcm.isEmpty()) {
            Log.w(TAG, "[SystemTTS] WAV без данных")
            return null
        }
        return pcm
    }

    /** Останавливает текущую фразу и снимает ожидающие вызовы. */
    fun stop() {
        engine?.let { runCatching { it.stop() } }
        failPending()
    }

    /** Прямая озвучка с индивидуальным голосом (без смены глобального). */
    suspend fun speakWithVoice(
        text: String,
        voiceName: String,
        utteranceId: String,
        ratePercent: Int = 0,
        pitchPercent: Int = 0,
    ): Boolean {
        if (!awaitReady()) return false
        val tts = engine ?: return false
        val voice = runCatching { tts.voices?.firstOrNull { it.name == voiceName } }.getOrNull()
            ?: return false
        val rc = runCatching { tts.setVoice(voice) }.getOrElse {
            Log.w(TAG, "[SystemTTS] setVoice($voiceName): ${it.message}")
            return false
        }
        val ok = speak(text, utteranceId, ratePercent, pitchPercent)
        if (rc == TextToSpeech.SUCCESS) runCatching { tts.voice = null }
        return ok
    }

    fun shutdown() {
        if (!shuttingDown.compareAndSet(false, true)) return
        synchronized(lock) {
            runCatching { engine?.stop() }
            runCatching { engine?.shutdown() }
            engine = null
            initialized = false
        }
        failPending()
    }

    private fun failPending() {
        for ((_, deferred) in pending.entries) deferred.complete(TextToSpeech.ERROR)
        pending.clear()
    }

    /** +15% со скорости десктопа → 1.15 в диапазоне [0.5; 2.0]. */
    fun rateMultiplier(ratePercent: Int): Float =
        ((100f + ratePercent) / 100f).coerceIn(MIN_FACTOR, MAX_FACTOR)

    /** Единицы pitch -50..+50 → множитель 1.0 ± 0.5, тоже в [0.5; 2.0]. */
    fun pitchMultiplier(pitchPercent: Int): Float =
        (1f + pitchPercent / 100f).coerceIn(MIN_FACTOR, MAX_FACTOR)

    /** Минимальный разбор WAV: RIFF/WAVE → 16-битное моно. */
    private fun readWav(bytes: ByteArray): ShortArray? {
        if (bytes.size < 44) return null
        var pos = 12
        var sampleRate = 22050
        var channels = 1
        var bitsPerSample = 16
        var dataOffset = -1
        var dataSize = 0
        while (pos + 8 <= bytes.size) {
            val id = String(bytes, pos, 4, Charsets.US_ASCII)
            val size = readLeInt(bytes, pos + 4)
            val body = pos + 8
            if (size < 0 || body > bytes.size) break
            when (id) {
                "fmt " -> {
                    channels = readLeShort(bytes, body + 2)
                    sampleRate = readLeInt(bytes, body + 4)
                    bitsPerSample = readLeShort(bytes, body + 14)
                }
                "data" -> {
                    dataOffset = body
                    dataSize = minOf(size, bytes.size - body)
                }
            }
            pos = body + size + (size and 1)
            if (dataOffset >= 0 && id == "data") break
        }
        if (dataOffset < 0 || dataSize <= 0) return null
        if (bitsPerSample != 16) {
            Log.w(TAG, "[SystemTTS] Неподдерживаемый WAV: ${bitsPerSample} бит, ${sampleRate} Гц")
            return null
        }
        val step = if (channels > 1) 2 else 1
        val frames = dataSize / 2 / step
        if (frames <= 0) return null
        val out = ShortArray(frames)
        var i = 0
        var offset = dataOffset
        while (i < frames) {
            out[i] = readLeShort(bytes, offset).toShort()
            offset += 2 * step
            i++
        }
        Log.i(TAG, "[SystemTTS] WAV: ${frames} сэмплов @ $sampleRate Гц, каналов=$channels")
        return out
    }

    private fun readLeInt(b: ByteArray, off: Int): Int =
        (b[off].toInt() and 0xFF) or ((b[off + 1].toInt() and 0xFF) shl 8) or
            ((b[off + 2].toInt() and 0xFF) shl 16) or ((b[off + 3].toInt() and 0xFF) shl 24)

    private fun readLeShort(b: ByteArray, off: Int): Int =
        (b[off].toInt() and 0xFF) or ((b[off + 1].toInt() and 0xFF) shl 8)

    companion object {
        private const val MIN_FACTOR = 0.5f
        private const val MAX_FACTOR = 2.0f
        private const val SYNTH_TIMEOUT_MS = 25_000L
    }
}

package com.screenocr.tts.tts

import android.media.MediaCodec
import android.media.MediaFormat
import android.os.SystemClock
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.withContext
import kotlinx.coroutines.withTimeoutOrNull
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.Response
import okhttp3.WebSocket
import okhttp3.WebSocketListener
import okio.ByteString
import org.json.JSONObject
import java.io.ByteArrayOutputStream
import java.net.SocketTimeoutException
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.security.MessageDigest
import java.text.SimpleDateFormat
import java.util.Date
import java.util.Locale
import java.util.TimeZone
import java.util.UUID
import java.util.concurrent.TimeUnit
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference
import kotlin.coroutines.resume

private const val TAG = "ScreenOCR"

/**
 * Порт tts_engine.py::_gen_edge — синтез через облачный Microsoft Edge Read Aloud.
 *
 * Протокол воспроизведён вручную (Python-библиотека edge-tts недоступна на Android):
 *   1. WSS-подключение с Sec-MS-GEC (SHA-256 от Windows-тиков + trusted token).
 *   2. Текстовое сообщение Path:speech.config с outputFormat.
 *   3. Текстовое сообщение Path:ssml с <voice>/<prosody>.
 *   4. Бинарные кадры: [uint16 длина заголовка][заголовок Path:audio][\r\n][MP3].
 *   5. Path:turn.end завершает синтез.
 *
 * Наружу отдаётся MP3; разбор в PCM делает [Mp3PcmDecoder] (MediaCodec).
 */
class EdgeTts {

    data class SynthesisRequest(
        val text: String,
        val voice: String,
        val ratePercent: Int = 0,
        val pitchHz: Int = 0,
        val volumePercent: Int = 0,
        val outputFormat: String = OUTPUT_FORMAT,
    )

    data class RemoteVoice(
        val code: String,
        val name: String,
        val gender: String,
        val locale: String,
    )

    private val client: OkHttpClient = OkHttpClient.Builder()
        .connectTimeout(CONNECT_TIMEOUT_SEC, TimeUnit.SECONDS)
        .readTimeout(0, TimeUnit.MILLISECONDS)
        .writeTimeout(WRITE_TIMEOUT_SEC, TimeUnit.SECONDS)
        .pingInterval(0, TimeUnit.MILLISECONDS)
        .retryOnConnectionFailure(true)
        .build()

    @Volatile
    private var activeSocket: WebSocket? = null

    /** Смещение часов относительно сервера; подстраивается по ответу 403. */
    private val clockSkewSeconds = AtomicReference(0L)

    /**
     * Синтез речи. [onAudio] вызывается на потоке WebSocket для каждого
     * фрагмента MP3 — используется для потокового воспроизведения.
     */
    suspend fun synthesize(
        request: SynthesisRequest,
        onAudio: ((ByteArray) -> Unit)? = null,
    ): Result<ByteArray> {
        val text = sanitize(request.text)
        if (text.isEmpty()) return Result.failure(IllegalArgumentException("Edge TTS: пустой текст"))

        val chunks = splitTextByByteLength(text, MAX_CHUNK_BYTES)
        val sink = ByteArrayOutputStream(64 * 1024)
        var lastError: Throwable = SocketTimeoutException("Edge TTS: нет ответа")

        // Две попытки: первая с заголовком subprotocol, вторая — без него и
        // с пересчитанным Sec-MS-GEC после возможного 403 из-за расхождения часов.
        for (attempt in 0 until 2) {
            val result = withTimeoutOrNull(REQUEST_TIMEOUT_MS) {
                streamOnce(text, chunks, request, onAudio, useSubProtocol = attempt == 0, sink)
            } ?: Result.failure(SocketTimeoutException("Edge TTS: таймаут ${REQUEST_TIMEOUT_MS} мс"))
            val audio = result.getOrNull()
            if (result.isSuccess && audio != null && audio.isNotEmpty()) {
                return Result.success(audio)
            }
            lastError = result.exceptionOrNull() ?: lastError
            Log.w(TAG, "[Edge] Попытка ${attempt + 1} не удалась: ${lastError.message}")
        }
        return Result.failure(lastError)
    }

    private suspend fun streamOnce(
        text: String,
        chunks: List<String>,
        request: SynthesisRequest,
        onAudio: ((ByteArray) -> Unit)?,
        useSubProtocol: Boolean,
        out: ByteArrayOutputStream,
    ): Result<ByteArray> = suspendCancellableCoroutine { cont ->
        val done = AtomicBoolean(false)
        var receivedAudio = false

        fun succeed() {
            if (done.compareAndSet(false, true)) {
                val audio = out.toByteArray()
                if (audio.isEmpty() && !receivedAudio) {
                    cont.resume(Result.failure(SocketTimeoutException("Edge TTS: аудио не получено")))
                } else {
                    if (!receivedAudio) Log.w(TAG, "[Edge] Соединение закрыто без turn.end, отдаём усечённый MP3")
                    cont.resume(Result.success(audio))
                }
            }
        }

        fun fail(error: Throwable) {
            if (done.compareAndSet(false, true)) cont.resume(Result.failure(error))
        }

        val listener = object : WebSocketListener() {
            override fun onOpen(webSocket: WebSocket, response: Response) {
                if (!cont.isActive) return
                webSocket.send(speechConfigMessage(request.outputFormat))
                for (chunk in chunks) {
                    webSocket.send(ssmlMessage(chunk, request))
                }
            }

            override fun onMessage(webSocket: WebSocket, text: String) {
                if (pathOf(text).equals("turn.end", ignoreCase = true)) {
                    succeed()
                    webSocket.close(NORMAL_CLOSURE, null)
                }
            }

            override fun onMessage(webSocket: WebSocket, bytes: ByteString) {
                val data = bytes.toByteArray()
                if (data.size < 4) return
                val headerLength = ((data[0].toInt() and 0xFF) shl 8) or (data[1].toInt() and 0xFF)
                if (headerLength <= 0 || 4 + headerLength > data.size) return
                val header = String(data, 2, headerLength, Charsets.UTF_8)
                if (!header.contains("Path:audio", ignoreCase = true)) return
                val payloadStart = 4 + headerLength
                if (payloadStart >= data.size) return
                val payload = data.copyOfRange(payloadStart, data.size)
                if (payload.isEmpty()) return
                receivedAudio = true
                out.write(payload)
                onAudio?.invoke(payload)
            }

            override fun onClosing(webSocket: WebSocket, code: Int, reason: String) {
                webSocket.close(NORMAL_CLOSURE, null)
            }

            override fun onClosed(webSocket: WebSocket, code: Int, reason: String) {
                succeed()
            }

            override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
                if (response?.code == HTTP_FORBIDDEN) {
                    adjustClockSkew(response.header("Date"))
                }
                fail(t)
            }
        }

        fun open(useProtocol: Boolean): WebSocket {
            val builder = Request.Builder().url(buildUrl())
            for ((name, value) in baseHeaders()) builder.header(name, value)
            if (useProtocol) builder.header(HEADER_SUBPROTOCOL, SUBPROTOCOL)
            return client.newWebSocket(builder.build(), listener)
        }

        val socket = try {
            open(useSubProtocol)
        } catch (e: IllegalArgumentException) {
            // Некоторые версии OkHttp запрещают ручной Sec-WebSocket-Protocol
            Log.w(TAG, "[Edge] Subprotocol-заголовок отклонён клиентом: ${e.message}")
            open(false)
        }
        activeSocket = socket
        cont.invokeOnCancellation {
            socket.cancel()
            if (activeSocket === socket) activeSocket = null
        }
    }

    /** Список облачных голосов (кэшируется вызывающим в TtsEngine). */
    suspend fun listVoices(): Result<List<RemoteVoice>> = withContext(Dispatchers.IO) {
        runCatching {
            val url = "$VOICE_LIST_URL?trustedclienttoken=$TRUSTED_CLIENT_TOKEN" +
                "&Sec-MS-GEC=${generateSecMsGec()}&Sec-MS-GEC-Version=$SEC_GEC_VERSION"
            val builder = Request.Builder().url(url)
            for ((name, value) in baseHeaders()) builder.header(name, value)
            builder.header("Accept", "*/*")
            builder.header("Sec-Fetch-Site", "none")
            builder.header("Sec-Fetch-Mode", "cors")
            builder.header("Sec-Fetch-Dest", "empty")

            client.newCall(builder.build()).execute().use { response ->
                if (response.code == HTTP_FORBIDDEN) adjustClockSkew(response.header("Date"))
                if (!response.isSuccessful) error("Edge voices HTTP ${response.code}")
                val body = response.body?.string().orEmpty()
                val array = JSONObject(body).optJSONArray("voices")
                    ?: error("Edge voices: нет поля voices")
                val voices = ArrayList<RemoteVoice>(array.length())
                for (i in 0 until array.length()) {
                    val obj = array.optJSONObject(i) ?: continue
                    val shortName = obj.optString("ShortName")
                    if (shortName.isBlank()) continue
                    voices += RemoteVoice(
                        code = "edge:$shortName",
                        name = obj.optString("FriendlyName", shortName),
                        gender = obj.optString("Gender", "Unknown"),
                        locale = obj.optString("Locale", ""),
                    )
                }
                voices
            }
        }.onFailure { Log.w(TAG, "[Edge] Список голосов недоступен: ${it.message}") }
    }

    fun cancel() {
        activeSocket?.cancel()
        activeSocket = null
    }

    fun close() {
        cancel()
        runCatching {
            client.dispatcher.executorService.shutdown()
            client.connectionPool.evictAll()
        }
    }

    // ── протокол ─────────────────────────────────────────────────

    private fun buildUrl(): String = buildString {
        append(WSS_BASE_URL)
        append("?TrustedClientToken=").append(TRUSTED_CLIENT_TOKEN)
        append("&ConnectionId=").append(UUID.randomUUID().toString().replace("-", ""))
        append("&Sec-MS-GEC=").append(generateSecMsGec())
        append("&Sec-MS-GEC-Version=").append(SEC_GEC_VERSION)
    }

    private fun baseHeaders(): Map<String, String> = linkedMapOf(
        "Pragma" to "no-cache",
        "Cache-Control" to "no-cache",
        "Origin" to EDGE_EXTENSION_ORIGIN,
        "User-Agent" to USER_AGENT,
        "Accept-Language" to "en-US,en;q=0.9",
        "Cookie" to "muid=${randomMuid()};",
    )

    private fun speechConfigMessage(outputFormat: String): String = buildString {
        append("X-Timestamp:").append(jsDate()).append("\r\n")
        append("Content-Type:application/json; charset=utf-8\r\n")
        append("Path:speech.config\r\n\r\n")
        append("""{"context":{"synthesis":{"audio":{"metadataoptions":{"sentenceBoundaryEnabled":"true",""")
        append(""""wordBoundaryEnabled":"false"},"outputFormat":"""").append(outputFormat)
        append(""""},"settings":{}}}}""")
    }

    private fun ssmlMessage(text: String, request: SynthesisRequest): String {
        val lang = request.voice.substringBefore('-').ifBlank { "en" } + "-US"
        val pitch = if (request.pitchHz == 0) "+0Hz" else signed(request.pitchHz) + "Hz"
        val rate = signed(request.ratePercent) + "%"
        val volume = signed(request.volumePercent) + "%"
        val ssml = buildString {
            append("<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' xml:lang='")
            append(lang).append("'><voice name='").append(request.voice)
            append("'><prosody pitch='").append(pitch)
            append("' rate='").append(rate)
            append("' volume='").append(volume).append("'>")
            append(escapeXml(text))
            append("</prosody></voice></speak>")
        }
        return buildString {
            append("X-RequestId:").append(UUID.randomUUID().toString().replace("-", "")).append("\r\n")
            append("Content-Type:application/ssml+xml\r\n")
            // Лишний "Z" после даты — обязательный quirks протокола Edge.
            append("X-Timestamp:").append(jsDate()).append("Z\r\n")
            append("Path:ssml\r\n\r\n")
            append(ssml)
        }
    }

    private fun pathOf(message: String): String? {
        val end = message.indexOf("\r\n\r\n")
        val head = if (end >= 0) message.substring(0, end) else message
        return head.lineSequence()
            .firstOrNull { it.startsWith("Path:", ignoreCase = true) }
            ?.substring(5)?.trim()
    }

    /**
     * Sec-MS-GEC = SHA-256("windowsFileTime" + trustedToken), где время
     * округлено вниз до 5 минут. При 403 сервер сообщает своё Date —
     * из него считается смещение часов (DRM.handle_client_response_error).
     */
    private fun generateSecMsGec(): String {
        val unix = System.currentTimeMillis() / 1000L + clockSkewSeconds.get()
        val ticks = unix + WIN_EPOCH_SECONDS
        val quantized = ticks - (ticks % GEC_WINDOW_SECONDS)
        val intervals = quantized * TICKS_PER_SECOND
        val payload = "$intervals$TRUSTED_CLIENT_TOKEN".toByteArray(Charsets.US_ASCII)
        val digest = MessageDigest.getInstance("SHA-256").digest(payload)
        val out = StringBuilder(digest.size * 2)
        for (b in digest) out.append(HEX[(b.toInt() shr 4) and 0x0F]).append(HEX[b.toInt() and 0x0F])
        return out.toString()
    }

    private fun adjustClockSkew(dateHeader: String?) {
        val serverDate = dateHeader ?: return
        val parsed = runCatching {
            SERVER_DATE_FORMAT.get().parse(serverDate)?.time
        }.getOrNull() ?: return
        val local = System.currentTimeMillis()
        val skew = (parsed - local) / 1000L
        if (skew != 0L) {
            clockSkewSeconds.set(skew)
            Log.w(TAG, "[Edge] Смещение часов сервера: ${skew} c")
        }
    }

    // ── текст ────────────────────────────────────────────────────

    /** Убирает несовместимые с сервисом управляющие символы. */
    private fun sanitize(text: String): String {
        val builder = StringBuilder(min(text.length, MAX_TEXT_CHARS))
        for (c in text) {
            val code = c.code
            val bad = code <= 8 || (code in 11..12) || (code in 14..31)
            builder.append(if (bad) ' ' else c)
            if (builder.length >= MAX_TEXT_CHARS) break
        }
        return builder.toString().replace(WHITESPACE, " ").trim()
    }

    /** Порт split_text_by_byte_length: разрыв по пробелу/переводу строки, без рваных UTF-8. */
    private fun splitTextByByteLength(text: String, maxBytes: Int): List<String> {
        val result = ArrayList<String>()
        var rest = text
        while (rest.length > maxBytes) {
            val cut = findSplitPoint(rest, maxBytes)
            val chunk = rest.substring(0, cut).trim()
            if (chunk.isNotEmpty()) result += chunk
            rest = rest.substring(cut)
            if (result.size > MAX_CHUNKS) break
        }
        val tail = rest.trim()
        if (tail.isNotEmpty()) result += tail
        return result.ifEmpty { listOf(text) }
    }

    private fun findSplitPoint(text: String, maxBytes: Int): Int {
        var bytes = 0
        var lastBoundary = -1
        var consumed = 0
        for (i in text.indices) {
            val size = when {
                text[i].code < 0x80 -> 1
                text[i].code < 0x800 -> 2
                else -> 3
            }
            if (bytes + size > maxBytes) {
                return if (lastBoundary > 0) lastBoundary else i.coerceAtLeast(1)
            }
            bytes += size
            consumed = i + 1
            if (text[i] == '\n' || text[i] == ' ') lastBoundary = consumed
        }
        return consumed.coerceAtLeast(1)
    }

    private fun escapeXml(text: String): String {
        val out = StringBuilder(text.length + 16)
        for (c in text) {
            when (c) {
                '&' -> out.append("&amp;")
                '<' -> out.append("&lt;")
                '>' -> out.append("&gt;")
                '\'' -> out.append("&apos;")
                '"' -> out.append("&quot;")
                else -> out.append(c)
            }
        }
        return out.toString()
    }

    private fun signed(value: Int): String = if (value >= 0) "+$value" else "$value"

    private fun jsDate(): String = JS_DATE_FORMAT.get().format(Date())

    private fun randomMuid(): String {
        val bytes = ByteArray(16)
        MUID_RANDOM.nextBytes(bytes)
        val sb = StringBuilder(32)
        for (b in bytes) sb.append(HEX[(b.toInt() shr 4) and 0x0F]).append(HEX[b.toInt() and 0x0F])
        return sb.toString().uppercase(Locale.US)
    }

    companion object {
        const val TRUSTED_CLIENT_TOKEN = "6A5AA1D4EAFF4E9FB37E23D68491D6F4"
        const val OUTPUT_FORMAT = "audio-24khz-48kbitrate-mono-mp3"

        const val WSS_BASE_URL =
            "wss://speech.platform.bing.com/consumer/speech/synthesize/readaloud/edge/v1"
        const val VOICE_LIST_URL =
            "https://speech.platform.bing.com/consumer/speech/synthesize/readaloud/voices/list"

        /** 4 дефолтных голоса, пока список с сервера не получен. */
