            RemoteVoice("edge:ru-RU-SvetlanaNeural", "Svetlana (ru)", "Female", "ru-RU"),
            RemoteVoice("edge:ru-RU-DashaNeural", "Dasha (ru)", "Female", "ru-RU"),
            RemoteVoice("edge:en-US-GuyNeural", "Guy (en)", "Male", "en-US"),
            RemoteVoice("edge:en-US-JennyNeural", "Jenny (en)", "Female", "en-US"),
