/**
 * Декодер MP3 → PCM через MediaCodec (системный stagefright-декодер).
 * Работает потоково: [decode] можно вызывать по мере прихода фрагментов.
 */
internal class Mp3PcmDecoder(private val targetSampleRate: Int = 24_000) {

    private var codec: MediaCodec? = null
    private var ptsUs = 0L
    private var started = false

    var outputSampleRate: Int = targetSampleRate
        private set

    fun start(): Boolean {
        if (started) return true
        return try {
            val format = MediaFormat.createAudioFormat(
                MediaFormat.MIMETYPE_AUDIO_MPEG,
                targetSampleRate,
                CHANNEL_COUNT,
            )
            codec = MediaCodec.createDecoderByType(MediaFormat.MIMETYPE_AUDIO_MPEG).apply {
                configure(format, null, null, 0)
                start()
            }
            started = true
            true
        } catch (e: Throwable) {
            Log.e(TAG, "[Edge] MediaCodec для MP3 недоступен: ${e.message}")
            release()
            false
        }
    }

    /** Скормить очередной кусок MP3; [sink] получает декодированный PCM. */
    fun decode(mp3: ByteArray, sink: (ShortArray) -> Unit) {
        val c = codec ?: return
        var offset = 0
        while (offset < mp3.size) {
            if (!started) return
            val inputIndex = c.dequeueInputBuffer(TIMEOUT_US)
            if (inputIndex < 0) {
                drain(c, sink)
                continue
            }
            val buffer = c.getInputBuffer(inputIndex)
            if (buffer == null) {
                c.queueInputBuffer(inputIndex, 0, 0, ptsUs, 0)
                continue
            }
            val chunk = minOf(mp3.size - offset, buffer.remaining())
            buffer.put(mp3, offset, chunk)
            c.queueInputBuffer(inputIndex, 0, chunk, ptsUs, 0)
            ptsUs += chunk * MP3_BITS_PER_BYTE * MICROS_PER_SECOND / MP3_BITRATE_BPS
            offset += chunk
            drain(c, sink)
        }
    }

    /** Достать хвост: помечает вход EOS и ждёт конца потока. */
    fun finish(sink: (ShortArray) -> Unit) {
        val c = codec ?: return
        try {
            val inputIndex = c.dequeueInputBuffer(TIMEOUT_US)
            if (inputIndex >= 0) {
                c.queueInputBuffer(inputIndex, 0, 0, ptsUs, MediaCodec.BUFFER_FLAG_END_OF_STREAM)
            }
            val deadline = SystemClock.elapsedRealtime() + DRAIN_TIMEOUT_MS
            while (SystemClock.elapsedRealtime() < deadline) {
                if (!drain(c, sink)) break
            }
        } catch (e: Throwable) {
            Log.w(TAG, "[Edge] Сброс декодера: ${e.message}")
        }
    }

    /** @return true, если есть ещё что вычитывать. */
    private fun drain(codec: MediaCodec, sink: (ShortArray) -> Unit): Boolean {
        val info = MediaCodec.BufferInfo()
        var pending = false
        while (true) {
            val outIndex = codec.dequeueOutputBuffer(info, TIMEOUT_US)
            when {
                outIndex >= 0 -> {
                    readOutputFormat(codec)
                    codec.getOutputBuffer(outIndex)?.let { buffer ->
                        val pcm = toShortArray(buffer, info)
                        if (pcm.isNotEmpty()) sink(pcm)
                    }
                    codec.releaseOutputBuffer(outIndex, false)
                    pending = true
                    if (info.flags and MediaCodec.BUFFER_FLAG_END_OF_STREAM != 0) return false
                }
                outIndex == MediaCodec.INFO_OUTPUT_FORMAT_CHANGED -> {
                    readOutputFormat(codec)
                    pending = true
                }
                outIndex == MediaCodec.INFO_TRY_AGAIN_LATER -> return pending
                else -> pending = true
            }
        }
    }

    private fun readOutputFormat(codec: MediaCodec) {
        if (outputSampleRate > 0 && outputSampleRate != targetSampleRate) return
        runCatching {
            val format = codec.outputFormat
            if (format.containsKey(MediaFormat.KEY_SAMPLE_RATE)) {
                outputSampleRate = format.getInteger(MediaFormat.KEY_SAMPLE_RATE)
            }
        }.onFailure { Log.w(TAG, "[Edge] Формат выхода: ${it.message}") }
    }

    fun release() {
        started = false
        val c = codec ?: return
        codec = null
        runCatching { c.stop() }
        runCatching { c.release() }
    }

    private companion object {
        const val TIMEOUT_US = 10_000L
        const val DRAIN_TIMEOUT_MS = 1_500L
        const val CHANNEL_COUNT = 1
        const val MICROS_PER_SECOND = 1_000_000L
        const val MP3_BITRATE_BPS = 48_000
        const val MP3_BITS_PER_BYTE = 8
    }
}

private fun toShortArray(buffer: ByteBuffer, info: MediaCodec.BufferInfo): ShortArray {
    val count = minOf(info.size / 2, buffer.remaining() / 2)
    if (count <= 0) return ShortArray(0)
    val view = buffer.order(ByteOrder.LITTLE_ENDIAN).asShortBuffer()
    val out = ShortArray(count)
    view.get(out, 0, count)
    return out
}

