private suspend fun streamOnce(
    text: String,
    chunks: List<String>,
    request: SynthesisRequest,
    onAudio: ((ByteArray) -> Unit)?,
    useSubProtocol: Boolean,
    out: ByteArrayOutputStream,
): Result<ByteArray> = suspendCancellableCoroutine { cont ->
    val done = AtomicBoolean(false)
    var receivedAudio = false

    fun succeed() {
        if (done.compareAndSet(false, true)) {
            val audio = out.toByteArray()
            if (audio.isEmpty() && !receivedAudio) {
                cont.resume(Result.failure(SocketTimeoutException("Edge TTS: аудио не получено")))
            } else {
                if (!receivedAudio) Log.w(TAG, "[Edge] Соединение закрыто без turn.end, отдаём усечённый MP3")
                cont.resume(Result.success(audio))
            }
        }
    }

    fun fail(error: Throwable) {
        if (done.compareAndSet(false, true)) cont.resume(Result.failure(error))
    }

    val listener = object : WebSocketListener() {
        override fun onOpen(webSocket: WebSocket, response: Response) {
            if (!cont.isActive) return
            webSocket.send(speechConfigMessage(request.outputFormat))
            for (chunk in chunks) {
                webSocket.send(ssmlMessage(chunk, request))
            }
