            if (data.size < 4) return
            val headerLength = ((data[0].toInt() and 0xFF) shl 8) or (data[1].toInt() and 0xFF)
            if (headerLength <= 0 || 4 + headerLength > data.size) return
            val header = String(data, 2, headerLength, Charsets.UTF_8)
            if (!header.contains("Path:audio", ignoreCase = true)) return
            val payloadStart = 4 + headerLength
            if (payloadStart >= data.size) return
            val payload = data.copyOfRange(payloadStart, data.size)
            if (payload.isEmpty()) return
            receivedAudio = true
            out.write(payload)
            onAudio?.invoke(payload)
        }

        override fun onClosing(webSocket: WebSocket, code: Int, reason: String) {
            webSocket.close(NORMAL_CLOSURE, null)
        }

        override fun onClosed(webSocket: WebSocket, code: Int, reason: String) {
            succeed()
        }

        override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
            if (response?.code == HTTP_FORBIDDEN) {
                adjustClockSkew(response.header("Date"))
            }
            fail(t)
        }
    }

