private const val TAG = "ScreenOCR"

/**
 * Порт tts_engine.py (класс TTSEngine).
 *
 * Синтез идёт одним из двух бэкендов:
 *  - **Edge** — облачные нейросетевые голоса (те же, что на десктопе),
 *    MP3 декодируется в PCM через MediaCodec и играется в AudioTrack;
 *  - **Android TTS** — системный движок, работает всегда и офлайн.
 *
 * ВыборEdge/system происходит автоматически: если сети нет или Edge не ответил,
 * фраза уходит системному движку. Эмоции, per-role pitch/rate, dual voice,
 * разбивка на предложения и кэш перенесены один в один.
 */
class TtsEngine(private val context: Context, private val settings: Settings) {

    enum class Role { MALE, FEMALE, NARRATOR }

    data class VoiceInfo(
        val code: String,
        val name: String,
        val engine: String,
        val gender: String,
        val locale: String,
    )

    private enum class Backend { EDGE, SYSTEM }

    private enum class SentenceType { STATEMENT, QUESTION, EXCLAMATION }

    private val appContext = context.applicationContext
    private val edgeTts = EdgeTts()
    private val systemTts = AndroidTtsBackend(appContext)
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)
    private val lock = Any()
    private val cacheLock = Any()
    private val utteranceSeq = AtomicLong(0)

    @Volatile
    private var backend: Backend = Backend.EDGE

    @Volatile
    private var voice: String = DEFAULT_VOICE

    @Volatile
    private var volume: Float = 1f

    @Volatile
    private var emotionAuto = true

    @Volatile
    private var voicePreset: String? = null

    @Volatile
    private var dualVoice = false

    @Volatile
    private var cacheEnabled = true

    @Volatile
    private var showAllEdgeVoices = false

    @Volatile
    private var currentRole = Role.MALE

    @Volatile
    var isPlaying: Boolean = false
        private set

    /** Метки фактического звучания — нужны STT для анти-эха. */
    @Volatile
    var playbackStartedAt: Long = 0L
        private set

    @Volatile
    var playbackEndedAt: Long = 0L
        private set

    private val rolePitch = ConcurrentHashMap<Role, Int>()
    private val roleRate = ConcurrentHashMap<Role, Int>()

    /**
     * Кэш синтезированного PCM. При переполнении LinkedHashMap вытесняет
     * ровно одну самую старую запись, а не очищается целиком.
     */
    private val audioCache = object : LinkedHashMap<String, ShortArray>(64, 0.75f, false) {
        override fun removeEldestEntry(eldest: MutableMap.MutableEntry<String, ShortArray>?): Boolean =
            size > MAX_CACHE_ENTRIES
    }

    @Volatile
    private var voiceCache: List<VoiceInfo> = emptyList()

    @Volatile
    private var voicesRequested = false

    @Volatile
    private var activeJob: Job? = null

    @Volatile
    private var player: PcmPlayer? = null

    @Volatile
    private var online: Pair<Long, Boolean>? = null

    init {
        reloadSettings()
    }

    // ── публичный API ────────────────────────────────────────────

    /** Озвучить текст. @return true — звук реально прозвучал. */
    suspend fun speak(text: String, role: Role = Role.NARRATOR): Boolean {
        val clean = cleanText(text) ?: return false
        return play(clean, role, streaming = false, onFirstChunk = null)
    }

    /**
     * Потоковое озвучивание: звук начинается с первого MP3-фрагмента.
     * [onFirstChunk] вызывается, когда первые сэмплы ушли в AudioTrack.
     */
    suspend fun speakStreaming(
        text: String,
        role: Role = Role.NARRATOR,
        onFirstChunk: (() -> Unit)? = null,
    ): Boolean {
        val clean = cleanText(text) ?: return false
        return play(clean, role, streaming = true, onFirstChunk = onFirstChunk)
    }

    /** Синтез без воспроизведения. PCM 24 кГц моно или null, если не вышло. */
    suspend fun generatePcm(text: String, role: Role): ShortArray? {
        val clean = cleanText(text) ?: return null
        val adjustments = emotionAdjustments(clean, role, sentenceType(clean))
        val cacheKey = cacheKey(clean, role, adjustments) ?: return null
        cached(cacheKey)?.let { return it }

        val pcm = if (useEdge()) synthesizeEdgePcm(clean, role)
        else synthesizeSystemPcm(clean, role, adjustments)
        if (pcm == null || pcm.isEmpty()) return null
        val processed = applyPreset(pcm)
        store(cacheKey, processed)
        return processed
    }

    /** Немедленная остановка всего, что сейчас звучит. */
    fun stop() {
        activeJob?.cancel()
        activeJob = null
        edgeTts.cancel()
        player?.stop()
        player = null
        systemTts.stop()
        isPlaying = false
        playbackEndedAt = SystemClock.elapsedRealtime()
        Log.i(TAG, "[TTS] Остановлено")
    }

    /**
     * Выбор голоса. Формат: `edge:ru-RU-DmitryNeural`, `system:ru-RU-x-xpf-local`,
     * `profile:Имя` либо «голый» код (`ru-RU-DmitryNeural` → edge).
     */
    fun setVoice(voiceCode: String) {
        if (voiceCode.startsWith(PROFILE_PREFIX)) {
            val name = voiceCode.removePrefix(PROFILE_PREFIX)
            val profile = VoiceProfiles.loadUserProfiles(appContext).firstOrNull { it.name == name }
            if (profile == null) {
                Log.w(TAG, "[TTS] Профиль не найден: $name")
                return
            }
            applyProfile(profile)
            return
        }
        val (target, name) = parseVoiceCode(voiceCode)
        backend = target
        voice = name
        settings.set(Settings.Tts.VOICE, voiceCode)
        Log.i(TAG, "[TTS] Голос: $voiceCode")
    }

    /** Текущий голос в каноническом виде `engine:code`. */
    fun currentVoice(): String = "${backend.name.lowercase()}:$voice"

    /**
     * Список голосов: системные (только ru) + облачные (4 дефолтных, либо все).
     * Список догружается в фоне при первом обращении.
     */
    fun listVoices(): List<VoiceInfo> {
        requestVoices()
        return voiceCache
    }

    suspend fun refreshVoices(): List<VoiceInfo> {
        val system = if (systemTts.awaitReady()) systemTts.listVoices() else emptyList()
        val remote = edgeTts.listVoices().getOrDefault(emptyList())
            .map { VoiceInfo(it.code, it.name, "edge", it.gender, it.locale) }
            .ifEmpty { EdgeTts.DEFAULT_VOICES.map { VoiceInfo(it.code, it.name, "edge", it.gender, it.locale) } }

        val merged = ArrayList<VoiceInfo>(system.size + remote.size)
        merged += system
        for (info in remote) {
            if (!showAllEdgeVoices && info.code.removePrefix("edge:") !in EDGE_DEFAULT_VOICES) continue
            merged += info
        }
        for (profile in VoiceProfiles.loadUserProfiles(appContext)) {
            merged += VoiceInfo(
                code = PROFILE_PREFIX + profile.name,
                name = "★ " + profile.name,
                engine = "profile",
                gender = profile.gender,
                locale = profile.language,
            )
        }
        voiceCache = merged
        saveVoiceCache(system + remote)
        return merged
    }

    /** Включает/выключает автоматический подбор эмоции по тексту. */
    fun setEmotionAuto(enabled: Boolean) {
        emotionAuto = enabled
    }

    fun isEmotionAutoEnabled(): Boolean = emotionAuto

    /** DSP-пресет поверх синтеза (VoiceChanger): female, robot, child… */
    fun setVoicePreset(presetName: String?) {
        voicePreset = presetName?.takeIf { it != "original" && VoiceChanger.PRESETS.containsKey(it) }
    }

    fun currentVoicePreset(): String? = voicePreset

    fun setRole(role: Role) {
        currentRole = role
    }

    fun setRolePitch(role: Role, pitch: Int) {
        rolePitch[role] = pitch.coerceIn(PITCH_MIN, PITCH_MAX)
    }

    fun setRoleRate(role: Role, rate: Int) {
        roleRate[role] = rate.coerceIn(RATE_MIN, RATE_MAX)
    }

    fun getRolePitch(role: Role): Int = rolePitch[role] ?: 0

    fun getRoleRate(role: Role): Int = roleRate[role] ?: 0

    fun currentRate(): Int = getRoleRate(currentRole)

    fun currentPitch(): Int = getRolePitch(currentRole)

    fun setVolume(value: Float) {
        volume = value.coerceIn(0f, 2f)
    }

    fun clearCache() {
        synchronized(cacheLock) { audioCache.clear() }
    }

    fun cacheSize(): Int = synchronized(cacheLock) { audioCache.size }

    /** Перечитывает настройки — вызывать при изменении конфига из UI. */
    fun reloadSettings() {
        setVoice(settings.get(Settings.Tts.VOICE, DEFAULT_VOICE_CODE))
        volume = settings.get(Settings.Tts.VOLUME, 1f)
        cacheEnabled = settings.get(Settings.Tts.CACHE, true)
        dualVoice = settings.get(Settings.Tts.DUAL_VOICE, false)
        showAllEdgeVoices = settings.get(KEY_SHOW_ALL_EDGE, false)
        rolePitch[Role.MALE] = settings.get(Settings.Tts.MALE_PITCH, 0)
        rolePitch[Role.FEMALE] = settings.get(Settings.Tts.FEMALE_PITCH, 0)
        rolePitch[Role.NARRATOR] = settings.get(Settings.Tts.NARRATOR_PITCH, 0)
        roleRate[Role.MALE] = settings.get(Settings.Tts.MALE_RATE, 15)
        roleRate[Role.FEMALE] = settings.get(Settings.Tts.FEMALE_RATE, 15)
        roleRate[Role.NARRATOR] = settings.get(Settings.Tts.NARRATOR_RATE, 15)
        val engine = settings.get(Settings.Tts.ENGINE, "edge")
        if (engine == "system") backend = Backend.SYSTEM
    }

    /** Освобождение ресурсов (вызывать при остановке сервиса). */
    fun close() {
        stop()
        scope.coroutineContext[Job]?.cancel()
        edgeTts.close()
        systemTts.shutdown()
    }

    // ── воспроизведение ──────────────────────────────────────────

    private suspend fun play(
        text: String,
        role: Role,
        streaming: Boolean,
        onFirstChunk: (() -> Unit)?,
    ): Boolean {
        val job = scope.async(Dispatchers.Default) { doPlay(text, role, streaming, onFirstChunk) }
        activeJob = job
        return try {
            job.await()
        } catch (e: kotlinx.coroutines.CancellationException) {
            false
        } finally {
            if (activeJob === job) activeJob = null
        }
    }

    private suspend fun doPlay(
        text: String,
        role: Role,
        streaming: Boolean,
        onFirstChunk: (() -> Unit)?,
    ): Boolean {
        isPlaying = true
        try {
            val adjustments = emotionAdjustments(text, role, sentenceType(text))
            val key = cacheKey(text, role, adjustments)
            val cached = key?.let { cached(it) }
            if (cached != null) {
                Log.d(TAG, "[TTS] Кэш: ${text.take(30)}")
                return playPcm(cached, onFirstChunk)
            }

            if (useEdge()) {
                val played = if (streaming) playEdgeStreaming(text, role, onFirstChunk)
                else playEdgeBuffered(text, role)
                if (played) {
                    key?.let { store(it, lastGeneratedPcm) }
                    return true
                }
                Log.w(TAG, "[TTS] Edge не ответил, переключаюсь на системный TTS")
            }
            return playSystem(text, adjustments)
        } catch (e: kotlinx.coroutines.CancellationException) {
            throw e
        } catch (e: Throwable) {
            Log.e(TAG, "[TTS] Ошибка воспроизведения: ${e.message}")
            return false
        } finally {
            isPlaying = false
            player = null
        }
    }

    /** Edge целиком: MP3 → PCM → AudioTrack; при неудачной декодировке — MediaPlayer. */
    private suspend fun playEdgeBuffered(text: String, role: Role): Boolean {
        val pcm = synthesizeEdgePcm(text, role)
        if (pcm != null) {
            lastGeneratedPcm = pcm
            return playPcm(pcm, null)
        }
        val mp3 = synthesizeEdgeMp3(text, role)
        if (mp3 == null || mp3.isEmpty()) return false
        return playMp3(mp3)
    }

    /**
     * Edge потоком: MP3-фрагменты летят в декодер, PCM сразу уходит в AudioTrack.
     */
    private suspend fun playEdgeStreaming(
        text: String,
        role: Role,
        onFirstChunk: (() -> Unit)?,
    ): Boolean {
        val segments = splitByLanguage(text)
        if (segments.isEmpty()) return false

        val channel = Channel<ByteArray>(Channel.UNLIMITED)
        val collected = ArrayList<ShortArray>(segments.size)
        var produced = false
        var notified = false

        val feedJob = launch(Dispatchers.Default) {
            val decoder = Mp3PcmDecoder(EDGE_SAMPLE_RATE)
            val pcmPlayer: PcmPlayer
            if (!decoder.start()) {
                channel.close()
                return@launch
            }
            var local: PcmPlayer? = null
            val sink: (ShortArray) -> Unit = { pcm ->
                val current = local ?: PcmPlayer(decoder.outputSampleRate, volume).also {
                    local = it
                    it.play()
                }
                synchronized(collected) {
                    collected += pcm
                    if (!notified) {
                        notified = true
                        onFirstChunk?.invoke()
                    }
                }
                current.write(pcm)
                produced = true
            }
            for (chunk in channel) {
                if (!startedFlag) break
                decoder.decode(chunk, sink)
            }
            decoder.finish(sink)
            local?.awaitCompletion()
            local?.release()
            decoder.release()
        }

        for ((segment, lang, type) in segments) {
            val request = synthesisRequest(segment, role, lang, type)
            if (request == null) {
                channel.close()
                feedJob.join()
                return false
            }
            val result = edgeTts.synthesize(request) { channel.trySend(it) }
            result.exceptionOrNull()?.let { Log.w(TAG, "[Edge] ${it.message}") }
            if (result.isFailure) {
                channel.close()
                feedJob.join()
                return false
            }
        }
        channel.close()
        feedJob.join()

        if (!produced) {
            // Медиакодек недоступен — откат на буферизованный путь
            return playEdgeBuffered(text, role)
        }
        val joined = synchronized(collected) {
            crossfadeAll(collected)
        }
        lastGeneratedPcm = joined
        return true
    }

    private suspend fun playPcm(pcm: ShortArray, onFirstChunk: (() -> Unit)?): Boolean {
        if (pcm.isEmpty()) return false
        val pcmPlayer = PcmPlayer(EDGE_SAMPLE_RATE, volume)
        if (!pcmPlayer.isValid) {
            Log.e(TAG, "[TTS] AudioTrack недоступен")
            return false
        }
        player = pcmPlayer
        playbackStartedAt = SystemClock.elapsedRealtime()
        pcmPlayer.play()
        pcmPlayer.write(pcm)
        onFirstChunk?.invoke()
        pcmPlayer.awaitCompletion()
        pcmPlayer.release()
        playbackEndedAt = SystemClock.elapsedRealtime()
        if (player === pcmPlayer) player = null
        return true
    }

    /** Откат: MP3 целиком через MediaPlayer — работает даже без MediaCodec. */
    private suspend fun playMp3(mp3: ByteArray): Boolean = withContext(Dispatchers.Main) {
        val file = File(appContext.cacheDir, "tts_edge_" + nextUtteranceId() + ".mp3")
        try {
            file.writeBytes(mp3)
            playbackStartedAt = SystemClock.elapsedRealtime()
            val done = kotlinx.coroutines.CompletableDeferred<Boolean>()
            val mediaPlayer = MediaPlayer()
            mediaPlayer.setOnCompletionListener { done.complete(true) }
            mediaPlayer.setOnErrorListener { _, _, _ -> done.complete(false); true }
            mediaPlayer.setDataSource(file.absolutePath)
            mediaPlayer.prepare()
            mediaPlayer.start()
            done.await()
            mediaPlayer.release()
            playbackEndedAt = SystemClock.elapsedRealtime()
            return@withContext true
        } catch (e: Throwable) {
            Log.e(TAG, "[TTS] MediaPlayer: ${e.message}")
            playbackEndedAt = SystemClock.elapsedRealtime()
            return@withContext false
        } finally {
            file.delete()
        }
    }

    private suspend fun playSystem(text: String, adjustments: Pair<Int, Int>): Boolean {
        val id = nextUtteranceId()
        playbackStartedAt = SystemClock.elapsedRealtime()
        val ok = if (backend == Backend.SYSTEM) {
            systemTts.speakWithVoice(text, voice, id, adjustments.first, adjustments.second)
        } else {
            systemTts.speak(text, id, adjustments.first, adjustments.second, volume)
        }
        playbackEndedAt = SystemClock.elapsedRealtime()
        if (!ok) Log.e(TAG, "[SystemTTS] Не озвучено: ${systemTts.lastError}")
        return ok
    }

    // ── синтез ───────────────────────────────────────────────────

    private var lastGeneratedPcm: ShortArray = ShortArray(0)

    private var startedFlag = true

    private suspend fun synthesizeEdgePcm(text: String, role: Role): ShortArray? {
        val segments = splitByLanguage(text)
        if (segments.isEmpty()) return null
        val parts = ArrayList<ShortArray>(segments.size)
        for ((segment, lang, type) in segments) {
            val request = synthesisRequest(segment, role, lang, type) ?: return null
            val mp3 = edgeTts.synthesize(request).getOrElse {
                Log.w(TAG, "[Edge] Синтез не удался: ${it.message}")
                return null
            }
            if (mp3.isEmpty()) return null
            val pcm = decodeMp3(mp3)
            if (pcm == null || pcm.isEmpty()) {
                Log.w(TAG, "[Edge] MediaCodec не декодировал MP3")
                return null
            }
            parts += pcm
        }
        return crossfadeAll(parts)
    }

    private suspend fun synthesizeEdgeMp3(text: String, role: Role): ByteArray? {
        val segments = splitByLanguage(text)
        if (segments.isEmpty()) return null
        val out = java.io.ByteArrayOutputStream()
        for ((segment, lang, type) in segments) {
            val request = synthesisRequest(segment, role, lang, type) ?: return null
            val mp3 = edgeTts.synthesize(request).getOrNull() ?: return null
            if (mp3.isEmpty()) return null
            out.write(mp3)
        }
        return out.toByteArray()
    }

    private suspend fun synthesizeSystemPcm(
        text: String,
        role: Role,
        adjustments: Pair<Int, Int>,
    ): ShortArray? {
        val id = nextUtteranceId()
        val pcm = if (backend == Backend.SYSTEM) {
            systemTts.speakWithVoicePcm(text, voice, id, adjustments.first, adjustments.second)
        } else {
            systemTts.synthesizeToPcm(text, id, adjustments.first, adjustments.second)
        }
        return pcm
    }

    private fun decodeMp3(mp3: ByteArray): ShortArray? = withContext(Dispatchers.Default) {
        val decoder = Mp3PcmDecoder(EDGE_SAMPLE_RATE)
        if (!decoder.start()) return@withContext null
        val chunks = ArrayList<ShortArray>(256)
        try {
            decoder.decode(mp3) { pcm -> chunks += pcm }
            decoder.finish { pcm -> chunks += pcm }
        } catch (e: Throwable) {
            Log.e(TAG, "[Edge] Декодирование: ${e.message}")
            return@withContext null
        } finally {
            decoder.release()
        }
        if (chunks.isEmpty()) return@withContext null
        val total = chunks.sumOf { it.size }
        val result = ShortArray(total)
        var offset = 0
        for (chunk in chunks) {
            chunk.copyInto(result, offset)
            offset += chunk.size
        }
        result
    }

    private fun synthesisRequest(
        segment: String,
        role: Role,
        lang: String,
        type: SentenceType,
    ): EdgeTts.SynthesisRequest? {
        val clean = EmotionRules.preprocess(segment).replace(WHITESPACE, " ").trim()
        if (clean.isEmpty()) return null
        val (rate, pitch) = emotionAdjustments(segment, role, type)
        val voiceName = voiceForLanguage(lang)
        return EdgeTts.SynthesisRequest(
            text = clean,
            voice = voiceName,
            ratePercent = rate.coerceIn(RATE_MIN, RATE_MAX),
            pitchHz = pitch.coerceIn(PITCH_MIN, PITCH_MAX),
            volumePercent = ((volume - 1f) * 100f).toInt().coerceIn(-100, 100),
        )
    }

    /**
     * Порт _get_emotion_adjustments: базовые значения роли + эмоция + просодия
     * по типу предложения (вопрос +12% pitch / -5% rate, восклицание +7% / +5%).
     */
    private fun emotionAdjustments(
        text: String,
        role: Role,
        type: SentenceType,
    ): Pair<Int, Int> {
        var rate = getRoleRate(role)
        var pitch = getRolePitch(role)
        if (emotionAuto) {
            val prosody = EmotionRules.prosodyFor(EmotionRules.detectEmotion(text))
            rate += prosody.rate
            pitch += prosody.pitch
        }
        when (type) {
            SentenceType.QUESTION -> {
                pitch += 12
                rate -= 5
            }
            SentenceType.EXCLAMATION -> {
                pitch += 7
                rate += 5
            }
            SentenceType.STATEMENT -> Unit
        }
        return rate.coerceIn(RATE_MIN, RATE_MAX) to pitch.coerceIn(PITCH_MIN, PITCH_MAX)
    }

    private fun sentenceType(text: String): SentenceType = when {
        text.contains('?') -> SentenceType.QUESTION
        text.contains('!') -> SentenceType.EXCLAMATION
        else -> SentenceType.STATEMENT
    }

    /**
     * Порт _split_by_language: предложения до 200 символов, тип и язык
     * каждого фрагмента — для dual voice и просодии.
     */
    private fun splitByLanguage(text: String): List<Triple<String, String, SentenceType>> {
        val trimmed = text.trim()
        if (trimmed.isEmpty()) return emptyList()
        val parts = SENTENCE_SPLIT.split(trimmed)
        val result = ArrayList<Triple<String, String, SentenceType>>()
        var buffer = StringBuilder()

        for (raw in parts) {
            val part = raw.trim()
            if (part.isEmpty()) continue
            if (buffer.isNotEmpty() && buffer.length + part.length > MAX_SENTENCE_CHARS) {
                result += flush(buffer.toString())
                buffer = StringBuilder()
            }
            if (buffer.isNotEmpty()) buffer.append(' ')
            buffer.append(part)
            if (part.last() in SENTENCE_ENDS) {
                result += flush(buffer.toString())
                buffer = StringBuilder()
            }
        }
        if (buffer.isNotBlank()) result += flush(buffer.toString())
        return result.ifEmpty { listOf(Triple(trimmed, VoiceProfiles.detectTextLanguage(trimmed), sentenceType(trimmed))) }
    }

    private fun flush(buffer: String): Triple<String, String, SentenceType> =
        Triple(buffer, VoiceProfiles.detectTextLanguage(buffer), sentenceType(buffer))

    /** Порт _crossfade: 80 мс перекрытия между соседними кусками PCM. */
    private fun crossfadeAll(parts: List<ShortArray>): ShortArray {
        if (parts.isEmpty()) return ShortArray(0)
        if (parts.size == 1) return parts[0]
        var result = parts[0]
        for (i in 1 until parts.size) {
            result = crossfade(result, parts[i], CROSSFADE_MS)
        }
        return result
    }

    private fun crossfade(first: ShortArray, second: ShortArray, fadeMs: Int): ShortArray {
        val fade = min(min(first.size, second.size), EDGE_SAMPLE_RATE * fadeMs / 1000)
        if (fade < 16) {
            val joined = ShortArray(first.size + second.size)
            first.copyInto(joined, 0)
            second.copyInto(joined, first.size)
            return joined
        }
        val out = ShortArray(first.size + second.size - fade)
        first.copyInto(out, 0, 0, first.size - fade)
        for (i in 0 until fade) {
            val t = i.toFloat() / fade
            val tail = first[first.size - fade + i]
            val head = second[i]
            out[first.size - fade + i] = (tail * (1f - t) + head * t).toInt().toShort()
        }
        second.copyInto(out, first.size - fade, fade, second.size)
        return out
    }

    // ── голоса, роли, кэш ────────────────────────────────────────

    private fun voiceForLanguage(lang: String): String {
        if (!dualVoice) return voice
        val code = voice.substringAfter(':')
        val currentLang = code.substringBefore('-')
        if (lang.equals(currentLang, ignoreCase = true)) return code
        val female = FEMALE_MARKERS.any { code.contains(it, ignoreCase = true) }
        return if (female) EN_FEMALE_VOICE else EN_MALE_VOICE
    }

    private fun parseVoiceCode(code: String): Pair<Backend, String> {
        val trimmed = code.trim()
        return when {
            trimmed.startsWith("edge:") -> Backend.EDGE to trimmed.removePrefix("edge:")
            trimmed.startsWith("system:") -> Backend.SYSTEM to trimmed.removePrefix("system:")
            // rhvoice / silero / persona — движки Windows, на Android идут в системный TTS
            DESKTOP_ONLY_PREFIXES.any { trimmed.startsWith(it) } -> Backend.SYSTEM to trimmed
            else -> Backend.EDGE to trimmed
        }
    }

    private fun applyProfile(profile: VoiceProfile) {
        val (target, name) = parseVoiceCode(profile.voiceCode)
        backend = target
        voice = name
        setRolePitch(currentRole, profile.pitch)
        setRoleRate(currentRole, profile.rate)
        if (profile.volume > 0f) volume = profile.volume
        settings.set(Settings.Tts.VOICE, profile.voiceCode)
        Log.i(TAG, "[TTS] Профиль '${profile.name}': ${profile.voiceCode}")
    }

    private fun useEdge(): Boolean {
        if (backend == Backend.SYSTEM) return false
        if (settings.get(Settings.Tts.ENGINE, "edge") == "system") return false
        if (VoiceProfiles.detectTextLanguage("") == "en" && !isOnline()) return false
        return isOnline()
    }

    private fun isOnline(): Boolean {
        val now = SystemClock.elapsedRealtime()
        online?.let { (ts, value) -> if (now - ts < ONLINE_TTL_MS) return value }
        val manager = appContext.getSystemService(Context.CONNECTIVITY_SERVICE) as? ConnectivityManager
        val result = try {
            val network = manager?.activeNetwork
            val caps = network?.let { manager.getNetworkCapabilities(it) }
            caps?.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) == true
        } catch (e: Throwable) {
            Log.w(TAG, "[TTS] Проверка сети: ${e.message}")
            false
        }
        online = now to result
        return result
    }

    private fun requestVoices() {
        if (voicesRequested) return
        synchronized(lock) {
            if (voicesRequested) return
            voicesRequested = true
            voiceCache = readVoiceCache().ifEmpty {
                EdgeTts.DEFAULT_VOICES.map { VoiceInfo(it.code, it.name, "edge", it.gender, it.locale) }
            }
            scope.launch { refreshVoices() }
        }
    }

    private fun readVoiceCache(): List<VoiceInfo> = runCatching {
        val file = File(appContext.filesDir, VOICE_CACHE_FILE)
        if (!file.exists()) return emptyList()
        val array = JSONArray(file.readText())
        val out = ArrayList<VoiceInfo>(array.length())
        for (i in 0 until array.length()) {
            val obj = array.optJSONObject(i) ?: continue
            out += VoiceInfo(
                code = obj.optString("code"),
                name = obj.optString("name"),
                engine = obj.optString("engine", "edge"),
                gender = obj.optString("gender", "Unknown"),
                locale = obj.optString("locale", ""),
            )
        }
        out
    }.getOrElse {
        Log.w(TAG, "[TTS] Кэш голосов: ${it.message}")
        emptyList()
    }

    private fun saveVoiceCache(voices: List<VoiceInfo>) {
        runCatching {
            val array = JSONArray()
            for (info in voices) {
                array.put(
                    JSONObject()
                        .put("code", info.code)
                        .put("name", info.name)
                        .put("engine", info.engine)
                        .put("gender", info.gender)
                        .put("locale", info.locale),
                )
            }
            File(appContext.filesDir, VOICE_CACHE_FILE).writeText(array.toString())
        }.onFailure { Log.w(TAG, "[TTS] Запись кэша голосов: ${it.message}") }
    }

    private fun cacheKey(text: String, role: Role, adjustments: Pair<Int, Int>): String? = runCatching {
        val raw = "$text|${backend.name}|${voice}|$volume|${adjustments.first}|${adjustments.second}|$role|$currentRole"
        MessageDigest.getInstance("MD5").digest(raw.toByteArray(Charsets.UTF_8))
            .joinToString("") { "%02x".format(it) }
    }.getOrElse {
        Log.w(TAG, "[TTS] MD5: ${it.message}")
        null
    }

    private fun cached(key: String): ShortArray? = synchronized(cacheLock) {
        audioCache[key]
    }

    private fun store(key: String, pcm: ShortArray) {
        if (pcm.isEmpty()) return
        synchronized(cacheLock) { audioCache[key] = pcm }
    }

    private fun applyPreset(pcm: ShortArray): ShortArray {
        val preset = voicePreset ?: return pcm
        return runCatching { VoiceChanger.transform(pcm, preset) }.getOrElse {
            Log.w(TAG, "[VoiceChanger] ${it.message}, возвращаю оригинал")
            pcm
        }
    }

    // ── текст ────────────────────────────────────────────────────

    /** Порт очистки текста из speak(): режем всё, кроме букв и базовой пунктуации. */
    private fun cleanText(text: String?): String? {
        if (text.isNullOrBlank()) return null
        val collapsed = WHITESPACE.replace(text.trim(), " ").trim()
        if (collapsed.isEmpty()) return null
        val cleaned = TTS_ALLOWED.replace(collapsed, "")
        val result = if (cleaned.isBlank()) collapsed else WHITESPACE.replace(cleaned, " ").trim()
        return result.ifEmpty { null }
    }

    private fun nextUtteranceId(): String = "tts-${utteranceSeq.incrementAndGet()}-${System.currentTimeMillis()}"

    companion object {
        private const val DEFAULT_VOICE = "ru-RU-DmitryNeural"
        private const val DEFAULT_VOICE_CODE = "edge:ru-RU-DmitryNeural"
        private const val EN_MALE_VOICE = "en-US-GuyNeural"
        private const val EN_FEMALE_VOICE = "en-US-JennyNeural"
        private const val PROFILE_PREFIX = "profile:"
        private const val VOICE_CACHE_FILE = "tts_edge_voices.json"
        private const val KEY_SHOW_ALL_EDGE = "tts.show_all_edge_voices"

        private const val MAX_CACHE_ENTRIES = 50
        private const val EDGE_SAMPLE_RATE = 24_000
        private const val MAX_SENTENCE_CHARS = 200
        private const val CROSSFADE_MS = 80
        private const val ONLINE_TTL_MS = 30_000L

        private const val RATE_MIN = -100
        private const val RATE_MAX = 100
        private const val PITCH_MIN = -50
        private const val PITCH_MAX = 50

        private val EDGE_DEFAULT_VOICES = setOf(
            "ru-RU-DmitryNeural", "ru-RU-SvetlanaNeural",
            "en-US-GuyNeural", "en-US-JennyNeural",
        )
        private val DESKTOP_ONLY_PREFIXES = listOf("rhvoice:", "silero:", "persona:")
        private val FEMALE_MARKERS = listOf("svetlana", "dasha", "jenny", "alena", "milena", "female", "katya")
        private val SENTENCE_ENDS = charArrayOf('.', '!', '?', '…')

        private val SENTENCE_SPLIT = Regex("(?<=[.!?…])\\s+|\\n+")
        private val WHITESPACE = Regex("\\s+")
        private val TTS_ALLOWED =
            Regex("[^\\p{L}\\p{N}_\\s.,!?;:\\-–—…()\\[\\]\"']")
    }
}

/**
 * Воспроизведение PCM через AudioTrack в потоковом режиме.
 * Ждёт реального проигрывания всех записанных кадров, а не только приёма в буфер.
 */
internal class PcmPlayer(private val sampleRate: Int, private val volume: Float = 1f) {

    private val track: AudioTrack? = try {
        val minBuffer = AudioTrack.getMinBufferSize(
            sampleRate,
            AudioFormat.CHANNEL_OUT_MONO,
            AudioFormat.ENCODING_PCM_16BIT,
        )
        val bufferSize = if (minBuffer > 0) minBuffer * 2 else sampleRate * 4
        AudioTrack.Builder()
            .setAudioAttributes(
                AudioAttributes.Builder()
                    .setUsage(AudioAttributes.USAGE_MEDIA)
                    .setContentType(AudioAttributes.CONTENT_TYPE_SPEECH)
                    .build(),
            )
            .setAudioFormat(
                AudioFormat.Builder()
                    .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                    .setSampleRate(sampleRate)
                    .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                    .build(),
            )
            .setBufferSizeInBytes(bufferSize)
            .setTransferMode(AudioTrack.MODE_STREAM)
            .build()
    } catch (e: Throwable) {
        Log.e(TAG, "[TTS] AudioTrack: ${e.message}")
        null
    }

    val isValid: Boolean get() = track != null

    private var writtenFrames = 0L
    private var playing = false

    fun play() {
        val t = track ?: return
        runCatching {
            t.setVolume(volume.coerceIn(0f, 1f))
            t.play()
            playing = true
        }.onFailure { Log.w(TAG, "[TTS] play(): ${it.message}") }
    }

    fun write(pcm: ShortArray) {
        val t = track ?: return
        if (pcm.isEmpty()) return
        if (!playing) play()
        val buffer = java.nio.ByteBuffer.allocateDirect(pcm.size * 2)
            .order(java.nio.ByteOrder.LITTLE_ENDIAN)
        for (sample in pcm) buffer.putShort(sample)
        buffer.flip()
        var written = 0
        while (written < buffer.limit()) {
            val chunk = runCatching {
                t.write(buffer, buffer.limit(), AudioTrack.WRITE_BLOCKING)
            }.getOrElse {
                Log.w(TAG, "[TTS] write(): ${it.message}")
                return
            }
            if (chunk <= 0) break
            written += chunk
        }
        writtenFrames += written / 2
    }

    /** Ожидание фактического проигрывания с защитным таймаутом. */
    suspend fun awaitCompletion() {
        val t = track ?: return
        val expected = writtenFrames
        if (expected <= 0) {
            stop()
            return
        }
        val durationMs = expected * 1000L / max(1, sampleRate)
        val deadline = SystemClock.elapsedRealtime() + durationMs + PLAYBACK_TIMEOUT_MS
        while (SystemClock.elapsedRealtime() < deadline) {
            val position = t.playbackHeadPosition.toLong() and 0xFFFFFFFFL
            if (position >= expected) break
            if (!playing) break
            delay(PLAYBACK_POLL_MS)
        }
        stop()
    }

    fun stop() {
        val t = track ?: return
        if (playing) {
            runCatching { t.pause(); t.flush(); t.stop() }
            playing = false
        }
    }

    fun release() {
        stop()
        runCatching { track?.release() }
    }

    private companion object {
        const val PLAYBACK_TIMEOUT_MS = 5_000L
        const val PLAYBACK_POLL_MS = 20L
    }
}

