    utteranceId: String,
    ratePercent: Int = 0,
    pitchPercent: Int = 0,
): Boolean {
    if (!awaitReady()) return false
    val tts = engine ?: return false
    val voice = runCatching { tts.voices?.firstOrNull { it.name == voiceName } }.getOrNull()
        ?: return false
    val rc = runCatching { tts.setVoice(voice) }.getOrElse {
        Log.w(TAG, "[SystemTTS] setVoice($voiceName): ${it.message}")
        return false
    }
    val ok = speak(text, utteranceId, ratePercent, pitchPercent)
    if (rc == TextToSpeech.SUCCESS) runCatching { tts.voice = null }
    return ok
}

