private fun adjustClockSkew(dateHeader: String?) {
    val serverDate = dateHeader ?: return
    val parsed = runCatching {
        Instant.from(SERVER_DATE_FORMAT.parse(serverDate)).toEpochMilli()
    }.getOrNull() ?: return
    val skew = (parsed - System.currentTimeMillis()) / 1000L
    if (skew != 0L) {
        clockSkewSeconds.set(skew)
        Log.w(TAG, "[Edge] Смещение часов сервера: ${skew} c")
    }
}

