/**
 * WSOLA: overlap-add с поиском оптимального сдвига анализируемого окна.
 * [stretch] > 1 — длиннее и медленнее, [stretch] < 1 — короче и быстрее.
 */
fun timeStretch(input: FloatArray, stretch: Float): FloatArray {
    if (abs(stretch - 1f) < 0.01f || input.size < 4096) return input
    val frame = 1024
    val synHop = frame / 4
    // Чем больше растяжение, тем реже берём analysis-кадры → длиннее результат.
    val anaHop = max(1, (synHop / stretch).roundToInt())
    val search = frame / 8
    val window = hann(frame)

    val frames = (input.size - frame) / anaHop + 1
    val outSize = (frames - 1) * synHop + frame
    val out = FloatArray(outSize)
    val norm = FloatArray(outSize)

    var anaPos = 0
    var synPos = 0
    while (anaPos + frame <= input.size) {
        val start = if (synPos == 0) anaPos else bestOffset(input, out, anaPos, synPos, search, frame)
        for (i in 0 until frame) {
            val w = window[i]
            out[synPos + i] += input[start + i] * w
            norm[synPos + i] += w
        }
        anaPos += anaHop
        synPos += synHop
    }
    val result = FloatArray(outSize)
    for (i in 0 until outSize) {
        result[i] = if (norm[i] > 1e-4f) out[i] / norm[i] else 0f
    }
    return result
}

/** Сдвиг, при котором сигнал лучше всего продолжает уже синтезированный фрагмент. */
private fun bestOffset(
    input: FloatArray,
    out: FloatArray,
    anaPos: Int,
    synPos: Int,
    search: Int,
    frame: Int,
): Int {
    val limit = min(search, min(anaPos, input.size - anaPos - frame).coerceAtLeast(0))
    if (limit <= 0 || synPos < 256) return anaPos
    var bestPos = anaPos
    var bestScore = Float.NEGATIVE_INFINITY
    for (delta in -limit..limit) {
        val pos = anaPos + delta
        if (pos < 0 || pos + frame > input.size) continue
        var score = 0f
        var i = 0
        while (i < 256) {
            score += out[synPos - 256 + i] * input[pos + i]
            i += 2
        }
        if (score > bestScore) {
            bestScore = score
            bestPos = pos
        }
    }
    return bestPos
}

