private fun ssmlMessage(text: String, request: SynthesisRequest): String {
    val pitch = if (request.pitchHz == 0) "+0Hz" else signed(request.pitchHz) + "Hz"
    val rate = signed(request.ratePercent) + "%"
    val volume = signed(request.volumePercent) + "%"
    val ssml = buildString {
        append("<speak version='1.0' xmlns='http://www.w3.org/2001/10/synthesis' xml:lang='")
        append(localeOf(request.voice)).append("'><voice name='").append(request.voice)
        append("'><prosody pitch='").append(pitch)
        append("' rate='").append(rate)
        append("' volume='").append(volume).append("'>")
        append(escapeXml(text))
        append("</prosody></voice></speak>")
    }
    return buildString {
        append("X-RequestId:").append(UUID.randomUUID().toString().replace("-", "")).append("\r\n")
        append("Content-Type:application/ssml+xml\r\n")
        // Лишний "Z" после даты — обязательный quirks протокола Edge.
        append("X-Timestamp:").append(jsDate()).append("Z\r\n")
        append("Path:ssml\r\n\r\n")
        append(ssml)
    }
}

/** «ru-RU-DmitryNeural» → «ru-RU», «en-EmmaNeural» → «en-US». */
private fun localeOf(voice: String): String {
    val parts = voice.split('-')
    val lang = parts.firstOrNull().orEmpty()
    if (parts.size >= 2 && parts[1].length == 2 && parts[1].all { it.isUpperCase() || it.isDigit() }) {
        return "$lang-${parts[1]}"
    }
    return "$lang-US".ifEmpty { "en-US" }
}

