/** Порт split_text_by_byte_length: разрыв по пробелу/переводу строки, без рваных UTF-8. */
private fun splitTextByByteLength(text: String, maxBytes: Int): List<String> {
    val result = ArrayList<String>()
    var rest = text
    while (utf8Length(rest) > maxBytes && result.size < MAX_CHUNKS) {
        val cut = findSplitPoint(rest, maxBytes)
        val chunk = rest.substring(0, cut).trim()
        if (chunk.isNotEmpty()) result += chunk
        rest = rest.substring(cut)
    }
    val tail = rest.trim()
    if (tail.isNotEmpty()) result += tail
    return result.ifEmpty { listOf(text) }
}

private fun utf8Length(text: String): Int {
    var bytes = 0
    for (c in text) {
        bytes += when {
            c.code < 0x80 -> 1
            c.code < 0x800 -> 2
            else -> 3
        }
    }
    return bytes
}

private fun findSplitPoint(text: String, maxBytes: Int): Int {
    var bytes = 0
    var lastBoundary = -1
    var consumed = 0
    for (i in text.indices) {
        val size = when {
            text[i].code < 0x80 -> 1
            text[i].code < 0x800 -> 2
            else -> 3
        }
        if (bytes + size > maxBytes) {
            return if (lastBoundary > 0) lastBoundary else i.coerceAtLeast(1)
        }
        bytes += size
        consumed = i + 1
        if (text[i] == '\n' || text[i] == ' ') lastBoundary = consumed
    }
    return consumed.coerceAtLeast(1)
}

