init {
    reloadSettings()
}

// ── публичный API ────────────────────────────────────────────

/** Озвучить текст. @return true — звук реально прозвучал. */
suspend fun speak(text: String, role: Role = Role.NARRATOR): Boolean {
    val clean = cleanText(text) ?: return false
    return play(clean, role, streaming = false, onFirstChunk = null)
}

/**
 * Потоковое озвучивание: звук начинается с первого MP3-фрагмента.
 * [onFirstChunk] вызывается, когда первые сэмплы ушли в AudioTrack.
 */
suspend fun speakStreaming(
    text: String,
    role: Role = Role.NARRATOR,
    onFirstChunk: (() -> Unit)? = null,
): Boolean {
    val clean = cleanText(text) ?: return false
    return play(clean, role, streaming = true, onFirstChunk = onFirstChunk)
}

/** Синтез без воспроизведения. PCM 24 кГц моно или null, если не вышло. */
suspend fun generatePcm(text: String, role: Role): ShortArray? {
    val clean = cleanText(text) ?: return null
    val adjustments = emotionAdjustments(clean, role, sentenceType(clean))
    val cacheKey = cacheKey(clean, role, adjustments) ?: return null
    cached(cacheKey)?.let { return it }

    val pcm = if (useEdge()) synthesizeEdgePcm(clean, role)
    else synthesizeSystemPcm(clean, role, adjustments)
    if (pcm == null || pcm.isEmpty()) return null
    val processed = applyPreset(pcm)
    store(cacheKey, processed)
    return processed
}

