private fun voiceForLanguage(lang: String): String {
    if (!dualVoice) return voice
    val code = voice.substringAfter(':')
    val currentLang = code.substringBefore('-')
    if (lang.equals(currentLang, ignoreCase = true)) return code
    val female = FEMALE_MARKERS.any { code.contains(it, ignoreCase = true) }
    return if (female) EN_FEMALE_VOICE else EN_MALE_VOICE
}

private fun parseVoiceCode(code: String): Pair<Backend, String> {
    val trimmed = code.trim()
    return when {
        trimmed.startsWith("edge:") -> Backend.EDGE to trimmed.removePrefix("edge:")
        trimmed.startsWith("system:") -> Backend.SYSTEM to trimmed.removePrefix("system:")
        // rhvoice / silero / persona — движки Windows, на Android идут в системный TTS
        DESKTOP_ONLY_PREFIXES.any { trimmed.startsWith(it) } -> Backend.SYSTEM to trimmed
        else -> Backend.EDGE to trimmed
    }
}

private fun applyProfile(profile: VoiceProfile) {
    val (target, name) = parseVoiceCode(profile.voiceCode)
    backend = target
    voice = name
    setRolePitch(currentRole, profile.pitch)
    setRoleRate(currentRole, profile.rate)
    if (profile.volume > 0f) volume = profile.volume
    settings.set(Settings.Tts.VOICE, profile.voiceCode)
    Log.i(TAG, "[TTS] Профиль '${profile.name}': ${profile.voiceCode}")
}

private fun useEdge(): Boolean {
    if (backend == Backend.SYSTEM) return false
    if (settings.get(Settings.Tts.ENGINE, "edge") == "system") return false
    return isOnline()
}

private fun isOnline(): Boolean {
    val now = SystemClock.elapsedRealtime()
    online?.let { (ts, value) -> if (now - ts < ONLINE_TTL_MS) return value }
    val manager = appContext.getSystemService(Context.CONNECTIVITY_SERVICE) as? ConnectivityManager
    val result = try {
        val network = manager?.activeNetwork
        val caps = network?.let { manager.getNetworkCapabilities(it) }
        caps?.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET) == true
    } catch (e: Throwable) {
        Log.w(TAG, "[TTS] Проверка сети: ${e.message}")
        false
    }
    online = now to result
    return result
}

