private fun cacheKey(text: String, role: Role, adjustments: Pair<Int, Int>): String? = runCatching {
    val raw = "$text|${backend.name}|${voice}|$volume|${adjustments.first}|${adjustments.second}|$role|$currentRole"
    MessageDigest.getInstance("MD5").digest(raw.toByteArray(Charsets.UTF_8))
        .joinToString("") { "%02x".format(it) }
}.getOrElse {
    Log.w(TAG, "[TTS] MD5: ${it.message}")
    null
}

private fun cached(key: String): ShortArray? = synchronized(cacheLock) {
