): ShortArray? = withTemporaryVoice(voiceName) {
    synthesizeToPcm(text, utteranceId, ratePercent, pitchPercent)
}

private suspend fun <T> withTemporaryVoice(voiceName: String, block: suspend () -> T): T? {
    if (!awaitReady()) return null
    val tts = engine ?: return null
    val voice = runCatching { tts.voices?.firstOrNull { it.name == voiceName } }.getOrNull()
    if (voice == null) {
        Log.w(TAG, "[SystemTTS] Голос не найден: $voiceName")
        return null
    }
    val applied = runCatching { tts.setVoice(voice) }.isSuccess
    if (!applied) Log.w(TAG, "[SystemTTS] setVoice($voiceName) не поддержан")
    return try {
        block()
    } finally {
        if (applied) runCatching { tts.voice = null }
    }
}

fun shutdown() {
    if (!shuttingDown.compareAndSet(false, true)) return
    synchronized(lock) {
        runCatching { engine?.stop() }
        runCatching { engine?.shutdown() }
        engine = null
        initialized = false
    }
    failPending()
}

private fun failPending() {
    for ((_, deferred) in pending.entries) deferred.complete(TextToSpeech.ERROR)
    pending.clear()
}

/** +15% со скорости десктопа → 1.15 в диапазоне [0.5; 2.0]. */
fun rateMultiplier(ratePercent: Int): Float =
    ((100f + ratePercent) / 100f).coerceIn(MIN_FACTOR, MAX_FACTOR)

/** Единицы pitch -50..+50 → множитель 1.0 ± 0.5, тоже в [0.5; 2.0]. */
fun pitchMultiplier(pitchPercent: Int): Float =
    (1f + pitchPercent / 100f).coerceIn(MIN_FACTOR, MAX_FACTOR)

