```kotlin
/**
 * Билинейно/area-average ресемплинг Bitmap → IntArray ARGB.
 * PIL LANCZOS недоступен в Android; при сильном уменьшении используется
 * точный box-фильтр (снимает алиасинг, как LANCZOS на даунскейле),
 * при увеличении — билинейная интерполяция.
 */
internal object OcrBitmapOps {

    fun toArgb(src: Bitmap): IntArray {
        val w = src.width
        val h = src.height
        val px = IntArray(w * h)
        src.getPixels(px, 0, w, 0, 0, w, h)
        return px
    }

    fun resample(src: IntArray, srcW: Int, srcH: Int, dstW: Int, dstH: Int): IntArray {
        if (srcW == dstW && srcH == dstH) return src
        val xTaps = axisTaps(dstW, srcW)
        val yTaps = axisTaps(dstH, srcH)
        val dst = IntArray(dstW * dstH)
        for (dy in 0 until dstH) {
            val yStart = yTaps.start[dy]
            val yCount = yTaps.count[dy]
            val yBase = dy * yTaps.stride
            val outBase = dy * dstW
            for (dx in 0 until dstW) {
                val xStart = xTaps.start[dx]
                val xCount = xTaps.count[dx]
                val xBase = dx * xTaps.stride
                var a = 0f; var r = 0f; var g = 0f; var b = 0f
                for (j in 0 until yCount) {
                    val rowBase = (yStart + j) * srcW
                    val wy = yTaps.weights[yBase + j]
                    for (i in 0 until xCount) {
                        val p = src[rowBase + xStart + i]
                        val w = wy * xTaps.weights[xBase + i]
                        a += w * ((p ushr 24) and 0xFF)
                        r += w * ((p ushr 16) and 0xFF)
                        g += w * ((p ushr 8) and 0xFF)
                        b += w * (p and 0xFF)
                    }
                }
                dst[outBase + dx] = (-0x1000000) or
                    (clamp255(a) shl 16) or (clamp255(g) shl 8) or clamp255(b)
            }
        }
        return dst
    }

    private fun clamp255(v: Float): Int {
        val i = (v + 0.5f).toInt()
        return if (i < 0) 0 else if (i > 255) 255 else i
    }
```

`axisTaps`:
```kotlin
    private class Taps(val dstSize: Int, val stride: Int, val start: IntArray, val count: IntArray, val weights: FloatArray)

    private fun axisTaps(dstSize: Int, srcSize: Int): Taps {
        if (srcSize <= 0 || dstSize <= 0) return Taps(0,1,IntArray(0),IntArray(0),FloatArray(0))
        return if (dstSize <= srcSize) boxTaps(dstSize, srcSize) else bilinearTaps(dstSize, srcSize)
    }

    private fun boxTaps(dstSize: Int, srcSize: Int): Taps {
        val scale = srcSize.toDouble() / dstSize
        var stride = ceil(scale).toInt() + 2
        val start = IntArray(dstSize); val count = IntArray(dstSize)
        val weights = FloatArray(dstSize * stride)
        for (d in 0 until dstSize) {
            val left = d * scale
            val right = left + scale
            var s0 = floor(left).toInt()
            var s1 = ceil(right).toInt()
            if (s0 < 0) s0 = 0
            if (s1 > srcSize) s1 = srcSize
            var n = 0
            var sum = 0f
            for (s in s0 until s1) {
                val l = max(left, s.toDouble())
                val r = min(right, (s + 1).toDouble())
                val w = (r - l).toFloat()
                if (w > 0f) { weights[d*stride + n] = w; sum += w; n++ }
            }
            if (n == 0) { weights[d*stride] = 1f; sum = 1f; n = 1 }
            if (sum != 1f) { val inv = 1f/sum; for (i in 0 until n) weights[d*stride+i] *= inv }
            start[d] = s0
            count[d] = n
        }
        return Taps(dstSize, stride, start, count, weights)
    }
```

Careful: `n` could exceed stride? n = number of source pixels in [s0, s1) ≤ ceil(scale)+1... s1 - s0 ≤ ceil(right) - floor(left) ≤ ceil(scale) + 1. stride = ceil(scale)+2. OK safe.

Edge: s0 could be >= srcSize? floor(left) where left = d*scale < dstSize*scale = srcSize, so floor(left) <= srcSize-1. Good.

```kotlin
    private fun bilinearTaps(dstSize: Int, srcSize: Int): Taps {
        val stride = 2
        val start = IntArray(dstSize); val count = IntArray(dstSize)
        val weights = FloatArray(dstSize * stride)
        val denom = (dstSize - 1).toDouble()
        for (d in 0 until dstSize) {
            val pos = if (dstSize == 1) 0.0 else d * (srcSize - 1) / denom
            var i0 = floor(pos).toInt()
            if (i0 < 0) i0 = 0
            if (i0 > srcSize - 1) i0 = srcSize - 1
            val f = (pos - i0).toFloat()
            start[d] = i0
            if (i0 + 1 <= srcSize - 1) {
                count[d] = 2
                weights[d*stride] = 1f - f
                weights[d*stride+1] = f
            } else {
                count[d] = 1
                weights[d*stride] = 1f
            }
        }
        return Taps(dstSize, stride, start, count, weights)
    }
