    private fun pad(box: Box, w: Int, h: Int): Box {
        val px = max(2, (box.width * 0.04f).toInt())
        val py = max(2, (box.height * 0.12f).toInt())
        val left = (box.x - px).coerceIn(0, w - 1)
        val top = (box.y - py).coerceIn(0, h - 1)
        val right = (box.right + px).coerceIn(left + 1, w)
        val bottom = (box.bottom + py).coerceIn(top + 1, h)
        return Box(left, top, right - left, bottom - top)
    }
