    private fun collectComponents(
        scale: Float, offsetX: Int, offsetY: Int,
        srcW: Int, srcH: Int, offX: Int, offY: Int,
        out: MutableList<Box>,
    ): Boolean {
        val n = size
        val prob = probability
        visited.fill(false)
        val total = n * n
        val lastX = n - 1
        for (start in 0 until total) {
            if (visited[start] || prob[start] < DETECTOR_THRESHOLD) continue
            var head = 0
            var tail = 0
            queue[tail++] = start
            visited[start] = true
            var minX = n; var minY = n; var maxX = 0; var maxY = 0; var area = 0
            while (head < tail) {
                val idx = queue[head++]
                val x = idx - (idx / n) * n     // hmm just idx % n
                val y = idx / n
                if (x < minX) minX = x
                if (y < minY) minY = y
                if (x > maxX) maxX = x
                if (y > maxY) maxY = y
                area++
                val y0 = if (y > 0) y - 1 else 0
                val y1 = if (y < lastX) y + 1 else n - 1
                val x0 = if (x > 0) x - 1 else 0
                val x1 = if (x < lastX) x + 1 else n - 1
                for (ny in y0..y1) {
                    val base = ny * n
                    for (nx in x0..x1) {
                        val ni = base + nx
                        if (!visited[ni] && prob[ni] >= DETECTOR_THRESHOLD) {
                            visited[ni] = true
                            queue[tail++] = ni
                        }
                    }
                }
            }
            if (area < MIN_COMPONENT_AREA || maxX - minX < 3 || maxY - minY < 3) continue
            val expandX = max(3, ((maxX - minX) * EXPAND_X_FACTOR).toInt())
            val expandY = max(2, ((maxY - minY) * EXPAND_Y_FACTOR).toInt())
            var left = offX + max(0, ((minX - expandX - offsetX) / scale).toInt())
            var top = offY + max(0, ((minY - expandY - offsetY) / scale).toInt())
            var right = offX + min(srcW.toFloat(), ceil((maxX + expandX - offsetX) / scale)).toInt()
            var bottom = offY + min(srcH.toFloat(), ceil((maxY + expandY - offsetY) / scale)).toInt()
            if (right < left + 1) right = left + 1
            if (bottom < top + 1) bottom = top + 1
            if (right - left >= MIN_BOX_SIDE && bottom - top >= MIN_BOX_SIDE) {
                out.add(Box(left, top, right - left, bottom - top))
            }
        }
        return true
    }
