    private fun mergeBoxes(boxes: List<Box>): List<Box> {
        if (boxes.isEmpty()) return emptyList()
        val merged = ArrayList(boxes)
        merged.sortWith(compareBy({ it.y }, { it.x }))
        var changed = true
        while (changed) {
            changed = false
            outer@ for (i in merged.indices) {
                val a = merged[i]
                for (j in i + 1 until merged.size) {
                    val b = merged[j]
                    val overlapY = max(0, min(a.bottom, b.bottom) - max(a.y, b.y))
                    val minH = max(1, min(a.height, b.height))
                    val gapX = max(0, max(a.x, b.x) - min(a.right, b.right))
                    if (overlapY >= minH * MERGE_OVERLAP_Y_FACTOR &&
                        gapX <= max(a.height, b.height) * MERGE_GAP_X_FACTOR) {
                        merged[i] = Box(
