```kotlin
    private fun otsuThreshold(gray: IntArray, total: Int): Int {
        val hist = IntArray(256)
        for (v in gray) hist[v]++
        var sumAll = 0.0
        for (v in 0 until 256) sumAll += v.toDouble() * hist[v]
        var sumB = 0.0
        var wB = 0
        var maxBetween = -1.0
        var otsu = 127
        for (v in 0 until 256) {
            wB += hist[v]
            if (wB == 0) continue
            val wF = total - wB
            if (wF == 0) break
            sumB += v.toDouble() * hist[v]
            val mB = sumB / wB
            val mF = (sumAll - sumB) / wF
            val between = wB.toDouble() * wF * (mB - mF) * (mB - mF)
            if (between > maxBetween) { maxBetween = between; otsu = v }
        }
        return otsu
    }
```
