    private fun rescueNarrowGap(piece: Bitmap, whole: Recognition): Recognition? {
        val w = piece.width
        val h = piece.height
        if (h >= 20) return null
        val toks = whole.text.split(Regex("\\s+")).filter { it.isNotEmpty() }
        if (toks.size != 1) return null
        val tok = toks[0]
        if (tok.length < 6) return null
        if (GuardLexicon.isKnown(tok.lowercase())) return null
        val gray = OcrBitmapOps.toGray(OcrBitmapOps.toArgb(piece))
        val col = IntArray(w)
        for (x in 0 until w) { var s = 0; for (y in 0 until h) if (gray[y*w+x] < 128) s++; col[x] = s }
        val gapsX = IntArray(w); val gapsW = IntArray(w); var gaps = 0
        var x = 0
        while (x < w) {
            if (col[x] > 0) { x++; continue }
            val x0 = x
            while (x < w && col[x] == 0) x++
            val gw = x - x0
            if (gw in 3..4 && x0 > w * 0.15 && x < w * 0.85) { gapsX[gaps] = x0; gapsW[gaps] = gw; gaps++ }
        }
        if (gaps == 0) return null
        // sort by width desc (stable)
        val order = (0 until gaps).sortedByDescending { gapsW[it] }
        val wholeAlpha = whole.text.count { it.isLetter() }
        for (gi in order) {
            val gx = gapsX[gi]
            val leftBmp = Bitmap.createBitmap(piece, 0, 0, gx, h)
            val rightBmp = Bitmap.createBitmap(piece, gx, 0, w - gx, h)
            val rl = recognizeCrop(leftBmp)
            val rr = recognizeCrop(rightBmp)
            if (rl.text.isBlank() || rr.text.isBlank()) continue
            val joined = (rl.text.trim() + " " + rr.text.trim()).trim()
            if (joined == whole.text) continue
            if (joined.count { it.isLetter() } < wholeAlpha - 1) continue
            return Recognition(joined, (rl.confidence + rr.confidence) / 2f, whole.model, max(rl.coverage, rr.coverage), rl.nLat + rr.nLat, rl.nCyr + rr.nCyr)
        }
        return null
    }
