                if (dp[start] == null) continue
                val candidate = word.substring(start, i)
                if (!Guard.KNOWN.contains(candidate)) continue
                val prev = dp[start]!!
                val cur = dp[i]
                val newList = IntArray(prev.size + 1)
                System.arraycopy(prev, 0, newList, 0, prev.size)
                newList[prev.size] = length
                if (cur == null || newList.size < cur.size) dp[i] = newList
            }
        }
        return dp[n]
    }
