package com.screenocr.tts.ocr

import android.graphics.Bitmap
import com.screenocr.tts.core.Box
import org.tensorflow.lite.Interpreter
import java.io.File
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.nio.FloatBuffer
import kotlin.math.ceil
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min

/**
 * Итог детекции: боксы в координатах исходного кадра плюс карта вероятностей
 * детектора. Массив [probability] — внутренний буфер движка, он перезаписывается
 * следующим вызовом [TfliteDetector.detect].
 */
class DetectionResult(
    val boxes: List<Box>,
    val probability: FloatArray,
)

/**
 * Порт детектора PP-OCRv4 DB из tflite_ocr.py.
 *
 * Перенесены `_detect_text_boxes`, `_run_detection`, `_merge_boxes`,
 * `_projection_boxes` и `_pad`.
 *
 * Вход модели — NHWC float32 [1, N, N, 3], белый фон, RGB→BGR,
 * нормализация mean=[0.485, 0.456, 0.406] / std=[0.229, 0.224, 0.225].
 * Текстовые боксы достаются connected-component BFS по карте вероятностей.
 */
class TfliteDetector(
    modelFile: File,
    limitSide: Int,
) {

    companion object {
        /** Порог бинаризации карты вероятностей (OcrTuning, пресет BALANCED). */
        const val DETECTOR_THRESHOLD = 0.20f

        /** Минимальная площадь связной компоненты в пикселях карты 736×736. */
        const val MIN_COMPONENT_AREA = 16

        /** Больше боксов движок всё равно не успевает распознать за кадр. */
        const val MAX_TEXT_BOXES = 128

        const val MERGE_OVERLAP_Y_FACTOR = 0.55f
        const val MERGE_GAP_X_FACTOR = 0.55f

        /** Перекрытие тайлов при дополнительном проходе по крупному кадру. */
        const val TILE_OVERLAP = 0.12f

        /** Тайл меньше этой стороны пропускается — там нет читаемого текста. */
        const val MIN_TILE_SIDE = 96

        /** Расширение бокса компоненты перед возвратом в координаты кадра. */
        const val EXPAND_X_FACTOR = 0.16f
        const val EXPAND_Y_FACTOR = 0.20f
        const val MIN_BOX_SIDE = 6

        private const val MEAN_B = 0.485f
        private const val MEAN_G = 0.456f
        private const val MEAN_R = 0.406f
        private const val STD_B = 0.229f
        private const val STD_G = 0.224f
        private const val STD_R = 0.225f
        private const val INV_255 = 1f / 255f
    }

    // num_threads=1: XNNPACK при параллельных свёртках переворачивает argmax
    // между прогонами, когда логиты почти равны (flat-softmax).
    private val interpreter: Interpreter =
        Interpreter(modelFile, Interpreter.Options().setNumThreads(1))

    private val modelInputShape: IntArray = interpreter.getInputTensor(0).shape()
    private val modelOutputShape: IntArray = interpreter.getOutputTensor(0).shape()

    /**
     * Сторона входа детектора. Берётся из модели: [limitSide] используется,
     * только если модель не сообщает квадратный вход (иначе infer упадёт).
     */
    private val size: Int = if (
        modelInputShape.size >= 3 && modelInputShape[1] == modelInputShape[2] && modelInputShape[1] > 0
    ) {
        modelInputShape[1]
    } else {
        limitSide.coerceAtLeast(1)
    }

    private val inputValues = FloatArray(size * size * 3)
    private val inputBuffer: ByteBuffer =
        ByteBuffer.allocateDirect(inputValues.size * 4).order(ByteOrder.nativeOrder())
    private val outputValueCount: Int =
        modelOutputShape.fold(1) { acc, dim -> acc * max(1, dim) }
    private val outputBuffer: ByteBuffer =
        ByteBuffer.allocateDirect(outputValueCount * 4).order(ByteOrder.nativeOrder())
    private val inputView: FloatBuffer = inputBuffer.asFloatBuffer()
    private val outputView: FloatBuffer = outputBuffer.asFloatBuffer()

    private val probability = FloatArray(size * size)
    private val visited = BooleanArray(size * size)
    private val queue = IntArray(size * size)

    init {
        require(modelInputShape.size == 4 && modelInputShape[3] == 3) {
            "detector: ожидался вход NHWC [1,N,N,3], получено ${modelInputShape.contentToString()}"
        }
        require(outputValueCount >= size * size) {
            "detector: выход ${modelOutputShape.contentToString()} меньше карты $size×$size"
        }
        interpreter.allocateTensors()
    }

    /**
     * Порт `_detect_text_boxes` + `_pad`.
     *
     * Кадр больше [size] дополнительно проходится четырьмя тайлами с
     * перекрытием [TILE_OVERLAP]; результаты всех проходов сливаются.
     * Если после слияния ничего не осталось — включается запасной
     * `_projection_boxes` по проекциям строк/столбцов.
     */
    @Synchronized
    fun detect(image: Bitmap): DetectionResult {
        if (image.isRecycled || image.width <= 0 || image.height <= 0) {
            return DetectionResult(emptyList(), probability)
        }
        val raw = ArrayList<Box>(64)
        runDetection(image, 0, 0, raw)

        if (max(image.width, image.height) > size) {
            val overX = (image.width * TILE_OVERLAP).toInt()
            val overY = (image.height * TILE_OVERLAP).toInt()
            val halfW = image.width / 2
            val halfH = image.height / 2
            val tiles = intArrayOf(
                0, 0, halfW + overX, halfH + overY,
                halfW - overX, 0, image.width, halfH + overY,
                0, halfH - overY, halfW + overX, image.height,
                halfW - overX, halfH - overY, image.width, image.height,
            )
            var t = 0
            while (t < tiles.size) {
                val x1 = max(0, tiles[t])
                val y1 = max(0, tiles[t + 1])
                val x2 = min(image.width, tiles[t + 2])
                val y2 = min(image.height, tiles[t + 3])
                t += 4
                if (x2 - x1 < MIN_TILE_SIDE || y2 - y1 < MIN_TILE_SIDE) continue
                runDetection(Bitmap.createBitmap(image, x1, y1, x2 - x1, y2 - y1), x1, y1, raw)
            }
        }

        val merged = mergeBoxes(raw)
        if (merged.isEmpty()) return DetectionResult(projectionBoxes(image), probability)
        val limited = if (merged.size > MAX_TEXT_BOXES) {
            merged.subList(0, MAX_TEXT_BOXES).toList()
        } else {
            merged
        }
        // Каждый бокс распознаётся отдельно, поля обязательны: без левого
        // контекста распознаватель теряет крайний глиф (заголовок «П»).
        return DetectionResult(limited.map { pad(it, image.width, image.height) }, probability)
    }

    fun close() {
        interpreter.close()
    }

    // ── ДЕТЕКЦИЯ ───────────────────────────────────────────

    /** Порт `_run_detection`: масштаб в limitSide, infer, BFS по компонентам. */
    private fun runDetection(source: Bitmap, offX: Int, offY: Int, out: MutableList<Box>) {
        val srcW = source.width
        val srcH = source.height
        if (srcW <= 0 || srcH <= 0 || source.isRecycled) return

        val scale = min(size.toFloat() / srcW, size.toFloat() / srcH)
        val scaledW = max(1, (srcW * scale).toInt())
        val scaledH = max(1, (srcH * scale).toInt())
        val offsetX = (size - scaledW) / 2
        val offsetY = (size - scaledH) / 2

        val resized = OcrBitmapOps.resample(
            OcrBitmapOps.toArgb(source), srcW, srcH, scaledW, scaledH,
        )
        if (!infer(resized, scaledW, scaledH, offsetX, offsetY)) return
        collectComponents(scale, offsetX, offsetY, srcW, srcH, offX, offY, out)
    }

    /**
     * Заливка входа и вызов интерпретатора.
     * Значение вне вставленного прямоугольника — белый фон, как в оригинале.
     */
    private fun infer(px: IntArray, w: Int, h: Int, offsetX: Int, offsetY: Int): Boolean {
        val whiteB = (1f - MEAN_B) / STD_B
        val whiteG = (1f - MEAN_G) / STD_G
        val whiteR = (1f - MEAN_R) / STD_R
        val values = inputValues
        for (y in 0 until size) {
            val rowBase = y * size * 3
            val srcRow = y - offsetY
            val hasRow = srcRow in 0 until h
            val srcBase = if (hasRow) srcRow * w else 0
            for (x in 0 until size) {
                val i = rowBase + x * 3
                val srcCol = x - offsetX
                if (hasRow && srcCol in 0 until w) {
                    val p = px[srcBase + srcCol]
                    values[i] = (((p and 0xFF) * INV_255) - MEAN_B) / STD_B
                    values[i + 1] = ((((p ushr 8) and 0xFF) * INV_255) - MEAN_G) / STD_G
                    values[i + 2] = (((((p ushr 16) and 0xFF) * INV_255) - MEAN_R) / STD_R
                } else {
                    values[i] = whiteB
                    values[i + 1] = whiteG
                    values[i + 2] = whiteR
                }
            }
        }
        inputView.clear()
        inputView.put(values)
        inputBuffer.rewind()
        outputBuffer.rewind()
        interpreter.run(inputBuffer, outputBuffer)
        outputView.clear()
        outputView.get(probability, 0, size * size)
        return true
    }

    /**
     * Connected-component BFS по 8-связности. Очередь и карта посещённых —
     * предвыделенные массивы размера N×N, в цикле аллокаций нет.
     */
    private fun collectComponents(
        scale: Float,
        offsetX: Int,
        offsetY: Int,
        srcW: Int,
        srcH: Int,
        offX: Int,
        offY: Int,
        out: MutableList<Box>,
    ) {
        val n = size
        val last = n - 1
        val total = n * n
        val prob = probability
        visited.fill(false)
        for (start in 0 until total) {
            if (visited[start] || prob[start] < DETECTOR_THRESHOLD) continue
            var head = 0
            var tail = 0
            queue[tail++] = start
            visited[start] = true
            var minX = n
            var minY = n
            var maxX = 0
            var maxY = 0
            var area = 0
            while (head < tail) {
                val idx = queue[head++]
                val y = idx / n
                val x = idx - y * n
                if (x < minX) minX = x
                if (y < minY) minY = y
                if (x > maxX) maxX = x
                if (y > maxY) maxY = y
                area++
                val y0 = if (y > 0) y - 1 else 0
                val y1 = if (y < last) y + 1 else last
                val x0 = if (x > 0) x - 1 else 0
                val x1 = if (x < last) x + 1 else last
                for (ny in y0..y1) {
                    val base = ny * n
                    for (nx in x0..x1) {
                        val ni = base + nx
                        if (!visited[ni] && prob[ni] >= DETECTOR_THRESHOLD) {
                            visited[ni] = true
                            queue[tail++] = ni
                        }
                    }
                }
            }

            if (area < MIN_COMPONENT_AREA || maxX - minX < 3 || maxY - minY < 3) continue

            val expandX = max(3, ((maxX - minX) * EXPAND_X_FACTOR).toInt())
            val expandY = max(2, ((maxY - minY) * EXPAND_Y_FACTOR).toInt())
            var left = offX + max(0, ((minX - expandX - offsetX) / scale).toInt())
            var top = offY + max(0, ((minY - expandY - offsetY) / scale).toInt())
            var right = offX + min(srcW.toFloat(), ceil((maxX + expandX - offsetX) / scale)).toInt()
            var bottom = offY + min(srcH.toFloat(), ceil((maxY + expandY - offsetY) / scale)).toInt()
            if (right < left + 1) right = left + 1
            if (bottom < top + 1) bottom = top + 1
            if (right - left >= MIN_BOX_SIDE && bottom - top >= MIN_BOX_SIDE) {
                out.add(Box(left, top, right - left, bottom - top))
            }
        }
    }

    /**
     * Порт `_merge_boxes`: попарное слияние близких боксов с перезапуском
     * прохода после каждого слияния (как в оригинале).
     */
    private fun mergeBoxes(boxes: List<Box>): List<Box> {
        if (boxes.isEmpty()) return emptyList()
        val merged = ArrayList(boxes)
        merged.sortWith(compareBy({ it.y }, { it.x }))
        var changed = true
        while (changed) {
            changed = false
            outer@ for (i in merged.indices) {
                for (j in i + 1 until merged.size) {
                    val a = merged[i]
                    val b = merged[j]
                    val overlapY = max(0, min(a.bottom, b.bottom) - max(a.y, b.y))
                    val minH = max(1, min(a.height, b.height))
                    val gapX = max(0, max(a.x, b.x) - min(a.right, b.right))
                    if (
                        overlapY >= minH * MERGE_OVERLAP_Y_FACTOR &&
                        gapX <= max(a.height, b.height) * MERGE_GAP_X_FACTOR
                    ) {
                        val left = min(a.x, b.x)
                        val top = min(a.y, b.y)
                        merged[i] = Box(
                            left,
                            top,
                            max(a.right, b.right) - left,
                            max(a.bottom, b.bottom) - top,
                        )
                        merged.removeAt(j)
                        changed = true
                        break@outer
                    }
                }
            }
        }
        merged.sortWith(compareBy({ it.y }, { it.x }))
        return merged
    }

    /**
     * Порт `_projection_boxes`: запасной детектор по горизонтальным полосам
     * «тёмных» строк и крайним столбцам с чернилами внутри полосы.
     */
    private fun projectionBoxes(image: Bitmap): List<Box> {
        val w = image.width
        val h = image.height
        val gray = OcrBitmapOps.toGray(OcrBitmapOps.toArgb(image))
        val rowSums = IntArray(h)
        for (y in 0 until h) {
            val base = y * w
            var sum = 0
            for (x in 0 until w) {
                if (gray[base + x] < 180) sum++
            }
            rowSums[y] = sum
        }
        val boxes = ArrayList<Box>()
        var inRegion = false
        var yStart = 0
        for (y in 0 until h) {
            if (rowSums[y] > 5 && !inRegion) {
                inRegion = true
                yStart = y
            } else if (rowSums[y] <= 5 && inRegion) {
                inRegion = false
                addProjectedBox(boxes, gray, w, yStart, y)
            }
        }
        if (inRegion) addProjectedBox(boxes, gray, w, yStart, h)
        return boxes
    }

    private fun addProjectedBox(out: MutableList<Box>, gray: IntArray, w: Int, y0: Int, y1: Int) {
        var first = -1
        var last = -1
        for (y in y0 until y1) {
            val base = y * w
            for (x in 0 until w) {
                if (gray[base + x] < 180) {
                    if (first < 0) first = x
                    last = x
                }
            }
        }
        if (first >= 0) out.add(Box(first, y0, last + 1 - first, y1 - y0))
    }

    /** Порт `_pad`: поля 4% по X и 12% по Y, обрезанные по границам кадра. */
    private fun pad(box: Box, w: Int, h: Int): Box {
        val px = max(2, (box.width * 0.04f).toInt())
        val py = max(2, (box.height * 0.12f).toInt())
        val left = (box.x - px).coerceIn(0, max(0, w - 1))
        val top = (box.y - py).coerceIn(0, max(0, h - 1))
        val right = (box.right + px).coerceIn(left + 1, w)
        val bottom = (box.bottom + py).coerceIn(top + 1, h)
        return Box(left, top, right - left, bottom - top)
    }
}

/**
 * Растровые примитивы, общие для [TfliteDetector] и [TfliteRecognizer]:
 * выгрузка пикселей, luma и ресемплинг.
 *
 * PIL LANCZOS в Android недоступен: при уменьшении используется точный
 * box-фильтр по покрытию (снимает алиасинг на сильном даунскейле, как и
 * LANCZOS), при увеличении — билинейная интерполяция.
 */
internal object OcrBitmapOps {

    fun toArgb(source: Bitmap): IntArray {
        val w = source.width
        val h = source.height
        val px = IntArray(w * h)
        source.getPixels(px, 0, w, 0, 0, w, h)
        return px
    }

    /** ITU-R 601-2 luma — то же преобразование, что даёт PIL `convert("L")`. */
    fun toGray(px: IntArray): IntArray {
        val gray = IntArray(px.size)
        for (i in px.indices) {
            val p = px[i]
            gray[i] = ((p ushr 16 and 0xFF) * 19595 + (p ushr 8 and 0xFF) * 38470 +
                (p and 0xFF) * 7471 + 0x8000) shr 16
        }
        return gray
    }

    fun resample(src: IntArray, srcW: Int, srcH: Int, dstW: Int, dstH: Int): IntArray {
        if (srcW <= 0 || srcH <= 0 || dstW <= 0 || dstH <= 0) return IntArray(0)
        if (srcW == dstW && srcH == dstH) return src
        val xTaps = axisTaps(dstW, srcW)
        val yTaps = axisTaps(dstH, srcH)
        val dst = IntArray(dstW * dstH)
        for (dy in 0 until dstH) {
            val yStart = yTaps.start[dy]
            val yCount = yTaps.count[dy]
            val yBase = dy * yTaps.stride
            val outBase = dy * dstW
            for (dx in 0 until dstW) {
                val xStart = xTaps.start[dx]
                val xCount = xTaps.count[dx]
                val xBase = dx * xTaps.stride
                var a = 0f
                var r = 0f
                var g = 0f
                var b = 0f
                for (j in 0 until yCount) {
                    val rowBase = (yStart + j) * srcW
                    val wy = yTaps.weights[yBase + j]
                    for (i in 0 until xCount) {
                        val p = src[rowBase + xStart + i]
                        val w = wy * xTaps.weights[xBase + i]
                        a += w * (p ushr 24 and 0xFF)
                        r += w * (p ushr 16 and 0xFF)
                        g += w * (p ushr 8 and 0xFF)
                        b += w * (p and 0xFF)
                    }
                }
                dst[outBase + dx] = -0x1000000 or
                    (clamp255(r) shl 16) or (clamp255(g) shl 8) or clamp255(b)
            }
        }
        return dst
    }

    private fun clamp255(v: Float): Int {
        val i = (v + 0.5f).toInt()
        return if (i < 0) 0 else if (i > 255) 255 else i
    }

    private class Taps(
        val stride: Int,
        val start: IntArray,
        val count: IntArray,
        val weights: FloatArray,
    )

    private fun axisTaps(dstSize: Int, srcSize: Int): Taps = when {
        dstSize <= srcSize -> boxTaps(dstSize, srcSize)
        else -> bilinearTaps(dstSize, srcSize)
    }

    /** Среднее по точному перекрытию интервалов [dst*d, dst*d+1) — без алиасинга. */
    private fun boxTaps(dstSize: Int, srcSize: Int): Taps {
        val scale = srcSize.toDouble() / dstSize
        val stride = ceil(scale).toInt() + 2
        val start = IntArray(dstSize)
        val count = IntArray(dstSize)
        val weights = FloatArray(dstSize * stride)
        for (d in 0 until dstSize) {
            val left = d * scale
            val right = left + scale
            var s0 = floor(left).toInt()
            var s1 = ceil(right).toInt()
            if (s0 < 0) s0 = 0
            if (s1 > srcSize) s1 = srcSize
            val base = d * stride
            var n = 0
            var sum = 0f
            for (s in s0 until s1) {
                val l = max(left, s.toDouble())
                val r = min(right, (s + 1).toDouble())
                val w = (r - l).toFloat()
                if (w > 0f) {
                    weights[base + n] = w
                    sum += w
                    n++
                }
            }
            if (n == 0) {
                weights[base] = 1f
                n = 1
            } else if (sum != 1f) {
                val inv = 1f / sum
                for (i in 0 until n) weights[base + i] *= inv
            }
            start[d] = s0
            count[d] = n
        }
        return Taps(stride, start, count, weights)
    }

    private fun bilinearTaps(dstSize: Int, srcSize: Int): Taps {
        val stride = 2
        val start = IntArray(dstSize)
        val count = IntArray(dstSize)
        val weights = FloatArray(dstSize * stride)
        val denom = (dstSize - 1).toDouble()
        for (d in 0 until dstSize) {
            val pos = if (dstSize == 1) 0.0 else d * (srcSize - 1) / denom
            var i0 = floor(pos).toInt()
            if (i0 < 0) i0 = 0
            if (i0 > srcSize - 1) i0 = srcSize - 1
            val f = (pos - i0).toFloat()
            start[d] = i0
            if (i0 + 1 <= srcSize - 1) {
                count[d] = 2
                weights[d * stride] = 1f - f
                weights[d * stride + 1] = f
            } else {
                count[d] = 1
                weights[d * stride] = 1f
            }
        }
        return Taps(stride, start, count, weights)
    }
}

package com.screenocr.tts.ocr

import android.graphics.Bitmap
import org.tensorflow.lite.Interpreter
import java.io.File
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.nio.FloatBuffer
import kotlin.math.exp
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min

/**
 * Порт CTC-распознавателя PP-OCR из tflite_ocr.py.
 *
 * Перенесены `_recognize_line_bitmap`, `_recognize_crop`, `_run_recognizer`,
 * `_infer_window`, `_decode_ctc`, `_split_words`, `_join_pieces`,
 * `_rescue_narrow_gap`, `_select_line_recognition`, `_candidate_quality`,
 * `_create_high_contrast`, `_merge_window_texts`.
 *
 * Вход модели — NHWC float32 [1, 48, 320, 3], серый фон 128, RGB→BGR,
 * нормализация (v/255 − 0.5) / 0.5 (та же, что в оригинале и в test_tflite.py).
 * Выход — сырые логиты [1, steps, num_classes]; softmax считается на лету.
 */
class TfliteRecognizer(
    modelFile: File,
    dictionary: String,
    private val recWidth: Int = 320,
    private val recHeight: Int = 48,
) {

    companion object {
        /** Ниже этого порога модель повторяет кроп в высококонтрастном виде. */
        const val CONTRAST_RETRY_CONFIDENCE = 0.90f

        const val MIN_COVERAGE = 0.12f
        const val VERIFIER_CYRILLIC_BONUS = 0.20f
        const val WHOLE_LINE_BOUNDARY_BONUS = 0.08f
        const val SPLIT_MIN_WIDTH_PX = 32
        const val MIN_WORD_GAP_PX = 5
        const val WORD_GAP_FACTOR = 1.7f
        const val LENGTH_BONUS_PER_CHAR = 0.01f
        const val MAX_LENGTH_BONUS = 0.12f

        /** ALLOWED_PUNCTUATION из tflite_ocr.py. */
        val ALLOWED_PUNCTUATION: Set<Char> = setOf(
            ' ', '.', ',', '!', '?', ';', ':', '-', '(', ')', '[', ']', '{', '}',
            '\\', '"', '\'', '«', '»', '„', '%', '№', '+', '/', '=', '…', '—', '–',
        )

        private const val MODEL_V3 = "v3"
        private const val MODEL_V5 = "v5"

        /** У v5 852 класса, у v3 — 165; порог достаточен для различения. */
        private const val V5_MIN_CLASSES = 512

        private const val REC_BACKGROUND = 128f
        private const val HIGH_CONTRAST_GAIN = 1.5f
        private const val HIGH_CONTRAST_BIAS = -45f

        /** Порог преобладания латиницы/кириллицы в CTC-шаге. */
        private const val SCRIPT_EVIDENCE_MIN = 0.008f
        private const val SCRIPT_EVIDENCE_MARGIN = 1.2f

        private val WHITESPACE = Regex("\\s+")
        private val NEG_INF = Float.NEGATIVE_INFINITY
    }

    /** Кандидат-распознавание строки; [model] — тег «v3»/«v5». */
    private class Recognition(
        val text: String,
        val confidence: Float,
        val model: String,
        val coverage: Float,
        val nLat: Int = 0,
        val nCyr: Int = 0,
    )

    /** Результат жадного CTC-декода одного окна. */
    private class CtcResult(
        val text: String,
        val confidence: Float,
        val emitted: Int,
        val coverage: Float,
        val nLat: Int,
        val nCyr: Int,
    )

    private val interpreter: Interpreter =
        Interpreter(modelFile, Interpreter.Options().setNumThreads(1))

    private val modelInputShape: IntArray = interpreter.getInputTensor(0).shape()
    private val modelOutputShape: IntArray = interpreter.getOutputTensor(0).shape()

    /** Словарь символов: 1-я строка — пробел, символ класса i равен chars[i−1]. */
    private val chars: List<String> = parseDictionary(dictionary)
    private val numClasses: Int = if (modelOutputShape.size >= 3) modelOutputShape[2] else 0
    private val modelName: String = if (numClasses >= V5_MIN_CLASSES) MODEL_V5 else MODEL_V3

    // Классы вне словаря (164/165 у v3, 851/852 у v5) отбрасываются в декоде.
    private val classAllowed = BooleanArray(numClasses)
    private val isLatinClass = BooleanArray(numClasses)
    private val isCyrillicClass = BooleanArray(numClasses)
    private val classChar = Array(numClasses) { "" }

    private val inputValues = FloatArray(recWidth * recHeight * 3)
    private val inputBuffer: ByteBuffer =
        ByteBuffer.allocateDirect(inputValues.size * 4).order(ByteOrder.nativeOrder())
    private val outputValueCount: Int =
        modelOutputShape.fold(1) { acc, dim -> acc * max(1, dim) }
    private val outputValues = FloatArray(outputValueCount)
    private val outputBuffer: ByteBuffer =
        ByteBuffer.allocateDirect(outputValueCount * 4).order(ByteOrder.nativeOrder())
    private val inputView: FloatBuffer = inputBuffer.asFloatBuffer()
    private val outputView: FloatBuffer = outputBuffer.asFloatBuffer()

    init {
        require(recWidth > 0 && recHeight > 0) { "recognizer: некорректный размер входа" }
        require(modelInputShape.size == 4 && modelInputShape[1] == recHeight && modelInputShape[2] == recWidth) {
            "recognizer: ожидался вход NHWC [1,$recHeight,$recWidth,3], " +
                "получено ${modelInputShape.contentToString()}"
        }
        require(numClasses >= 2 && outputValueCount >= numClasses) {
            "recognizer: некорректный выход ${modelOutputShape.contentToString()}"
        }
        for (idx in 1 until numClasses) {
            val ch = chars.getOrNull(idx - 1)
            if (ch == null) continue
            classChar[idx] = ch
            if (!isAllowed(ch)) continue
            classAllowed[idx] = true
            if (ch.length == 1) {
                val c = ch[0]
                if (c in 'a'..'z' || c in 'A'..'Z') {
                    isLatinClass[idx] = true
                } else if (isCyrillicCode(c)) {
                    isCyrillicClass[idx] = true
                }
            }
        }
        interpreter.allocateTensors()
    }

    /**
     * Порт `_recognize_line_bitmap`: вернуть текст и confidence (0..1) для
     * одного бокса детектора.
     */
    @Synchronized
    fun recognizeLine(crop: Bitmap): Pair<String, Float> {
        if (crop.isRecycled || crop.width <= 0 || crop.height <= 0) return "" to 0f
        val best = recognizeLineBitmap(crop)
        return best.text to best.confidence
    }

    fun close() {
        interpreter.close()
    }

    // ── СТРОКА ─────────────────────────────────────────────

    /**
     * Кандидаты «вся строка» против «разрезанная по словам», выбор по quality.
     * При единственном куске дополнительно пробуем `_rescue_narrow_gap`.
     */
    private fun recognizeLineBitmap(crop: Bitmap): Recognition {
        val words = splitWords(crop)
        val wholeLine = recognizeCrop(crop)
        if (words.size == 1) {
            return rescueNarrowGap(words[0], wholeLine) ?: wholeLine
        }
        val parts = ArrayList<String>(words.size)
        var confSum = 0f
        var count = 0
        for (wordImg in words) {
            val r = recognizeCrop(wordImg)
            if (r.text.isNotBlank()) {
                confSum += r.confidence
                count++
                parts.add(r.text)
            }
        }
        val segmented = Recognition(
            text = joinPieces(parts),
            confidence = if (count > 0) confSum / count else 0f,
            model = wholeLine.model,
            coverage = wholeLine.coverage,
        )
        return selectLineRecognition(wholeLine, segmented)
    }

    /**
     * Порт `_recognize_crop`: базовый проход плюс high-contrast повтор при
     * низкой уверенности, лучший кандидат — по quality.
     */
    private fun recognizeCrop(crop: Bitmap): Recognition {
        var best = runRecognizer(crop)
        if (best.confidence < CONTRAST_RETRY_CONFIDENCE) {
            val retry = runRecognizer(createHighContrast(crop))
            if (candidateQuality(retry) > candidateQuality(best)) best = retry
        }
        return best
    }

    /**
     * Порт `_run_recognizer`. Длинные кропы сжимались бы в 320px по горизонтали
     * (глифы становятся узкими и декодятся с ошибками) — вместо этого кроп
     * накрывается перекрывающимися окнами, результаты склеиваются.
     */
    private fun runRecognizer(crop: Bitmap): Recognition {
        val w = crop.width
        val h = crop.height
        if (w <= 0 || h <= 0) return Recognition("", 0f, modelName, 0f)

        val scale = recHeight / max(1, h).toFloat()
        val starts: IntArray
        val winW: Int
        if (w * scale <= recWidth) {
            winW = w
            starts = intArrayOf(0)
        } else {
            winW = max(16, recWidth * h / recHeight)
            val stride = max(8, winW - max(16, winW / 5))
            val collected = ArrayList<Int>(8)
            val limit = max(1, w - winW + 1)
            var s = 0
            while (s < limit) {
                collected.add(s)
                s += stride
            }
            if (collected.isEmpty() || collected[collected.size - 1] + winW < w) {
                collected.add(max(0, w - winW))
            }
            starts = collected.toIntArray()
        }

        val texts = ArrayList<String>(starts.size)
        var confSum = 0f
        var confCount = 0
        var coverage = 0f
        var nLat = 0
        var nCyr = 0
        for (start in starts) {
            val end = min(w, start + winW)
            val width = (end - start).coerceAtLeast(1)
            val win = if (start == 0 && end == w) {
                crop
            } else {
                Bitmap.createBitmap(crop, start, 0, width, h)
            }
            val r = inferWindow(win)
            texts.add(r.text)
            confSum += r.confidence
            confCount++
            if (r.coverage > coverage) coverage = r.coverage
            nLat += r.nLat
            nCyr += r.nCyr
        }
        return Recognition(
            text = mergeWindowTexts(texts),
            confidence = if (confCount > 0) confSum / confCount else 0f,
            model = modelName,
            coverage = coverage,
            nLat = nLat,
            nCyr = nCyr,
        )
    }

    /**
     * Порт `_infer_window`: ресемплинг по высоте в [recHeight] с серым фоном
     * 128, нормализация (v/255 − 0.5) / 0.5, вызов CTC-декода.
     */
    private fun inferWindow(crop: Bitmap): CtcResult {
        val h = crop.height
        val w = crop.width
        if (w <= 0 || h <= 0) return EMPTY_CTC
        val scale = recHeight / max(1, h).toFloat()
        val targetW = min(recWidth, max(1, (w * scale).toInt()))
        val resized = OcrBitmapOps.resample(OcrBitmapOps.toArgb(crop), w, h, targetW, recHeight)
        if (resized.isEmpty()) return EMPTY_CTC

        val background = (REC_BACKGROUND / 255f - 0.5f) / 0.5f
        val values = inputValues
        for (y in 0 until recHeight) {
            val rowBase = y * recWidth * 3
            val srcBase = y * targetW
            for (x in 0 until recWidth) {
                val i = rowBase + x * 3
                if (x < targetW) {
                    val p = resized[srcBase + x]
                    values[i] = ((p and 0xFF) / 255f - 0.5f) / 0.5f
                    values[i + 1] = (((p ushr 8) and 0xFF) / 255f - 0.5f) / 0.5f
                    values[i + 2] = ((((p ushr 16) and 0xFF) / 255f) - 0.5f) / 0.5f
                } else {
                    values[i] = background
                    values[i + 1] = background
                    values[i + 2] = background
                }
            }
        }
        inputView.clear()
        inputView.put(values)
        inputBuffer.rewind()
        outputBuffer.rewind()
        interpreter.run(inputBuffer, outputBuffer)
        outputView.clear()
        outputView.get(outputValues, 0, outputValueCount)
        return decodeCtc(outputValues, numClasses)
    }

    /**
     * Порт `_decode_ctc`: жадный CTC (collapse повторов, выброс blank=0) плюс
     * softmax для confidence и определения доминирующего алфавита.
     *
     * Классы за пределами словаря пропускаются: в кадре обхода сравнивается
     * `probs[idx] > best_score`, а для idx вне словаря символ пустой и
     * запрещён `_allowed`. Сравнение логитов эквивалентно сравнению вероятностей
     * (нормализация монотонна), поэтому softmax считается только в конце шага.
     */
    private fun decodeCtc(values: FloatArray, classes: Int): CtcResult {
        if (classes <= 1 || values.size < classes) return EMPTY_CTC
        val steps = values.size / classes
        val text = StringBuilder(64)
        var prev = -1
        var confSum = 0f
        var confCount = 0
        var blankSteps = 0
        var countingBlanks = false
        var nLat = 0
        var nCyr = 0
        var latLogit = Float.NEGATIVE_INFINITY
        var cyrLogit = Float.NEGATIVE_INFINITY
        var latFound = false
        var cyrFound = false

        for (step in 0 until steps) {
            val base = step * classes
            val blankLogit = values[base]
            var maxLogit = blankLogit
            var bestIdx = 0
            var bestLogit = blankLogit
            latLogit = Float.NEGATIVE_INFINITY
            cyrLogit = Float.NEGATIVE_INFINITY
            latFound = false
            cyrFound = false
            for (idx in 1 until classes) {
                val v = values[base + idx]
                if (v > maxLogit) maxLogit = v
                if (!classAllowed[idx]) continue
                if (v > bestLogit) {
                    bestLogit = v
                    bestIdx = idx
                }
                if (isLatinClass[idx]) {
                    if (!latFound || v > latLogit) {
                        latLogit = v
                        latFound = true
                    }
                } else if (isCyrillicClass[idx]) {
                    if (!cyrFound || v > cyrLogit) {
                        cyrLogit = v
                        cyrFound = true
                    }
                }
            }
            var sumExp = 0f
            for (idx in 0 until classes) {
                sumExp += exp(values[base + idx] - maxLogit)
            }
            val invSum = if (sumExp > 0f) 1f / sumExp else 0f
            val bestProb = exp(bestLogit - maxLogit) * invSum
            val latProb = if (latFound) exp(latLogit - maxLogit) * invSum else 0f
            val cyrProb = if (cyrFound) exp(cyrLogit - maxLogit) * invSum else 0f

            // Свидетельство алфавита: нужен и отрыв от шума, и отрыв от другого
            // алфавита, иначе шаги padding'а (blank/равномерно) голосуют.
            if (latProb > SCRIPT_EVIDENCE_MIN && latProb > cyrProb * SCRIPT_EVIDENCE_MARGIN) {
                nLat++
            } else if (cyrProb > SCRIPT_EVIDENCE_MIN && cyrProb > latProb * SCRIPT_EVIDENCE_MARGIN) {
                nCyr++
            }

            if (bestIdx != 0 && bestIdx != prev) {
                if (bestIdx - 1 < chars.size) text.append(classChar[bestIdx])
                confSum += bestProb
                confCount++
                countingBlanks = true
            } else if (bestIdx == 0 && countingBlanks) {
                blankSteps++
            }
            prev = bestIdx
        }

        val decoded = text.toString().trim()
        val confidence = if (confCount > 0) confSum / confCount else 0f
        var coverage = 0f
        if (confCount > 0 && steps > 0) {
            val inner = steps - confCount
            if (inner > 0) {
                coverage = min(1f, blankSteps.toFloat()) * (inner.toFloat() / steps)
            }
        }
        return CtcResult(decoded, confidence, confCount, coverage, nLat, nCyr)
    }

    // ── РАЗБИЕНИЕ НА СЛОВА ─────────────────────────────────

    /**
     * Порт `_split_words`: Otsu по гистограмме, вертикальная проекция чернил,
     * поиск разрывов ≥ max(MIN_WORD_GAP_PX, median×WORD_GAP_FACTOR).
     */
    private fun splitWords(crop: Bitmap): List<Bitmap> {
        val w = crop.width
        val h = crop.height
        if (w < SPLIT_MIN_WIDTH_PX) return listOf(crop)

        val gray = OcrBitmapOps.toGray(OcrBitmapOps.toArgb(crop))
        val otsu = otsuThreshold(gray, w * h)
        val ink = IntArray(w)
        for (y in 0 until h) {
            val base = y * w
            for (x in 0 until w) {
                if (gray[base + x] < otsu) ink[x]++
            }
        }

        val runStart = IntArray(w)
        val runEnd = IntArray(w)
        var runs = 0
        var start = -1
        for (x in 0 until w) {
            if (ink[x] > 0) {
                if (start < 0) start = x
            } else if (start >= 0) {
                runStart[runs] = start
                runEnd[runs] = x - 1
                runs++
                start = -1
            }
        }
        if (start >= 0) {
            runStart[runs] = start
            runEnd[runs] = w - 1
            runs++
        }
        if (runs < 2) return listOf(crop)

        val gaps = IntArray(runs - 1)
        for (i in 0 until runs - 1) {
            gaps[i] = runStart[i + 1] - runEnd[i] - 1
        }
        val positives = IntArray(runs - 1)
        var posCount = 0
        for (g in gaps) {
            if (g > 0) positives[posCount++] = g
        }
        positives.sort(0, posCount)
        val median = if (posCount > 0) positives[posCount / 2].toFloat() else 1f
        val threshold = max(MIN_WORD_GAP_PX, roundHalfEven(median * WORD_GAP_FACTOR))

        val out = ArrayList<Bitmap>(4)
        var groupStart = runStart[0]
        var splits = 0
        for (i in 0 until runs - 1) {
            if (gaps[i] >= threshold) {
                addWordCrop(out, crop, w, h, groupStart, runEnd[i])
                groupStart = runStart[i + 1]
                splits++
            }
        }
        if (splits == 0) return listOf(crop)
        addWordCrop(out, crop, w, h, groupStart, runEnd[runs - 1])
        return out
    }

    /**
     * Щедрые поля: распознаватель теряет крайний глиф без левого контекста
     * (в заголовке пропадал «П» при отступе −4px).
     */
    private fun addWordCrop(
        out: MutableList<Bitmap>,
        crop: Bitmap,
        w: Int,
        h: Int,
        groupStart: Int,
        groupEnd: Int,
    ) {
        val left = max(0, groupStart - 10)
        val right = max(left + 1, min(w, groupEnd + 8))
        val width = (right - left).coerceIn(1, w - left)
        out.add(Bitmap.createBitmap(crop, left, 0, width, h))
    }

    private fun otsuThreshold(gray: IntArray, total: Int): Int {
        val hist = IntArray(256)
        for (v in gray) {
            if (v in 0..255) hist[v]++
        }
        var sumAll = 0.0
        for (v in 0 until 256) {
            sumAll += v.toDouble() * hist[v]
        }
        var sumB = 0.0
        var wB = 0
        var maxBetween = -1.0
        var otsu = 127
        for (v in 0 until 256) {
            wB += hist[v]
            if (wB == 0) continue
            val wF = total - wB
            if (wF == 0) break
            sumB += v.toDouble() * hist[v]
            val mB = sumB / wB
            val mF = (sumAll - sumB) / wF
            val between = wB.toDouble() * wF * (mB - mF) * (mB - mF)
            if (between > maxBetween) {
                maxBetween = between
                otsu = v
            }
        }
        return otsu
    }

    /** Python `round()` — округление к чётному, как в оригинале. */
    private fun roundHalfEven(v: Float): Int {
        val f = floor(v.toDouble())
        val diff = v - f
        val base = f.toInt()
        return when {
            diff > 0.5 -> base + 1
            diff < 0.5 -> base
            else -> if (base % 2 == 0) base else base + 1
        }
    }

    /**
     * Порт `_join_pieces`. У кусков щедрые поля, в них может попасть крайний
     * глиф соседа («и» + «иподелиться»). Дублирующийся префикс срезается, но
     * только когда остаток — известное слово, иначе легитимные повторы
     * («кот» + «торт») испортились бы до «кот орт».
     */
    private fun joinPieces(parts: List<String>): String {
        val out = ArrayList<String>(parts.size)
        for (raw in parts) {
            var p = raw.trim()
            if (p.isEmpty()) continue
            if (out.isNotEmpty() && !p.contains(' ') && startsWithCyrillic(p)) {
                val tail = canon(compactLetters(out[out.size - 1]).takeLast(8))
                val head = canon(p.take(8))
                var k = min(3, p.length)
                while (k > 0) {
                    if (!tail.endsWith(head.substring(0, k))) {
                        k--
                        continue
                    }
                    val rest = p.substring(k)
                    if (rest.isEmpty()) {
                        if (p.length == 1) p = ""
                        break
                    }
                    val core = stripNonCyrillic(rest)
                    if (GuardLexicon.isKnownCyrillic(core.lowercase())) p = rest
                    break
                }
                if (p.isEmpty()) continue
            }
            out.add(p)
        }
        return out.joinToString(" ").trim()
    }

    // ── СПАСЕНИЕ СКЛЕЕННЫХ СЛОВ ────────────────────────────

    /**
     * Порт `_rescue_narrow_gap`. Сплиттер не нашёл разрывов ≥5px, но мелкий UI-
     * текст прячет настоящий пробел в 3–4px («АлисуAI»). Только для низких
     * кропов (h<20: там межбуквенный зазор 1–2px, значит 3–4px — это пробел;
     * на размерах манги буквы расходятся на 3–4px и резать нельзя) и только
     * если обе половины дают непустой текст, отличный от целого, и не теряют
     * больше одной буквы.
     */
    private fun rescueNarrowGap(piece: Bitmap, whole: Recognition): Recognition? {
        val w = piece.width
        val h = piece.height
        if (h >= 20 || w <= 0) return null
        val tokens = whole.text.split(WHITESPACE).filter { it.isNotEmpty() }
        if (tokens.size != 1) return null
        val token = tokens[0]
        if (token.length < 6) return null
        if (GuardLexicon.isKnown(token.lowercase())) return null

        val gray = OcrBitmapOps.toGray(OcrBitmapOps.toArgb(piece))
        val col = IntArray(w)
        for (x in 0 until w) {
            var sum = 0
            val base = x
            for (y in 0 until h) {
                if (gray[y * w + base] < 128) sum++
            }
            col[x] = sum
        }
        val gapX = IntArray(w)
        val gapW = IntArray(w)
        var gaps = 0
        var x = 0
        while (x < w) {
            if (col[x] > 0) {
                x++
                continue
            }
            val start = x
            while (x < w && col[x] == 0) x++
            val gw = x - start
            if (gw in 3..4 && start > w * 0.15f && x < w * 0.85f) {
                gapX[gaps] = start
                gapW[gaps] = gw
                gaps++
            }
        }
        if (gaps == 0) return null

        val order = (0 until gaps).sortedByDescending { gapW[it] }
        val wholeAlpha = whole.text.count { it.isLetter() }
        for (gi in order) {
            val gx = gapX[gi]
            if (gx <= 0 || gx >= w) continue
            val rl = recognizeCrop(Bitmap.createBitmap(piece, 0, 0, gx, h))
            val rr = recognizeCrop(Bitmap.createBitmap(piece, gx, 0, w - gx, h))
            if (rl.text.isBlank() || rr.text.isBlank()) continue
            val joined = (rl.text.trim() + " " + rr.text.trim()).trim()
            if (joined == whole.text) continue
            // Подрезанные глифы исчезают — одну потерю буквы терпим.
            if (joined.count { it.isLetter() } < wholeAlpha - 1) continue
            return Recognition(
                text = joined,
                confidence = (rl.confidence + rr.confidence) / 2f,
                model = whole.model,
                coverage = max(rl.coverage, rr.coverage),
                nLat = rl.nLat + rr.nLat,
                nCyr = rl.nCyr + rr.nCyr,
            )
        }
        return null
    }

    // ── СКЛЕЙКА ОКОН ──────────────────────────────────────

    /**
     * Канонические омоглифы: кириллица/украинские look-alike приводятся к
     * базовой букве, чтобы ошибка в один символ (і/и, о/o, е/e) между окнами
     * не ломала склейку.
     */
    private fun canon(s: String): String {
        if (s.isEmpty()) return s
        val sb = StringBuilder(s.length)
        for (c in s) {
            val mapped = MERGE_CANON[c] ?: c
            sb.append(if (mapped.length == 1) mapped[0].lowercaseChar() else mapped)
        }
        return sb.toString()
    }

    /**
     * Порт `_merge_window_texts`. Окна перекрываются, поэтому дописывается
     * только неперекрытый хвост. Общий фрагмент ищется как наибольшая общая
     * ПОДСТРОКА хвоста и начала следующего окна (окно может обрезать крайний
     * глиф), в канонической форме омоглифов; склейка идёт исходными строками.
     */
    private fun mergeWindowTexts(texts: List<String>): String {
        if (texts.isEmpty()) return ""
        val sb = StringBuilder(texts[0])
        for (i in 1 until texts.size) {
            val nxt = texts[i]
            if (nxt.isEmpty()) continue
            if (sb.isEmpty()) {
                sb.append(nxt)
                continue
            }
            val merged = sb.toString()
            val tail = canon(merged.takeLast(48))
            val head = canon(nxt.take(48))
            var bestK = 0
            var bestL = 0
            val maxK = min(24, nxt.length)
            var k = 0
            while (k < maxK) {
                var len = min(nxt.length - k, tail.length)
                while (len > 3) {
                    if (len > bestL) {
                        val end = min(head.length, k + len)
                        val sub = if (k < end) head.substring(k, end) else ""
                        if (sub.isNotEmpty() && tail.contains(sub)) {
                            bestK = k
                            bestL = len
                            break
                        }
                    }
                    len--
                }
                if (bestL >= 8) break
                k++
            }
            sb.append(nxt, bestK + bestL, nxt.length)
        }
        return sb.toString()
    }

    // ── ОЦЕНКА КАНДИДАТОВ ──────────────────────────────────

    /**
     * Порт `_select_line_recognition`. Цельная строка получает бонус, если
     * очистка нашла в ней пропущенную границу слов (окно CTC проглотило пробел).
     */
    private fun selectLineRecognition(whole: Recognition, segmented: Recognition): Recognition {
        if (segmented.text.isBlank()) return whole
        if (whole.text.isBlank()) return segmented
        val restores = restoresWordBoundaries(whole.text)
        val wholeQuality =
            if (restores) candidateQuality(whole) + WHOLE_LINE_BOUNDARY_BONUS else candidateQuality(whole)
        val segmentedQuality = candidateQuality(segmented)
        if (restores && wholeQuality >= segmentedQuality) return whole
        return segmented
    }

    /**
     * Порт `_candidate_quality`. Confidence прибавляется, а не умножается:
     * у этих дистиллированных моделей пик вероятности ~0.016 даже на идеальном
     * входе, и при умножении мусор v3 обгонял бы чистую кириллицу v5.
     */
    private fun candidateQuality(rec: Recognition): Float {
        if (rec.text.isBlank()) return NEG_INF
        val fitness = cyrillicFitness(rec.text)
        val lengthBonus = min(rec.text.length * LENGTH_BONUS_PER_CHAR, MAX_LENGTH_BONUS)
        val verifierBonus = if (
            rec.model == MODEL_V5 && isAcceptableCyrillicText(rec.text)
        ) {
            VERIFIER_CYRILLIC_BONUS
        } else {
            0f
        }
        return fitness + lengthBonus + verifierBonus + rec.confidence
    }

    /** Порт `_coverage_penalty`. */
    private fun coveragePenalty(confidence: Float, coverage: Float): Float {
        if (coverage <= MIN_COVERAGE) return confidence
        val over = min(1f, (coverage - MIN_COVERAGE) / (1f - MIN_COVERAGE))
        return confidence * (1f - 0.40f * over)
    }

    /** Порт `cyrillic_fitness`: доля кириллицы среди букв, 0..1. */
    private fun cyrillicFitness(text: String): Float {
        var alpha = 0
        var cyr = 0
        for (c in text) {
            if (!c.isLetter()) continue
            alpha++
            val lower = c.lowercaseChar()
            if (lower in 'а'..'я' || c == 'ё' || c == 'Ё') cyr++
        }
        if (alpha == 0) return 0f
        return cyr.toFloat() / alpha
    }

    /** Порт `is_acceptable_cyrillic_text`. */
    private fun isAcceptableCyrillicText(text: String): Boolean {
        if (text.isEmpty()) return false
        for (word in text.split(WHITESPACE)) {
            val clean = word.trim(".,!?;:—–-")
            if (clean.isEmpty()) continue
            if (clean.all { isCyrillicLetter(it) }) continue
            if (clean.all { it in 'a'..'z' || it in 'A'..'Z' }) continue
            val hasCyr = clean.any { isCyrillicLetter(it) }
            val hasLat = clean.any { it in 'a'..'z' || it in 'A'..'Z' }
            if (hasCyr && hasLat) continue
            return false
        }
        return true
    }

    /**
     * Порт `_create_high_contrast`: обесцвечивание по luma, затем ×1.5 и −45
     * на канал (в оригинале — ColorMatrix setSaturation(0) + postConcat).
     */
    private fun createHighContrast(crop: Bitmap): Bitmap {
        val w = crop.width
        val h = crop.height
        val src = OcrBitmapOps.toArgb(crop)
        val out = IntArray(src.size)
        for (i in src.indices) {
            val p = src[i]
            val lum = (p ushr 16 and 0xFF) * 0.299f +
                (p ushr 8 and 0xFF) * 0.587f +
                (p and 0xFF) * 0.114f
            val v = clamp255(lum * HIGH_CONTRAST_GAIN + HIGH_CONTRAST_BIAS)
            out[i] = -0x1000000 or (v shl 16) or (v shl 8) or v
        }
        return Bitmap.createBitmap(out, w, h, Bitmap.Config.ARGB_8888)
    }

    // ── ПРОСТЫЕ ХЕЛПЕРЫ ────────────────────────────────────

    private fun parseDictionary(raw: String): List<String> {
        val body = if (raw.startsWith("﻿")) raw.substring(1) else raw
        val lines = body.split("\r\n", "\n", "\r")
        var end = lines.size
        while (end > 0 && lines[end - 1].isEmpty()) end--
        return if (end == 0) emptyList() else lines.subList(0, end)
    }

    /** Порт `_allowed`: алфавит декода = покрытие словаря. */
    private fun isAllowed(ch: String): Boolean {
        if (ch.length != 1) return false
        val c = ch[0]
        if (isCyrillicCode(c)) return true
        if (c.isWhitespace() || ALLOWED_PUNCTUATION.contains(c)) return true
        if (c in 'a'..'z' || c in 'A'..'Z' || c in '0'..'9') return true
        return false
    }

    private fun isCyrillicCode(c: Char): Boolean {
        val cp = c.code
        return (cp in 0x0400..0x052F) || (cp in 0xA640..0xA69F)
    }

    private fun isCyrillicLetter(c: Char): Boolean = c in 'а'..'я' || c == 'ё' || c == 'Ё'

    private fun isLatinLetter(c: Char): Boolean = c in 'a'..'z' || c in 'A'..'Z'

    private fun isLetterRun(s: String): Boolean = s.isNotEmpty() && s.all { isLetterRunChar(it) }

    private fun isLetterRunChar(c: Char): Boolean =
        isLatinLetter(c) || (c.code in 0x0400..0x052F) || (c.code in 0xA640..0xA69F)

    private fun compactLetters(s: String): String {
        val sb = StringBuilder(s.length)
        for (c in s) if (isLetterRunChar(c)) sb.append(c)
        return sb.toString()
    }

    /** Аналог `^[^A-Za-z]*[а-яА-ЯёЁ]`. */
    private fun startsWithCyrillic(s: String): Boolean {
        var i = 0
        while (i < s.length) {
            val c = s[i]
            if (isLatinLetter(c)) return false
            if (isCyrillicLetter(c)) return true
            i++
        }
        return false
    }

    /** Аналог `^[^а-яА-ЯёЁ]+|[^а-яА-ЯёЁ]+$`. */
    private fun stripNonCyrillic(s: String): String {
        var a = 0
        var b = s.length
        while (a < b && !isCyrillicLetter(s[a])) a++
        while (b > a && !isCyrillicLetter(s[b - 1])) b--
        return s.substring(a, b)
    }

    private fun clamp255(v: Float): Int {
        val i = (v + 0.5f).toInt()
        return if (i < 0) 0 else if (i > 255) 255 else i
    }

    /**
     * Часть `normalize_local_cyrillic_caption`, увеличивающая длину текста:
     * вставка границы на стыке длинных латинского и кириллического прогонов
     * и DP-сегментация слипшегося кириллического блока по известным словам.
     * Остальные шаги очистки длину не меняют, поэтому для решения
     * «восстанавливаются ли границы слов» достаточно этих двух.
     */
    private fun restoresWordBoundaries(text: String): Boolean {
        if (text.isEmpty()) return false
        val normalized = restoreKnownWords(insertScriptBoundaries(text))
        return normalized.length > text.length
    }

    /** Ветка fix_lookalikes_per_word, вставляющая пробел между алфавитами. */
    private fun insertScriptBoundaries(text: String): String {
        val sb = StringBuilder(text.length + 8)
        var i = 0
        while (i < text.length) {
            if (!isLetterRunChar(text[i])) {
                sb.append(text[i])
                i++
                continue
            }
            var end = i
            while (end < text.length && isLetterRunChar(text[end])) end++
            // Блок короче двух букв разные алфавиты не разделяем.
            if (end - i < 2) {
                sb.append(text, i, end)
            } else {
                var cut = i
                var p = i
                while (p < end) {
                    val latin = isLatinLetter(text[p])
                    var q = p
                    while (q < end && isLatinLetter(text[q]) == latin) q++
                    if (p > cut && q - p >= 2 && end - p >= 2) {
                        // p — начало текущего прогона, cut — конец предыдущего;
                        // оба прогона буквенные и длиной ≥ 2.
                        sb.append(text, cut, p).append(' ')
                        cut = p
                    }
                    p = q
                }
                sb.append(text, cut, end)
            }
            i = end
        }
        return sb.toString()
    }

    /** Порт `restore_known_words`: границы ставятся, только если все части известны. */
    private fun restoreKnownWords(text: String): String {
        val words = text.split(WHITESPACE)
        val out = ArrayList<String>(words.size)
        for (word in words) {
            if (word.length < 6 || !word.all { isCyrillicLetter(it) }) {
                out.add(word)
                continue
            }
            val low = word.lowercase()
            if (GuardLexicon.KNOWN.contains(low)) {
                out.add(word)
                continue
            }
            val split = dpSplitOnKnown(low)
            if (split == null || split.size <= 1) {
                out.add(word)
                continue
            }
            val sb = StringBuilder(word.length + split.size)
            var idx = 0
            for (length in split) {
                if (sb.isNotEmpty()) sb.append(' ')
                val slice = word.substring(idx, min(word.length, idx + length))
                val upper = slice.isNotEmpty() && slice.all { !it.isLetter() || it.isUpperCase() }
                val capital = slice.isNotEmpty() && slice[0].isUpperCase()
                val piece = low.substring(min(low.length, idx), min(low.length, idx + length))
                when {
                    upper -> sb.append(piece.uppercase())
                    capital -> sb.append(piece.replaceFirstChar { ch -> ch.uppercaseChar() })
                    else -> sb.append(piece)
                }
                idx += length
            }
            out.add(sb.toString())
        }
        return out.joinToString(" ")
    }

    /** Порт `_dp_split_on_known`. */
    private fun dpSplitOnKnown(word: String, maxWordLen: Int = 20): IntArray? {
        val n = word.length
        if (n == 0) return IntArray(0)
        if (n > 200) return null
        val dp = arrayOfNulls<IntArray>(n + 1)
        dp[0] = IntArray(0)
        for (i in 1..n) {
            val maxLen = min(maxWordLen, i)
            for (length in 1..maxLen) {
                val start = i - length
                val prev = dp[start] ?: continue
                if (!GuardLexicon.KNOWN.contains(word.substring(start, i))) continue
                val current = dp[i]
                val candidate = IntArray(prev.size + 1)
                System.arraycopy(prev, 0, candidate, 0, prev.size)
                candidate[prev.size] = length
                if (current == null || candidate.size < current.size) dp[i] = candidate
            }
        }
        return dp[n]
    }

    private companion object Extras {
        val EMPTY_CTC = CtcResult("", 0f, 0, 0f, 0, 0)

        /** `_MERGE_CANON` из tflite_ocr.py — только для сравнения перекрытий. */
        val MERGE_CANON: Map<Char, String> = mapOf(
            'а' to "a", 'с' to "c", 'е' to "e", 'о' to "o", 'р' to "p", 'х' to "x", 'у' to "y",
            'А' to "a", 'В' to "b", 'С' to "c", 'Е' to "e", 'Н' to "h", 'К' to "k", 'М' to "m",
            'О' to "o", 'Р' to "p", 'Т' to "t", 'Х' to "x", 'У' to "y",
            'і' to "i", 'І' to "i", 'ї' to "i", 'є' to "e", 'Є' to "e", 'ґ' to "g", 'Ґ' to "g",
            'ё' to "е", 'Ё' to "е",
        )
    }
}

/**
 * Лексикон-хранитель для [TfliteRecognizer].
 *
 * Десктоп берёт `_ru_valid_words()` / `_en_valid_words()` из
 * ocr_text_cleaner.py: это `_KNOWN_WORDS` + `_EN_TECH` + `_CONFUSION_SEEDS` плюс
 * слова, собранные из 5-МБ json-словарей. Распознаватель не имеет Context и не
 * должен зависеть от OcrTextCleaner, поэтому здесь перенесён «хардкодный» состав
 * словарей. Полный JSON-урожай живёт в модуле очистки текста; на консервативные
 * ветки (срезка «призрачного» глифа, спасение узкого разрыва) это влияет только
 * в сторону «ничего не резать».
 */
private object GuardLexicon {

    /** `_KNOWN_WORDS` из ocr_text_cleaner.py. */
    private val knownWords: Set<String> = setOf(
