package com.screenocr.tts.ocr

import android.graphics.Bitmap
import org.tensorflow.lite.Interpreter
import java.io.File
import java.nio.ByteBuffer
import java.nio.ByteOrder
import java.nio.FloatBuffer
import kotlin.math.exp
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min

/**
 * Порт CTC-распознавателя PP-OCR из tflite_ocr.py.
 *
 * Перенесены `_recognize_line_bitmap`, `_recognize_crop`, `_run_recognizer`,
 * `_infer_window`, `_decode_ctc`, `_split_words`, `_join_pieces`,
 * `_rescue_narrow_gap`, `_select_line_recognition`, `_candidate_quality`,
 * `_create_high_contrast`, `_merge_window_texts`.
 *
 * Вход модели — NHWC float32 [1, 48, 320, 3], серый фон 128, RGB→BGR,
 * нормализация (v/255 − 0.5) / 0.5 (та же, что в оригинале и в test_tflite.py).
 * Выход — сырые логиты [1, steps, num_classes]; softmax считается на лету.
 */
class TfliteRecognizer(
    modelFile: File,
    dictionary: String,
    private val recWidth: Int = 320,
    private val recHeight: Int = 48,
) {

    companion object {
        /** Ниже этого порога модель повторяет кроп в высококонтрастном виде. */
        const val CONTRAST_RETRY_CONFIDENCE = 0.90f

        const val MIN_COVERAGE = 0.12f
        const val VERIFIER_CYRILLIC_BONUS = 0.20f
        const val WHOLE_LINE_BOUNDARY_BONUS = 0.08f
        const val SPLIT_MIN_WIDTH_PX = 32
        const val MIN_WORD_GAP_PX = 5
        const val WORD_GAP_FACTOR = 1.7f
        const val LENGTH_BONUS_PER_CHAR = 0.01f
        const val MAX_LENGTH_BONUS = 0.12f

        /** ALLOWED_PUNCTUATION из tflite_ocr.py. */
        val ALLOWED_PUNCTUATION: Set<Char> = setOf(
            ' ', '.', ',', '!', '?', ';', ':', '-', '(', ')', '[', ']', '{', '}',
            '\\', '"', '\'', '«', '»', '„', '%', '№', '+', '/', '=', '…', '—', '–',
        )

        private const val MODEL_V3 = "v3"
        private const val MODEL_V5 = "v5"

        /** У v5 852 класса, у v3 — 165; порог достаточен для различения. */
        private const val V5_MIN_CLASSES = 512

        private const val REC_BACKGROUND = 128f
        private const val HIGH_CONTRAST_GAIN = 1.5f
        private const val HIGH_CONTRAST_BIAS = -45f

        /** Порог преобладания латиницы/кириллицы в CTC-шаге. */
        private const val SCRIPT_EVIDENCE_MIN = 0.008f
        private const val SCRIPT_EVIDENCE_MARGIN = 1.2f

        private val WHITESPACE = Regex("\\s+")
        private val NEG_INF = Float.NEGATIVE_INFINITY

        private val EMPTY_CTC = CtcResult("", 0f, 0, 0f, 0, 0)

        /** `_MERGE_CANON` из tflite_ocr.py — только для сравнения перекрытий. */
        private val MERGE_CANON: Map<Char, Char> = mapOf(
            'а' to 'a', 'с' to 'c', 'е' to 'e', 'о' to 'o', 'р' to 'p', 'х' to 'x', 'у' to 'y',
            'А' to 'a', 'В' to 'b', 'С' to 'c', 'Е' to 'e', 'Н' to 'h', 'К' to 'k', 'М' to 'm',
            'О' to 'o', 'Р' to 'p', 'Т' to 't', 'Х' to 'x', 'У' to 'y',
            'і' to 'i', 'І' to 'i', 'ї' to 'i', 'є' to 'e', 'Є' to 'e', 'ґ' to 'g', 'Ґ' to 'g',
            'ё' to 'е', 'Ё' to 'е',
        )
    }

    /** Кандидат-распознавание строки; [model] — тег «v3»/«v5». */
    private class Recognition(
        val text: String,
        val confidence: Float,
        val model: String,
        val coverage: Float,
        val nLat: Int = 0,
        val nCyr: Int = 0,
    )

    /** Результат жадного CTC-декода одного окна. */
    private class CtcResult(
        val text: String,
        val confidence: Float,
        val emitted: Int,
        val coverage: Float,
        val nLat: Int,
        val nCyr: Int,
    )

    private val interpreter: Interpreter =
        Interpreter(modelFile, Interpreter.Options().setNumThreads(1))

    private val modelInputShape: IntArray = interpreter.getInputTensor(0).shape()
    private val modelOutputShape: IntArray = interpreter.getOutputTensor(0).shape()

    /** Словарь символов: 1-я строка — пробел, символ класса i равен chars[i−1]. */
    private val chars: List<String> = parseDictionary(dictionary)
    private val numClasses: Int = if (modelOutputShape.size >= 3) modelOutputShape[2] else 0
    private val modelName: String = if (numClasses >= V5_MIN_CLASSES) MODEL_V5 else MODEL_V3

    // Классы вне словаря (164/165 у v3, 851/852 у v5) отбрасываются в декоде.
    private val classAllowed = BooleanArray(numClasses)
    private val isLatinClass = BooleanArray(numClasses)
    private val isCyrillicClass = BooleanArray(numClasses)
    private val classChar = Array(numClasses) { "" }

    private val inputValues = FloatArray(recWidth * recHeight * 3)
    private val inputBuffer: ByteBuffer =
        ByteBuffer.allocateDirect(inputValues.size * 4).order(ByteOrder.nativeOrder())
    private val outputValueCount: Int =
        modelOutputShape.fold(1) { acc, dim -> acc * max(1, dim) }
    private val outputValues = FloatArray(outputValueCount)
    private val outputBuffer: ByteBuffer =
        ByteBuffer.allocateDirect(outputValueCount * 4).order(ByteOrder.nativeOrder())
    private val inputView: FloatBuffer = inputBuffer.asFloatBuffer()
    private val outputView: FloatBuffer = outputBuffer.asFloatBuffer()

    init {
        require(recWidth > 0 && recHeight > 0) { "recognizer: некорректный размер входа" }
        require(modelInputShape.size == 4 && modelInputShape[1] == recHeight && modelInputShape[2] == recWidth) {
            "recognizer: ожидался вход NHWC [1,$recHeight,$recWidth,3], " +
                "получено ${modelInputShape.contentToString()}"
        }
        require(numClasses >= 2 && outputValueCount >= numClasses) {
            "recognizer: некорректный выход ${modelOutputShape.contentToString()}"
        }
        for (idx in 1 until numClasses) {
            val ch = chars.getOrNull(idx - 1)
            if (ch == null) continue
            classChar[idx] = ch
            if (!isAllowed(ch)) continue
            classAllowed[idx] = true
            if (ch.length == 1) {
                val c = ch[0]
                if (c in 'a'..'z' || c in 'A'..'Z') {
                    isLatinClass[idx] = true
                } else if (isCyrillicCode(c)) {
                    isCyrillicClass[idx] = true
                }
            }
        }
        interpreter.allocateTensors()
    }

    /**
     * Порт `_recognize_line_bitmap`: вернуть текст и confidence (0..1) для
     * одного бокса детектора.
     */
    @Synchronized
    fun recognizeLine(crop: Bitmap): Pair<String, Float> {
        if (crop.isRecycled || crop.width <= 0 || crop.height <= 0) return "" to 0f
        val best = recognizeLineBitmap(crop)
        return best.text to best.confidence
    }

    fun close() {
        interpreter.close()
    }

    // ── СТРОКА ─────────────────────────────────────────────

    /**
     * Кандидаты «вся строка» против «разрезанная по словам», выбор по quality.
     * При единственном куске дополнительно пробуем `_rescue_narrow_gap`.
     */
    private fun recognizeLineBitmap(crop: Bitmap): Recognition {
        val words = splitWords(crop)
        val wholeLine = recognizeCrop(crop)
        if (words.size == 1) {
            return rescueNarrowGap(words[0], wholeLine) ?: wholeLine
        }
        val parts = ArrayList<String>(words.size)
        var confSum = 0f
        var count = 0
        for (wordImg in words) {
            val r = recognizeCrop(wordImg)
            if (r.text.isNotBlank()) {
                confSum += r.confidence
                count++
                parts.add(r.text)
            }
        }
        val segmented = Recognition(
            text = joinPieces(parts),
            confidence = if (count > 0) confSum / count else 0f,
            model = wholeLine.model,
            coverage = wholeLine.coverage,
        )
