/**
 * Порт `_recognize_crop`: базовый проход плюс high-contrast повтор при
 * низкой уверенности, лучший кандидат — по quality.
 */
private fun recognizeCrop(crop: Bitmap): Recognition {
    var best = runRecognizer(crop)
    if (best.confidence < CONTRAST_RETRY_CONFIDENCE) {
        val retry = runRecognizer(createHighContrast(crop))
        if (candidateQuality(retry) > candidateQuality(best)) best = retry
    }
    return best
}

