private fun otsuThreshold(gray: IntArray, total: Int): Int {
    val hist = IntArray(256)
    for (v in gray) {
        if (v in 0..255) hist[v]++
    }
    var sumAll = 0.0
    for (v in 0 until 256) {
        sumAll += v.toDouble() * hist[v]
    }
    var sumB = 0.0
    var wB = 0
    var maxBetween = -1.0
    var otsu = 127
    for (v in 0 until 256) {
        wB += hist[v]
        if (wB == 0) continue
        val wF = total - wB
        if (wF == 0) break
        sumB += v.toDouble() * hist[v]
        val mB = sumB / wB
        val mF = (sumAll - sumB) / wF
        val between = wB.toDouble() * wF * (mB - mF) * (mB - mF)
        if (between > maxBetween) {
            maxBetween = between
            otsu = v
        }
    }
    return otsu
}

/** Python `round()` — округление к чётному, как в оригинале. */
private fun roundHalfEven(v: Float): Int {
    val f = floor(v.toDouble())
    val diff = v - f
    val base = f.toInt()
    return when {
        diff > 0.5 -> base + 1
        diff < 0.5 -> base
        else -> if (base % 2 == 0) base else base + 1
    }
}

/**
 * Порт `_join_pieces`. У кусков щедрые поля, в них может попасть крайний
 * глиф соседа («и» + «иподелиться»). Дублирующийся префикс срезается, но
 * только когда остаток — известное слово, иначе легитимные повторы
 * («кот» + «торт») испортились бы до «кот орт».
 */
private fun joinPieces(parts: List<String>): String {
    val out = ArrayList<String>(parts.size)
    for (raw in parts) {
        var p = raw.trim()
        if (p.isEmpty()) continue
        if (out.isNotEmpty() && !p.contains(' ') && startsWithCyrillic(p)) {
            val tail = canon(compactLetters(out[out.size - 1]).takeLast(8))
            val head = canon(p.take(8))
            var k = min(3, p.length)
            while (k > 0) {
                if (!tail.endsWith(head.substring(0, k))) {
                    k--
                    continue
                }
                val rest = p.substring(k)
                if (rest.isEmpty()) {
                    if (p.length == 1) p = ""
                    break
                }
                val core = stripNonCyrillic(rest)
                if (GuardLexicon.RU.contains(core.lowercase())) p = rest
                break
            }
            if (p.isEmpty()) continue
        }
        out.add(p)
    }
    return out.joinToString(" ").trim()
}

// ── СПАСЕНИЕ СКЛЕЕННЫХ СЛОВ ────────────────────────────

/**
 * Порт `_rescue_narrow_gap`. Сплиттер не нашёл разрывов ≥5px, но мелкий UI-
 * текст прячет настоящий пробел в 3–4px («АлисуAI»). Только для низких
 * кропов (h<20: там межбуквенный зазор 1–2px, значит 3–4px — это пробел;
 * на размерах манги буквы расходятся на 3–4px и резать нельзя) и только
 * если обе половины дают непустой текст, отличный от целого, и не теряют
 * больше одной буквы.
 */
private fun rescueNarrowGap(piece: Bitmap, whole: Recognition): Recognition? {
    val w = piece.width
    val h = piece.height
    if (h >= 20 || w <= 0) return null
    val tokens = whole.text.split(WHITESPACE).filter { it.isNotEmpty() }
    if (tokens.size != 1) return null
    val token = tokens[0]
    if (token.length < 6) return null
    if (GuardLexicon.GUARD.contains(token.lowercase())) return null

    val gray = OcrBitmapOps.toGray(OcrBitmapOps.toArgb(piece))
    val col = IntArray(w)
    for (x in 0 until w) {
        var sum = 0
        val base = x
        for (y in 0 until h) {
            if (gray[y * w + base] < 128) sum++
        }
        col[x] = sum
    }
    val gapX = IntArray(w)
    val gapW = IntArray(w)
    var gaps = 0
    var x = 0
    while (x < w) {
        if (col[x] > 0) {
            x++
            continue
        }
        val start = x
        while (x < w && col[x] == 0) x++
        val gw = x - start
        if (gw in 3..4 && start > w * 0.15f && x < w * 0.85f) {
            gapX[gaps] = start
            gapW[gaps] = gw
            gaps++
        }
    }
    if (gaps == 0) return null

    val order = (0 until gaps).sortedByDescending { gapW[it] }
    val wholeAlpha = whole.text.count { it.isLetter() }
    for (gi in order) {
        val gx = gapX[gi]
        if (gx <= 0 || gx >= w) continue
        val rl = recognizeCrop(Bitmap.createBitmap(piece, 0, 0, gx, h))
        val rr = recognizeCrop(Bitmap.createBitmap(piece, gx, 0, w - gx, h))
        if (rl.text.isBlank() || rr.text.isBlank()) continue
        val joined = (rl.text.trim() + " " + rr.text.trim()).trim()
        if (joined == whole.text) continue
        // Подрезанные глифы исчезают — одну потерю буквы терпим.
        if (joined.count { it.isLetter() } < wholeAlpha - 1) continue
        return Recognition(
            text = joined,
            confidence = (rl.confidence + rr.confidence) / 2f,
            model = whole.model,
            coverage = max(rl.coverage, rr.coverage),
            nLat = rl.nLat + rr.nLat,
            nCyr = rl.nCyr + rr.nCyr,
        )
    }
    return null
}

// ── СКЛЕЙКА ОКОН ──────────────────────────────────────

/**
 * Канонические омоглифы: кириллица/украинские look-alike приводятся к
 * базовой букве, чтобы ошибка в один символ (і/и, о/o, е/e) между окнами
 * не ломала склейку.
 */
private fun canon(s: String): String {
    if (s.isEmpty()) return s
    val sb = StringBuilder(s.length)
    for (c in s) {
        sb.append((MERGE_CANON[c] ?: c).lowercaseChar())
    }
    return sb.toString()
}

/**
 * Порт `_merge_window_texts`. Окна перекрываются, поэтому дописывается
 * только неперекрытый хвост. Общий фрагмент ищется как наибольшая общая
 * ПОДСТРОКА хвоста и начала следующего окна (окно может обрезать крайний
 * глиф), в канонической форме омоглифов; склейка идёт исходными строками.
 */
private fun mergeWindowTexts(texts: List<String>): String {
    if (texts.isEmpty()) return ""
    val sb = StringBuilder(texts[0])
    for (i in 1 until texts.size) {
        val nxt = texts[i]
        if (nxt.isEmpty()) continue
        if (sb.isEmpty()) {
            sb.append(nxt)
            continue
        }
        val merged = sb.toString()
        val tail = canon(merged.takeLast(48))
        val head = canon(nxt.take(48))
        var bestK = 0
        var bestL = 0
        val maxK = min(24, nxt.length)
        var k = 0
        while (k < maxK) {
            var len = min(nxt.length - k, tail.length)
            while (len > 3) {
                if (len > bestL) {
                    val end = min(head.length, k + len)
                    val sub = if (k < end) head.substring(k, end) else ""
                    if (sub.isNotEmpty() && tail.contains(sub)) {
                        bestK = k
                        bestL = len
                        break
                    }
                }
                len--
            }
            if (bestL >= 8) break
            k++
        }
        sb.append(nxt, bestK + bestL, nxt.length)
    }
    return sb.toString()
}

