/**
 * Порт `_select_line_recognition`. Цельная строка получает бонус, если
 * очистка нашла в ней пропущенную границу слов (окно CTC проглотило пробел).
 */
private fun selectLineRecognition(whole: Recognition, segmented: Recognition): Recognition {
    if (segmented.text.isBlank()) return whole
    if (whole.text.isBlank()) return segmented
    val restores = restoresWordBoundaries(whole.text)
    val wholeQuality =
        if (restores) candidateQuality(whole) + WHOLE_LINE_BOUNDARY_BONUS else candidateQuality(whole)
    val segmentedQuality = candidateQuality(segmented)
    if (restores && wholeQuality >= segmentedQuality) return whole
    return segmented
}

/**
 * Порт `_candidate_quality`. Confidence прибавляется, а не умножается:
 * у этих дистиллированных моделей пик вероятности ~0.016 даже на идеальном
 * входе, и при умножении мусор v3 обгонял бы чистую кириллицу v5.
 */
private fun candidateQuality(rec: Recognition): Float {
    if (rec.text.isBlank()) return NEG_INF
    val fitness = cyrillicFitness(rec.text)
    val lengthBonus = min(rec.text.length * LENGTH_BONUS_PER_CHAR, MAX_LENGTH_BONUS)
    val verifierBonus = if (
        rec.model == MODEL_V5 && isAcceptableCyrillicText(rec.text)
    ) {
        VERIFIER_CYRILLIC_BONUS
    } else {
        0f
    }
    return fitness + lengthBonus + verifierBonus + rec.confidence
}

/** Порт `_coverage_penalty`. */
private fun coveragePenalty(confidence: Float, coverage: Float): Float {
    if (coverage <= MIN_COVERAGE) return confidence
    val over = min(1f, (coverage - MIN_COVERAGE) / (1f - MIN_COVERAGE))
    return confidence * (1f - 0.40f * over)
}

/** Порт `cyrillic_fitness`: доля кириллицы среди букв, 0..1. */
private fun cyrillicFitness(text: String): Float {
    var alpha = 0
    var cyr = 0
    for (c in text) {
        if (!c.isLetter()) continue
        alpha++
        val lower = c.lowercaseChar()
        if (lower in 'а'..'я' || c == 'ё' || c == 'Ё') cyr++
    }
    if (alpha == 0) return 0f
    return cyr.toFloat() / alpha
}

/** Порт `is_acceptable_cyrillic_text`. */
private fun isAcceptableCyrillicText(text: String): Boolean {
    if (text.isEmpty()) return false
    for (word in text.split(WHITESPACE)) {
        val clean = word.trim(".,!?;:—–-")
        if (clean.isEmpty()) continue
        if (clean.all { isCyrillicLetter(it) }) continue
        if (clean.all { it in 'a'..'z' || it in 'A'..'Z' }) continue
        val hasCyr = clean.any { isCyrillicLetter(it) }
        val hasLat = clean.any { it in 'a'..'z' || it in 'A'..'Z' }
        if (hasCyr && hasLat) continue
        return false
    }
    return true
}

