    /** Порт `_allowed`: алфавит декода = покрытие словаря. */
    private fun isAllowed(ch: String): Boolean {
        if (ch.length != 1) return false
        val c = ch[0]
        if (isCyrillicCode(c)) return true
        if (c.isWhitespace() || ALLOWED_PUNCTUATION.contains(c)) return true
        if (c in 'a'..'z' || c in 'A'..'Z' || c in '0'..'9') return true
        return false
    }

    private fun isCyrillicCode(c: Char): Boolean {
        val cp = c.code
        return (cp in 0x0400..0x052F) || (cp in 0xA640..0xA69F)
    }

    private fun isCyrillicLetter(c: Char): Boolean = c in 'а'..'я' || c == 'ё' || c == 'Ё'

    private fun isLatinLetter(c: Char): Boolean = c in 'a'..'z' || c in 'A'..'Z'

    private fun isLetterRun(s: String): Boolean = s.isNotEmpty() && s.all { isLetterRunChar(it) }

    private fun isLetterRunChar(c: Char): Boolean =
        isLatinLetter(c) || (c.code in 0x0400..0x052F) || (c.code in 0xA640..0xA69F)

    private fun compactLetters(s: String): String {
        val sb = StringBuilder(s.length)
        for (c in s) if (isLetterRunChar(c)) sb.append(c)
        return sb.toString()
    }

    /** Аналог `^[^A-Za-z]*[а-яА-ЯёЁ]`. */
    private fun startsWithCyrillic(s: String): Boolean {
        var i = 0
        while (i < s.length) {
            val c = s[i]
            if (isLatinLetter(c)) return false
            if (isCyrillicLetter(c)) return true
            i++
        }
        return false
    }

    /** Аналог `^[^а-яА-ЯёЁ]+|[^а-яА-ЯёЁ]+$`. */
    private fun stripNonCyrillic(s: String): String {
        var a = 0
        var b = s.length
        while (a < b && !isCyrillicLetter(s[a])) a++
        while (b > a && !isCyrillicLetter(s[b - 1])) b--
        return s.substring(a, b)
    }

    private fun clamp255(v: Float): Int {
        val i = (v + 0.5f).toInt()
        return if (i < 0) 0 else if (i > 255) 255 else i
    }

    /**
     * Часть `normalize_local_cyrillic_caption`, увеличивающая длину текста:
     * вставка границы на стыке длинных латинского и кириллического прогонов
     * и DP-сегментация слипшегося кириллического блока по известным словам.
     * Остальные шаги очистки длину не меняют, поэтому для решения
     * «восстанавливаются ли границы слов» достаточно этих двух.
     */
    private fun restoresWordBoundaries(text: String): Boolean {
        if (text.isEmpty()) return false
        val normalized = restoreKnownWords(insertScriptBoundaries(text))
        return normalized.length > text.length
    }

    /** Ветка fix_lookalikes_per_word, вставляющая пробел между алфавитами. */
    private fun insertScriptBoundaries(text: String): String {
        val sb = StringBuilder(text.length + 8)
        var i = 0
        while (i < text.length) {
            if (!isLetterRunChar(text[i])) {
                sb.append(text[i])
                i++
                continue
            }
            var end = i
            while (end < text.length && isLetterRunChar(text[end])) end++
            // Блок короче двух букв разные алфавиты не разделяем.
            if (end - i < 2) {
                sb.append(text, i, end)
            } else {
                var cut = i
                var p = i
                var prevLen = 0
                var prevLatin = false
                while (p < end) {
                    val latin = isLatinLetter(text[p])
                    var q = p
                    while (q < end && isLatinLetter(text[q]) == latin) q++
                    val len = q - p
                    // Пробел только на границе двух длинных прогонов разных алфавитов.
                    if (p > cut && prevLen >= 2 && len >= 2 && prevLatin != latin) {
                        sb.append(text, cut, p).append(' ')
                        cut = p
                    }
                    prevLen = len
                    prevLatin = latin
                    p = q
                }
                sb.append(text, cut, end)
            }
            i = end
        }
        return sb.toString()
    }

    /** Порт `restore_known_words`: границы ставятся, только если все части известны. */
    private fun restoreKnownWords(text: String): String {
        val words = text.split(WHITESPACE)
        val out = ArrayList<String>(words.size)
        for (word in words) {
            if (word.length < 6 || !word.all { isCyrillicLetter(it) }) {
                out.add(word)
                continue
            }
            val low = word.lowercase()
            if (GuardLexicon.CAPTION.contains(low)) {
                out.add(word)
                continue
            }
            val split = dpSplitOnKnown(low)
            if (split == null || split.size <= 1) {
                out.add(word)
                continue
            }
            val sb = StringBuilder(word.length + split.size)
            var idx = 0
            for (length in split) {
                if (sb.isNotEmpty()) sb.append(' ')
                val slice = word.substring(idx, min(word.length, idx + length))
                val upper = slice.isNotEmpty() && slice.all { !it.isLetter() || it.isUpperCase() }
                val capital = slice.isNotEmpty() && slice[0].isUpperCase()
                val piece = low.substring(min(low.length, idx), min(low.length, idx + length))
                when {
                    upper -> sb.append(piece.uppercase())
                    capital -> sb.append(piece.replaceFirstChar { ch -> ch.uppercaseChar() })
                    else -> sb.append(piece)
                }
                idx += length
            }
            out.add(sb.toString())
        }
        return out.joinToString(" ")
    }

    /** Порт `_dp_split_on_known`. */
    private fun dpSplitOnKnown(word: String, maxWordLen: Int = 20): IntArray? {
        val n = word.length
        if (n == 0) return IntArray(0)
        if (n > 200) return null
        val dp = arrayOfNulls<IntArray>(n + 1)
        dp[0] = IntArray(0)
        for (i in 1..n) {
            val maxLen = min(maxWordLen, i)
            for (length in 1..maxLen) {
                val start = i - length
                val prev = dp[start] ?: continue
                if (!GuardLexicon.CAPTION.contains(word.substring(start, i))) continue
                val current = dp[i]
                val candidate = IntArray(prev.size + 1)
                System.arraycopy(prev, 0, candidate, 0, prev.size)
                candidate[prev.size] = length
                if (current == null || candidate.size < current.size) dp[i] = candidate
            }
        }
        return dp[n]
    }
}

