"""Сверка портированных строковых алгоритмов с оригиналом tflite_ocr.py."""
import random
import re
import sys

sys.path.insert(0, '/home/runner/hub-work/ScreenOCR_TTS/code')

# ── оригинал ────────────────────────────────────────────────
_MERGE_CANON = {
    'а': 'a', 'с': 'c', 'е': 'e', 'о': 'o', 'р': 'p', 'х': 'x', 'у': 'y',
    'А': 'a', 'В': 'b', 'С': 'c', 'Е': 'e', 'Н': 'h', 'К': 'k', 'М': 'm',
    'О': 'o', 'Р': 'p', 'Т': 't', 'Х': 'x', 'У': 'y',
    'і': 'i', 'І': 'i', 'ї': 'i', 'є': 'e', 'Є': 'e', 'ґ': 'g', 'Ґ': 'g',
    'ё': 'е', 'Ё': 'е',
}


def canon(s):
    return ''.join(_MERGE_CANON.get(c, c).lower() for c in s)


def merge_window_texts(texts):
    merged = texts[0] if texts else ""
    for nxt in texts[1:]:
        if not nxt:
            continue
        if not merged:
            merged = nxt
            continue
        tail = canon(merged[-48:])
        head = canon(nxt[:48])
        best_k, best_L = 0, 0
        for k in range(0, min(24, len(nxt))):
            maxL = min(len(nxt) - k, len(tail))
            for L in range(maxL, 3, -1):
                if L > best_L and head[k:k + L] in tail:
                    best_k, best_L = k, L
                    break
            if best_L >= 8:
                break
        merged += nxt[best_k + best_L:]
    return merged


def join_pieces(parts, valid):
    out = []
    for part in parts:
        p = part.strip()
        if not p:
            continue
        if out and " " not in p and re.match(r"^[^A-Za-z]*[а-яА-ЯёЁ]", p):
            tail = canon(out[-1].replace(" ", "")[-8:])
            head = canon(p[:8])
            for k in range(min(3, len(p)), 0, -1):
                if not tail.endswith(head[:k]):
                    continue
                rest = p[k:]
                if not rest:
                    if len(p) == 1:
                        p = ""
                    break
                core = re.sub(r"^[^а-яА-ЯёЁ]+|[^а-яА-ЯёЁ]+$", "", rest)
                if core.lower() in valid:
                    p = rest
                break
            if not p:
                continue
        out.append(p)
    return " ".join(out).strip()


def starts_with_cyrillic(s):
    i = 0
    while i < len(s):
        c = s[i]
        if c.isascii() and c.isalpha():
            return False
        if ('а' <= c <= 'я') or c in 'ёЁ':
            return True
        i += 1
    return False


def strip_non_cyrillic(s):
    a = 0
    b = len(s)
    while a < b and not (('а' <= s[a] <= 'я') or s[a] in 'ёЁ'):
        a += 1
    while b > a and not (('а' <= s[b - 1] <= 'я') or s[b - 1] in 'ёЁ'):
        b -= 1
    return s[a:b]


def compact_letters(s):
    return ''.join(c for c in s if c.isascii() and c.isalpha() or 'Ѐ' <= c <= 'ԯ')


# ── порт моего Kotlin (дословно) ────────────────────────────
def k_merge_window_texts(texts):
    if not texts:
        return ""
    sb = texts[0]
    for i in range(1, len(texts)):
        nxt = texts[i]
        if not nxt:
            continue
        if not sb:
            sb += nxt
            continue
        tail = canon(sb[-48:])
        head = canon(nxt[:48])
        best_k = 0
        best_L = 0
        max_k = min(24, len(nxt))
        k = 0
        while k < max_k:
            ln = min(len(nxt) - k, len(tail))
            while ln > 3:
                if ln > best_L:
                    end = min(len(head), k + ln)
                    sub = head[k:end] if k < end else ""
                    if sub and sub in tail:
                        best_k, best_L = k, ln
                        break
                ln -= 1
            if best_L >= 8:
                break
            k += 1
        sb += nxt[best_k + best_L:]
    return sb


def k_join_pieces(parts, valid):
    out = []
    for raw in parts:
        p = raw.strip()
        if not p:
            continue
        if out and " " not in p and starts_with_cyrillic(p):
            tail = canon(compact_letters(out[-1])[-8:])
            head = canon(p[:8])
            k = min(3, len(p))
            while k > 0:
                if not tail.endswith(head[:k]):
                    k -= 1
                    continue
                rest = p[k:]
                if not rest:
                    if len(p) == 1:
                        p = ""
                    break
                core = strip_non_cyrillic(rest)
                if core.lower() in valid:
                    p = rest
                break
            if not p:
                continue
        out.append(p)
    return " ".join(out).strip()


VALID = {'поделиться', 'содержимое', 'кот', 'торт', 'народ', 'и', 'объект'}

ALPHABET = 'абвгдеёжзийклмнопрстуфхцчшщъыьэюяАБВГДЕЁЖЗИЙКЛМНОП ' + \
           'abcdeopxyABCEHKMOPTXY' + '.,!?-'

random.seed(7)
bad = 0
for _ in range(20000):
    n = random.randint(1, 4)
    texts = []
    for _ in range(n):
        ln = random.randint(0, 30)
        texts.append(''.join(random.choice(ALPHABET) for _ in range(ln)).strip())
    a = merge_window_texts(texts)
    b = k_merge_window_texts(texts)
    if a != b:
        bad += 1
        if bad < 4:
            print('MERGE MISMATCH', repr(texts), repr(a), repr(b))

for _ in range(20000):
    parts = []
    for _ in range(random.randint(1, 4)):
        ln = random.randint(0, 14)
        parts.append(''.join(random.choice(ALPHABET) for _ in range(ln)))
    a = join_pieces(parts, VALID)
    b = k_join_pieces(parts, VALID)
    if a != b:
        bad += 1
        if bad < 8:
            print('JOIN MISMATCH', repr(parts), repr(a), repr(b))

print('mismatches:', bad)

