"""Сверка _split_words (Otsu + проекция) и _decode_ctc с портом."""
import math
import random
import sys

# ── оригинал (tflite_ocr.py), переписанный на 2D-массив серого ──
SPLIT_MIN_WIDTH_PX = 32
MIN_WORD_GAP_PX = 5
WORD_GAP_FACTOR = 1.7
ALLOWED_PUNCTUATION = set(' .,!?;:-()[]{}\\"\'«»„""%№+/=…—–')
DETECTOR_THRESHOLD = 0.20


def orig_split_words(gray, w, h):
    if w < SPLIT_MIN_WIDTH_PX:
        return None
    hist = [0] * 256
    for v in gray:
        hist[v] += 1
    total = w * h
    sum_all = sum(v * hist[v] for v in range(256))
    sum_b = 0.0
    w_b = 0
    max_between = -1.0
    otsu = 127
    for v in range(256):
        w_b += hist[v]
        if w_b == 0:
            continue
        w_f = total - w_b
        if w_f == 0:
            break
        sum_b += v * hist[v]
        m_b = sum_b / w_b
        m_f = (sum_all - sum_b) / w_f
        between = w_b * w_f * (m_b - m_f) ** 2
        if between > max_between:
            max_between = between
            otsu = v
    ink = [0] * w
    for y in range(h):
        for x in range(w):
            if gray[y * w + x] < otsu:
                ink[x] += 1
    runs = []
    start = -1
    for x in range(w):
        if ink[x] > 0:
            if start < 0:
                start = x
        elif start >= 0:
            runs.append((start, x - 1))
            start = -1
    if start >= 0:
        runs.append((start, w - 1))
    if len(runs) < 2:
        return ('single',)
    gaps = [runs[i + 1][0] - runs[i][1] - 1 for i in range(len(runs) - 1)]
    positive = sorted(g for g in gaps if g > 0)
    median = positive[len(positive) // 2] if positive else 1.0
    threshold = max(MIN_WORD_GAP_PX, round(median * WORD_GAP_FACTOR))
    groups = []
    group_start = runs[0][0]
    split_after = 0
    for i, gap in enumerate(gaps):
        if gap >= threshold:
            groups.append((group_start, runs[i][1]))
            group_start = runs[i + 1][0]
            split_after += 1
    if split_after == 0:
        return ('single', threshold)
    groups.append((group_start, runs[-1][1]))
    if len(groups) <= 1:
        return ('single',)
    out = []
    for g_start, g_end in groups:
        left = max(0, g_start - 10)
        right = min(w, g_end + 8)
        out.append((left, 0, max(left + 1, right), h))
    return (otsu, threshold) + tuple(out)


def orig_decode_ctc(values, chars, num_classes):
    if num_classes <= 1 or len(values) < num_classes:
        return ("", 0.0, 0, 0.0, 0, 0)
    is_lat = [False] * num_classes
    is_cyr = [False] * num_classes
    for idx in range(1, num_classes):
        if idx - 1 >= len(chars):
            continue
        ch = chars[idx - 1]
        if len(ch) == 1:
            if "a" <= ch <= "z" or "A" <= ch <= "Z":
                is_lat[idx] = True
            elif 0x0400 <= ord(ch) <= 0x052F or 0xA640 <= ord(ch) <= 0xA69F:
                is_cyr[idx] = True

    def allowed(ch):
        if len(ch) != 1:
            return False
        cp = ord(ch)
        if 0x0400 <= cp <= 0x052F or 0xA640 <= cp <= 0xA69F:
            return True
        if ch.isspace() or ch in ALLOWED_PUNCTUATION:
            return True
        if 'a' <= ch <= 'z' or 'A' <= ch <= 'Z' or '0' <= ch <= '9':
            return True
        return False

    steps = len(values) // num_classes
    parts = []
    prev = -1
    conf_sum = 0.0
    conf_count = 0
    blank_steps = 0
    counting_blanks = False
    n_lat = n_cyr = 0
    for step in range(steps):
        base = step * num_classes
        logits = values[base:base + num_classes]
        m = max(logits)
        ex = [math.exp(v - m) for v in logits]
        s = sum(ex)
        probs = [v / s for v in ex]
        best_idx = 0
        best_score = probs[0]
        best_lat = 0.0
        best_cyr = 0.0
        for idx in range(1, num_classes):
            ch = chars[idx - 1] if idx - 1 < len(chars) else ''
            if not allowed(ch):
                continue
            if probs[idx] > best_score:
                best_score = probs[idx]
                best_idx = idx
            if is_lat[idx] and probs[idx] > best_lat:
                best_lat = probs[idx]
            elif is_cyr[idx] and probs[idx] > best_cyr:
                best_cyr = probs[idx]
        if best_lat > 0.008 and best_lat > best_cyr * 1.2:
            n_lat += 1
        elif best_cyr > 0.008 and best_cyr > best_lat * 1.2:
            n_cyr += 1
        if best_idx != 0 and best_idx != prev:
            if best_idx - 1 < len(chars):
                parts.append(chars[best_idx - 1])
            conf_sum += best_score
            conf_count += 1
            counting_blanks = True
        elif best_idx == 0 and counting_blanks:
            blank_steps += 1
        prev = best_idx
    text = "".join(parts).strip()
    conf = conf_sum / conf_count if conf_count > 0 else 0.0
    cov = 0.0
    if conf_count > 0 and steps > 0:
        inner = steps - conf_count
        if inner > 0:
            cov = min(1.0, blank_steps) * (inner / steps)
    return (text, round(conf, 9), conf_count, round(cov, 9), n_lat, n_cyr)


# ── мой порт (дословная транслитерация Kotlin) ───────────────
def k_split_words(gray, w, h):
    if w < SPLIT_MIN_WIDTH_PX:
        return ('single',)
    hist = [0] * 256
    for v in gray:
        if 0 <= v <= 255:
            hist[v] += 1
    sum_all = 0.0
    for v in range(256):
        sum_all += v * hist[v]
    sum_b = 0.0
    w_b = 0
    max_between = -1.0
    otsu = 127
    for v in range(256):
        w_b += hist[v]
        if w_b == 0:
            continue
        w_f = w * h - w_b
        if w_f == 0:
            break
        sum_b += v * hist[v]
        m_b = sum_b / w_b
        m_f = (sum_all - sum_b) / w_f
        between = w_b * w_f * (m_b - m_f) * (m_b - m_f)
        if between > max_between:
            max_between = between
            otsu = v
    ink = [0] * w
    for y in range(h):
        base = y * w
        for x in range(w):
            if gray[base + x] < otsu:
                ink[x] += 1
    run_start = [0] * w
    run_end = [0] * w
    runs = 0
    start = -1
    for x in range(w):
        if ink[x] > 0:
            if start < 0:
                start = x
        elif start >= 0:
            run_start[runs] = start
            run_end[runs] = x - 1
            runs += 1
            start = -1
    if start >= 0:
        run_start[runs] = start
        run_end[runs] = w - 1
        runs += 1
    if runs < 2:
        return ('single',)
    gaps = [run_start[i + 1] - run_end[i] - 1 for i in range(runs - 1)]
    positives = sorted(g for g in gaps if g > 0)
    median = float(positives[len(positives) // 2]) if positives else 1.0
    v = median * WORD_GAP_FACTOR
    import math as _m
    f = _m.floor(v)
    diff = v - f
    if diff > 0.5:
        base = f + 1
    elif diff < 0.5:
        base = f
    else:
        base = f if int(f) % 2 == 0 else f + 1
    threshold = max(MIN_WORD_GAP_PX, base)
    out = []
    group_start = run_start[0]
    splits = 0
    for i in range(runs - 1):
        if gaps[i] >= threshold:
            left = max(0, group_start - 10)
            right = max(left + 1, min(w, run_end[i] + 8))
            width = max(1, min(w - left, right - left))
            out.append((left, 0, left + width, h))
            group_start = run_start[i + 1]
            splits += 1
    if splits == 0:
        return ('single', threshold)
    left = max(0, group_start - 10)
    right = max(left + 1, min(w, run_end[runs - 1] + 8))
    width = max(1, min(w - left, right - left))
    out.append((left, 0, left + width, h))
    return (otsu, threshold) + tuple(out)


def k_decode_ctc(values, chars, classes):
    if classes <= 1 or len(values) < classes:
        return ("", 0.0, 0, 0.0, 0, 0)
    class_allowed = [False] * classes
    is_lat = [False] * classes
    is_cyr = [False] * classes
    class_char = [""] * classes
    for idx in range(1, classes):
        ch = chars[idx - 1] if idx - 1 < len(chars) else None
        if ch is None:
