    steps = len(values) // classes
    parts = []
    prev = -1
    conf_sum = 0.0
    conf_count = 0
    blank_steps = 0
    counting_blanks = False
    n_lat = n_cyr = 0
    for step in range(steps):
        base = step * classes
        blank = values[base]
        max_logit = blank
        best_idx = 0
        best_logit = blank
        lat_logit = cyr_logit = float('-inf')
        lat_found = cyr_found = False
        for idx in range(1, classes):
            v = values[base + idx]
            if v > max_logit:
                max_logit = v
            if not class_allowed[idx]:
                continue
            if v > best_logit:
                best_logit = v
                best_idx = idx
            if is_lat[idx]:
                if not lat_found or v > lat_logit:
                    lat_logit = v
                    lat_found = True
            elif is_cyr[idx]:
                if not cyr_found or v > cyr_logit:
                    cyr_logit = v
                    cyr_found = True
        sum_exp = 0.0
        for idx in range(classes):
            sum_exp += math.exp(values[base + idx] - max_logit)
        inv = 1.0 / sum_exp if sum_exp > 0 else 0.0
        best_prob = math.exp(best_logit - max_logit) * inv
        lat_prob = math.exp(lat_logit - max_logit) * inv if lat_found else 0.0
        cyr_prob = math.exp(cyr_logit - max_logit) * inv if cyr_found else 0.0
        if lat_prob > 0.008 and lat_prob > cyr_prob * 1.2:
            n_lat += 1
        elif cyr_prob > 0.008 and cyr_prob > lat_prob * 1.2:
            n_cyr += 1
        if best_idx != 0 and best_idx != prev:
            if best_idx - 1 < len(chars):
                parts.append(class_char[best_idx])
            conf_sum += best_prob
            conf_count += 1
            counting_blanks = True
        elif best_idx == 0 and counting_blanks:
            blank_steps += 1
        prev = best_idx
    text = "".join(parts).strip()
    conf = conf_sum / conf_count if conf_count > 0 else 0.0
    cov = 0.0
    if conf_count > 0 and steps > 0:
        inner = steps - conf_count
        if inner > 0:
            cov = min(1.0, float(blank_steps)) * (inner / steps)
    return (text, round(conf, 9), conf_count, round(cov, 9), n_lat, n_cyr)


def k_allowed(ch):
    if len(ch) != 1:
        return False
    cp = ord(ch)
    if (0x0400 <= cp <= 0x052F) or (0xA640 <= cp <= 0xA69F):
        return True
