/**
 * Порт `_detect_text_boxes` + `_pad`.
 *
 * Кадр больше [size] дополнительно проходится четырьмя тайлами с
 * перекрытием [TILE_OVERLAP]; результаты всех проходов сливаются.
 * Если после слияния ничего не осталось — включается запасной
 * `_projection_boxes` по проекциям строк/столбцов.
 */
@Synchronized
fun detect(image: Bitmap): DetectionResult {
    if (image.isRecycled || image.width <= 0 || image.height <= 0) {
        return DetectionResult(emptyList(), probability)
    }
    val raw = ArrayList<Box>(64)
    runDetection(image, 0, 0, raw)

    if (max(image.width, image.height) > size) {
        val overX = (image.width * TILE_OVERLAP).toInt()
        val overY = (image.height * TILE_OVERLAP).toInt()
        val halfW = image.width / 2
        val halfH = image.height / 2
        val tiles = intArrayOf(
            0, 0, halfW + overX, halfH + overY,
            halfW - overX, 0, image.width, halfH + overY,
            0, halfH - overY, halfW + overX, image.height,
            halfW - overX, halfH - overY, image.width, image.height,
        )
        var t = 0
        while (t < tiles.size) {
            val x1 = max(0, tiles[t])
            val y1 = max(0, tiles[t + 1])
            val x2 = min(image.width, tiles[t + 2])
            val y2 = min(image.height, tiles[t + 3])
            t += 4
            if (x2 - x1 < MIN_TILE_SIDE || y2 - y1 < MIN_TILE_SIDE) continue
            runDetection(Bitmap.createBitmap(image, x1, y1, x2 - x1, y2 - y1), x1, y1, raw)
        }
    }

    val merged = mergeBoxes(raw)
    if (merged.isEmpty()) return DetectionResult(projectionBoxes(image), probability)
    val limited = if (merged.size > MAX_TEXT_BOXES) {
        merged.subList(0, MAX_TEXT_BOXES).toList()
    } else {
        merged
    }
    // Каждый бокс распознаётся отдельно, поля обязательны: без левого
    // контекста распознаватель теряет крайний глиф (заголовок «П»).
    return DetectionResult(limited.map { pad(it, image.width, image.height) }, probability)
}

fun close() {
    interpreter.close()
}

// ── ДЕТЕКЦИЯ ───────────────────────────────────────────

/** Порт `_run_detection`: масштаб в limitSide, infer, BFS по компонентам. */
private fun runDetection(source: Bitmap, offX: Int, offY: Int, out: MutableList<Box>) {
    val srcW = source.width
    val srcH = source.height
    if (srcW <= 0 || srcH <= 0 || source.isRecycled) return

    val scale = min(size.toFloat() / srcW, size.toFloat() / srcH)
    val scaledW = max(1, (srcW * scale).toInt())
    val scaledH = max(1, (srcH * scale).toInt())
    val offsetX = (size - scaledW) / 2
    val offsetY = (size - scaledH) / 2

    val resized = OcrBitmapOps.resample(
        OcrBitmapOps.toArgb(source), srcW, srcH, scaledW, scaledH,
    )
    if (!infer(resized, scaledW, scaledH, offsetX, offsetY)) return
    collectComponents(scale, offsetX, offsetY, srcW, srcH, offX, offY, out)
}

/**
 * Заливка входа и вызов интерпретатора.
 * Значение вне вставленного прямоугольника — белый фон, как в оригинале.
 */
private fun infer(px: IntArray, w: Int, h: Int, offsetX: Int, offsetY: Int): Boolean {
    val whiteB = (1f - MEAN_B) / STD_B
    val whiteG = (1f - MEAN_G) / STD_G
    val whiteR = (1f - MEAN_R) / STD_R
    val values = inputValues
    for (y in 0 until size) {
        val rowBase = y * size * 3
        val srcRow = y - offsetY
        val hasRow = srcRow in 0 until h
        val srcBase = if (hasRow) srcRow * w else 0
        for (x in 0 until size) {
            val i = rowBase + x * 3
            val srcCol = x - offsetX
            if (hasRow && srcCol in 0 until w) {
                val p = px[srcBase + srcCol]
                val b = (p and 0xFF) * INV_255
                val g = ((p ushr 8) and 0xFF) * INV_255
                val r = ((p ushr 16) and 0xFF) * INV_255
                values[i] = (b - MEAN_B) / STD_B
                values[i + 1] = (g - MEAN_G) / STD_G
                values[i + 2] = (r - MEAN_R) / STD_R
            } else {
                values[i] = whiteB
                values[i + 1] = whiteG
                values[i + 2] = whiteR
            }
        }
    }
    inputView.clear()
    inputView.put(values)
    inputBuffer.rewind()
    outputBuffer.rewind()
    interpreter.run(inputBuffer, outputBuffer)
    outputView.clear()
    outputView.get(probability, 0, size * size)
    return true
}

