fun dpSplitOnKnown(word: String, maxWordLen: Int = DEFAULT_MAX_WORD_LEN): List<String>? {
    val n = word.length
    if (n == 0) return emptyList()
    if (n > 200) return null
    val dp = arrayOfNulls<ArrayList<String>?>(n + 1)
    dp[0] = ArrayList(0)
    for (i in 1..n) {
        val startFrom = maxOf(1, i - maxWordLen)
        for (start in startFrom until i) {
            val prev = dp[start] ?: continue
            val candidate = word.substring(start, i)
            if (candidate in KNOWN_WORDS) {
                val newList = ArrayList(prev.size + 1)
                newList.addAll(prev)
                newList.add(candidate)
                val cur = dp[i]
                if (cur == null || newList.size < cur.size) dp[i] = newList
            }
        }
    }
    return dp[n]
}
```
