    private val LAT_CHAR_RE = rx("""[a-zA-Z]""")

    private val GARBAGE_WHITELIST: Set<Char> = ".,!?;:-'\"()—–…/ \n".toSet()
    private val STRIP_PUNCT: Set<Char> = ".,!?;:—–-".toSet()
    private val LEAD_PUNCT: Set<Char> = ".,!?:;»”’'\"…—–-".toSet()

    private const val DP_MAX_WORD_LEN = 20
    private const val DP_MAX_INPUT = 200

    // ═══════════════════════════════════════════════════════════
    // СЛОВАРИ (assets/dict)
    // ═══════════════════════════════════════════════════════════

    private const val DICT_ASSET = "dict/eng_rus_dict.json"

    private class DictData(
        val ruValid: Set<String>,
        val ruFreq: Map<String, Int>,
        val enValid: Set<String>,
    )

    @Volatile
    private var dictData: DictData? = null

    @Volatile
    private var appContext: Context? = null

    private val dictLock = Any()

    /**
     * Единственная точка, где модуль получает доступ к assets.
     * Вызывается из [com.screenocr.tts.App.onCreate]; хранит application-context,
     * поэтому утечки Activity не возникает.
     */
    @JvmStatic
    fun attach(context: Context) {
        appContext = context.applicationContext
    }

    /** Словари уже разобраны (для диагностики). */
    @JvmStatic
    fun dictionariesLoaded(): Boolean = dictData != null

    /**
     * Словарь валидации кириллицы: KNOWN_WORDS + сиды + кириллические токены
     * переводов из harvest-словаря. Считается один раз, дальше отдаётся кеш.
     */
    @JvmStatic
    fun ruValidWords(): Set<String> = ensureDict().ruValid

    /** Английский лексикон: ключи harvest-словаря + технические аббревиатуры. */
    @JvmStatic
    fun enValidWords(): Set<String> = ensureDict().enValid

    /** Частотность слова в harvest-словаре (0 — не встречается). */
    @JvmStatic
    fun ruWordFreq(word: String): Int = ensureDict().ruFreq[word] ?: 0

    private fun ensureDict(): DictData {
        dictData?.let { return it }
        synchronized(dictLock) {
            dictData?.let { return it }
            val ctx = appContext
            val built = try {
                buildDict(ctx)
            } catch (e: Throwable) {
                // OOM на 5 МБ JSON не должно ронять распознавание:
                // деградируем до слов-сидов, как при отсутствии файла в Python.
                Log.w(TAG, "[Cleaner] dictionaries not loaded: ${e.message}")
                buildDict(null)
            }
            dictData = built
            return built
        }
    }

    private fun buildDict(context: Context?): DictData {
        val freq = HashMap<String, Int>(1 shl 18)
        for (w in CONFUSION_SEEDS) bumpFreq(freq, w, 5)
        for (w in KNOWN_WORDS) bumpFreq(freq, w.lowercase(), 5)

        val enValid = HashSet<String>(1 shl 16)
        enValid.addAll(EN_TECH)

        if (context != null) {
            val json = try {
                context.assets.open(DICT_ASSET).use { input ->
                    InputStreamReader(input, Charsets.UTF_8).use { JSONObject(it) }
                }
            } catch (e: Exception) {
                Log.w(TAG, "[Cleaner] RU validation dict not loaded: ${e.message}")
                null
            }
            if (json != null) harvest(json, freq, enValid)
        }

        Log.i(TAG, "[Cleaner] RU validation dict: ${freq.size} words")
        Log.i(TAG, "[Cleaner] EN validation dict: ${enValid.size} words")
        return DictData(Collections.unmodifiableSet(freq), freq, enValid)
    }

    private fun harvest(json: JSONObject, freq: HashMap<String, Int>, enValid: HashSet<String>) {
        val keys = json.keys()
        while (keys.hasNext()) {
            val key = keys.next()
            forEachLatToken(key) { enValid.add(it) }
            when (val value = json.opt(key)) {
                is String -> forEachCyrToken(value) { bumpFreq(freq, it, 1) }
                is JSONArray -> {
                    val n = value.length()
                    for (i in 0 until n) {
                        val item = value.opt(i)
                        if (item is String) forEachCyrToken(item) { bumpFreq(freq, it, 1) }
                    }
                }
                else -> Unit
            }
        }
    }

    private fun bumpFreq(freq: HashMap<String, Int>, word: String, delta: Int) {
        val old = freq[word]
        freq[word] = (old ?: 0) + delta
    }

    /**
     * Кириллические токены длиной 2+ (аналог `re.findall(r"[а-яё]{2,}", s.lower())`).
     * Регистр не сворачиваем заранее: `lowercase()` не меняет границы прогонов,
     * поэтому результат идентичен, а 5 МБ текста не пересоздаются.
     */
    private inline fun forEachCyrToken(s: String, sink: (String) -> Unit) {
        var i = 0
        while (i < s.length) {
            if (!isCyrTokenChar(s[i])) {
                i++
                continue
            }
            val start = i
            while (i < s.length && isCyrTokenChar(s[i])) i++
            if (i - start >= 2) sink(s.substring(start, i).lowercase())
        }
    }

    /** Латинские токены длиной 2+ (аналог `re.findall(r"[a-z]{2,}", k.lower())`). */
    private inline fun forEachLatToken(s: String, sink: (String) -> Unit) {
        var i = 0
        while (i < s.length) {
            if (!isLatTokenChar(s[i])) {
                i++
                continue
            }
            val start = i
            while (i < s.length && isLatTokenChar(s[i])) i++
            if (i - start >= 2) sink(s.substring(start, i).lowercase())
        }
    }

    // 'а'..'я' уже покрывает 'ё'; 'Ё' лежит вне 'А'..'Я'.
    private fun isCyrTokenChar(c: Char): Boolean =
        c in 'а'..'я' || c in 'А'..'Я' || c == 'Ё'

    private fun isLatTokenChar(c: Char): Boolean = c in 'a'..'z' || c in 'A'..'Z'

    // ═══════════════════════════════════════════════════════════
    // Символьные утилиты
    // ═══════════════════════════════════════════════════════════

    private fun isCyr(c: Char): Boolean {
        val o = c.code
        return (o in 0x0400..0x052F) || (o in 0xA640..0xA69F)
    }

    private fun isAsciiLetter(c: Char): Boolean = c in 'a'..'z' || c in 'A'..'Z'

    /** Письмо с учётом кириллицы: цифры и пунктуация письмами не считаются. */
    private fun isAlphaChar(c: Char): Boolean = isAsciiLetter(c) || isCyr(c)

    private fun isAlnumChar(c: Char): Boolean = c in '0'..'9' || isAlphaChar(c)

    private fun isLatRun(s: String): Boolean {
        if (s.isEmpty()) return false
        for (c in s) if (!isAsciiLetter(c)) return false
        return true
    }

    private fun isCyrRun(s: String): Boolean {
        if (s.isEmpty()) return false
        for (c in s) if (!isCyr(c)) return false
        return true
    }

    /** Аналог `str.isupper()`: есть заглавные и нет строчных. */
    private fun isAllUpper(s: String): Boolean {
        var hasCased = false
        for (c in s) {
            if (c.isUpperCase()) {
                hasCased = true
            } else if (c.isLowerCase() || c.isTitleCase()) {
                return false
            }
        }
        return hasCased
    }

    /** Аналог `str.capitalize()`: первая буква вверх, остальные вниз. */
    private fun capitalize(s: String): String =
        if (s.isEmpty()) s else s[0].uppercaseChar() + s.substring(1).lowercase()

    private fun mapChars(s: String, table: Map<Char, Char>): String {
        var need = false
        for (c in s) {
            if (table.containsKey(c)) {
                need = true
                break
            }
        }
        if (!need) return s
        val sb = StringBuilder(s.length)
        for (c in s) sb.append(table[c] ?: c)
        return sb.toString()
    }

    private fun splitWhitespace(s: String): List<String> {
        val raw = WHITESPACE_SPLIT_RE.split(s)
        if (raw.size == 1) return if (raw[0].isEmpty()) emptyList() else listOf(raw[0])
        val out = ArrayList<String>(raw.size)
        for (r in raw) if (r.isNotEmpty()) out.add(r)
        return out
    }

    // ═══════════════════════════════════════════════════════════
    // ОСНОВНЫЕ ФУНКЦИИ
    // ═══════════════════════════════════════════════════════════

    /**
     * Поочерёдная замена латинских lookalike на кириллицу в словах, которые
     * в основном кириллические. Чисто латинские слова (SOS, Wi-Fi) сохраняются.
     *
     * 1. Для каждого слова считаем количество «однозначных» букв каждого алфавита.
     * 2. Если кириллицы больше — латинские lookalike заменяем на кириллицу.
     * 3. Если латиницы больше — кириллические lookalike заменяем на латиницу.
     * 4. Если равны — не трогаем.
     */
    @JvmStatic
    fun fixLookalikesPerWord(text: String): String {
        if (text.isEmpty()) return text
        val m = WORD_RE.matcher(text)
        if (!m.find()) return text
        val sb = StringBuilder(text.length)
        var last = 0
        do {
            sb.append(text, last, m.start())
            sb.append(fixWord(m.group(0)))
            last = m.end()
        } while (m.find())
        sb.append(text, last, text.length)
        return sb.toString()
    }

    private fun fixWord(word: String): String {
        val runs = letterRuns(word)
        // Склеенные разными алфавитами куски (окна CTC уронили пробел):
        // «Поискиклонированиеyomihon» → два слова, иначе голосование за единый
        // алфавит портит латинский хвост (y→у, o→о).
        if (runs.size >= 2 && hasAlphabetSwitch(runs)) return splitMixedRuns(runs)

        var cyrUnique = 0
        var latUnique = 0
        for (c in word) {
            if (CYR_UNIQUE.contains(c)) cyrUnique++
            if (LAT_UNIQUE.contains(c)) latUnique++
        }

        if (cyrUnique == 0 && latUnique == 0) {
            // Нет однозначных букв (одни омоглифы): решает большинство по полному
            // составу алфавитов, иначе не трогаем.
            var cyrAll = 0
            var latAll = 0
            for (c in word) {
                if (isCyr(c)) cyrAll++
                if (isAsciiLetter(c)) latAll++
            }
            if (cyrAll > latAll) return mapChars(mapChars(word, LAT_TO_CYR), UKR_TO_RUS)
            if (latAll > cyrAll) return mapChars(word, CYR_TO_LAT)
            return word
        }

        if (cyrUnique > latUnique) {
            // Русское слово → латинские lookalike → кириллица, украинские → русские
            return mapChars(mapChars(word, LAT_TO_CYR), UKR_TO_RUS)
        }
        if (latUnique > cyrUnique) {
            // Английское слово → кириллические lookalike → латиница
            return mapChars(word, CYR_TO_LAT)
        }
        return word
    }

    private fun letterRuns(word: String): List<String> {
        val out = ArrayList<String>(4)
        val m = RUN_RE.matcher(word)
        while (m.find()) {
            val s = m.group(0)
            if (isLatRun(s) || isCyrRun(s)) out.add(s)
        }
        return out
    }

    private fun hasAlphabetSwitch(runs: List<String>): Boolean {
        for (i in 0 until runs.size - 1) {
            val a = runs[i]
            val b = runs[i + 1]
            if (a.length >= 2 && b.length >= 2 &&
                ((isCyrRun(a) && isLatRun(b)) || (isLatRun(a) && isCyrRun(b)))
            ) return true
        }
        return false
    }

    private fun splitMixedRuns(runs: List<String>): String {
        val sb = StringBuilder()
        var prevLetters = ""
        var hasPrev = false
        for (r in runs) {
            val chunk = if (isCyrRun(r) && r.length >= 2) mapChars(r, UKR_TO_RUS) else r
            // Пробел только на границе длинные буквенные прогоны разных алфавитов
            if (hasPrev && r.length >= 2 &&
                ((isLatRun(r) && isCyrRun(prevLetters)) ||
                    (isCyrRun(r) && isLatRun(prevLetters)))
            ) sb.append(' ')
            sb.append(chunk)
            hasPrev = true
            when {
                isLatRun(r) || isCyrRun(r) -> prevLetters = r
                chunk.isBlank() -> prevLetters = ""
            }
        }
        return sb.toString()
    }

    /**
     * Склейка переносов строк с дефисом: 'пере-\nносится' → 'переносится'.
     * Второй проход того же шаблона в оригинале избыточен: он не может найти
     * новых совпадений, т.к. единственный \n между буквами уже удалён.
     */
    @JvmStatic
    fun joinLineHyphens(text: String): String {
        if (text.isEmpty()) return text
        val m = HYPHEN_RE.matcher(text)
        if (!m.find()) return text
        val sb = StringBuilder(text.length)
        var last = 0
        do {
            sb.append(text, last, m.start(1))
            sb.append(text, m.start(2), m.end(2))
            last = m.end()
        } while (m.find())
        sb.append(text, last, text.length)
        return sb.toString()
    }

    private const val OP_SUB = 0
    private const val OP_DEL = 1
    private const val OP_INS = 2

    private class Cand(val score: Int, val op: Int)

    /**
     * Кандидаты на расстоянии 1 визуальной правки.
     *
     * Вес отражает механизм ошибки модели: замена внутри пары-омоглифа или
     * удаление/вставка буквы рядом с её парным соседом (расщеплённый глиф:
     * 'грана' → 'рана') — 2; вставка рядом с парным соседом — 1; прочее — 0.
     * Операция нужна гейту: нулевые вставки/замены запрещены (выдумывают буквы:
     * 'теат' → 'театр'), нулевые удаления разрешены (заикание модели).
     */
    private fun confusionCandidates(word: String): HashMap<String, Cand> {
        val out = HashMap<String, Cand>(word.length * 2)
        val n = word.length

        // Замены внутри пар-омоглифов
        for (i in 0 until n) {
            val alts = CONFUSION_NEIGHBORS[word[i]] ?: continue
            for (alt in alts) {
                bumpCand(out, word, word.substring(0, i) + alt + word.substring(i + 1), 2, OP_SUB)
            }
        }
        // Удаление одного символа
        for (i in 0 until n) {
            val ch = word[i]
            val mates = CONFUSION_NEIGHBORS[ch]
            val near = HashSet<Char>(3)
            for (j in maxOf(0, i - 1)..minOf(n - 1, i + 1)) {
                if (word[j] != ch) near.add(word[j])
            }
            val score = if (mates != null && near.any { mates.contains(it) }) 2 else 0
            bumpCand(out, word, word.substring(0, i) + word.substring(i + 1), score, OP_DEL)
        }
        // Вставка буквы из пар
        for (i in 0..n) {
            val near = HashSet<Char>(2)
            for (j in maxOf(0, i - 1)..minOf(n - 1, i)) near.add(word[j])
            for (ch in CONFUSION_LETTERS) {
                val mates = CONFUSION_NEIGHBORS[ch] ?: continue
                val score = if (near.any { mates.contains(it) }) 1 else 0
                bumpCand(out, word, word.substring(0, i) + ch + word.substring(i), score, OP_INS)
            }
        }
        return out
    }

    private fun bumpCand(out: HashMap<String, Cand>, word: String, key: String, score: Int, op: Int) {
        if (key == word) return
        val prev = out[key]
        if (prev == null || score > prev.score) out[key] = Cand(score, op)
    }

    /**
     * Правит одиночные визуальные ошибки модели по словарю.
     *
     * Безопасно: трогает только чисто кириллические токены длиной 4+, которых
     * НЕТ в словаре, и только если ровно один кандидат ЕСТЬ.
     */
    @JvmStatic
    fun correctVisualConfusions(text: String): String {
        if (text.isEmpty()) return text
        val valid = ruValidWords()
        val result = ArrayList<String>()
        for (tok in text.split(' ')) {
            val m = TOKEN_CORE_RE.matcher(tok)
            if (!m.matches()) {
                result.add(tok)
                continue
            }
            val pre = m.group(1)
            val core = m.group(2)
            val post = m.group(3)
            if (core.length < 4 || !CYR_ONLY_RE.matcher(core.lowercase()).matches()) {
                result.add(tok)
                continue
            }
            val low = core.lowercase()
            if (low in valid) {
                result.add(tok)
                continue
            }
            val hits = ArrayList<Pair<String, Cand>>()
            for ((cand, info) in confusionCandidates(low)) {
                if (cand in valid) hits.add(cand to info)
            }
            if (hits.isEmpty()) {
                result.add(tok)
                continue
            }
            var best = Int.MIN_VALUE
            for (p in hits) if (p.second.score > best) best = p.second.score
            var winners = ArrayList<Pair<String, Cand>>(2)
            for (p in hits) if (p.second.score == best) winners.add(p)

            val fixed = if (winners.size == 1) {
                val p = winners[0]
                // Нулевые вставки/замены запрещены: они выдумывают буквы
                // ('теат' → 'театр' из ничего). Нулевые удаления разрешены.
                if (best == 0 && p.second.op != OP_DEL) {
                    result.add(tok)
                    continue
                }
                p.first
            } else {
                // Ничья по механизму ошибки — решает частотность (редкое
                // собственное имя вроде 'гана' проигрывает обычному 'рана').
                // Строго больше, иначе не трогаем.
                var topIdx = 0
                var topVal = ruWordFreq(winners[0].first)
                for (i in 1 until winners.size) {
                    val f = ruWordFreq(winners[i].first)
                    if (f > topVal) {
                        topVal = f
                        topIdx = i
                    }
                }
                var secondVal = Int.MIN_VALUE
                for (i in winners.indices) {
                    if (i == topIdx) continue
                    val f = ruWordFreq(winners[i].first)
                    if (f > secondVal) secondVal = f
                }
                if (topVal <= secondVal) {
                    result.add(tok)
                    continue
                }
                if (best == 0 && winners[topIdx].second.op != OP_DEL) {
                    result.add(tok)
                    continue
                }
                winners[topIdx].first
            }

            val out = when {
                isAllUpper(core) -> fixed.uppercase()
                core[0].isUpperCase() -> capitalize(fixed)
                else -> fixed
            }
            result.add(pre + out + post)
        }
        return result.joinToString(" ")
    }

    /**
     * DP-сегментация слипшегося текста через словарь известных слов.
     *
     * Динамическое программирование находит оптимальное разбиение кириллического
     * текста на известные слова. Вставляет границы ТОЛЬКО если ВСЕ фрагменты —
     * известные слова.
     */
    @JvmStatic
    fun restoreKnownWords(text: String): String {
        if (text.isEmpty()) return text
        val result = ArrayList<String>()
        for (word in splitWhitespace(text)) {
            // Только для слов из подозрительно длинных кириллических блоков
            if (word.length < 6 || !CYR_WORD_RE.matcher(word).matches()) {
                result.add(word)
                continue
            }
            val low = word.lowercase()
            if (low in KNOWN_WORDS) {
                result.add(word)
                continue
            }
            val split = dpSplitOnKnown(low, DP_MAX_WORD_LEN)
            if (split != null && split.size > 1 && split.all { it in KNOWN_WORDS }) {
                val restored = ArrayList<String>(split.size)
                var idx = 0
                for (part in split) {
                    val origSlice = word.substring(idx, idx + part.length)
                    // Сохраняем регистр исходного сегмента
                    restored.add(
                        when {
                            isAllUpper(origSlice) -> part.uppercase()
                            origSlice[0].isUpperCase() -> capitalize(part)
                            else -> part
                        }
                    )
                    idx += part.length
                }
                result.add(restored.joinToString(" "))
            } else {
                result.add(word)
            }
        }
        return result.joinToString(" ")
    }

    /**
     * DP-алгоритм: разбивает слово на список известных подслов.
     * Возвращает null, если разбиение невозможно.
     */
    @JvmStatic
    @JvmOverloads
    fun dpSplitOnKnown(word: String, maxWordLen: Int = DP_MAX_WORD_LEN): List<String>? {
        val n = word.length
        if (n == 0) return emptyList()
        if (n > DP_MAX_INPUT) return null

        // dp[i] = слова для word[0, i) или null, если невозможно
        val dp = arrayOfNulls<ArrayList<String>?>(n + 1)
        dp[0] = ArrayList(0)

        for (i in 1..n) {
            for (start in maxOf(0, i - maxWordLen) until i) {
                val prev = dp[start] ?: continue
                val candidate = word.substring(start, i)
                if (candidate !in KNOWN_WORDS) continue
                val newList = ArrayList<String>(prev.size + 1)
                newList.addAll(prev)
                newList.add(candidate)
                val cur = dp[i]
                if (cur == null || newList.size < cur.size) dp[i] = newList
            }
        }
        return dp[n]
    }

    /**
     * Поочерёдное удаление мусорных токенов, сохраняя нормальные: токен, не
     * содержащий ни кириллицы, ни латиницы, ни «безопасной» пунктуации/цифр,
     * выбрасывается, остальные токены строки сохраняются.
     */
    @JvmStatic
    fun filterGarbageTokens(text: String): String {
        if (text.isEmpty()) return text
        val sb = StringBuilder(text.length)
        var first = true
        for (line in text.split('\n')) {
            val cleaned = ArrayList<String>()
            for (w in splitWhitespace(line)) {
                when {
                    // Токен нормальный, если содержит кириллицу
                    CYRILLIC_RE.matcher(w).find() -> cleaned.add(w)
                    // Или латиницу (английские слова)
                    LATIN_RE.matcher(w).find() -> cleaned.add(w)
                    // Или это чистая пунктуация/цифры
                    w.all { GARBAGE_WHITELIST.contains(it) || it in '0'..'9' } -> cleaned.add(w)
                    else -> Log.d(TAG, "[Cleaner] Garbage token removed: '$w'")
                }
            }
            if (cleaned.isNotEmpty()) {
                if (!first) sb.append('\n')
                first = false
                sb.append(cleaned.joinToString(" "))
            }
        }
        return sb.toString()
    }

    /**
     * Артефакт CTC-декодера: длинные последовательные восходящие Unicode codepoints.
     * Ключевой критерий: 10+ последовательных восходящих codepoints БЕЗ пробелов
     * и пунктуации (декодер «скатывается» по таблице символов).
     */
    @JvmStatic
    fun looksLikeDictionaryRamp(text: String): Boolean {
        if (text.length < 10) return false
        for (word in RAMP_SPLIT_RE.split(text)) {
            if (word.length < 8) continue
            var ascending = 1
            for (i in 1 until word.length) {
                if (word[i] > word[i - 1]) {
                    ascending++
                    if (ascending >= 10) return true
                } else {
                    ascending = 1
                }
            }
        }
        return false
    }

    /** Нормализация пробелов и пунктуации. */
    @JvmStatic
    fun normalizeWhitespace(text: String): String {
        if (text.isEmpty()) return text
        var out = SPACES_RUN_RE.matcher(text).replaceAll(" ")
        out = AROUND_NL_RE.matcher(out).replaceAll("\n")
        out = FOUR_DOTS_RE.matcher(out).replaceAll("…")
        out = THREE_DOTS_RE.matcher(out).replaceAll("…")
        // Запятые/точки с пробелами
        out = SPACE_BEFORE_PUNCT_RE.matcher(out).replaceAll("\$1")
        out = SPACE_AFTER_OPEN_RE.matcher(out).replaceAll("\$1")
        val sb = StringBuilder(out.length)
        val lines = out.split('\n')
        for ((i, l) in lines.withIndex()) {
            if (i > 0) sb.append('\n')
            sb.append(l.trim())
        }
        return sb.toString()
    }

    /**
     * Чистка чисел: 1.5000000 → 1.50, 100.00000 → 100, 1.00 → 1.
     * Хвостовые нули после десятичной точки — артефакт float-форматирования OCR.
     */
    @JvmStatic
    fun normalizeNumbers(text: String): String {
        if (text.isEmpty()) return text
        val m = TRAILING_ZEROS_RE.matcher(text)
        if (!m.find()) return text
        val sb = StringBuilder(text.length)
        var last = 0
        do {
            sb.append(text, last, m.start())
            sb.append(cleanNumber(m.group(0)))
            last = m.end()
        } while (m.find())
        sb.append(text, last, text.length)
        return sb.toString()
    }

    private fun cleanNumber(s: String): String {
        if (s.indexOf('.') < 0 && s.indexOf(',') < 0) return s
        // Запятую/точку обрабатываем как есть и восстанавливаем как была
        val sepIndex = s.indexOf(',').let { if (it >= 0) it else s.indexOf('.') }
        val sepChar = s[sepIndex]
        val integer = s.substring(0, sepIndex)
        val frac = s.substring(sepIndex + 1).trimEnd('0')
        if (frac.isEmpty()) return integer // 1.00 → 1
        return integer + sepChar + frac
    }

    /** Доля кириллических символов среди букв (0.0..1.0). */
    @JvmStatic
    fun cyrillicFitness(text: String): Double {
        var alpha = 0
        var cyr = 0
        for (c in text) {
            if (!isAlphaChar(c)) continue
            alpha++
            val l = c.lowercaseChar()
            if (l in 'а'..'я' || c == 'Ё') cyr++
        }
        if (alpha == 0) return 0.0
        return cyr.toDouble() / alpha
    }

    /** Доля ASCII-латиницы среди букв. Пара к [cyrillicFitness]. */
    @JvmStatic
    fun latinFitness(text: String): Double {
        var alpha = 0
        var lat = 0
        for (c in text) {
            if (!isAlphaChar(c)) continue
            alpha++
            if (isAsciiLetter(c)) lat++
        }
        if (alpha == 0) return 0.0
        return lat.toDouble() / alpha
    }

    /**
     * Возвращает оторванную ведущую пунктуацию предыдущему слову.
     * Артефакт сегментации/CTC: запятая предыдущего слова оказывается в начале
     * следующего токена ('файл' ',чтобы' → 'файл,' 'чтобы').
     */
