    fun reattachLeadingPunct(text: String): String {
        val out = ArrayList<String>()
        for (tok in text.split(' ')) {
            var i = 0
            while (i < tok.length && LEAD_PUNCT.contains(tok[i])) i++
            val last = if (out.isEmpty()) null else out[out.size - 1]
            if (i > 0 && i < tok.length && last != null && last.isNotEmpty() &&
                !LEAD_PUNCT.contains(last[last.length - 1]) &&
                isAlnumChar(last[last.length - 1])
            ) {
                out[out.size - 1] = last + tok.substring(0, i)
                val rest = tok.substring(i)
                if (rest.isNotEmpty()) out.add(rest)
            } else {
                out.add(tok)
            }
        }
        val sb = StringBuilder(text.length)
        var first = true
        for (t in out) {
            if (t.isEmpty()) continue
            if (!first) sb.append(' ')
            first = false
            sb.append(t)
        }
        return sb.toString()
    }

