    fun isAcceptableCyrillicText(text: String): Boolean {
        if (text.isEmpty()) return false
        for (w in splitWhitespace(text)) {
            val clean = w.trim { it in STRIP_PUNCT }
            if (clean.isEmpty()) continue
            // Кириллическое слово — ок
            if (CYR_WORD_RE.matcher(clean).matches()) continue
            // Чисто латинское — допускаем (SOS, Wi-Fi, OK)
            if (LAT_ONLY_RE.matcher(clean).matches()) continue
            // Смешанное — допускаем, если есть хотя бы одна кириллическая буква
            val hasCyr = CYR_CHAR_RE.matcher(clean).find()
            val hasLat = LAT_CHAR_RE.matcher(clean).find()
            if (hasCyr && hasLat) continue
            // Непонятное — отклоняем
            return false
        }
        return true
    }

    /** Точечная замена известных ошибочно распознанных терминов. */
    @JvmStatic
    fun applyKnownCorrections(text: String): String {
        if (text.isEmpty()) return text
        val m = LATIN_RUN_RE.matcher(text)
        if (!m.find()) return text
        val sb = StringBuilder(text.length)
        var last = 0
        do {
            sb.append(text, last, m.start())
            val w = m.group(0)
            sb.append(KNOWN_CORRECTIONS[w.lowercase()] ?: w)
            last = m.end()
        } while (m.find())
        sb.append(text, last, text.length)
        return sb.toString()
    }

    /**
     * Полный пайплайн пост-обработки кириллического текста:
     * joinLineHyphens → fixLookalikesPerWord → restoreKnownWords
     * → correctVisualConfusions → reattachLeadingPunct.
     */
    @JvmStatic
    fun normalizeLocalCyrillicCaption(text: String): String {
        if (text.isEmpty()) return text
        var t = joinLineHyphens(text)
        t = fixLookalikesPerWord(t)
        t = restoreKnownWords(t)
        t = correctVisualConfusions(t)
        t = reattachLeadingPunct(t)
        return t
    }

    /**
     * Полный пайплайн очистки OCR-текста.
     *
     * 1. Нормализация пробелов
     * 2. Исправление lookalike-букв
     * 3. Склейка переносов
     * 4. DP-сегментация слипшегося текста (только для кириллицы)
     * 5. Фильтр мусорных токенов
     * 6. Точечные правки известных терминов
     * 7. Нормализация чисел (1.5000000 → 1.50)
     * 8. Финальная нормализация пробелов
     * 9. Проверка на «словарный рэмп»
     */
    @JvmStatic
    @JvmOverloads
    fun fullCleanPipeline(text: String, engineType: String = ENGINE_TFLITE): String {
        if (text.isEmpty()) return text

        var t = normalizeWhitespace(text)          // 1
        t = fixLookalikesPerWord(t)                // 2
        t = joinLineHyphens(t)                     // 3
        if (engineType in CYRILLIC_ENGINES) t = restoreKnownWords(t) // 4
        t = filterGarbageTokens(t)                 // 5
        t = applyKnownCorrections(t)               // 6
        t = normalizeNumbers(t)                    // 7
        t = normalizeWhitespace(t)                 // 8
        if (looksLikeDictionaryRamp(t)) {          // 9
            Log.w(TAG, "[Cleaner] Dictionary ramp detected, text may be garbage: ${t.take(80)}")
        }
        return t
    }
}

