package org.json;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/** Минимальный org.json для JVM-харнесса (реальный Android использует свой). */
public class JSONException extends RuntimeException {
    public JSONException(String m) { super(m); }
}

final class Parser {
    private final String s;
    private int p;

    Parser(String s) { this.s = s; }

    Object parse() {
        ws();
        Object v = value();
        return v;
    }

    private void ws() {
        while (p < s.length() && (s.charAt(p) == ' ' || s.charAt(p) == '\n'
                || s.charAt(p) == '\r' || s.charAt(p) == '\t')) p++;
    }

    private Object value() {
        char c = s.charAt(p);
        if (c == '{') {
            p++;
            Map<String, Object> m = new LinkedHashMap<String, Object>();
            ws();
            if (s.charAt(p) == '}') { p++; return m; }
            while (true) {
                ws();
                String k = str();
                ws();
                if (s.charAt(p) != ':') throw new JSONException("expected ':' at " + p);
                p++;
                ws();
                m.put(k, value());
                ws();
                char d = s.charAt(p++);
                if (d == '}') return m;
                if (d != ',') throw new JSONException("expected ',' at " + (p - 1));
            }
        }
        if (c == '[') {
            p++;
            List<Object> a = new ArrayList<Object>();
            ws();
            if (s.charAt(p) == ']') { p++; return a; }
            while (true) {
                ws();
                a.add(value());
                ws();
                char d = s.charAt(p++);
                if (d == ']') return a;
                if (d != ',') throw new JSONException("expected ',' at " + (p - 1));
            }
        }
        if (c == '"') return str();
        if (s.startsWith("true", p)) { p += 4; return Boolean.TRUE; }
        if (s.startsWith("false", p)) { p += 5; return Boolean.FALSE; }
        if (s.startsWith("null", p)) { p += 4; return null; }
        int st = p;
        while (p < s.length() && "+-0123456789.eE".indexOf(s.charAt(p)) >= 0) p++;
        return Double.valueOf(s.substring(st, p));
    }

    private String str() {
        if (s.charAt(p) != '"') throw new JSONException("expected '\"' at " + p);
        p++;
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = s.charAt(p++);
            if (c == '"') return sb.toString();
            if (c == '\\') {
                char e = s.charAt(p++);
                switch (e) {
                    case 'n': sb.append('\n'); break;
                    case 't': sb.append('\t'); break;
                    case 'r': sb.append('\r'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'u':
                        sb.append((char) Integer.parseInt(s.substring(p, p + 4), 16));
                        p += 4;
                        break;
                    default: sb.append(e);
                }
            } else {
                sb.append(c);
            }
        }
    }
}

package org.json;

import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.Map;

public class JSONObject {

    private final Map<String, Object> map = new LinkedHashMap<String, Object>();

    public JSONObject() { }

    @SuppressWarnings("unchecked")
    public JSONObject(String json) {
        Object o = new Parser(json).parse();
        if (!(o instanceof Map)) throw new JSONException("not a JSON object");
        map.putAll((Map<String, Object>) o);
    }

    public Iterator<String> keys() {
        return map.keySet().iterator();
    }

    public Object opt(String name) {
        return map.get(name);
    }

    public int length() {
        return map.size();
    }
}

package org.json;

import java.util.ArrayList;
import java.util.List;

public class JSONArray {

    private final List<Object> list = new ArrayList<Object>();

    @SuppressWarnings("unchecked")
    public JSONArray(String json) {
        Object o = new Parser(json).parse();
        if (!(o instanceof List)) throw new JSONException("not a JSON array");
        list.addAll((List<Object>) o);
    }

    public int length() {
        return list.size();
    }

    public Object opt(int index) {
        if (index < 0 || index >= list.size()) return null;
        return list.get(index);
    }
}

