/**
 * Склейка переносов строк с дефисом: 'пере-\nносится' → 'переносится'.
 *
 * Проход делается дважды — как в оригинале: первый склеивает «пере-\nнос»,
 * второй дожимает цепочки вида «а-\nб-\nв», где дефис остался на стыке.
 */
@JvmStatic
fun joinLineHyphens(text: String): String {
    if (text.isEmpty()) return text
    return joinHyphensOnce(joinHyphensOnce(text))
}

private fun joinHyphensOnce(text: String): String {
    val m = HYPHEN_RE.matcher(text)
    if (!m.find()) return text
    val sb = StringBuilder(text.length)
    var last = 0
    do {
        sb.append(text, last, m.end(1))
        sb.append(text, m.start(2), m.end(2))
        last = m.end()
    } while (m.find())
    sb.append(text, last, text.length)
    return sb.toString()
}

