/** Доля кириллических символов среди букв (0.0..1.0). */
@JvmStatic
fun cyrillicFitness(text: String): Double {
    var alpha = 0
    var cyr = 0
    for (c in text) {
        if (!isAlphaChar(c)) continue
        alpha++
        // 'ё' (U+0451) стоит ПОСЛЕ 'я' (U+044F), поэтому проверяем отдельно
        val l = c.lowercaseChar()
        if (l in 'а'..'я' || l == 'ё') cyr++
    }
    if (alpha == 0) return 0.0
    return cyr.toDouble() / alpha
}

