import base64
import json
import random
import subprocess
import sys

sys.path.insert(0, "/home/runner/hub-work/ScreenOCR_TTS/code")
import ocr_text_cleaner as oc  # noqa: E402

random.seed(20260928)

# Пул реальных слов из harvest-словаря
_data = json.load(open("/home/runner/hub-work/ScreenOCR_TTS/code/eng_rus_dict.json", encoding="utf-8"))
_ru = []
for v in list(_data.values())[:6000]:
    for s in v[:2]:
        for tok in s.split():
            if tok.isalpha() and 2 <= len(tok) <= 12:
                _ru.append(tok)
_en = [k.lower() for k in list(_data.keys())[:6000] if k.isalpha() and 2 <= len(k) <= 10]
_ru = random.sample(_ru, 1500)
_en = random.sample(_en, 800)

CONF = [("г", "р"), ("п", "г"), ("и", "й"), ("е", "ё"), ("ш", "щ"), ("б", "в"),
        ("ъ", "ь"), ("л", "д"), ("э", "з"), ("п", "л"), ("ы", "и"), ("о", "а")]
PUNCT = [",", ".", "!", "?", ";", ":", "-", "—", "…", "(", ")", "[", "]", '"', "'", "«", "»", "%"]
NUMS = ["1.5000000", "100.00000", "1.00", "3.14", "0.0", "2024", "12.3456000", "1,20000", "5."]
GLUE = list(oc._KNOWN_WORDS)[:80]
CYR_SYM = "абвгдеёжзийклмнопрстуфхцчшщъыьэюя"


def mutate(w):
    ops = random.randint(1, 2)
    for _ in range(ops):
        if len(w) < 3:
            break
        kind = random.random()
        i = random.randrange(len(w))
        if kind < 0.45:  # замена похожей буквы
            a, b = random.choice(CONF)
            if w[i] == a:
                w = w[:i] + b + w[i + 1:]
        elif kind < 0.7:  # удаление
            w = w[:i] + w[i + 1:]
        elif kind < 0.9:  # вставка
            w = w[:i] + random.choice(CYR_SYM) + w[i:]
        else:  # латиница в кириллическое слово
            w = w[:i] + random.choice("aceopxy") + w[i + 1:]
    return w


def word():
    r = random.random()
    if r < 0.30:
        return random.choice(_ru)
    if r < 0.42:
        return mutate(random.choice(_ru))
    if r < 0.55:
        return random.choice(_en)
    if r < 0.62:
        return random.choice(NUMS)
    if r < 0.70:
        return mutate(random.choice(_en))
    if r < 0.80:
        return "".join(random.choice(CYR_SYM) for _ in range(random.randint(1, 14)))
    if r < 0.88:
        return random.choice(GLUE) + random.choice(GLUE)
    if r < 0.94:
        return random.choice(PUNCT)
    return "".join(random.choice(CYR_SYM + "abcdefgh") for _ in range(random.randint(1, 9)))


def sentence():
    n = random.randint(1, 9)
    parts = []
    for _ in range(n):
        w = word()
        if random.random() < 0.15:
            w += random.choice(PUNCT)
        if random.random() < 0.08:
            w = w + "-" + random.choice(GLUE)
        parts.append(w)
    s = " ".join(parts)
    if random.random() < 0.25:
        s = s.replace(" ", "\n", 1)
    if random.random() < 0.15:
        s = s + "-\n" + word()
    if random.random() < 0.2:
        s = s.upper() if random.random() < 0.5 else s.capitalize()
    if random.random() < 0.15:
        s = "  " + s + "  "
    if random.random() < 0.1:
        s = s.replace(" ", "\u00a0", 1)
    return s


FIELD_NAMES = [
    "full", "full_easyocr", "full_lens", "fix_lookalikes", "join_hyphens",
    "restore_known", "confusions", "garbage", "known_corr", "numbers",
    "whitespace", "caption", "punct", "cyrfit", "latfit", "acceptable", "ramp", "dp",
]


def py_row(t):
    dp = oc._dp_split_on_known(t)
    return [
        oc.full_clean_pipeline(t),
        oc.full_clean_pipeline(t, "easyocr"),
        oc.full_clean_pipeline(t, "google_lens"),
        oc.fix_lookalikes_per_word(t),
        oc.join_line_hyphens(t),
        oc.restore_known_words(t),
        oc.correct_visual_confusions(t),
        oc.filter_garbage_tokens(t),
        oc.apply_known_corrections(t),
        oc.normalize_numbers(t),
        oc.normalize_whitespace(t),
        oc.normalize_local_cyrillic_caption(t),
        oc.reattach_leading_punct(t),
        oc.cyrillic_fitness(t),
        oc.latin_fitness(t),
        oc.is_acceptable_cyrillic_text(t),
        oc.looks_like_dictionary_ramp(t),
        "|".join(dp) if dp is not None else "<null>",
    ]


def main():
    inputs = [sentence() for _ in range(3000)]
    with open("/tmp/opencode/h/fuzz.json", "w", encoding="utf-8") as f:
        json.dump(inputs, f, ensure_ascii=False)

    proc = subprocess.run(
        ["java", "-Xmx3g", "-cp",
         "/tmp/opencode/h/out:/usr/share/kotlinc/lib/kotlin-stdlib.jar",
         "harness.Main", "/tmp/opencode/h/fuzz.json"],
        capture_output=True, text=True,
    )
    if proc.returncode != 0:
        print("HARNESS FAILED", proc.stderr[-3000:])
        return 1
    lines = proc.stdout.split("\n")
    bad = 0
    shown = 0
    for i, t in enumerate(inputs):
        py = py_row(t)
        kt = lines[i].split("\t")
        for name, pv, kv in zip(FIELD_NAMES, py, kt):
            if name in ("cyrfit", "latfit"):
                if abs(float(pv) - float(kv)) > 1e-12:
                    print(f"[{i}] {name}: py={pv} kt={kv}\n    in={t!r}")
                    bad += 1
                continue
            if name in ("acceptable", "ramp"):
                if ("1" if pv else "0") != kv:
                    print(f"[{i}] {name}: py={pv} kt={kv}\n    in={t!r}")
                    bad += 1
                continue
            ktd = base64.b64decode(kv).decode("utf-8")
            if pv != ktd:
                shown += 1
                if shown <= 12:
                    print(f"[{i}] {name}:\n    py={pv!r}\n    kt={ktd!r}\n    in={t!r}")
                bad += 1
    print(f"\nfuzz mismatches: {bad} over {len(inputs)} inputs x {len(FIELD_NAMES)} fields")
    return 0 if bad == 0 else 1


if __name__ == "__main__":
    sys.exit(main())

package harness

import com.screenocr.tts.ocr.OcrTextCleaner
import android.content.Context
import org.json.JSONArray
import java.util.Base64

object DebugMain {
    @JvmStatic
    fun main(args: Array<String>) {
        OcrTextCleaner.attach(Context())
        val content = java.io.File(args[0]).readText(Charsets.UTF_8)
        val arr = JSONArray(content)
        for (i in 0 until arr.length()) {
            val t = arr.opt(i) as String
            val steps = ArrayList<String>()
            var x = t
            steps.add(x)
            x = OcrTextCleaner.joinLineHyphens(x); steps.add(x)
            x = OcrTextCleaner.fixLookalikesPerWord(x); steps.add(x)
            x = OcrTextCleaner.restoreKnownWords(x); steps.add(x)
            x = OcrTextCleaner.correctVisualConfusions(x); steps.add(x)
            x = OcrTextCleaner.reattachLeadingPunct(x); steps.add(x)
            println(i.toString() + "\t" + steps.joinToString("\t") { b64(it) })
        }
    }

    private fun b64(s: String): String = Base64.getEncoder().encodeToString(s.toByteArray(Charsets.UTF_8))
}

