def is_word(c):
    return c.isalnum() or c == "_"

def build_trie(phrases):
    root = {}
    for p, v in phrases.items():
        node = root
        for ch in p:
            node = node.setdefault(ch, [None, {}])[1]
        node[0] = v
    return root

CONTRACT_RE = re.compile(
    "(?<![A-Za-z])(" + "|".join(sorted(CONTRACTIONS, key=len, reverse=True).__iter__().__length_hint__() and map(re.escape, sorted(CONTRACTIONS, key=len, reverse=True))) + ")(?![A-Za-z])"
)

class Proto:
    def __init__(self, ref):
        self.words = {}
        self.phrases = {}
        d = json.load(open('/home/runner/hub-work/ScreenOCR_TTS/code/en_rus_full.json', encoding='utf-8'))
        for k, v in d.items():
            if ' ' in k:
                self.phrases[k] = v
            else:
                self.words[k] = v
        self.trie = build_trie(self.phrases)
        self.ref = ref

    def translate(self, text):
        t = text.lower().strip()
        t = CONTRACT_RE.sub(lambda m: CONTRACTIONS[m.group(1)], t)
        direct = self.phrases.get(t)
        if direct is not None:
            return direct
        out = []
        plain = []
        n = len(t)
        i = 0
        while i < n:
            if i == 0 or not is_word(t[i-1]):
                node = self.trie
                j = i
                best = None
                while j < n:
                    nxt = node.get(t[j])
                    if nxt is None:
                        break
                    node = nxt[1]
                    j += 1
                    if node.get(0) is not None and (j == n or not is_word(t[j])):
                        best = (j, node[0])
                if best is not None:
                    if plain:
                        self._flush(out, "".join(plain)); plain.clear()
                    out.append(best[1])
                    i = best[0]
                    continue
            plain.append(t[i]); i += 1
        if plain:
            self._flush(out, "".join(plain))
        return " ".join(x for x in out if x)

    def _flush(self, out, chunk):
        for w in chunk.split():
            c = "".join(ch for ch in w if is_word(ch))
            if not c:
                continue
            if c in ARTICLES:
                continue
            out.append(self.words.get(c) or c)

