package com.screenocr.tts.translate

import android.content.Context
import android.content.res.AssetManager
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.io.File

/**
 * Порт `offline_dict.py` — офлайн-переводчик EN→RU по словарю из ассетов.
 *
 * Сеть не используется ни при каких обстоятельствах: это единственный
 * переводчик, доступный в режиме `Translator.ENGINE_OFFLINE` (работа без
 * интернета). Провайдеры Zen/Google/DeepL живут в [Translator].
 *
 * ## Отличие от оригинала
 *
 * В Python для каждой многословной фразы на каждый вызов `translate()`
 * компилировался новый `re.Pattern` и делался полный проход по строке —
 * 191 мс на короткую фразу, 47 с на страницу. Здесь при загрузке словаря
 * один раз строится бор (trie) по многословным фразам, и перевод — это
 * один проход по токенам: O(n · maxLen фразы) вместо O(n · фраз).
 *
 * Ещё одно отличие, намеренное: токены — это максимальные участки из
 * символов «слово» (буквы/цифры/подчёркивание), а не результат
 * `str.split()`. Для OCR-текста это важно: «Level 5,Boss» в Python давал
 * один токен `level5boss` (промах по словарю), здесь — `level`, `5`, `boss`.
 * Пунктуация при этом, как и в оригинале, в перевод не попадает.
 *
 * Первая загрузка (парсинг 2.3 МБ JSON) занимает сотни миллисекунд —
 * вызывайте [prepare] из фонового потока. [Translator] делает это сам
 * перед первым офлайн-переводом.
 */
class OfflineDict private constructor(context: Context) {

    private val assets: AssetManager = context.applicationContext.assets
    private val filesDir: File = context.applicationContext.filesDir

    private val loadLock = Any()
    @Volatile private var data: DictData? = null

    /** Число записей словаря (однословных + многословных фраз). */
    val size: Int get() = data?.size ?: 0

    /** Словарь уже разобран. */
    val isLoaded: Boolean get() = data != null

    /**
     * Прогревает загрузку словаря (I/O + парсинг) в фоновом потоке.
     * Идемпотентна и потокобезопасна.
     */
    suspend fun prepare() {
        if (data == null) withContext(Dispatchers.IO) { ensureLoaded() }
    }

    /**
     * Пословный перевод EN→RU.
     *
     * Конвейер: lower-case → раскрытие сокращений → поиск многословных фраз
     * (longest match) → пословный перевод с отбрасыванием артиклей → сборка.
     */
    fun translate(text: String): String {
        if (text.isEmpty()) return ""
        val d = data ?: ensureLoaded()

        val normalized = Contractions.expand(text.lowercase().trim())
        if (normalized.isEmpty()) return ""

        val tokens = ArrayList<String>(16)
        tokenizeInto(normalized, tokens)
        if (tokens.isEmpty()) return ""

        // Строки, переведённые ранее онлайн-провайдером, отдаём как есть
        // (порт _learned из offline_dict.py).
        d.learnedLookup(normalized)?.let { return it }
        d.exactPhrase(tokens)?.let { return it }

        val out = StringBuilder(normalized.length + 32)
        var first = true
        var i = 0
        while (i < tokens.size) {
            val phrase = d.longestPhrase(tokens, i)
            if (phrase != null) {
                if (!first) out.append(' ')
                out.append(phrase.value)
                first = false
                i += phrase.length
                continue
            }
            val token = tokens[i]
            i++
            if (token in ARTICLES) continue
            val value = d.words[token] ?: token
            if (!first) out.append(' ')
            out.append(value)
            first = false
        }
        return out.toString()
    }

    /**
     * Порт `has_untranslated`: грубые признаки некачественного пословного
     * перевода — «залипшие» латинские слова, почти совпадающий с исходником
     * текст или подозрительно короткий результат.
     */
    fun hasUntranslated(text: String): Boolean {
        val result = translate(text)
        if (result.isEmpty()) return true
        for (chunk in words(result)) {
            val latinLettersOnly = chunk.length > 2 &&
                chunk.all { it.code < 128 } &&
                chunk.all { it.isLetter() }
            if (latinLettersOnly) return true
        }
        val source = words(text.lowercase()).toSet()
        val target = words(result.lowercase()).toSet()
        if (target.intersect(source).size > source.size * 0.5) return true
        if (words(result).size < words(text).size * 0.4) return true
        return false
    }

    /**
     * Запоминает удачный онлайн-перевод для последующих офлайн-вызовов
     * (порт `_learned[key] = online; _save_learned()`). Пишет в filesDir.
     */
    suspend fun learn(text: String, translation: String) {
        val key = text.lowercase().trim()
        if (key.isEmpty() || translation.isBlank()) return
        withContext(Dispatchers.IO) {
            val d = ensureLoaded()
            d.learnedPut(key, translation.trim())
            saveLearned(d.learnedSnapshot())
        }
    }

    // ── Загрузка словаря ─────────────────────────────────────────────

    private fun ensureLoaded(): DictData {
        data?.let { return it }
        synchronized(loadLock) {
            data?.let { return it }
            val startedNs = System.nanoTime()
            val built = buildData()
            data = built
            val ms = (System.nanoTime() - startedNs) / 1_000_000
            Log.i(
                TAG,
                "[OfflineDict] ${built.size} entries " +
                    "(${built.words.size} words, ${built.phrases} phrases, " +
                    "${built.learnedSize} learned) loaded in ${ms}ms",
            )
            return built
        }
    }

    private fun buildData(): DictData {
        val words = HashMap<String, String>(1 shl 17)
        val root = PhraseNode()
        val tokens = ArrayList<String>(8)
        var phrases = 0
        var maxPhraseLen = 1

        val raw = readAsset(DICT_ASSET)
        if (raw != null) {
            // На Android у org.json нет JSONObject(Reader) — читаем ассет в строку.
            val json = JSONObject(raw)
            val keys = json.keys()
            while (keys.hasNext()) {
                val key = keys.next()
                val value = json.opt(key) as? String ?: continue
                if (value.isEmpty()) continue
                tokens.clear()
                tokenizeInto(key, tokens)
                when {
                    tokens.isEmpty() -> continue
                    // Ключ нормализуем по токену: "-curtains" станет "curtains",
                    // иначе он недостижим при переводе (пунктуация срезается).
                    tokens.size == 1 -> words[tokens[0]] = value
                    else -> {
                        var node = root
                        for (token in tokens) {
                            node = node.children.getOrPut(token) { PhraseNode() }
                        }
                        if (node.value == null) {
                            node.value = value
                            phrases++
                            if (tokens.size > maxPhraseLen) maxPhraseLen = tokens.size
                        }
                    }
                }
            }
        }

        return DictData(
            words = words,
            phrases = phrases,
            maxPhraseLen = maxPhraseLen,
            learned = loadLearned(),
            root = root,
        )
    }

    private fun readAsset(name: String): String? = try {
        assets.open(name).use { input -> input.readBytes().toString(Charsets.UTF_8) }
    } catch (e: Exception) {
        Log.w(TAG, "[OfflineDict] asset '$name' unavailable: ${e.message}")
        null
    }

    private fun loadLearned(): MutableMap<String, String> {
        val file = File(filesDir, LEARNED_FILE)
        if (!file.exists()) return HashMap()
        return try {
            val json = JSONObject(file.readText(Charsets.UTF_8))
            val out = HashMap<String, String>((json.length() * 2).coerceAtLeast(16))
            val keys = json.keys()
            while (keys.hasNext()) {
                val key = keys.next()
                val value = json.opt(key) as? String ?: continue
                if (key.isNotEmpty() && value.isNotEmpty()) out[key] = value
            }
            out
        } catch (e: Exception) {
            Log.w(TAG, "[OfflineDict] learned dict ignored: ${e.message}")
            HashMap()
        }
    }

    private fun saveLearned(learned: Map<String, String>) {
        try {
            val json = JSONObject()
            for ((key, value) in learned) json.put(key, value)
            val target = File(filesDir, LEARNED_FILE)
            val tmp = File(filesDir, "$LEARNED_FILE.tmp")
            tmp.writeText(json.toString(), Charsets.UTF_8)
            // Запись через временный файл: битый learned_dict.json не должен
            // ломать перевод на всех следующих запусках.
            if (!tmp.renameTo(target)) {
                tmp.copyTo(target, overwrite = true)
                tmp.delete()
            }
        } catch (e: Exception) {
            Log.w(TAG, "[OfflineDict] learned dict not saved: ${e.message}")
        }
    }

    // ── Токенизация ──────────────────────────────────────────────────

    /**
     * `\w` из Python — это Unicode-слово (буквы, цифры, подчёркивание);
     * в Java `Character.isLetterOrDigit` даёт тот же результат для наших
     * данных, в том числе для кириллицы.
     */
    private fun isWordChar(c: Char): Boolean =
        c in 'a'..'z' || c in 'A'..'Z' || c in '0'..'9' || c == '_' ||
            (c.code > 127 && Character.isLetterOrDigit(c))

    private fun tokenizeInto(text: String, out: MutableList<String>) {
        var start = -1
        for (i in text.indices) {
            if (isWordChar(text[i])) {
                if (start < 0) start = i
            } else if (start >= 0) {
                out.add(text.substring(start, i))
                start = -1
            }
        }
        if (start >= 0) out.add(text.substring(start))
    }

    /** Аналог `str.split()` в Python: только по пробельным символам, без пустых. */
    private fun words(text: String): List<String> =
        text.split(WHITESPACE).filter { it.isNotEmpty() }

    // ── Данные словаря ───────────────────────────────────────────────

    /** Узел бора многословных фраз: дети — следующие слова, [value] — перевод. */
    private class PhraseNode {
        val children = HashMap<String, PhraseNode>(4)
        var value: String? = null
    }

    private class PhraseMatch(val length: Int, val value: String)

    private class DictData(
        val words: HashMap<String, String>,
        val phrases: Int,
        val maxPhraseLen: Int,
        val learned: MutableMap<String, String>,
        private val root: PhraseNode,
    ) {
        val size: Int get() = words.size + phrases

        @Synchronized
        fun learnedLookup(key: String): String? = learned[key]

        @Synchronized
        fun learnedPut(key: String, value: String) {
            learned[key] = value
        }

        @Synchronized
        fun learnedSnapshot(): Map<String, String> = HashMap(learned)

        @Synchronized
        val learnedSize: Int get() = learned.size

        /** Весь текст целиком является ключом словаря (например «good morning»). */
        fun exactPhrase(tokens: List<String>): String? {
            if (tokens.size < 2) return null
            val match = longestPhrase(tokens, 0) ?: return null
            return if (match.length == tokens.size) match.value else null
        }

        /**
         * Longest match фразы, начинающейся в [from]: спускаемся по бору так
         * глубоко, как позволяет словарь, и запоминаем самый глубокий узел
         * с переводом. Возвращает [PhraseMatch] либо null.
         */
        fun longestPhrase(tokens: List<String>, from: Int): PhraseMatch? {
            val limit = minOf(tokens.size, from + maxPhraseLen)
            var node = root
            var bestLength = 0
            var bestValue: String? = null
            for (i in from until limit) {
                node = node.children[tokens[i]] ?: break
                val value = node.value
                if (value != null) {
                    bestLength = i - from + 1
                    bestValue = value
                }
            }
            val value = bestValue ?: return null
            return PhraseMatch(bestLength, value)
        }
    }

    companion object {
        private const val TAG = "ScreenOCR"
        private const val DICT_ASSET = "dict/en_rus_full.json"
        private const val LEARNED_FILE = "learned_dict.json"

        /** Артикли отбрасываются: в русском их нет (порт _ARTICLES). */
        private val ARTICLES = setOf("the", "a", "an")

        private val WHITESPACE = Regex("\\s+")

        @Volatile
        private var instance: OfflineDict? = null

        /** Процессный синглтон: словарь 68k записей грузится один раз. */
        fun get(context: Context): OfflineDict = instance ?: synchronized(this) {
            instance ?: OfflineDict(context).also { instance = it }
        }
    }
}

