package com.screenocr.tts.translate

import android.content.Context
import android.util.Log
import com.screenocr.tts.settings.Settings
import kotlinx.coroutines.CancellationException
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.delay
import kotlinx.coroutines.suspendCancellableCoroutine
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import okhttp3.Call
import okhttp3.Callback
import okhttp3.FormBody
import okhttp3.HttpUrl
import okhttp3.HttpUrl.Companion.toHttpUrlOrNull
import okhttp3.MediaType
import okhttp3.MediaType.Companion.toMediaType
import okhttp3.OkHttpClient
import okhttp3.Request
import okhttp3.RequestBody
import okhttp3.RequestBody.Companion.toRequestBody
import okhttp3.Response
import org.json.JSONArray
import org.json.JSONObject
import org.json.JSONTokener
import java.io.IOException
import java.util.concurrent.TimeUnit

/**
 * Порт `translator.py` — переводчик с цепочкой провайдеров и кешем.
 *
 * Цепочка: Zen (opencode.ai) → Google Translate (unofficial gtx) →
 * DeepL (unofficial JSON-RPC) → офлайн-словарь [OfflineDict].
 * Движок `ENGINE_OFFLINE` жёстко обходится без сети: провайдеры не вызываются
 * вообще, работает только словарь из ассетов.
 *
 * Отличия от десктопа:
 * - удалённые провайдеры OrcaRouter (404) и OpenRouter (403) не обрабатываются:
 *   `setEngine("orcarouter")` переключает на `auto` и пишет предупреждение в лог
 *   вместо обращения к мёртвым адресам;
 * - `Settings.Translate.ZEN_KEY` (если задан) уходит в `Authorization: Bearer`;
 *   `Settings.Translate.DEEPL_KEY` переключает DeepL на официальный бесплатный
 *   endpoint — десктопный неофициальный ключ не принимает;
 * - проверка `Settings.Translate.ENABLED` остаётся на вызывающей стороне
 *   (десктоп — `gui.py:_translate_for_tts`).
 */
class Translator(context: Context, private val settings: Settings) {

    /**
     * Офлайн-словарь разрешён только для OCR-пути. Для озвучки его выключают
     * (порт `allow_offline_dict`): пословный перевод звучит хуже молчания.
     */
    var allowOfflineDict: Boolean = true

    private val offline = OfflineDict.get(context)

    private val http: OkHttpClient = OkHttpClient.Builder()
        .connectTimeout(CONNECT_TIMEOUT_S, TimeUnit.SECONDS)
        .readTimeout(TIMEOUT_S, TimeUnit.SECONDS)
        .writeTimeout(TIMEOUT_S, TimeUnit.SECONDS)
        .callTimeout(TIMEOUT_S, TimeUnit.SECONDS)
        .retryOnConnectionFailure(true)
        .addInterceptor { chain ->
            // Один keep-alive клиент на процесс (порт requests.Session) плюс
            // браузерный User-Agent: Google отдаёт 429 ботам без него.
            val request = chain.request()
            if (request.header("User-Agent") != null) {
                chain.proceed(request)
            } else {
                chain.proceed(request.newBuilder().header("User-Agent", USER_AGENT).build())
            }
        }
        .build()

    /** Короткий клиент для проверки соединения (десктоп — timeout 15 с). */
    private val probeHttp: OkHttpClient by lazy {
        http.newBuilder().callTimeout(PROBE_TIMEOUT_S, TimeUnit.SECONDS).build()
    }

    @Volatile
    private var engineId: String = normalizeEngine(settings.get(Settings.Translate.ENGINE, ENGINE_OFFLINE))

    /** Текущий движок: [availableEngines]. */
    val engine: String get() = engineId

    // ═══════════════════════════════════════════════════════════
    // Публичный API
    // ═══════════════════════════════════════════════════════════

    /**
     * Переводит текст, пробуя провайдеры выбранного движка по порядку.
     *
     * @param src код исходного языка или `auto`; пустое значение — из настроек.
     * @param dst код целевого языка; пустое значение — из настроек.
     * @return перевод либо маркер отказа вида `[...]`, если не сработал никто.
     */
    suspend fun translate(text: String, src: String = "auto", dst: String = "ru"): String {
        if (text.isBlank()) return ""
        val source = src.ifBlank { settings.get(Settings.Translate.SRC_LANG, "auto") }
        val target = dst.ifBlank { settings.get(Settings.Translate.DST_LANG, "ru") }
        val input = text.trim()

        val key = CacheKey(source, target, input)
        cacheGet(key)?.let { return it }

        val started = System.nanoTime()
        val result = when (engineId) {
            ENGINE_OFFLINE -> offlineOnly(input, source, target, key)
            ENGINE_ZEN -> zenOnly(input, source, target, key)
            ENGINE_GOOGLE -> useProvider("Google", key) { translateGoogle(input, source, target) }
            ENGINE_DEEPL -> useProvider("DeepL", key) { translateDeepl(input, source, target) }
            else -> autoChain(input, source, target, key)
        }
        val ms = (System.nanoTime() - started) / 1_000_000
        if (result.isNotEmpty() && !isFailureMarker(result)) {
            Log.d(TAG, "[Translator] $engineId '$source'->'$target' in ${ms}ms: ${result.take(60)}")
        }
        return result
    }

    /**
     * Проверка доступности текущего движка: для `offline` — что словарь
     * загрузился, для сетевых — реальный запрос минимальным текстом.
     */
    suspend fun testConnection(): Boolean = when (engineId) {
        ENGINE_OFFLINE -> {
            offline.prepare()
            val ready = offline.isLoaded
            Log.i(TAG, "[Translator] offline dict ready=$ready, entries=${offline.size}")
            ready
        }
        ENGINE_ZEN -> probe("Zen") { zenProbe() }
        ENGINE_GOOGLE -> probe("Google") { translateGoogle(PROBE_TEXT, "en", "ru").isNotEmpty() }
        ENGINE_DEEPL -> probe("DeepL") { translateDeepl(PROBE_TEXT, "en", "ru").isNotEmpty() }
        else -> probe("Zen") { zenProbe() } ||
            probe("Google") { translateGoogle(PROBE_TEXT, "en", "ru").isNotEmpty() } ||
            probe("DeepL") { translateDeepl(PROBE_TEXT, "en", "ru").isNotEmpty() }
    }

    /** Переключает движок и сохраняет выбор в настройках. */
    fun setEngine(engine: String) {
        val id = normalizeEngine(engine)
        engineId = id
        settings.set(Settings.Translate.ENGINE, id)
        Log.i(TAG, "[Translator] engine -> $id")
    }

    /** Список поддерживаемых движков (для UI). */
    fun availableEngines(): List<String> = listOf(
        ENGINE_OFFLINE, ENGINE_ZEN, ENGINE_GOOGLE, ENGINE_DEEPL, ENGINE_AUTO,
    )

    /** Сброс кеша — например, после смены языка или модели. */
    fun clearCache() {
        synchronized(cacheLock) { cache.clear() }
    }

    // ═══════════════════════════════════════════════════════════
    // Цепочки провайдеров
    // ═══════════════════════════════════════════════════════════

    /** `auto`: Zen → Google → DeepL → офлайн (приоритет из translator.py). */
    private suspend fun autoChain(
        text: String,
        src: String,
        dst: String,
        key: CacheKey,
    ): String {
        for (model in zenCandidates()) {
            val hit = useProvider("Zen/$model", key) { translateZen(text, src, dst, model) }
            if (hit.isNotEmpty()) {
                rememberOnline(text, hit)
                return hit
            }
        }

        val google = useProvider("Google", key) { translateGoogle(text, src, dst) }
        if (google.isNotEmpty()) {
            rememberOnline(text, google)
            return google
        }

        val deepl = useProvider("DeepL", key) { translateDeepl(text, src, dst) }
        if (deepl.isNotEmpty()) {
            rememberOnline(text, deepl)
            return deepl
        }

        // ВНИМАНИЕ: словарь переводит ПОСЛОВНО и даёт мусор
        // («Are you bringing the map?» -> «ЕСТЬ ТЫ ПРИВЕДЕНИЕ КАРТА»),
        // поэтому озвучка его выключает флагом allowOfflineDict.
        val offline = offlineOnly(text, src, dst, key)
        if (offline.isNotEmpty()) return offline

        return FAIL_MARKER
    }

    /** Движок `zen`: перебор моделей, при полном провале — маркер с причиной. */
    private suspend fun zenOnly(
        text: String,
        src: String,
        dst: String,
        key: CacheKey,
    ): String {
        var last = "no models"
        for (model in zenCandidates()) {
            val raw = try {
                translateZen(text, src, dst, model)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Throwable) {
                Log.d(TAG, "[Translator] Zen/$model failed: ${e.message}")
                "Zen/$model: ${e.message}"
            }
            val hit = accept(raw, key, "Zen/$model")
            if (hit.isNotEmpty()) {
                rememberOnline(text, hit)
                return hit
            }
            last = raw
        }
        return "[Zen failed: $last]"
    }

    /** Единственный сетевой-free путь: словарь из ассетов, без обращений наружу. */
    private suspend fun offlineOnly(
        text: String,
        src: String,
        dst: String,
        key: CacheKey,
    ): String {
        if (!allowOfflineDict) return ""
        if (dst != "ru" || (src != "en" && src != "auto")) return ""
        offline.prepare()
        val result = withContext(Dispatchers.Default) { offline.translate(text) }
        if (result.isEmpty()) return ""
        if (offline.hasUntranslated(text)) {
            Log.w(TAG, "[Translator] offline dict gave a rough result for '${text.take(40)}'")
        }
        return cachePut(key, result)
    }

    private suspend fun useProvider(
        provider: String,
        key: CacheKey,
        block: suspend () -> String,
    ): String {
        val raw = try {
            // Вся работа провайдера (сеть + разбор JSON) вне главного потока.
            withContext(Dispatchers.IO) { block() }
        } catch (e: CancellationException) {
            throw e
        } catch (e: Throwable) {
            Log.d(TAG, "[Translator] $provider failed: ${e.message}")
            ""
        }
        return accept(raw, key, provider)
    }

    /**
     * Порт `_accept`: пустой ответ, маркер отказа `[...]` и «непереведённый»
     * текст (лат��ница внутри русского) отбрасываются, принятое — в кеш.
     */
    private fun accept(result: String, key: CacheKey, provider: String): String {
        if (result.isEmpty()) return ""
        if (isFailureMarker(result)) {
            Log.d(TAG, "[Translator] $provider returned a failure marker: $result")
            return ""
        }
        if (looksUntranslated(result, key.dst)) {
            Log.w(TAG, "[Translator] $provider returned untranslated text, dropped: '${result.take(60)}'")
            return ""
        }
        return cachePut(key, result)
    }

    /**
     * Онлайн-перевод запоминается офлайн-словарём (порт `_learned`).
     * Словарь не трогаем, пока он не загружен: незачем читать 2.3 МБ ради
     * одной записи и тормозить первый же сетевой перевод.
     */
    private suspend fun rememberOnline(text: String, translation: String) {
        if (!offline.isLoaded || offline.isLearned(text)) return
        offline.learn(text, translation)
    }

    // ═══════════════════════════════════════════════════════════
    // Zen (opencode.ai) — OpenAI-совместимый chat/completions
    // ═══════════════════════════════════════════════════════════

    private suspend fun translateZen(text: String, src: String, dst: String, model: String): String {
        val dstName = LANG_NAMES[dst] ?: dst
        val prompt = if (src == "auto") {
            "Translate the following text to $dstName. " +
                "Output ONLY the translated text, nothing else.\n\n$text"
        } else {
            val srcName = LANG_NAMES[src] ?: src
            "Translate the following text from $srcName to $dstName. " +
                "Output ONLY the translated text, nothing else.\n\n$text"
        }

        val body = JSONObject()
            .put("model", model.ifBlank { ZEN_DEFAULT_MODEL })
            .put(
                "messages",
                JSONArray().put(JSONObject().put("role", "user").put("content", prompt)),
            )
            .put("temperature", 0.1)
            .put("max_tokens", MAX_TOKENS)
            .toString()

        val response = postJson(ZEN_URL, body, zenHeaders())
        if (response.code != HTTP_OK) {
            throw IOException("HTTP ${response.code}: ${response.body.take(200)}")
        }
        val choices = JSONObject(response.body).optJSONArray("choices") ?: return ""
        val content = choices.optJSONObject(0)
            ?.optJSONObject("message")
            ?.optString("content", "")
            ?: ""
        return content.trim()
    }

    private suspend fun zenProbe(): Boolean {
        val body = JSONObject()
            .put("model", zenCandidates().first())
            .put(
                "messages",
                JSONArray().put(JSONObject().put("role", "user").put("content", ZEN_PROBE_TEXT)),
            )
            .put("max_tokens", 10)
            .toString()
        val response = postJson(ZEN_URL, body, zenHeaders(), probeHttp)
        if (response.code != HTTP_OK) {
            Log.w(TAG, "[Translator] Zen probe HTTP ${response.code}: ${response.body.take(120)}")
            return false
        }
        val choices = JSONObject(response.body).optJSONArray("choices")
        val content = choices?.optJSONObject(0)
            ?.optJSONObject("message")
            ?.optString("content", "")
            .orEmpty()
        return content.isNotBlank()
    }

    private fun zenHeaders(): Map<String, String> {
        val headers = HashMap<String, String>(4)
        headers["Content-Type"] = "application/json"
        headers["HTTP-Referer"] = ZEN_REFERER
        headers["X-Title"] = ZEN_TITLE
        val key = settings.get(Settings.Translate.ZEN_KEY, "").trim()
        if (key.isNotEmpty()) headers["Authorization"] = "Bearer $key"
        return headers
    }

    /**
     * Модели Zen для перебора: из настроек, затем проверенные.
     * Идентификаторы Zen никогда не содержат «/», поэтому модели формата
     * openrouter/orcarouter отбрасываются без сетевого запроса.
     */
    private fun zenCandidates(): List<String> {
        val out = LinkedHashSet<String>(3)
        val configured = settings.get(Settings.Translate.ZEN_MODEL, "").trim()
        for (candidate in listOf(configured) + ZEN_MODELS) {
            if (candidate.isEmpty() || candidate.contains('/')) continue
            out.add(candidate)
        }
        return if (out.isEmpty()) ZEN_MODELS else out.toList()
    }

    // ═══════════════════════════════════════════════════════════
    // Google Translate (unofficial gtx) с троттлингом и повторами
    // ═══════════════════════════════════════════════════════════

    /**
     * Порт `_google_get`: глобальный лок с интервалом [GOOGLE_MIN_INTERVAL_MS]
     * между запросами, повтор с нарастающей паузой на 429/503, три попытки
     * суммарно. null — все попытки исчерпаны.
     */
    private suspend fun googleGet(url: HttpUrl): HttpResult? {
        for (attempt in GOOGLE_RETRY_DELAYS.indices + 1) {
            if (attempt > 0) {
                val pauseMs = (GOOGLE_RETRY_DELAYS[attempt - 1] * 1000).toLong()
                delay(pauseMs)
            }
            throttleGoogle()

            val response = try {
                get(url)
            } catch (e: CancellationException) {
                throw e
            } catch (e: Throwable) {
                Log.d(TAG, "[Translator] Google request failed: ${e.message}")
                continue
            }
            if (response.code == HTTP_OK) return response
            if (response.code == 429 || response.code == 503) {
                Log.d(TAG, "[Translator] Google throttled (${response.code}), retry")
                continue
            }
            Log.d(TAG, "[Translator] Google HTTP ${response.code}")
            return null
        }
        return null
    }

    /** Порт `_google_lock` + `_GOOGLE_MIN_INTERVAL`: не чаще раза в 1.1 с. */
    private suspend fun throttleGoogle() {
        googleLock.withLock {
            val waitNs = GOOGLE_MIN_INTERVAL_NS - (System.nanoTime() - googleLastCallNs)
            if (waitNs > 0) delay(waitNs / 1_000_000)
            googleLastCallNs = System.nanoTime()
        }
    }

    private suspend fun translateGoogle(text: String, src: String, dst: String): String {
        val url = GOOGLE_URL.toHttpUrlOrNull()
            ?.newBuilder()
            ?.addQueryParameter("client", "gtx")
            ?.addQueryParameter("sl", src)
            ?.addQueryParameter("tl", dst)
            ?.addQueryParameter("dt", "t")
            ?.addQueryParameter("q", text)
            ?.build()
            ?: throw IOException("malformed Google URL")

        val response = googleGet(url) ?: return ""
        val parsed = JSONTokener(response.body).nextValue() as? JSONArray ?: return ""

        val segments = parsed.optJSONArray(0) ?: return ""
        val translated = StringBuilder(text.length + 16)
        for (i in 0 until segments.length()) {
            val part = segments.optJSONArray(i) ?: continue
            val chunk = part.optString(0, "")
            if (chunk.isNotEmpty()) translated.append(chunk)
        }
        val result = translated.toString().trim()
        if (result.isNotEmpty() && result != text.trim()) return result

        // Google вернул исходник: это нормально, если текст уже на языке dst.
        val detected = parsed.optJSONArray(2)?.optString(0, "").orEmpty()
        if (detected == dst) return text.trim()
        return ""
    }

    // ═══════════════════════════════════════════════════════════
    // DeepL — неофициальный JSON-RPC либо официальный free по ключу
    // ═══════════════════════════════════════════════════════════

    private suspend fun translateDeepl(text: String, src: String, dst: String): String {
        val key = settings.get(Settings.Translate.DEEPL_KEY, "").trim()
        val sourceLang = if (src == "auto") "EN" else (DEEPL_LANGS[src] ?: "EN")
        val targetLang = DEEPL_LANGS[dst] ?: "RU"
        return if (key.isNotEmpty()) {
            translateDeeplOfficial(text, sourceLang, targetLang, key)
        } else {
            translateDeeplFree(text, sourceLang, targetLang)
        }
    }

    /** Порт `_translate_deepl_free`: https://www2.deepl.com/jsonrpc, ключ не нужен. */
    private suspend fun translateDeeplFree(text: String, sourceLang: String, targetLang: String): String {
        val texts = JSONArray().put(
            JSONObject().put("text", text).put("requestAlternatives", 0),
        )
        val params = JSONObject()
            .put("texts", texts)
            .put("splitting", "newlines")
            .put(
                "lang",
                JSONObject()
                    .put("source_lang_user_selected", sourceLang)
                    .put("target_lang", targetLang),
            )
            .put(
                "commonJobParams",
                JSONObject().put("wasSpoken", false).put("transcribe_as", ""),
            )
        val body = JSONObject()
            .put("jsonrpc", "2.0")
            .put("method", "LMT_handle_texts")
            .put("params", params)
            .toString()

        val headers = HashMap<String, String>(2)
        headers["User-Agent"] = "Mozilla/5.0"
        headers["Content-Type"] = "application/json"
        val response = postJson(DEEPL_URL, body, headers)
        if (response.code != HTTP_OK) {
            throw IOException("HTTP ${response.code}: ${response.body.take(200)}")
        }

        val data = JSONObject(response.body)
        val result = data.optJSONObject("result") ?: return ""
        val items = result.optJSONArray("texts") ?: return ""
        val translated = items.optJSONObject(0)?.optString("text", "").orEmpty().trim()
        if (translated.isNotEmpty() && translated != text.trim()) return translated
        return ""
    }

    /** Официальный бесплатный endpoint — работает, если задан DEEPL_KEY. */
    private suspend fun translateDeeplOfficial(
        text: String,
        sourceLang: String,
        targetLang: String,
        key: String,
    ): String {
        val form = FormBody.Builder()
            .add("text", text)
            .add("target_lang", targetLang)
            .add("source_lang", sourceLang)
            .build()
        val headers = mapOf("Authorization" to "DeepL-Auth-Key $key")
        val response = post(DEEPL_OFFICIAL_URL, form, headers)
        if (response.code != HTTP_OK) {
            throw IOException("HTTP ${response.code}: ${response.body.take(200)}")
        }
        val items = JSONTokener(response.body).nextValue() as? JSONArray ?: return ""
        val translated = items.optJSONObject(0)?.optString("text", "").orEmpty().trim()
        if (translated.isNotEmpty() && translated != text.trim()) return translated
        return ""
    }

    // ═══════════════════════════════════════════════════════════
    // Сеть
    // ═══════════════════════════════════════════════════════════

    private class HttpResult(val code: Int, val body: String)

    private suspend fun postJson(
        url: String,
        json: String,
        headers: Map<String, String> = emptyMap(),
        client: OkHttpClient = http,
    ): HttpResult = post(url, json.toRequestBody(JSON_MEDIA), headers, client)

    private suspend fun post(
        url: String,
        body: RequestBody,
        headers: Map<String, String> = emptyMap(),
        client: OkHttpClient = http,
    ): HttpResult {
        val builder = Request.Builder().url(url).post(body)
        for ((name, value) in headers) builder.header(name, value)
        return execute(builder.build(), client)
    }

    private suspend fun get(url: HttpUrl, client: OkHttpClient = http): HttpResult =
        execute(Request.Builder().url(url).get().build(), client)

    /**
     * Тело ответа читается в колбэке OkHttp (это его собственный поток),
     * поэтому вызывающий поток — главный или любой диспетчер — не блокируется,
     * а отмена корутины отменяет сам запрос.
     */
    private suspend fun execute(request: Request, client: OkHttpClient): HttpResult =
        suspendCancellableCoroutine { continuation ->
            val call = client.newCall(request)
            continuation.invokeOnCancellation { call.cancel() }
            call.enqueue(object : Callback {
                override fun onFailure(call: Call, e: IOException) {
                    if (continuation.isActive) continuation.resumeWithException(e)
                }

                override fun onResponse(call: Call, response: Response) {
                    val result = try {
                        response.use { HttpResult(it.code, it.body?.string() ?: "") }
                    } catch (e: IOException) {
                        if (continuation.isActive) continuation.resumeWithException(e)
                        return
                    }
                    if (continuation.isActive) {
                        continuation.resumeWith(Result.success(result))
                    }
                }
            })
        }

    private suspend fun <T> probe(name: String, block: suspend () -> T): Boolean = try {
        withContext(Dispatchers.IO) { block() }
    } catch (e: CancellationException) {
        throw e
    } catch (e: Throwable) {
        Log.d(TAG, "[Translator] $name probe failed: ${e.message}")
        false
    }

    // ═══════════════════════════════════════════════════════════
    // Кеш
    // ═══════════════════════════════════════════════════════════

    private data class CacheKey(val src: String, val dst: String, val text: String)

    /** Порядок вставки = порядок вытеснения, как у dict в Python. */
    private val cache = LinkedHashMap<CacheKey, String>(CACHE_MAX)
    private val cacheLock = Any()

    private fun cacheGet(key: CacheKey): String? = synchronized(cacheLock) { cache[key] }

    private fun cachePut(key: CacheKey, value: String): String = synchronized(cacheLock) {
        if (cache.size >= CACHE_MAX) {
            // Выбросим половину (FIFO-подобное усечение, порт _cache_put).
            val keys = cache.keys.toList()
            for (i in 0 until CACHE_MAX / 2) cache.remove(keys[i])
        }
        cache[key] = value
        value
    }

    // ═══════════════════════════════════════════════════════════
    // Служебное
    // ═══════════════════════════════════════════════════════════

    private fun normalizeEngine(value: String): String {
        val id = value.trim().lowercase()
        if (id in availableEngines()) return id
        Log.w(
            TAG,
            "[Translator] engine '$id' unknown or removed (OrcaRouter/OpenRouter " +
                "endpoints are dead) — falling back to $ENGINE_AUTO",
        )
        return ENGINE_AUTO
    }

    companion object {
        private const val TAG = "ScreenOCR"

        const val ENGINE_OFFLINE = "offline"
        const val ENGINE_ZEN = "zen"
        const val ENGINE_GOOGLE = "google"
        const val ENGINE_DEEPL = "deepl"
        const val ENGINE_AUTO = "auto"

        const val ZEN_URL = "https://opencode.ai/zen/v1/chat/completions"
        const val GOOGLE_URL = "https://translate.googleapis.com/translate_a/single"
        const val DEEPL_URL = "https://www2.deepl.com/jsonrpc"
        const val DEEPL_OFFICIAL_URL = "https://api-free.deepl.com/v2/translate"

        /**
         * Модели Zen, доступные без ключа (проверено 26.09.2026):
         * space-bunny-free -> HTTP 200 с точным русским. Остальные free-модели
         * отдают 403 FreeTierError «can only be used from within OpenCode».
         */
        val ZEN_MODELS: List<String> = listOf("space-bunny-free")

        private const val ZEN_DEFAULT_MODEL = "space-bunny-free"
        private const val ZEN_REFERER = "https://github.com/sj0404-collab/overlay-translator"
        private const val ZEN_TITLE = "ScreenOCR_TTS"
        private const val ZEN_PROBE_TEXT = "Say OK"
        private const val PROBE_TEXT = "Hello"
        private const val MAX_TOKENS = 4096

        /** Паузы перед повторами Google при 429/503 (translator.py:69). */
        private val GOOGLE_RETRY_DELAYS = doubleArrayOf(1.5, 4.0)
        private const val GOOGLE_MIN_INTERVAL_NS = 1_100_000_000L

        /** Русские цели, для которых латиница в ответе = «перевод не состоялся». */
        private val CYRILLIC_TARGETS = setOf("ru", "uk", "be", "bg")

        /** Латинское слово внутри русского текста: перевод suspicious. */
        private val LATIN_WORD = Regex("(?<![A-Za-z])([a-z]{2,})(?![A-Za-z])")

        private const val FAIL_MARKER = "[Translation failed: all services unavailable]"
        private const val CACHE_MAX = 500

        private const val HTTP_OK = 200
        private const val TIMEOUT_S = 30L
        private const val PROBE_TIMEOUT_S = 15L
        private const val CONNECT_TIMEOUT_S = 15L

        private val USER_AGENT = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) " +
            "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36"
        private val JSON_MEDIA: MediaType = "application/json; charset=utf-8".toMediaType()

        /** Названия языков для промпта LLM. */
        private val LANG_NAMES: Map<String, String> = mapOf(
            "auto" to "the appropriate language",
            "en" to "English", "ru" to "Russian", "ja" to "Japanese",
            "ko" to "Korean", "zh" to "Chinese", "de" to "German",
            "fr" to "French", "es" to "Spanish", "it" to "Italian",
            "pt" to "Portuguese", "ar" to "Arabic", "hi" to "Hindi",
            "tr" to "Turkish", "pl" to "Polish", "nl" to "Dutch",
            "sv" to "Swedish", "fi" to "Finnish", "uk" to "Ukrainian",
            "cs" to "Czech", "el" to "Greek", "he" to "Hebrew",
            "th" to "Thai", "vi" to "Vietnamese", "id" to "Indonesian",
            "ms" to "Malay",
        )

        /** Коды DeepL (порядок и набор — из translator.py:417). */
        private val DEEPL_LANGS: Map<String, String> = mapOf(
            "en" to "EN", "ru" to "RU", "de" to "DE", "fr" to "FR", "es" to "ES",
            "it" to "IT", "pt" to "PT", "ja" to "JA", "zh" to "ZH", "ko" to "KO",
            "nl" to "NL", "pl" to "PL", "uk" to "UK", "tr" to "TR",
        )

        /** Маркер отказа провайдера: `[Zen failed: ...]`, `[Translation failed...]`. */
        private fun isFailureMarker(text: String): Boolean =
            text.length > 1 && text.startsWith("[") && text.endsWith("]")

        /**
         * Порт `looks_untranslated`: русский текст с нетронутыми латинскими
         * словами («Adventure время»). Имена вроде Genshin/Paimon начинаются
         * с заглавной и потому допускаются.
         */
        fun looksUntranslated(text: String, dst: String = "ru"): Boolean {
            if (text.isEmpty() || dst !in CYRILLIC_TARGETS) return false
            return LATIN_WORD.containsMatchIn(text)
        }

        // Лок и метка последнего вызова Google — общие для всех экземпляров
        // (в Python это были глобальные переменные модуля).
        private val googleLock = Mutex()
        private var googleLastCallNs = 0L
    }
}

