// Zen (opencode.ai) — OpenAI-совместимый chat/completions
// ═══════════════════════════════════════════════════════════

private suspend fun translateZen(text: String, src: String, dst: String, model: String): String {
    val dstName = LANG_NAMES[dst] ?: dst
    val prompt = if (src == "auto") {
        "Translate the following text to $dstName. " +
            "Output ONLY the translated text, nothing else.\n\n$text"
    } else {
        val srcName = LANG_NAMES[src] ?: src
        "Translate the following text from $srcName to $dstName. " +
            "Output ONLY the translated text, nothing else.\n\n$text"
    }

    val body = JSONObject()
        .put("model", model.ifBlank { ZEN_DEFAULT_MODEL })
        .put(
            "messages",
            JSONArray().put(JSONObject().put("role", "user").put("content", prompt)),
        )
        .put("temperature", 0.1)
        .put("max_tokens", MAX_TOKENS)
        .toString()

    val response = postJson(ZEN_URL, body, zenHeaders())
    if (response.code != HTTP_OK) {
        throw IOException("HTTP ${response.code}: ${response.body.take(200)}")
    }
    val choices = JSONObject(response.body).optJSONArray("choices") ?: return ""
    val content = choices.optJSONObject(0)
        ?.optJSONObject("message")
        ?.optString("content", "")
        ?: ""
    return content.trim()
}

private suspend fun zenProbe(): Boolean {
    val body = JSONObject()
        .put("model", zenCandidates().first())
        .put(
            "messages",
            JSONArray().put(JSONObject().put("role", "user").put("content", ZEN_PROBE_TEXT)),
        )
        .put("max_tokens", 10)
        .toString()
    val response = postJson(ZEN_URL, body, zenHeaders(), probeHttp)
    if (response.code != HTTP_OK) {
        Log.w(TAG, "[Translator] Zen probe HTTP ${response.code}: ${response.body.take(120)}")
        return false
    }
    val choices = JSONObject(response.body).optJSONArray("choices")
    val content = choices?.optJSONObject(0)
        ?.optJSONObject("message")
        ?.optString("content", "")
        .orEmpty()
    return content.isNotBlank()
}

private fun zenHeaders(): Map<String, String> {
    val headers = HashMap<String, String>(4)
    headers["Content-Type"] = "application/json"
    headers["HTTP-Referer"] = ZEN_REFERER
    headers["X-Title"] = ZEN_TITLE
    val key = settings.get(Settings.Translate.ZEN_KEY, "").trim()
    if (key.isNotEmpty()) headers["Authorization"] = "Bearer $key"
    return headers
}

/**
 * Модели Zen для перебора: из настроек, затем проверенные.
 * Идентификаторы Zen никогда не содержат «/», поэтому модели формата
 * openrouter/orcarouter отбрасываются без сетевого запроса.
 */
private fun zenCandidates(): List<String> {
    val out = LinkedHashSet<String>(3)
    val configured = settings.get(Settings.Translate.ZEN_MODEL, "").trim()
    for (candidate in listOf(configured) + ZEN_MODELS) {
        if (candidate.isEmpty() || candidate.contains('/')) continue
        out.add(candidate)
    }
    return if (out.isEmpty()) ZEN_MODELS else out.toList()
}

