    private data class CacheKey(val src: String, val dst: String, val text: String)

    /** Порядок вставки = порядок вытеснения, как у dict в Python. */
    private val cache = LinkedHashMap<CacheKey, String>(CACHE_MAX)
    private val cacheLock = Any()

    private fun cacheGet(key: CacheKey): String? = synchronized(cacheLock) { cache[key] }

    private fun cachePut(key: CacheKey, value: String): String = synchronized(cacheLock) {
        if (cache.size >= CACHE_MAX) {
            // Выбросим половину (FIFO-подобное усечение, порт _cache_put).
            val keys = cache.keys.toList()
            for (i in 0 until CACHE_MAX / 2) cache.remove(keys[i])
        }
        cache[key] = value
        value
    }

