package com.screenocr.tts.translate

import android.content.Context
import android.content.res.AssetManager
import android.util.Log
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import org.json.JSONObject
import java.io.File

/**
 * Порт `offline_dict.py` — офлайн-переводчик EN→RU по словарю из ассетов.
 *
 * Сеть не используется ни при каких обстоятельствах: это единственный
 * переводчик, доступный в режиме `Translator.ENGINE_OFFLINE` (работа без
 * интернета). Провайдеры Zen/Google/DeepL живут в [Translator].
 *
 * ## Отличие от оригинала
 *
 * В Python для каждой многословной фразы на каждый вызов `translate()`
 * компилировался новый `re.Pattern` и делался полный проход по строке —
 * 191 мс на короткую фразу, 47 с на страницу. Здесь при загрузке словаря
 * один раз строится бор (trie) по многословным фразам, и перевод — это
 * один проход по токенам: O(n · maxLen фразы) вместо O(n · фраз).
 *
 * Ещё одно отличие, намеренное: токены — это максимальные участки из
 * символов «слово» (буквы/цифры/подчёркивание), а не результат
 * `str.split()`. Для OCR-текста это важно: «Level 5,Boss» в Python давал
 * один токен `level5boss` (промах по словарю), здесь — `level`, `5`, `boss`.
 * Пунктуация при этом, как и в оригинале, в перевод не попадает.
 *
 * Первая загрузка (парсинг 2.3 МБ JSON) занимает сотни миллисекунд —
 * вызывайте [prepare] из фонового потока. [Translator] делает это сам
 * перед первым офлайн-переводом.
 */
class OfflineDict private constructor(context: Context) {

    private val assets: AssetManager = context.applicationContext.assets
    private val filesDir: File = context.applicationContext.filesDir

    private val loadLock = Any()
    @Volatile private var data: DictData? = null

    /** Число записей словаря (однословных + многословных фраз). */
    val size: Int get() = data?.size ?: 0

    /** Словарь уже разобран. */
    val isLoaded: Boolean get() = data != null

    /**
     * Прогревает загрузку словаря (I/O + парсинг) в фоновом потоке.
     * Идемпотентна и потокобезопасна.
     */
    suspend fun prepare() {
        if (data == null) withContext(Dispatchers.IO) { ensureLoaded() }
    }

    /**
     * Пословный перевод EN→RU.
     *
     * Конвейер: lower-case → раскрытие сокращений → поиск многословных фраз
     * (longest match) → пословный перевод с отбрасыванием артиклей → сборка.
     */
    fun translate(text: String): String {
        if (text.isEmpty()) return ""
        val d = data ?: ensureLoaded()

        val normalized = Contractions.expand(text.lowercase().trim())
        if (normalized.isEmpty()) return ""

        val tokens = ArrayList<String>(16)
        tokenizeInto(normalized, tokens)
        if (tokens.isEmpty()) return ""

        // Строки, переведённые ранее онлайн-провайдером, отдаём как есть
        // (порт _learned из offline_dict.py).
        d.learnedLookup(normalized)?.let { return it }
        d.exactPhrase(tokens)?.let { return it }

        val out = StringBuilder(normalized.length + 32)
        var first = true
        var i = 0
        while (i < tokens.size) {
            val phrase = d.longestPhrase(tokens, i)
            if (phrase != null) {
                if (!first) out.append(' ')
                out.append(phrase.value)
                first = false
                i += phrase.length
                continue
            }
            val token = tokens[i]
            i++
            if (token in ARTICLES) continue
            val value = d.words[token] ?: token
            if (!first) out.append(' ')
            out.append(value)
            first = false
        }
        return out.toString()
    }

    /**
     * Порт `has_untranslated`: грубые признаки некачественного пословного
     * перевода — «залипшие» латинские слова, почти совпадающий с исходником
     * текст или подозрительно короткий результат.
     */
    fun hasUntranslated(text: String): Boolean {
        val result = translate(text)
        if (result.isEmpty()) return true
        val resultWords = words(result)
        for (chunk in resultWords) {
            val latinLettersOnly = chunk.length > 2 &&
                chunk.all { it.code < 128 } &&
                chunk.all { it.isLetter() }
            if (latinLettersOnly) return true
        }
        val source = words(text.lowercase()).toSet()
        val target = resultWords.map { it.lowercase() }.toSet()
        if (target.intersect(source).size > source.size * 0.5) return true
        if (resultWords.size < words(text).size * 0.4) return true
        return false
    }

    /**
     * Есть ли уже запомненный перевод такой строки. Не вызывает загрузку
     * словаря: вызывающий сам решает, стоит ли её запускать.
     */
    fun isLearned(text: String): Boolean {
        val d = data ?: return false
        return d.learnedLookup(text.lowercase().trim()) != null
    }

    /**
     * Запоминает удачный онлайн-перевод для последующих офлайн-вызовов
     * (порт `_learned[key] = online; _save_learned()`). Пишет в filesDir.
     */
    suspend fun learn(text: String, translation: String) {
        val key = text.lowercase().trim()
        if (key.isEmpty() || translation.isBlank()) return
        withContext(Dispatchers.IO) {
            val d = ensureLoaded()
            d.learnedPut(key, translation.trim())
            saveLearned(d.learnedSnapshot())
        }
    }

    // ── Загрузка словаря ─────────────────────────────────────────────

    private fun ensureLoaded(): DictData {
        data?.let { return it }
        synchronized(loadLock) {
            data?.let { return it }
            val startedNs = System.nanoTime()
            val built = buildData()
            data = built
            val ms = (System.nanoTime() - startedNs) / 1_000_000
            Log.i(
                TAG,
                "[OfflineDict] ${built.size} entries " +
                    "(${built.words.size} words, ${built.phrases} phrases, " +
                    "${built.learnedSize} learned) loaded in ${ms}ms",
            )
            return built
        }
    }

    private fun buildData(): DictData {
        val words = HashMap<String, String>(1 shl 17)
        val root = PhraseNode()
        val tokens = ArrayList<String>(8)
        var phrases = 0
        var maxPhraseLen = 1

        val raw = readAsset(DICT_ASSET)

