        var phrases = 0
        var maxPhraseLen = 1

        val raw = readAsset(DICT_ASSET)
        if (raw != null) {
            // На Android у org.json нет JSONObject(Reader) — читаем ассет в строку.
            val json = JSONObject(raw)
            val keys = json.keys()
            while (keys.hasNext()) {
                val key = keys.next()
                val value = json.opt(key) as? String ?: continue
                if (value.isEmpty()) continue
                tokens.clear()
                tokenizeInto(key, tokens)
                when {
                    tokens.isEmpty() -> continue
                    // Ключ нормализуем по токену: "-curtains" станет "curtains",
                    // иначе он недостижим при переводе (пунктуация срезается).
                    tokens.size == 1 -> words[tokens[0]] = value
                    else -> {
                        var node = root
                        for (token in tokens) {
                            node = node.children.getOrPut(token) { PhraseNode() }
                        }
                        if (node.value == null) {
                            node.value = value
                            phrases++
                            if (tokens.size > maxPhraseLen) maxPhraseLen = tokens.size
                        }
                    }
                }
            }
        }

        return DictData(
            words = words,
            phrases = phrases,
            maxPhraseLen = maxPhraseLen,
            learned = loadLearned(),
            root = root,
        )
    }

    private fun readAsset(name: String): String? = try {
        assets.open(name).use { input -> input.readBytes().toString(Charsets.UTF_8) }
    } catch (e: Exception) {
        Log.w(TAG, "[OfflineDict] asset '$name' unavailable: ${e.message}")
        null
    }

    private fun loadLearned(): MutableMap<String, String> {
        val file = File(filesDir, LEARNED_FILE)
        if (!file.exists()) return HashMap()
        return try {
            val json = JSONObject(file.readText(Charsets.UTF_8))
            val out = HashMap<String, String>((json.length() * 2).coerceAtLeast(16))
            val keys = json.keys()
            while (keys.hasNext()) {
                val key = keys.next()
                val value = json.opt(key) as? String ?: continue
                if (key.isNotEmpty() && value.isNotEmpty()) out[key] = value
            }
            out
        } catch (e: Exception) {
            Log.w(TAG, "[OfflineDict] learned dict ignored: ${e.message}")
            HashMap()
        }
    }

    private fun saveLearned(learned: Map<String, String>) {
        try {
            val json = JSONObject()
            for ((key, value) in learned) json.put(key, value)
            val target = File(filesDir, LEARNED_FILE)
            val tmp = File(filesDir, "$LEARNED_FILE.tmp")
            tmp.writeText(json.toString(), Charsets.UTF_8)
            // Запись через временный файл: битый learned_dict.json не должен
            // ломать перевод на всех следующих запусках.
            if (!tmp.renameTo(target)) {
                tmp.copyTo(target, overwrite = true)
                tmp.delete()
            }
        } catch (e: Exception) {
            Log.w(TAG, "[OfflineDict] learned dict not saved: ${e.message}")
        }
    }

    // ── Токенизация ──────────────────────────────────────────────────

    /**
     * `\w` из Python — это Unicode-слово (буквы, цифры, подчёркивание);
     * в Java `Character.isLetterOrDigit` даёт тот же результат для наших
     * данных, в том числе для кириллицы.
     */
    private fun isWordChar(c: Char): Boolean =
        c in 'a'..'z' || c in 'A'..'Z' || c in '0'..'9' || c == '_' ||
            (c.code > 127 && Character.isLetterOrDigit(c))

    private fun tokenizeInto(text: String, out: MutableList<String>) {
        var start = -1
        for (i in text.indices) {
            if (isWordChar(text[i])) {
                if (start < 0) start = i
            } else if (start >= 0) {
                out.add(text.substring(start, i))
                start = -1
            }
        }
        if (start >= 0) out.add(text.substring(start))
    }

    /** Аналог `str.split()` в Python: только по пробельным символам, без пустых. */
    private fun words(text: String): List<String> =
        text.split(WHITESPACE).filter { it.isNotEmpty() }

    // ── Данные словаря ───────────────────────────────────────────────

    /** Узел бора многословных фраз: дети — следующие слова, [value] — перевод. */
    private class PhraseNode {
        val children = HashMap<String, PhraseNode>(4)
        var value: String? = null
    }

    private class PhraseMatch(val length: Int, val value: String)

    private class DictData(
        val words: HashMap<String, String>,
        val phrases: Int,
        val maxPhraseLen: Int,
        val learned: MutableMap<String, String>,
        private val root: PhraseNode,
    ) {
        val size: Int get() = words.size + phrases

        @Synchronized
        fun learnedLookup(key: String): String? = learned[key]

        @Synchronized
        fun learnedPut(key: String, value: String) {
            learned[key] = value
        }

        @Synchronized
        fun learnedSnapshot(): Map<String, String> = HashMap(learned)

        @get:Synchronized
        val learnedSize: Int get() = learned.size

        /** Весь текст целиком является ключом словаря (например «good morning»). */
        fun exactPhrase(tokens: List<String>): String? {
            if (tokens.size < 2) return null
            val match = longestPhrase(tokens, 0) ?: return null
            return if (match.length == tokens.size) match.value else null
        }

        /**
         * Longest match фразы, начинающейся в [from]: спускаемся по бору так
         * глубоко, как позволяет словарь, и запоминаем самый глубокий узел
         * с переводом. Возвращает [PhraseMatch] либо null.
         */
        fun longestPhrase(tokens: List<String>, from: Int): PhraseMatch? {
            val limit = minOf(tokens.size, from + maxPhraseLen)
            var node = root
            var bestLength = 0
            var bestValue: String? = null
            for (i in from until limit) {
                node = node.children[tokens[i]] ?: break
                val value = node.value
                if (value != null) {
                    bestLength = i - from + 1
                    bestValue = value
                }
            }
            val value = bestValue ?: return null
            return PhraseMatch(bestLength, value)
        }
    }

    companion object {
        private const val TAG = "ScreenOCR"
        private const val DICT_ASSET = "dict/en_rus_full.json"
        private const val LEARNED_FILE = "learned_dict.json"

        /** Артикли отбрасываются: в русском их нет (порт _ARTICLES). */
        private val ARTICLES = setOf("the", "a", "an")

        private val WHITESPACE = Regex("\\s+")

        @Volatile
        private var instance: OfflineDict? = null

        /** Процессный синглтон: словарь 68k записей грузится один раз. */
        fun get(context: Context): OfflineDict = instance ?: synchronized(this) {
            instance ?: OfflineDict(context).also { instance = it }
        }
    }
}

