        for ch in word:
            if "a" <= ch.lower() <= "z":
                if ch not in _LAT_HOMOGLYPHS:
                    lat_unique += 1
            elif ("а" <= ch.lower() <= "я") or ch in ("ё", "Ё", "і", "І", "ї", "Ї", "є", "Є"):
