        windows = [crop.crop((s, 0, min(crop.width, s + win_w), crop.height))
                   for s in starts]

    texts: List[str] = []
    conf_sum, conf_count = 0.0, 0
    coverage = 0.0
    n_lat_total, n_cyr_total = 0, 0
    for win in windows:
        text, conf, _emitted, cov, n_lat, n_cyr = self._infer_window(
            win, model, chars)
        texts.append(text)
        conf_sum += conf
        conf_count += 1
        coverage = max(coverage, cov)
        n_lat_total += n_lat
        n_cyr_total += n_cyr
    merged = self._merge_window_texts(texts)
    conf = conf_sum / conf_count if conf_count else 0.0
    return Recognition(text=merged, confidence=conf, model=model_name,
                       coverage=coverage, n_lat=n_lat_total,
                       n_cyr=n_cyr_total)

# Canonical homoglyph map for overlap comparison only: unifies
# Cyrillic/Ukrainian lookalikes to one base so a 1-char script
# confusion (і/и, о/o, е/e) between windows does not break merging.
_MERGE_CANON = {
    'а': 'a', 'с': 'c', 'е': 'e', 'о': 'o', 'р': 'p', 'х': 'x', 'у': 'y',
    'А': 'a', 'В': 'b', 'С': 'c', 'Е': 'e', 'Н': 'h', 'К': 'k', 'М': 'm',
    'О': 'o', 'Р': 'p', 'Т': 't', 'Х': 'x', 'У': 'y',
    'і': 'i', 'І': 'i', 'ї': 'i', 'є': 'e', 'Є': 'e', 'ґ': 'g', 'Ґ': 'g',
    'ё': 'е', 'Ё': 'е',
}

@classmethod
def _canon(cls, s: str) -> str:
    return "".join(cls._MERGE_CANON.get(c, c).lower() for c in s)

@classmethod
def _merge_window_texts(cls, texts: List[str]) -> str:
    # Overlapping windows share content: append only the non-overlapping
    # tail. Window cuts can drop edge glyphs, so the shared content is
    # found as a longest common SUBSTRING between the merged tail and
    # the next window head (not just affix), compared in canonical
    # homoglyph form; splicing keeps the original strings.
    merged = texts[0] if texts else ""
    for nxt in texts[1:]:
        if not nxt:
            continue
        if not merged:
            merged = nxt
            continue
        tail = cls._canon(merged[-48:])
        head = cls._canon(nxt[:48])
        best_k, best_L = 0, 0
        for k in range(0, min(24, len(nxt))):
            maxL = min(len(nxt) - k, len(tail))
            for L in range(maxL, 3, -1):
                if L > best_L and head[k:k + L] in tail:
                    best_k, best_L = k, L
                    break
            if best_L >= 8:
                break
        merged += nxt[best_k + best_L:]
    return merged

def _infer_window(self, crop: Image.Image, model, chars: List[str]):
    rec_img = Image.new("RGB", (RECOGNIZER_WIDTH, RECOGNIZER_HEIGHT), (128, 128, 128))
    scale = RECOGNIZER_HEIGHT / max(1, crop.height)
    target_w = min(RECOGNIZER_WIDTH, max(1, int(crop.width * scale)))
    resized = crop.resize((target_w, RECOGNIZER_HEIGHT), Image.Resampling.LANCZOS)
    rec_img.paste(resized, (0, 0))

    arr = np.array(rec_img, dtype=np.float32)
    arr = arr[:, :, ::-1]  # RGB -> BGR
    arr = (arr / 255.0 - 0.5) / 0.5

    inp = model.get_input_details()
    out = model.get_output_details()
    model.set_tensor(inp[0]['index'], arr.reshape(1, RECOGNIZER_HEIGHT, RECOGNIZER_WIDTH, 3))
    model.invoke()
    values = model.get_tensor(out[0]['index'])

    # Output shape: (1, steps, num_classes) - raw logits (see CtcScoring.softmax).
    # Classes come from actual output size, not dict length (165 vs 163+1).
    if values.ndim == 3:
        seq = values[0]  # (steps, num_classes)
        _steps, num_classes = seq.shape
        return self._decode_ctc(seq.reshape(-1), chars, int(num_classes))
    return ("", 0.0, 0, 0.0, 0, 0)

def _decode_ctc(self, values: np.ndarray, chars: List[str], num_classes: int):
    if num_classes <= 1 or len(values) < num_classes:
        return ("", 0.0, 0, 0.0, 0, 0)

    # Per-class script flags for EN/RU routing (digits/punct neutral).
    is_lat = [False] * num_classes
    is_cyr = [False] * num_classes
    for idx in range(1, num_classes):
        if idx - 1 >= len(chars):
            continue
        ch = chars[idx - 1]
        if len(ch) == 1:
            if "a" <= ch <= "z" or "A" <= ch <= "Z":
                is_lat[idx] = True
            elif 0x0400 <= ord(ch) <= 0x052F or 0xA640 <= ord(ch) <= 0xA69F:
                is_cyr[idx] = True

    steps = len(values) // num_classes
    text_parts = []
    prev = -1
    conf_sum = 0.0
    conf_count = 0
    blank_steps = 0
    counting_blanks = False
    n_lat = 0
    n_cyr = 0

    for step in range(steps):
        base = step * num_classes
        logits = values[base:base + num_classes]
        max_logit = np.max(logits)
        exp_logits = np.exp(logits - max_logit)
        probs = exp_logits / np.sum(exp_logits)

        best_idx = 0
        best_score = probs[0]
        best_lat = 0.0
        best_cyr = 0.0
        for idx in range(1, num_classes):
            # Match Kotlin: chars.getOrNull(idx-1).orEmpty() + allowed('')
            # Out-of-range classes (164/165, 851/852) are skipped.
            char = chars[idx - 1] if idx - 1 < len(chars) else ''
            if not self._allowed(char):
                continue
            if probs[idx] > best_score:
                best_score = probs[idx]
                best_idx = idx
            if is_lat[idx] and probs[idx] > best_lat:
                best_lat = probs[idx]
            elif is_cyr[idx] and probs[idx] > best_cyr:
                best_cyr = probs[idx]

        # Script evidence: winning side needs a clear margin AND to beat
        # uniform noise, so padding steps (blank/uniform) don't vote.
        if best_lat > 0.008 and best_lat > best_cyr * 1.2:
            n_lat += 1
        elif best_cyr > 0.008 and best_cyr > best_lat * 1.2:
            n_cyr += 1

        if best_idx != 0 and best_idx != prev:
            if best_idx - 1 < len(chars):
                text_parts.append(chars[best_idx - 1])
            conf_sum += best_score
            conf_count += 1
            counting_blanks = True
        elif best_idx == 0 and counting_blanks:
            blank_steps += 1

        prev = best_idx

    text = "".join(text_parts).strip()
    conf = conf_sum / conf_count if conf_count > 0 else 0.0
    inner_blank_cov = 0.0
    if conf_count > 0 and steps > 0:
        inner = steps - conf_count
        if inner > 0:
            inner_blank_cov = min(1.0, blank_steps) * (inner / steps)
    return (text, conf, conf_count, inner_blank_cov, n_lat, n_cyr)

def _allowed(self, char: str) -> bool:
    # Decode alphabet = dict coverage: Cyrillic + Latin + digits +
    # whitespace + punctuation. Script normalization happens later,
    # per word, in fix_lookalikes_per_word (Latin lookalikes -> Cyrillic
    # inside Cyrillic words, pure Latin kept as-is). Blocking Latin here
    # forces true-Latin steps into blank/Cyrillic crumbs and breaks
    # neighboring words (e.g. window title "... yomihon-custom ...").
    if len(char) != 1:
        return False
    cp = ord(char)
    if 0x0400 <= cp <= 0x052F or 0xA640 <= cp <= 0xA69F:
        return True
    if char.isspace() or char in ALLOWED_PUNCTUATION:
        return True
    if 'a' <= char <= 'z' or 'A' <= char <= 'Z' or '0' <= char <= '9':
        return True
    return False

def _candidate_quality(self, rec: Recognition) -> float:
    if not rec.text.strip():
        return float('-inf')
    from ocr_text_cleaner import cyrillic_fitness, latin_fitness, is_acceptable_cyrillic_text, fix_lookalikes_per_word
    if rec.model == "en":
        fitness = latin_fitness(rec.text)
    else:
        fitness = cyrillic_fitness(rec.text)
    length_bonus = min(len(rec.text) * 0.01, 0.12)
    verifier_bonus = 0.0
    if rec.model == "v5" and is_acceptable_cyrillic_text(fix_lookalikes_per_word(rec.text)):
        verifier_bonus = VERIFIER_CYRILLIC_BONUS
    # Additive confidence: these distilled models cap peak prob at
    # ~0.016 even on perfect inputs, so multiplicative conf would let
    # v3's Latin garbage outrank v5's cleaner Cyrillic on ties.
    return fitness + length_bonus + verifier_bonus + rec.confidence

def _accepts_confidence(self, rec: Recognition) -> bool:
    letters = sum(1 for c in rec.text if c.isalpha())
    threshold = SHORT_TEXT_MIN_CONFIDENCE if letters in (1, 2, 3) else MIN_ACCEPT_CONFIDENCE
    discounted = self._coverage_penalty(rec.confidence, rec.coverage)
    return discounted >= threshold

def _coverage_penalty(self, confidence: float, coverage: float) -> float:
    if coverage <= MIN_COVERAGE:
        return confidence
    over = min(1.0, (coverage - MIN_COVERAGE) / (1.0 - MIN_COVERAGE))
    return confidence * (1.0 - 0.40 * over)

def _create_high_contrast(self, source: Image.Image) -> Image.Image:
    # Match Kotlin createHighContrast: desaturate, then 1.5x + (-45) per channel
    # ColorMatrix: setSaturation(0) then postConcat(1.5, bias -45)
    arr = np.array(source.convert("RGB"), dtype=np.float32)
    # Luma desaturation (same weights as splitWords: 77/150/29)
    lum = (arr[:, :, 0] * 0.299 + arr[:, :, 1] * 0.587 + arr[:, :, 2] * 0.114)
    gray = np.stack([lum, lum, lum], axis=-1)
    out = gray * 1.5 - 45.0
    out = np.clip(out, 0, 255).astype(np.uint8)
    return Image.fromarray(out, mode="RGB")

def _fallback_whole_image(self, img: Image.Image) -> str:
    result = self._recognize_crop(img)
    if not result.text.strip() or not self._accepts_confidence(result):
        return ""
    return self._clean_recognition(result.text)

# ── POST-PROCESSING ────────────────────────────────────

def _merge_boxes(self, boxes: List[TextBox]) -> List[TextBox]:
    if not boxes:
        return []
    sorted_boxes = sorted(boxes, key=lambda b: (b.top, b.left))
    merged = list(sorted_boxes)
    changed = True
    while changed:
        changed = False
        for i in range(len(merged)):
            for j in range(i + 1, len(merged)):
                a, b = merged[i], merged[j]
                overlap_y = max(0, min(a.bottom, b.bottom) - max(a.top, b.top))
                min_h = max(1, min(a.height, b.height))
                gap_x = max(0, max(a.left, b.left) - min(a.right, b.right))
                if (overlap_y >= min_h * MERGE_OVERLAP_Y_FACTOR and
                        gap_x <= max(a.height, b.height) * MERGE_GAP_X_FACTOR):
                    new_box = TextBox(
                        min(a.left, b.left), min(a.top, b.top),
                        max(a.right, b.right), max(a.bottom, b.bottom),
                    )
                    merged[i] = new_box
                    merged.pop(j)
                    changed = True
                    break
            if changed:
                break
    return sorted(merged, key=lambda b: (b.top, b.left))

def _pad(self, box: TextBox, width: int, height: int) -> TextBox:
    px = max(2, int(box.right - box.left) * 0.04)
    py = max(2, int(box.height) * 0.12)
    return TextBox(
        max(0, box.left - px), max(0, box.top - py),
        min(width, box.right + px), min(height, box.bottom + py),
    )

def _assemble_reading_order(self, recognized: List[Tuple[TextBox, str]]) -> str:
    if not recognized:
        return ""
    rows = []
    for box, text in recognized:
        placed = False
        for row in rows:
            center = np.mean([b.center_y for b, _ in row])
            height = np.mean([b.height for b, _ in row])
            if abs(box.center_y - center) <= max(box.height, height) * 0.60:
                row.append((box, text))
                placed = True
                break
        if not placed:
            rows.append([(box, text)])
    rows.sort(key=lambda r: min(b.top for b, _ in r))
    lines = []
    for row in rows:
        row.sort(key=lambda x: x[0].left)
        lines.append(" ".join(t.strip() for _, t in row))
    return "\n".join(lines)

def _clean_recognition(self, text: str) -> str:
    from ocr_text_cleaner import (
        normalize_local_cyrillic_caption, looks_like_dictionary_ramp,
        is_acceptable_cyrillic_text, filter_garbage_tokens,
    )
    cleaned = normalize_local_cyrillic_caption(text).strip()
    if not cleaned or looks_like_dictionary_ramp(cleaned):
        return ""
    if is_acceptable_cyrillic_text(cleaned):
        return cleaned
    return filter_garbage_tokens(cleaned)

def close(self):
    for m in [self._detector, self._primary, self._verifier]:
        if m is not None:
            try:
                m.close()
            except Exception:
                pass
    self._detector = self._primary = self._verifier = None
    self._initialized = False

"""
Glens OCR — Google Lens OCR через protobuf API.

Портировано из overlay-translator (Kotlin -> Python).
Использует официальный Google Lens endpoint для распознавания текста.
"""
import io
import logging
import os
import random
import struct
import requests
from PIL import Image

logger = logging.getLogger(__name__)

_TIMEOUT = 30


class ProtoWriter:
    """Minimal protobuf writer."""

    def __init__(self):
        self._buf = io.BytesIO()

    def write_int32(self, field: int, value: int):
        self._write_tag(field, 0)
        self._write_varint32(value)

    def write_uint64(self, field: int, value: int):
        self._write_tag(field, 0)
        self._write_varint64(value)

    def write_string(self, field: int, value: str):
        self.write_bytes(field, value.encode("utf-8"))

    def write_bytes(self, field: int, value: bytes):
        self._write_tag(field, 2)
        self._write_varint32(len(value))
        self._buf.write(value)

    def write_message(self, field: int, builder):
        inner = ProtoWriter()
        builder(inner)
        self.write_bytes(field, inner.to_bytes())

    def to_bytes(self) -> bytes:
        return self._buf.getvalue()

    def _write_tag(self, field: int, wire: int):
        self._write_varint32((field << 3) | wire)

    def _write_varint32(self, value: int):
        while (value & ~0x7F) != 0:
            self._buf.write(bytes([(value & 0x7F) | 0x80]))
            value >>= 7
        self._buf.write(bytes([value & 0x7F]))

    def _write_varint64(self, value: int):
        while (value & ~0x7F) != 0:
            self._buf.write(bytes([((value & 0x7F) | 0x80) & 0xFF]))
            value >>= 7
        self._buf.write(bytes([value & 0x7F]))


class ProtoReader:
    """Minimal protobuf reader."""

    def __init__(self, data: bytes):
        self._data = data
        self._pos = 0

    def has_remaining(self) -> bool:
        return self._pos < len(self._data)

    def read_tag(self):
        if not self.has_remaining():
            return None
        return self._read_varint32()

    def read_bytes(self) -> bytes:
        length = self._read_varint32()
        if length is None:
            return b""
        safe_len = min(length, len(self._data) - self._pos)
        result = self._data[self._pos:self._pos + safe_len]
        self._pos += safe_len
        return result

    def read_string(self) -> str:
        return self.read_bytes().decode("utf-8", errors="replace")

    def skip_field(self, wire_type: int):
        if wire_type == 0:
            self._read_varint32()
        elif wire_type == 1:
            self._pos += 8
        elif wire_type == 2:
            length = self._read_varint32() or 0
            self._pos += min(length, len(self._data) - self._pos)
        elif wire_type == 5:
            self._pos += 4

    def _read_varint32(self):
        result = 0
        shift = 0
        while shift < 32:
            if not self.has_remaining():
                return None
            b = self._data[self._pos]
            self._pos += 1
            result |= (b & 0x7F) << shift
            if (b & 0x80) == 0:
                return result
            shift += 7
        return result


class GlensOCR:
    """Google Lens OCR через protobuf API."""

    ENDPOINT = "https://lensfrontend-pa.googleapis.com/v1/crupload"
    # Ключ НЕ в коде: берётся из настроек (ocr.online_api_key) или из
    # переменной окружения. Раньше здесь был захардкоженный ключ — он уезжал
    # в репозиторий вместе с исходниками.
    API_KEY = os.environ.get("GOOGLE_LENS_API_KEY", "")
    USER_AGENT = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/145.0.0.0 Safari/537.36"
    CLIENT_LANGUAGE = "ja"
    CLIENT_REGION = "Asia/Tokyo"
    MAX_IMAGE_DIMENSION = 1500

    def __init__(self, api_key: str = ""):
        self.api_key = api_key or self.API_KEY

    def recognize(self, image: Image.Image) -> str:
        """Распознаёт текст с изображения через Google Lens."""
        # Масштабируем если нужно
        m = max(image.width, image.height)
        if m > self.MAX_IMAGE_DIMENSION:
            s = self.MAX_IMAGE_DIMENSION / m
            image = image.resize(
                (int(image.width * s), int(image.height * s)),
                Image.Resampling.LANCZOS
            )

        # Конвертируем в PNG
        buf = io.BytesIO()
        image.save(buf, format="PNG")
        png_bytes = buf.getvalue()

        # Строим protobuf запрос
        payload = self._build_request(png_bytes, image.width, image.height)

        # Отправляем запрос
        response_bytes = self._execute_request(payload)

        # Парсим ответ
        return self._extract_text(response_bytes)

    def _build_request(self, png_bytes: bytes, width: int, height: int) -> bytes:
        """Строит protobuf запрос для Google Lens."""
        request_id = random.getrandbits(63)

        writer = ProtoWriter()
        writer.write_message(1, lambda obj_req: self._build_objects_request(
            obj_req, png_bytes, width, height, request_id
        ))
        return writer.to_bytes()

    def _build_objects_request(self, obj_req: ProtoWriter, png_bytes: bytes,
                               width: int, height: int, request_id: int):
        """Строит objects_request."""
        # objects_request_context
        obj_req.write_message(1, lambda ctx: self._build_context(ctx, request_id))

        # image_data
        obj_req.write_message(3, lambda img: self._build_image_data(
            img, png_bytes, width, height
        ))

    def _build_context(self, ctx: ProtoWriter, request_id: int):
        """Строит request_context."""
        # request_id
        ctx.write_message(3, lambda rid: self._build_request_id(rid, request_id))

        # client_context
        ctx.write_message(4, lambda cc: self._build_client_context(cc))

    def _build_request_id(self, rid: ProtoWriter, request_id: int):
        """Строит request_id."""
        rid.write_uint64(1, request_id)
        rid.write_int32(2, 0)
        rid.write_int32(3, 0)
        rid.write_bytes(4, random.randbytes(16))

    def _build_client_context(self, cc: ProtoWriter):
        """Строит client_context."""
        cc.write_int32(1, 3)  # PLATFORM_WEB
        cc.write_int32(2, 4)  # SURFACE_CHROMIUM

        # language_context
        cc.write_message(4, lambda lc: self._build_language_context(lc))

        # filters
        cc.write_message(7, lambda filters: self._build_filters(filters))

    def _build_language_context(self, lc: ProtoWriter):
        """Строит language_context."""
        lc.write_string(1, self.CLIENT_LANGUAGE)
        lc.write_string(2, self.CLIENT_REGION)

    def _build_filters(self, filters: ProtoWriter):
        """Строит filters."""
        filters.write_message(1, lambda fl: fl.write_int32(1, 1))  # AUTO_FILTER

    def _build_image_data(self, img: ProtoWriter, png_bytes: bytes,
                          width: int, height: int):
        """Строит image_data."""
        # png data
        img.write_message(1, lambda p: p.write_bytes(1, png_bytes))

        # dimensions
        img.write_message(3, lambda m: self._build_dimensions(m, width, height))

    def _build_dimensions(self, m: ProtoWriter, width: int, height: int):
        """Строит dimensions."""
        m.write_int32(1, width)
        m.write_int32(2, height)

    def _execute_request(self, payload: bytes) -> bytes:
        """Отправляет запрос в Google Lens."""
        resp = requests.post(
            self.ENDPOINT,
            data=payload,
            headers={
                "Content-Type": "application/x-protobuf",
                "User-Agent": self.USER_AGENT,
                "X-Goog-Api-Key": self.api_key,
            },
            timeout=_TIMEOUT,
        )
        resp.raise_for_status()
        return resp.content

    def _extract_text(self, data: bytes) -> str:
        """Извлекает текст из protobuf ответа."""
        reader = ProtoReader(data)
        all_lines = []

        while reader.has_remaining():
            tag = reader.read_tag()
            if tag is None:
                break
            field = tag >> 3
            wire = tag & 0x7

            if field == 2 and wire == 2:
                all_lines.extend(self._parse_objects_response(reader.read_bytes()))
            else:
                reader.skip_field(wire)

        return "\n".join(all_lines).strip()

    def _parse_objects_response(self, data: bytes) -> list:
        """Парсит objects_response."""
        reader = ProtoReader(data)
        lines = []

        while reader.has_remaining():
            tag = reader.read_tag()
            if tag is None:
                break
            field = tag >> 3
            wire = tag & 0x7

            if field == 3 and wire == 2:
                lines.extend(self._parse_text(reader.read_bytes()))
            else:
                reader.skip_field(wire)

        return lines

    def _parse_text(self, data: bytes) -> list:
        """Парсит text."""
        reader = ProtoReader(data)
        result = []

        while reader.has_remaining():
            tag = reader.read_tag()
            if tag is None:
                break
            field = tag >> 3
            wire = tag & 0x7

            if field == 1 and wire == 2:
                result.extend(self._parse_text_layout(reader.read_bytes()))
            else:
                reader.skip_field(wire)

        return result

    def _parse_text_layout(self, data: bytes) -> list:
        """Парсит text_layout."""
        reader = ProtoReader(data)
        lines = []

        while reader.has_remaining():
            tag = reader.read_tag()
            if tag is None:
                break
            field = tag >> 3
            wire = tag & 0x7

            if field == 1 and wire == 2:
                lines.extend(self._parse_paragraph(reader.read_bytes()))
            else:
                reader.skip_field(wire)

        return lines

    def _parse_paragraph(self, data: bytes) -> list:
        """Парсит paragraph."""
        reader = ProtoReader(data)
        lines = []

        while reader.has_remaining():
            tag = reader.read_tag()
            if tag is None:
                break
            field = tag >> 3
            wire = tag & 0x7

            if field == 2 and wire == 2:
                lines.append(self._parse_line(reader.read_bytes()))
            else:
                reader.skip_field(wire)

        return lines

    def _parse_line(self, data: bytes) -> str:
        """Парсит line (sequence of words)."""
        reader = ProtoReader(data)
        sb = io.StringIO()

        while reader.has_remaining():
            tag = reader.read_tag()
            if tag is None:
                break
            field = tag >> 3
            wire = tag & 0x7

            if field == 1 and wire == 2:
                sb.write(self._parse_word(reader.read_bytes()))
            else:
                reader.skip_field(wire)

        return sb.getvalue()

    def _parse_word(self, data: bytes) -> str:
        """Парсит word (text + separator)."""
        reader = ProtoReader(data)
        text = ""
        separator = ""

        while reader.has_remaining():
            tag = reader.read_tag()
            if tag is None:
                break
            field = tag >> 3
            wire = tag & 0x7

            if field == 2 and wire == 2:
                text = reader.read_string()
            elif field == 3 and wire == 2:
                separator = reader.read_string()
            else:
                reader.skip_field(wire)

        return text + separator

"""
Визуальная индикация процесса OCR.
Прогресс-бар и анимация сканирования.
"""
import logging
from PyQt6.QtWidgets import QWidget, QVBoxLayout, QProgressBar, QLabel, QGraphicsOpacityEffect
from PyQt6.QtCore import Qt, QTimer, QPropertyAnimation, QEasingCurve
from PyQt6.QtGui import QColor, QPainter, QPen, QBrush

logger = logging.getLogger(__name__)


class OCRIndicator(QWidget):
    """Виджет индикации процесса OCR"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._setup_ui()
        self._animation_timer = QTimer()
        self._animation_timer.timeout.connect(self._pulse)
        self._pulse_value = 0
        self._pulse_direction = 1

    def _setup_ui(self):
        self.setFixedHeight(30)
        self.setStyleSheet("""
            QWidget {
                background-color: transparent;
            }
        """)

        layout = QVBoxLayout(self)
        layout.setContentsMargins(5, 2, 5, 2)
        layout.setSpacing(2)

        # Метка статуса
        self.status_label = QLabel("Готов")
        self.status_label.setStyleSheet("""
            QLabel {
                color: #4caf50;
                font-size: 11px;
                font-weight: bold;
                background: transparent;
            }
        """)
        layout.addWidget(self.status_label)

        # Прогресс-бар
        self.progress_bar = QProgressBar()
        self.progress_bar.setRange(0, 100)
        self.progress_bar.setValue(0)
        self.progress_bar.setTextVisible(True)
        self.progress_bar.setFixedHeight(16)
        self.progress_bar.setStyleSheet("""
            QProgressBar {
                background-color: rgba(50, 50, 50, 150);
                border-radius: 8px;
                border: 1px solid rgba(100, 100, 100, 100);
                color: white;
                font-size: 10px;
            }
            QProgressBar::chunk {
                background-color: qlineargradient(x1:0, y1:0, x2:1, y2:0,
                    stop:0 #4caf50,
                    stop:1 #8bc34a);
                border-radius: 7px;
            }
        """)
        layout.addWidget(self.progress_bar)

        self.hide()

    def start_scanning(self):
        """Начало сканирования"""
        self.show()
        self.progress_bar.setValue(0)
        self.status_label.setText("⏳ Сканирование...")
        self.status_label.setStyleSheet("""
            QLabel {
                color: #ff9800;
                font-size: 11px;
                font-weight: bold;
                background: transparent;
            }
        """)
        self._animation_timer.start(30)
        logger.info("[INDICATOR] Сканирование начато")

    def update_progress(self, value: int):
        """Обновление прогресса (0-100)"""
        self.progress_bar.setValue(value)
        if value < 30:
            self.status_label.setText("📷 Захват экрана...")
        elif value < 70:
            self.status_label.setText("🔍 Распознавание...")
        elif value < 100:
            self.status_label.setText("✅ Завершение...")
        else:
            self.status_label.setText("✅ Готово!")

    def finish_scanning(self, success=True):
        """Завершение сканирования"""
        self._animation_timer.stop()
        if success:
            self.progress_bar.setValue(100)
            self.status_label.setText("✅ Текст распознан")
            self.status_label.setStyleSheet("""
                QLabel {
                    color: #4caf50;
                    font-size: 11px;
                    font-weight: bold;
                    background: transparent;
                }
            """)
        else:
            self.progress_bar.setValue(0)
            self.status_label.setText("❌ Ошибка")
            self.status_label.setStyleSheet("""
                QLabel {
                    color: #f44336;
                    font-size: 11px;
                    font-weight: bold;
                    background: transparent;
                }
            """)

        # Автоскрытие через 1.2 секунды
        QTimer.singleShot(1200, self.hide)

    def _pulse(self):
        """Пульсация прогресс-бара при активном сканировании"""
        self._pulse_value += self._pulse_direction * 8
        if self._pulse_value >= 100:
            self._pulse_direction = -1
        elif self._pulse_value <= 0:
            self._pulse_direction = 1

        current = self.progress_bar.value()
        if current < 90:
            self.progress_bar.setValue(self._pulse_value)


class ScanOverlay(QWidget):
    """Оверлей с анимацией сканирования поверх выбранной области"""

    def __init__(self, parent=None):
        super().__init__(parent)
        self._scan_position = 0
        self._scan_timer = QTimer()
        self._scan_timer.timeout.connect(self._update_scan)
        self.setStyleSheet("background: transparent;")

    def start_animation(self):
        """Запуск анимации сканирования"""
        self._scan_position = 0
        self._scan_timer.start(30)
        self.show()

    def stop_animation(self):
        """Остановка анимации"""
        self._scan_timer.stop()
        self.hide()

    def _update_scan(self):
        """Обновление позиции линии сканирования"""
        self._scan_position += 5
        if self._scan_position > self.height():
            self._scan_position = 0
        self.update()

    def paintEvent(self, event):
        """Отрисовка линии сканирования"""
        painter = QPainter(self)
        painter.setRenderHint(QPainter.RenderHint.Antialiasing)

        # Линия сканирования
        gradient_color = QColor(76, 175, 80, 150)
        painter.setPen(QPen(gradient_color, 2))
        painter.drawLine(0, self._scan_position, self.width(), self._scan_position)

        # Свечение вокруг линии
        glow = QColor(76, 175, 80, 50)
        painter.setPen(QPen(glow, 8))
        painter.drawLine(0, self._scan_position, self.width(), self._scan_position)

