h1{font-size:20px;color:#89b4fa;margin-bottom:8px}p{font-size:13px;color:#a6adc8;margin-bottom:20px}
a{color:#89b4fa}textarea{width:100%;height:120px;background:#181825;color:#cdd6f4;
